// ✂️ 2026-08-10: Google เข้มลิมิตความยาวพรอมต์วิดีโอ (นับ token — ไทยกินหนัก) → 400 "invalid argument" บางสินค้า/บางรอบ
//   พิสูจน์บนเว็บ Flow จริง: พรอมต์เต็ม = Failed แม้เจนมือ · ฉบับตัดสั้น (คำเดียวกัน) = ผ่าน — แก้พร้อม PD App v1.1.3
//   ระดับ 1 = ตัดท่อนเสริมท้าย (≤1500) · ระดับ 2 = ตัดแรง เหลือหัวฉาก + ท่อนบทพูด (~700 — ขนาดที่พิสูจน์ว่าผ่าน)
function _pdTrimPrompt(p, hard) {
  var t = String(p || '');
  var cuts = ['UNIVERSAL OVERLAY STYLE', 'HANDWRITING OVERLAY', 'Keep the handwritten white text'];
  for (var ci = 0; ci < cuts.length; ci++) { var idx = t.indexOf(cuts[ci]); if (idx > 200) t = t.slice(0, idx); }
  t = t.trim();
  var cap = hard ? 750 : 1500;
  if (t.length <= cap) return t;
  if (!hard) {
    var c1 = t.slice(0, cap); var j1 = Math.max(c1.lastIndexOf(','), c1.lastIndexOf(' '));
    return c1.slice(0, j1 > 800 ? j1 : cap).trim();
  }
  var m = t.match(/[^,]*พูด\s*"[^"]*"/);
  var head = t.slice(0, 400); var hj = Math.max(head.lastIndexOf(','), head.lastIndexOf(' '));
  var out = head.slice(0, hj > 200 ? hj : 400).trim();
  if (m && out.indexOf(m[0]) < 0) out += ', ' + m[0].trim();
  out += ', all spoken dialogue in Thai only, natural Thai accent, NO subtitles or captions on screen';
  return out;
}
function _pdIs400(e) { return /400|invalid argument/i.test((e && e.message) || ''); }

