function _ct(s){if(!s||typeof s!=='string'||_contentLang==='th')return s;if(_contentI18n[s])return _contentI18n[s];if(!/[\u0E00-\u0E7F]/.test(s))return s;let r=s;for(const[k,v]of Object.entries(_contentI18n)){if(k.length<3)continue;if(r.includes(k))r=r.split(k).join(v);if(!/[\u0E00-\u0E7F]/.test(r))break;}return r;}
