/**
 * v4.4.8: Privacy Curtain — ม่านบังหน้า Flow ตอน API Direct Mode ทำงาน
 * เป้าหมาย: คนเห็นแค่ว่า "บอทกำลังทำงาน" ไม่เห็นรายละเอียดบนหน้า Flow
 * ปลอดภัย — API Direct ไม่ใช้ DOM ของ Flow เลย overlay ไม่กระทบบอท
 */
function showApiDirectCurtain(message) {
  let curtain = document.getElementById('pd-api-direct-curtain');
  if (!curtain) {
    curtain = document.createElement('div');
    curtain.id = 'pd-api-direct-curtain';
    curtain.style.cssText = [
      'position:fixed', 'top:0', 'left:0', 'right:0', 'bottom:0',
      'width:100vw', 'height:100vh',
      'background:rgba(15,23,42,0.55)',
      'backdrop-filter:blur(18px)',
      '-webkit-backdrop-filter:blur(18px)',
      'z-index:2147483647',
      'display:flex', 'flex-direction:column',
      'align-items:center', 'justify-content:center',
      'color:#fff', 'font-family:Inter,system-ui,sans-serif',
      'pointer-events:auto',
      'transition:opacity 0.3s ease',
      'opacity:0'
    ].join(';');
    curtain.innerHTML = `
      <style>
        @keyframes pdCurtainSpin { to { transform: rotate(360deg); } }
        @keyframes pdCurtainPulse { 0%,100% { opacity:1; } 50% { opacity:0.5; } }
        #pd-api-direct-curtain .pd-curtain-spinner {
          width: 64px; height: 64px;
          border: 4px solid rgba(255,255,255,0.15);
          border-top: 4px solid #f59e0b;
          border-radius: 50%;
          animation: pdCurtainSpin 1s linear infinite;
          margin-bottom: 24px;
        }
        #pd-api-direct-curtain .pd-curtain-dot {
          display: inline-block; width: 8px; height: 8px; border-radius: 50%;
          background: #f59e0b; margin: 0 4px;
          animation: pdCurtainPulse 1.4s ease-in-out infinite;
        }
        #pd-api-direct-curtain .pd-curtain-dot:nth-child(2) { animation-delay: 0.2s; }
        #pd-api-direct-curtain .pd-curtain-dot:nth-child(3) { animation-delay: 0.4s; }
      </style>
      <div class="pd-curtain-spinner"></div>
      <div style="font-size:22px; font-weight:700; margin-bottom:10px; letter-spacing:0.5px;">
        🎬 PD Auto Footage กำลังทำงาน
      </div>
      <div id="pd-api-direct-curtain-msg" style="font-size:15px; color:#cbd5e1; margin-bottom:18px; text-align:center; max-width:80%;">
        ${message || 'กำลังเชื่อมต่อกับ Flow API...'}
      </div>
      <div style="font-size:12px; color:#94a3b8;">
        <span class="pd-curtain-dot"></span>
        <span class="pd-curtain-dot"></span>
        <span class="pd-curtain-dot"></span>
      </div>
      <div style="position:absolute; bottom:30px; font-size:11px; color:#64748b; text-align:center; line-height:1.6;">
        บอทกำลังทำงานในเบื้องหลัง — ห้ามปิดแท็บ<br>
        <span style="color:#94a3b8;">💡 ย่อจอให้เล็กได้ (ไปทำอย่างอื่นรอ)</span>
      </div>
    `;
    document.body.appendChild(curtain);
    // fade in
    requestAnimationFrame(() => { curtain.style.opacity = '1'; });
  } else if (message) {
    const msgEl = curtain.querySelector('#pd-api-direct-curtain-msg');
    if (msgEl) msgEl.textContent = message;
    curtain.style.opacity = '1';
  }
}

function updateApiDirectCurtain(message) {
  const msgEl = document.getElementById('pd-api-direct-curtain-msg');
  if (msgEl && message) msgEl.textContent = message;
}

function hideApiDirectCurtain() {
  const curtain = document.getElementById('pd-api-direct-curtain');
  if (!curtain) return;
  curtain.style.opacity = '0';
  setTimeout(() => { if (curtain.parentNode) curtain.parentNode.removeChild(curtain); }, 350);
}

/**
 * v4.4.8: forward log message → popup log panel
 * เพื่อให้ user เห็น progress ของ Direct API ใน log panel (ไม่ต้องเฝ้า Flow tab)
 */
function forwardLog(message) {
  try {
    chrome.runtime.sendMessage({ action: 'autoLog', message: message });
  } catch (e) {
    // popup ปิดอยู่ — เงียบไว้
  }
}

/** เรียก function ใน PDFlowAPI (MAIN world) จาก isolated world ผ่าน postMessage bridge */
function callFlowAPI(fn, ...args) {
  return new Promise((resolve, reject) => {
    const id = 'pdf-' + Math.random().toString(36).slice(2);
    const handler = (e) => {
      if (e.source !== window) return;
      const d = e.data;
      if (!d || !d.__pdFlowAPIResult || d.id !== id) return;
      window.removeEventListener('message', handler);
      clearTimeout(toid);
      if (d.error) {
        const err = new Error(d.error);
        err.status = d.errorStatus;
        err.body = d.errorBody;
        reject(err);
      } else {
        resolve(d.result);
      }
    };
    window.addEventListener('message', handler);
    const toid = setTimeout(() => {
      window.removeEventListener('message', handler);
      reject(new Error('callFlowAPI timeout: ' + fn));
    }, 120000);
    window.postMessage({ __pdFlowAPI: true, id, fn, args }, '*');
  });
}

/** Convert base64 (with or without data: prefix) → Blob */
function _pdBase64ToBlob(base64) {
  let mime = 'image/png';
  let dataPart = base64;
  if (typeof base64 === 'string' && base64.indexOf('data:') === 0) {
    const m = base64.match(/^data:([^;]+);base64,(.+)$/);
    if (m) { mime = m[1]; dataPart = m[2]; }
  }
  const bin = atob(dataPart);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return new Blob([buf], { type: mime });
}

/** หา projectId UUID จาก URL ปัจจุบันของ Flow */
function _pdGetProjectIdFromURL() {
  const m = (location.href || '').match(/\/project\/([0-9a-f-]{36})/);
  return m ? m[1] : null;
}

/** v4.4.7: Anti-abuse hardening — jitter helpers */
function _pdJitter(minMs, maxMs) {
  return minMs + Math.floor(Math.random() * Math.max(1, maxMs - minMs));
}
function _pdSleepJitter(minMs, maxMs) {
  return new Promise(r => setTimeout(r, _pdJitter(minMs, maxMs)));
}

/** v4.4.7: Poll video status loop — isolated-world side (3-6s jitter) */
/** v4.4.9: เพิ่ม log progress ทุก ~15 วิให้ user เห็นว่ายังรออยู่ */
async function _pdWaitForVideo(projectId, mediaId, opts) {
  opts = opts || {};
  const intervalMinMs = opts.intervalMinMs || 3000;
  const intervalMaxMs = opts.intervalMaxMs || 6000;
  const timeoutMs = opts.timeoutMs || 10 * 60 * 1000;
  const onProgress = opts.onProgress;
  // v4.4.9: tag = label เช่น "ฉาก 1/3" สำหรับ log progress
  const tag = opts.tag || 'คลิป';
  const progressLogIntervalMs = opts.progressLogIntervalMs || 15000; // log ทุก 15 วิ
  const start = Date.now();
  let lastStatus = null;
  let lastProgressLogTs = start; // เก็บ timestamp ล่าสุดที่ log progress
  while (true) {
    const r = await callFlowAPI('pollVideoStatus', { projectId, mediaId });
    const m = r && r.media && r.media[0];
    const status = m && m.mediaMetadata && m.mediaMetadata.mediaStatus && m.mediaMetadata.mediaStatus.mediaGenerationStatus;
    if (status !== lastStatus) {
      console.log('[v4.4.7 API] poll status: ' + status);
      lastStatus = status;
      // v4.4.9: เมื่อ status เปลี่ยน → log ให้ user เห็น (เช่น SCHEDULED → ACTIVE → SUCCESSFUL)
      if (status === 'MEDIA_GENERATION_STATUS_ACTIVE') {
        forwardLog(`⚡ ${tag} — Flow เริ่มสร้างแล้ว (ACTIVE)`);
      } else if (status === 'MEDIA_GENERATION_STATUS_SCHEDULED') {
        forwardLog(`⏳ ${tag} — เข้าคิว Flow แล้ว (SCHEDULED)`);
      }
    }
    if (onProgress) { try { onProgress(status, m); } catch (e) {} }
    if (status === 'MEDIA_GENERATION_STATUS_SUCCESSFUL') return m;
    if (status && /FAIL|ERROR|CANCEL/i.test(status)) {
      throw new Error('Video gen failed: ' + status);
    }
    if (Date.now() - start > timeoutMs) {
      throw new Error('waitForVideo timeout after ' + timeoutMs + 'ms');
    }
    // v4.4.9: log progress ทุก 15 วิ (กัน user คิดว่าค้าง)
    const now = Date.now();
    if (now - lastProgressLogTs >= progressLogIntervalMs) {
      const elapsedSec = Math.floor((now - start) / 1000);
      forwardLog(`⏳ รอ ${tag}... (${elapsedSec}s)`);
      lastProgressLogTs = now;
    }
    await _pdSleepJitter(intervalMinMs, intervalMaxMs);
  }
}

/** v4.4.7: Concat + poll loop */
async function _pdConcatAndWait(inputVideos, opts) {
  opts = opts || {};
  const intervalMinMs = opts.intervalMinMs || 3000;
  const intervalMaxMs = opts.intervalMaxMs || 6000;
  const timeoutMs = opts.timeoutMs || 10 * 60 * 1000;
  const onProgress = opts.onProgress;
  // v4.4.9: progress log ทุก ~15 วิ
  const progressLogIntervalMs = opts.progressLogIntervalMs || 15000;
  const op = await callFlowAPI('concatenate', { inputVideos });
  const operationName = op && op.operation && op.operation.operation && op.operation.operation.name;
  if (!operationName) throw new Error('concat did not return operation.name');
  console.log('[v4.4.7 API] concat job: ' + operationName);
  const start = Date.now();
  let lastStatus = null;
  let lastProgressLogTs = start;
  while (true) {
    const r = await callFlowAPI('checkConcatenationStatus', { operationName });
    if (r.status !== lastStatus) {
      console.log('[v4.4.7 API] concat status: ' + r.status);
      lastStatus = r.status;
      // v4.4.9: log status change ให้ user เห็น
      if (r.status === 'MEDIA_GENERATION_STATUS_ACTIVE') {
        forwardLog(`⚡ รวมคลิป — Flow เริ่ม encode แล้ว`);
      } else if (r.status === 'MEDIA_GENERATION_STATUS_SCHEDULED') {
        forwardLog(`⏳ รวมคลิป — เข้าคิว Flow แล้ว`);
      }
    }
    if (onProgress) { try { onProgress(r.status, r); } catch (e) {} }
    if (r.status === 'MEDIA_GENERATION_STATUS_SUCCESSFUL') return r;
    if (r.status && /FAIL|ERROR|CANCEL/i.test(r.status)) {
      const err = new Error('concat failed: ' + r.status);
      err.body = r;
      throw err;
    }
    if (Date.now() - start > timeoutMs) throw new Error('concat timeout ' + timeoutMs + 'ms');
    // v4.4.9: log progress ทุก 15 วิ
    const now = Date.now();
    if (now - lastProgressLogTs >= progressLogIntervalMs) {
      const elapsedSec = Math.floor((now - start) / 1000);
      forwardLog(`⏳ กำลังรวมคลิป... (${elapsedSec}s)`);
      lastProgressLogTs = now;
    }
    await _pdSleepJitter(intervalMinMs, intervalMaxMs);
  }
}

/**
 * v4.4.7: Auto Video Creation v2 — รับ extendScene จาก popup
 * ใช้ extendScene.scenes[i] (script ที่ popup gen ผ่าน AI) สำหรับ extend แต่ละฉาก
 */
async function startAutoVideoCreationViaAPI_v2(data, extendScene, imageInfo) {
  showApiDirectCurtain('กำลังต่อเชื่อมระบบสร้างวิดีโอ...');
  forwardLog(`🎬 [Express] เริ่มสร้างวิดีโอ — ${extendScene && extendScene.scenes ? (extendScene.scenes.length + 1) : 1} ฉาก`);
  const projectId = _pdGetProjectIdFromURL();
  if (!projectId) throw new Error('Express (video v2): ไม่พบ projectId ใน URL');
  if (!imageInfo || !imageInfo.mediaId) throw new Error('Express (video v2): missing imageInfo');

  const sessionId = ';' + Date.now();
  const scene1Prompt = (data.prompt || data.videoPrompt || 'cinematic camera, natural movement').trim();

  const allScenePrompts = [scene1Prompt];
  let extendCount = 0;
  if (extendScene && extendScene.enabled && Array.isArray(extendScene.scenes)) {
    for (const p of extendScene.scenes) {
      if (typeof p === 'string' && p.trim()) allScenePrompts.push(p.trim());
    }
    extendCount = allScenePrompts.length - 1;
  }
  const totalScenes = allScenePrompts.length;

  // v4.4.9b: fix model mapping — `veo_lite_lower` (Lower Priority / ฟรี 0 เครดิต) ของบอท default
  //          ต้อง map ไป `veo_3_1_i2v_lite_low_priority` (Flow backend name ของ tier นี้)
  //          เดิมใช้ `veo_3_1_i2v_lite` + `veo_3_1_extension_lite` ทำให้ Flow คิดเครดิต ลูกค้าเลือกผิดต่ำต้องการ
  // v4.5.2: Fast key อัพเดต → `veo_3_1_i2v_s_fast_portrait_ultra` (เปิด tier Ultra Fast portrait)
  const i2vModelMap = {
    'veo_lite_lower': 'veo_3_1_i2v_lite_low_priority',
    'veo_lite':       'veo_3_1_i2v_lite',
    'veo_fast':       'veo_3_1_i2v_s_fast_portrait_ultra',
    'veo_quality':    'veo_3_1_i2v_quality',
    'omni_flash':     'abra_i2v_8s',   // Omni Flash (i2v 8s, ~12 credits) — codename abra
  };
  const userI2vChoice = data.videoModel || 'veo_lite_lower';
  let i2vModelKey = i2vModelMap[userI2vChoice] || 'veo_3_1_i2v_lite_low_priority';
  // ⏱️ Omni Flash: จำนวนวิฝังในชื่อคีย์ (abra_i2v_8s / abra_i2v_10s) — ยืนยันจาก request จริง
  if (userI2vChoice === 'omni_flash') i2vModelKey = 'abra_i2v_' + (Number(data.omniSeconds) === 10 ? 10 : 8) + 's';
  // v4.5.2: ล็อค extend ฉาก 2+ เป็น Lite Lower (ฟรี 0 เครดิต) เสมอ — ไม่สนใจที่ลูกค้าเลือก
  //         เหตุผล: extension_fast/quality กินเครดิตหนัก, interpolation_lite_low_priority ฟรี + ทำได้จริง
  //         ลูกค้าเลือก Fast = เร็วแค่ฉาก 1 (i2v ultra), ฉาก 2+ คงเดิม ไม่กินเครดิต
  const extendModelKey = 'veo_3_1_i2v_lite_low_priority';
  console.log('[v4.4.7 API-v2] totalScenes=' + totalScenes + ' extendCount=' + extendCount + ' i2vModel=' + i2vModelKey + ' extendModel=' + extendModelKey);
  for (let i = 0; i < allScenePrompts.length; i++) {
    console.log('[v4.4.7 API-v2] scene ' + (i + 1) + ' prompt: ' + allScenePrompts[i].slice(0, 100));
  }

  try {
    const credits = await callFlowAPI('getCredits');
    console.log('[v4.4.7 API-v2] credits:', credits && credits.userPaygateTier, '|', credits && credits.credits, 'credits');
  } catch (e) {
    console.warn('[v4.4.7 API-v2] getCredits failed (non-fatal):', e.message);
  }

  await _pdSleepJitter(2000, 5000);

  // === Step 1: Animate (scene 1) ===
  const ANIMATE_MAX_ATTEMPTS = 3;
  let scene1VideoId = null;
  let scene1VideoWorkflowId = null;
  let animateLastErr = null;

  for (let attempt = 1; attempt <= ANIMATE_MAX_ATTEMPTS; attempt++) {
    try {
      showBotOverlay(
        '🚀 Express: Animate ฉาก 1/' + totalScenes + (attempt > 1 ? ' (retry ' + attempt + '/' + ANIMATE_MAX_ATTEMPTS + ')' : ''),
        'Veo i2v'
      );
      if (attempt === 1) forwardLog(`🎞️ [Express] animate ภาพ → คลิป ฉาก 1/${totalScenes}`);
      else forwardLog(`🔁 [Express] ลอง animate ฉาก 1 อีกครั้ง (รอบ ${attempt}/${ANIMATE_MAX_ATTEMPTS})`);
      console.log('[v4.4.7 API-v2] animate scene 1 (attempt ' + attempt + '/' + ANIMATE_MAX_ATTEMPTS + ')');

      // ✂️ รอบก่อนโดน 400 = พรอมต์ยาวเกินลิมิตใหม่ → รีทายด้วยฉบับตัด (รอบ 2 = ตัดท่อนเสริม · รอบ 3 = ตัดแรง)
      let animPrompt = allScenePrompts[0];
      if (attempt > 1 && _pdIs400(animateLastErr)) {
        animPrompt = _pdTrimPrompt(allScenePrompts[0], attempt >= 3);
        forwardLog(`✂️ [Express] พรอมต์ยาวเกินลิมิตใหม่ของ Google (400) — ${attempt >= 3 ? 'ตัดแรงขึ้น เหลือแก่นฉาก+บทพูด' : 'ตัดท่อนเสริมท้าย'} แล้วลองใหม่`);
      }
      const animateRes = await callFlowAPI('animateImage', {
        projectId, sessionId,
        prompt: animPrompt,
        imageMediaId: imageInfo.mediaId,
        aspectRatio: 'VIDEO_ASPECT_RATIO_PORTRAIT',
        videoModelKey: i2vModelKey,
        // cropCoordinates ถอดออก 2026-08-10 — เว็บจริงไม่ส่งแล้ว
      });
      const scene1VideoMedia = animateRes && animateRes.media && animateRes.media[0];
      scene1VideoId = scene1VideoMedia && scene1VideoMedia.name;
      scene1VideoWorkflowId = scene1VideoMedia && scene1VideoMedia.workflowId;
      if (!scene1VideoId) throw new Error('animate returned no videoMediaId');
      console.log('[v4.4.7 API-v2] animate started — mediaId=' + scene1VideoId + ' workflowId=' + scene1VideoWorkflowId);

      showBotOverlay('🚀 Express: รอ ฉาก 1/' + totalScenes, 'Polling');
      await _pdWaitForVideo(projectId, scene1VideoId, { timeoutMs: 10 * 60 * 1000, tag: `ฉาก 1/${totalScenes}` });
      console.log('[v4.4.7 API-v2] ✅ Scene 1 SUCCESSFUL (attempt ' + attempt + '/' + ANIMATE_MAX_ATTEMPTS + ')');
      forwardLog(`✅ [Express] ฉาก 1/${totalScenes} เสร็จแล้ว`);
      animateLastErr = null;
      break;
    } catch (err) {
      animateLastErr = err;
      const is403 = /403|reCAPTCHA|PERMISSION_DENIED|UNUSUAL_ACTIVITY/i.test(err.message || '');
      console.warn('[v4.4.7 API-v2 animate-retry] attempt ' + attempt + '/' + ANIMATE_MAX_ATTEMPTS + ' fail: ' + err.message);
      const failReason = is403 ? '403 reCAPTCHA (Flow flag user)' : err.message.substring(0, 80);
      forwardLog(`❌ [Express] animate ฉาก 1 รอบ ${attempt}/${ANIMATE_MAX_ATTEMPTS} เฟล: ${failReason}`);
      if (attempt < ANIMATE_MAX_ATTEMPTS) {
        // v4.4.8: escalating wait (5-10s → 25-35s) — ให้ Flow คลายธง
        const waitMs = attempt === 1 ? _pdJitter(5000, 10000) : _pdJitter(25000, 35000);
        const waitSec = Math.round(waitMs / 1000);
        showBotOverlay('🔁 retry animate scene 1 (' + (attempt + 1) + '/' + ANIMATE_MAX_ATTEMPTS + ')', 'wait ' + waitSec + 's');
        forwardLog(`⏳ รอ ${waitSec}s ก่อนลอง animate ฉาก 1 อีกครั้ง`);
        console.log('[v4.4.7 API-v2 animate-retry] wait ' + waitMs + 'ms before retry...');
        await new Promise(r => setTimeout(r, waitMs));
      }
    }
  }

  if (animateLastErr) {
    throw new Error('animate scene 1 failed after ' + ANIMATE_MAX_ATTEMPTS + ' attempts: ' + animateLastErr.message);
  }

  await _pdSleepJitter(2000, 5000);

  // === Step 2: Create scene container (เฉพาะกรณีต่อฉาก — single clip ไม่ต้อง) ===
  // v4.4.8 fix: scene container ใช้สำหรับ extend chain เท่านั้น (multi-clip → updateSceneWorkflowsOffsets + concat)
  //            ถ้า totalScenes === 1 (ไม่ต่อฉาก) → ข้าม createScene ประหยัด API call + เวลา
  let sceneId = null;
  let sceneAspect = null;
  if (totalScenes > 1) {
    showBotOverlay('🚀 Express: สร้าง Scene', 'Scene');
    const sceneRes = await callFlowAPI('createScene', {
      projectId,
      workflowIds: [scene1VideoWorkflowId]
    });
    sceneId = sceneRes && sceneRes.scene && sceneRes.scene.sceneId;
    sceneAspect = sceneRes && sceneRes.scene && sceneRes.scene.aspectRatio;
    console.log('[v4.4.7 API-v2] scene created — sceneId=' + sceneId + ' aspect=' + sceneAspect);
    if (sceneAspect && sceneAspect.indexOf('PORTRAIT') === -1) {
      console.warn('[v4.4.7 API-v2] ⚠️ scene aspect not PORTRAIT! got: ' + sceneAspect);
    }
  } else {
    console.log('[v4.4.8] Single clip (no extend) → skip createScene (ประหยัด API call)');
    forwardLog(`⏭️ [Express] ไม่ต่อฉาก — ข้าม createScene`);
  }

  const allClipMediaIds = [scene1VideoId];
  const allClipWorkflowIds = [scene1VideoWorkflowId];

  // === Step 3: Loop extend ===
  const EXTEND_MAX_ATTEMPTS = 3;
  const EXTEND_RETRY_WAIT_MS = 5000;
  for (let i = 1; i < totalScenes; i++) {
    await _pdSleepJitter(2000, 5000);
    const sceneNum = i + 1;
    const scenePrompt = allScenePrompts[i];
    console.log('[v4.4.7 API-v2] scene ' + sceneNum + ' prompt:', scenePrompt.slice(0, 120));
    forwardLog(`🎬 [Express] ต่อฉาก ${sceneNum}/${totalScenes}`);

    let extendVideoId = null;
    let extendWorkflowId = null;
    let lastErr = null;

    for (let attempt = 1; attempt <= EXTEND_MAX_ATTEMPTS; attempt++) {
      if (attempt > 1) {
        // v4.4.8: escalating retry wait (5-10s → 25-35s → 55-65s) — 403 reCAPTCHA ต้องรอ Flow คลายธง
        const retryWaitMs = attempt === 2 ? _pdJitter(5000, 10000)
                          : attempt === 3 ? _pdJitter(25000, 35000)
                          : _pdJitter(55000, 65000);
        const waitSec = Math.round(retryWaitMs / 1000);
        showBotOverlay('🔁 รอ ' + waitSec + 's ก่อนลองใหม่ ฉาก ' + sceneNum + ' (' + attempt + '/' + EXTEND_MAX_ATTEMPTS + ')', 'Cooldown');
        forwardLog(`⏳ รอ ${waitSec}s ก่อนลองต่อฉาก ${sceneNum} ใหม่ (รอบ ${attempt}/${EXTEND_MAX_ATTEMPTS})`);

        try {
          const survivors = allClipWorkflowIds.map((wfId, idx) => ({
            sceneId,
            workflow: { name: wfId },
            sceneWorkflowMetadata: {
              startTime: '0.000000000s',
              endTime: '8.000000000s',
              position: idx,
              totalDuration: '8s',
            }
          }));
          await callFlowAPI('updateSceneWorkflowsOffsets', {
            sceneId, projectId,
            sceneWorkflows: survivors,
          });
          console.log('[v4.4.7 API-v2 retry] cleanup OK — kept positions 0..' + (allClipWorkflowIds.length - 1));
        } catch (cleanupErr) {
          console.warn('[v4.4.7 API-v2 retry] cleanup failed (continuing anyway): ' + cleanupErr.message);
        }
        console.log('[v4.4.7 API-v2 retry] waiting ' + retryWaitMs + 'ms before re-extend...');
        await new Promise(r => setTimeout(r, retryWaitMs));
      }

      try {
        showBotOverlay(
          '🚀 Express: ต่อฉาก ' + sceneNum + '/' + totalScenes + (attempt > 1 ? ' (retry ' + attempt + '/' + EXTEND_MAX_ATTEMPTS + ')' : ''),
          'Extend'
        );
        if (attempt > 1) forwardLog(`🔁 [Express] ลองต่อฉาก ${sceneNum} อีกครั้ง (รอบ ${attempt}/${EXTEND_MAX_ATTEMPTS})`);
        const sourceMediaId = allClipMediaIds[allClipMediaIds.length - 1];
        console.log('[v4.4.7 API-v2] extending scene ' + sceneNum + ' from ' + sourceMediaId + ' (attempt ' + attempt + '/' + EXTEND_MAX_ATTEMPTS + ')');

        // ✂️ รอบก่อนโดน 400 = พรอมต์ยาวเกินลิมิตใหม่ → รีทายด้วยฉบับตัด
        let extPrompt = scenePrompt;
        if (attempt > 1 && _pdIs400(lastErr)) {
          extPrompt = _pdTrimPrompt(scenePrompt, attempt >= 3);
          forwardLog(`✂️ [Express] ฉาก ${sceneNum}: พรอมต์ยาวเกินลิมิตใหม่ (400) — ตัด${attempt >= 3 ? 'แรงขึ้น' : 'ท่อนเสริม'} แล้วลองใหม่`);
        }
        const extendRes = await callFlowAPI('extendVideo', {
          projectId, sessionId,
          sceneId,
          position: i,
          prompt: extPrompt,
          sourceVideoMediaId: sourceMediaId,
          videoModelKey: extendModelKey,
        });
        const extendMedia = extendRes && extendRes.media && extendRes.media[0];
        extendVideoId = extendMedia && extendMedia.name;
        extendWorkflowId = extendMedia && extendMedia.workflowId;
        if (!extendVideoId) throw new Error('extend ' + sceneNum + ' returned no mediaId');
        console.log('[v4.4.7 API-v2] extend ' + sceneNum + ' started — mediaId=' + extendVideoId + ' workflowId=' + extendWorkflowId);

        showBotOverlay('🚀 Express: รอ ฉาก ' + sceneNum + '/' + totalScenes, 'Polling');
        await _pdWaitForVideo(projectId, extendVideoId, { timeoutMs: 10 * 60 * 1000, tag: `ฉาก ${sceneNum}/${totalScenes}` });
        console.log('[v4.4.7 API-v2] ✅ Scene ' + sceneNum + ' SUCCESSFUL (attempt ' + attempt + '/' + EXTEND_MAX_ATTEMPTS + ')');
        forwardLog(`✅ [Express] ฉาก ${sceneNum}/${totalScenes} เสร็จแล้ว`);
        lastErr = null;
        break;
      } catch (err) {
        lastErr = err;
        const is403 = /403|reCAPTCHA|PERMISSION_DENIED|UNUSUAL_ACTIVITY/i.test(err.message || '');
        console.warn('[v4.4.7 API-v2 retry] scene ' + sceneNum + ' attempt ' + attempt + '/' + EXTEND_MAX_ATTEMPTS + ' fail: ' + err.message);
        const reason = is403 ? '403 reCAPTCHA (Flow flag user)' : err.message.substring(0, 80);
        forwardLog(`❌ [Express] ฉาก ${sceneNum} รอบ ${attempt}/${EXTEND_MAX_ATTEMPTS} เฟล: ${reason}`);
      }
    }

    if (lastErr) {
      throw new Error('extend scene ' + sceneNum + ' failed after ' + EXTEND_MAX_ATTEMPTS + ' attempts: ' + lastErr.message);
    }

    allClipMediaIds.push(extendVideoId);
    allClipWorkflowIds.push(extendWorkflowId);
  }

  console.log('[v4.4.7 API-v2] All scenes done — clipIds=' + JSON.stringify(allClipMediaIds));

  await _pdSleepJitter(2000, 5000);

  // === Step 4: Trim 1s ของ extends (เฉพาะกรณีมี > 1 clip) ===
  if (allClipMediaIds.length > 1) {
    const haveAllWorkflowIds = allClipWorkflowIds.every(w => !!w);
    if (haveAllWorkflowIds) {
      try {
        const sceneWorkflowsBody = allClipWorkflowIds.map((wfId, idx) => ({
          sceneId,
          workflow: { name: wfId },
          sceneWorkflowMetadata: {
            startTime: idx === 0 ? '0.000000000s' : '1.000000000s',
            endTime: '8.000000000s',
            position: idx,
            totalDuration: '8s',
          }
        }));
        showBotOverlay('🚀 Express: ตัด 1วิแรกของ extends', 'Trim');
        await callFlowAPI('updateSceneWorkflowsOffsets', {
          sceneId,
          projectId,
          sceneWorkflows: sceneWorkflowsBody,
        });
        console.log('[v4.4.7 API-v2 trim] ✅ trimmed ' + (allClipWorkflowIds.length - 1) + ' extend clip(s), 1s each');
      } catch (e) {
        console.warn('[v4.4.7 API-v2 trim] sceneWorkflows:update failed (non-fatal — fall back to inputVideos offsets):', e.message);
      }
    } else {
      console.warn('[v4.4.7 API-v2 trim] some workflowIds missing — skip scene trim, rely on inputVideos offsets');
    }
    await _pdSleepJitter(2000, 5000);
  }

  // === Step 5: Encode → MP4 base64 (รองรับทั้ง single + multi clip) ===
  // v4.4.8 fix: ก่อนหน้านี้ single clip reload page ทันที → ไม่โพส TikTok
  //          ตอนนี้ encode ทุกกรณีผ่าน concatenate (1 clip ก็ encode ได้)
  const isSingleClip = allClipMediaIds.length === 1;

  // === v4.4.8 quality: Direct download path สำหรับ single clip + 1080p/4K ===
  // **Full upscale flow** (ทุกคลิปที่บอทเพิ่ง gen เสร็จ → ยังไม่มี _upsampled):
  //   1. fetch _upsampled ลองก่อน (เผื่อมีแล้ว = idempotent)
  //   2. ถ้าไม่มี → เรียก batchAsyncGenerateVideoUpsampleVideo → poll status → รอเสร็จ
  //   3. แล้ว fetch /fx/api/trpc/media.getMediaUrlRedirect?name=<mediaId>_upsampled → MP4 binary
  //
  // ดักค้นเจอ endpoint (verified 2026-05-22):
  //   POST /v1/video:batchAsyncGenerateVideoUpsampleVideo  ← trigger upscale (ใช้เวลาเป็นนาที)
  //   POST /v1/video:batchCheckAsyncVideoGenerationStatus  ← poll (เหมือน animate/extend)
  //   GET  /fx/api/trpc/media.getMediaUrlRedirect?name=<id>_upsampled → MP4 binary
  //
  // **เฉพาะ single clip non-extend** — extend ต้อง concat เพราะรวมหลาย mediaId
  const wantUpscale = isSingleClip && data && (data.saveClipQuality === '1080p' || data.saveClipQuality === '4k');
  if (wantUpscale) {
    const qualityKey = data.saveClipQuality; // '1080p' หรือ '4k'
    const suffix = qualityKey === '4k' ? '_upsampled_4k' : '_upsampled';
    const resolution = qualityKey === '4k' ? 'VIDEO_RESOLUTION_4K' : 'VIDEO_RESOLUTION_1080P';
    const mediaId = allClipMediaIds[0];
    const workflowId = allClipWorkflowIds[0]; // จาก scene1VideoWorkflowId ตอน animate
    const upsampledName = mediaId + suffix;

    showBotOverlay('🚀 Express: เตรียม ' + qualityKey + '...', 'Upsample');
    forwardLog(`🎯 [Express ${qualityKey}] เริ่มกระบวนการ upscale → download`);
    console.log('[v4.4.8 quality] Want ' + qualityKey + ' for mediaId=' + mediaId + ' workflowId=' + workflowId);

    // === Step A: ลอง fetch _upsampled ก่อน (idempotent — เผื่อ retry หรือผู้ใช้เคย upscale ใน UI แล้ว) ===
    // ⚠️ ห้ามใส่ credentials:'include' — getMediaUrlRedirect 302 → CDN (flow-content.google) ที่ไม่มี CORS headers
    // ถ้าใส่ credentials browser จะ reject cross-origin redirect ด้วย "Failed to fetch" → fallback 720p
    // verified 2026-05-27: omit credentials = ได้ 9.1MB 1080p MP4 / include = Failed to fetch
    async function _tryFetchUpsampled() {
      const trpcUrl = '/fx/api/trpc/media.getMediaUrlRedirect?name=' + encodeURIComponent(upsampledName);
      const r = await fetch(trpcUrl, { method: 'GET' });
      if (!r.ok) throw new Error('getMediaUrlRedirect status=' + r.status);
      const blob = await r.blob();
      if (!blob || blob.size < 100 * 1024) throw new Error('blob too small: ' + (blob ? blob.size : 0));
      return blob;
    }

    let finalBlob = null;
    try {
      console.log('[v4.4.8 quality] Step A: try fetch existing _upsampled first');
      finalBlob = await _tryFetchUpsampled();
      console.log('[v4.4.8 quality] ✅ _upsampled exists already — skip upscale step');
      forwardLog(`✅ [Express ${qualityKey}] คลิป upscale แล้ว — ดาวน์โหลดเลย`);
    } catch (eFetchFirst) {
      // === Step B: ไม่มี → trigger upscale ===
      console.log('[v4.4.8 quality] Step A failed (' + eFetchFirst.message + ') — Step B: trigger upscale');
      if (!workflowId) {
        // ไม่มี workflowId → ทำต่อไม่ได้ → fallback concat 720p
        console.warn('[v4.4.8 quality] ❌ missing workflowId for upsample — fallback to 720p concat');
        forwardLog(`⚠️ [Express ${qualityKey}] ขาด workflowId — ใช้ 720p concat แทน`);
      } else {
        try {
          forwardLog(`⬆️ [Express ${qualityKey}] เริ่ม upscale (อาจใช้เวลา 1-3 นาที)...`);
          showBotOverlay('🚀 Express: upscale ' + qualityKey, 'Triggering');

          const upRes = await callFlowAPI('upsampleVideo', {
            projectId,
            sessionId,
            videoMediaId: mediaId,
            videoWorkflowId: workflowId,
            aspectRatio: 'VIDEO_ASPECT_RATIO_PORTRAIT', // ตาม animate
            resolution,
          });
          const upMedia = upRes && upRes.media && upRes.media[0];
          const pollName = (upMedia && upMedia.name) || upsampledName;
          console.log('[v4.4.8 quality] upsample triggered — pollName=' + pollName);
          forwardLog(`🔄 [Express ${qualityKey}] รอ Flow upscale คลิป (poll ทุก 3-6 วิ)...`);

          showBotOverlay('🚀 Express: รอ upscale ' + qualityKey, 'Polling');
          await _pdWaitForVideo(projectId, pollName, {
            timeoutMs: 10 * 60 * 1000, // 10 นาที (เผื่อช้า)
            tag: `upscale ${qualityKey}`,
            onProgress: function(status) {
              if (status === 'MEDIA_GENERATION_STATUS_ACTIVE') {
                showBotOverlay('🚀 Express: upscale ' + qualityKey + '...', 'Active');
              }
            },
          });
          console.log('[v4.4.8 quality] ✅ upscale SUCCESSFUL — fetching');
          forwardLog(`✅ [Express ${qualityKey}] upscale เสร็จ — ดาวน์โหลดไฟล์`);

          await _pdSleepJitter(1500, 3000); // เผื่อ Flow ทำ post-processing เล็กน้อย
          finalBlob = await _tryFetchUpsampled();
        } catch (eUpsample) {
          console.warn('[v4.4.8 quality] ❌ upsample/fetch failed:', eUpsample.message);
          forwardLog(`⚠️ [Express ${qualityKey}] upscale fail (${eUpsample.message}) — ใช้ 720p concat แทน`);
        }
      }
    }

    // === Step C: ถ้าได้ blob → dispatch event + send extendSceneComplete ===
    if (finalBlob) {
      const sizeMB = Math.round(finalBlob.size / 1024 / 1024 * 10) / 10;
      console.log('[v4.4.8 quality] ✅ Got ' + qualityKey + ' blob: ' + sizeMB + ' MB (' + finalBlob.type + ')');
      showBotOverlay('✅ ได้คลิป ' + qualityKey + '!', sizeMB + ' MB');
      forwardLog(`✅ [Express ${qualityKey}] ดาวน์โหลดเสร็จ — ${sizeMB} MB พร้อมเซฟ/โพส`);

      // Convert blob → data URL (popup จะแปลงกลับเป็น Blob URL ก่อน chrome.downloads.download)
      const dataUrl = await new Promise(function(resolve, reject) {
        const reader = new FileReader();
        reader.onloadend = function() { resolve(reader.result); };
        reader.onerror = function() { reject(new Error('FileReader fail')); };
        reader.readAsDataURL(finalBlob);
      });

      const ts = Date.now();
      const sourceTag = 'apiDirect_v4.4.8_' + qualityKey;
      const dlFilename = 'pd_api_v448_' + qualityKey + '_' + ts + '.mp4';

      window.dispatchEvent(new CustomEvent('__flow_final_video__', {
        detail: { base64: dataUrl, size: finalBlob.size, filename: dlFilename, source: sourceTag }
      }));

      await new Promise(function(r) { setTimeout(r, 1000); });

      try {
        chrome.runtime.sendMessage({
          action: 'extendSceneComplete',
          success: true,
          setIndex: data.autoSetIndex || 0,
          scenesCompleted: 1,
          videoFilename: dlFilename,
          source: sourceTag,
        });
        console.log('[v4.4.8 quality] sent extendSceneComplete — source=' + sourceTag);
      } catch (e) { console.warn('[v4.4.8 quality] sendMessage fail:', e); }

      try { hideApiDirectCurtain(); } catch (e) {}
      try { hideBotOverlay(); } catch (e) {}
      isProcessing = false;
      return { videoMediaIds: allClipMediaIds, sceneId, source: sourceTag, sizeBytes: finalBlob.size };
    }
    // ถ้าถึงนี่ = ไม่ได้ blob → ไหลต่อไป concat 720p ตามปกติ (fallback แจ้ง user แล้ว)
  }

  showBotOverlay(
    isSingleClip ? '🚀 Express: เตรียมคลิป 8วิ' : '🚀 Express: รวมคลิป ' + allClipMediaIds.length + ' ฉาก',
    isSingleClip ? 'Encode' : 'Concat'
  );
  forwardLog(isSingleClip
    ? `🎬 [Express] เตรียมคลิป 8 วิ เป็นไฟล์ MP4...`
    : `🎬 [Express] รวมคลิป ${allClipMediaIds.length} ฉาก เป็น MP4 ตัวเดียว...`);
  const inputVideos = allClipMediaIds.map((id, idx) => ({
    mediaGenerationId: id,
    length: '8000000000',
    startTimeOffset: idx === 0 ? '0s' : '1s',
    endTimeOffset: '8s',
  }));
  const concatRes = await _pdConcatAndWait(inputVideos, {
    timeoutMs: 10 * 60 * 1000,
    onProgress: (status) => {
      if (status === 'MEDIA_GENERATION_STATUS_ACTIVE') {
        showBotOverlay(isSingleClip ? '🚀 Express: กำลัง encode...' : '🚀 Express: กำลังรวมคลิป...', 'Active');
      }
    },
  });
  const encodedVideo = concatRes && concatRes.encodedVideo;
  if (!encodedVideo) throw new Error('concat SUCCESSFUL but no encodedVideo');

  const sizeEst = Math.round(encodedVideo.length * 3 / 4);
  const sizeMB = Math.round(sizeEst / 1024 / 1024 * 10) / 10;
  console.log('[v4.4.7 API-v2] ✅ Encode done — encodedVideo ' + encodedVideo.length + ' chars (~' + sizeMB + ' MB)');
  showBotOverlay('✅ ได้คลิปสุดท้าย!', sizeMB + ' MB');
  forwardLog(`✅ [Express] ${isSingleClip ? 'เตรียมคลิปเสร็จ' : 'รวมคลิปเสร็จ'} — ได้ไฟล์ MP4 ${sizeMB} MB พร้อมโพส`);

  window.dispatchEvent(new CustomEvent('__flow_final_video__', {
    detail: {
      base64: 'data:video/mp4;base64,' + encodedVideo,
      size: sizeEst,
      filename: 'pd_api_v447_' + Date.now() + '.mp4',
      source: 'apiDirect_v4.4.7',
    }
  }));
  console.log('[v4.4.7 API-v2] dispatched __flow_final_video__');

  await new Promise(r => setTimeout(r, 1500));

  try {
    chrome.runtime.sendMessage({
      action: 'extendSceneComplete',
      success: true,
      setIndex: data.autoSetIndex || 0,
      scenesCompleted: totalScenes,
      videoFilename: 'pd_api_v447_' + Date.now() + '.mp4',
      source: 'apiDirect_v4.4.7',
    });
    console.log('[v4.4.7 API-v2] sent extendSceneComplete — TikTok pipeline takes over');
  } catch (e) {
    console.warn('[v4.4.7 API-v2] sendMessage extendSceneComplete failed:', e);
  }

  // v4.4.8: ปิด overlay ทั้งหมดบน Flow tab — Flow ทำเสร็จแล้ว
  try { hideApiDirectCurtain(); } catch (e) {}
  try { hideBotOverlay(); } catch (e) {}
  isProcessing = false;
  return { videoMediaIds: allClipMediaIds, sceneId, encodedVideoLen: encodedVideo.length };
}

/**
 * v4.4.7: Auto Image Creation ผ่าน Flow API ตรงๆ
 * เรียกเมื่อ data.apiDirectMode === true เท่านั้น
 */
async function startAutoImageCreationViaAPI(data) {
  showBotOverlay('🚀 Express: เริ่มต้น...', 'พร้อม');
  showApiDirectCurtain('กำลังเตรียมสร้างภาพ...');
  forwardLog(`📷 [Express] เริ่มสร้างภาพ ชุดที่ ${(data.autoSetIndex || 0) + 1}`);
  const projectId = _pdGetProjectIdFromURL();
  if (!projectId) {
    throw new Error('Express: ไม่พบ projectId ใน URL — เปิดหน้า project ก่อน');
  }
  const sessionId = ';' + Date.now();
  console.log('[v4.4.7 API] data received:', {
    imageModel: data.imageModel,
    aspectRatio: data.aspectRatio,
    promptLen: (data.prompt || '').length,
    promptHead: (data.prompt || '').slice(0, 120),
    imagesCount: (data.images || []).length,
    imageFilenames: data.imageFilenames,
    autoSetIndex: data.autoSetIndex,
  });

  await callFlowAPI('isReady');

  // === Step 1: Upload reference images ===
  const imgs = Array.isArray(data.images) ? data.images : [];
  if (!imgs.length) {
    throw new Error('Express: ไม่มีรูป reference ใน data.images');
  }
  // v4.4.9: log จำนวนรูปที่จะอัพ ให้ user รู้ก่อนเริ่ม
  if (imgs.length > 0) {
    forwardLog(`📤 [Express] เริ่มอัพรูปอ้างอิง ${imgs.length} รูป...`);
  }
  const refUUIDs = [];
  for (let i = 0; i < imgs.length; i++) {
    if (i > 0) await _pdSleepJitter(2000, 5000);
    const fileName = (data.imageFilenames && data.imageFilenames[i]) || ('ref-' + i + '.png');
    // v4.4.9: log progress ทุกรูป ให้ user เห็นว่าอัพถึงไหนแล้ว
    showBotOverlay(`🚀 Express: อัพรูป ${i + 1}/${imgs.length}`, 'Upload');
    forwardLog(`📤 [Express] อัพรูป ${i + 1}/${imgs.length}: ${fileName}`);
    const base64 = imgs[i];
    const fileBlob = _pdBase64ToBlob(base64);
    const media = await callFlowAPI('uploadImage', {
      projectId, fileBlob, fileName, mimeType: fileBlob.type
    });
    refUUIDs.push(media.name);
    console.log('[v4.4.7 API] uploaded ' + fileName + ' → ' + media.name);
    forwardLog(`✅ [Express] อัพรูป ${i + 1}/${imgs.length} เสร็จ`);
  }

  await _pdSleepJitter(2000, 5000);

  // === Step 2: Generate image (with retry) ===
  showBotOverlay('🚀 Express: สร้างภาพ', 'Gen');
  // v4.5.2: nano_banana_2 ยังไม่มี API key ของ Flow → fallback ใช้ Pro (GEM_PIX_2) ชั่วคราว
  //          TODO: เมื่อ research API key ได้แล้ว เปลี่ยน mapping ตรงนี้
  const modelMap = {
    'nano_banana_pro': 'GEM_PIX_2',
    'nano_banana_2':   'GEM_PIX_2', // v4.5.2 TEMP — ใช้ Pro แทนจนกว่าจะรู้ API key ของ Nano 2
    'imagen_4': 'IMAGEN_4',
    'imagen_3_5': 'IMAGEN_3_5',
  };
  const imageModelName = modelMap[data.imageModel] || 'IMAGEN_4';
  if (data.imageModel === 'nano_banana_2') {
    forwardLog(`ℹ️ [Express] Nano Banana 2 ยังไม่รองรับใน API Direct → ใช้ Pro แทน (Merge Mode รองรับเต็ม)`);
  }

  const aspectMap = {
    '9:16': 'IMAGE_ASPECT_RATIO_PORTRAIT',
    '16:9': 'IMAGE_ASPECT_RATIO_LANDSCAPE',
    '1:1':  'IMAGE_ASPECT_RATIO_SQUARE',
  };
  const aspectRatio = aspectMap[data.aspectRatio] || 'IMAGE_ASPECT_RATIO_PORTRAIT';

  const IMG_MAX_403 = 3;
  const IMG_MAX_OTHER = 6;
  let attempts403 = 0;
  let attemptsOther = 0;
  let result = null;
  while (true) {
    try {
      result = await callFlowAPI('generateImage', {
        projectId, sessionId,
        prompt: data.prompt,
        refUUIDs,
        imageModelName,
        aspectRatio
      });
      const m = result && result.media && result.media[0];
      if (!m) throw new Error('image gen returned no media in response');
      break;
    } catch (err) {
      const is403 = err.status === 403;
      if (is403) attempts403++;
      else attemptsOther++;
      const totalAttempts = attempts403 + attemptsOther;
      console.warn('[v4.4.7 API img-retry] attempt ' + totalAttempts + ' fail (' + (is403 ? '403/anti-abuse' : 'non-403') + '): ' + err.message);

      if (is403 && attempts403 >= IMG_MAX_403) {
        throw new Error('image gen — 403 anti-abuse ครบ ' + IMG_MAX_403 + ' รอบ → ข้ามสินค้า');
      }
      if (!is403 && attemptsOther >= IMG_MAX_OTHER) {
        throw new Error('image gen — fail ครบ ' + IMG_MAX_OTHER + ' รอบ → ข้ามสินค้า: ' + err.message);
      }
      // v4.4.8: escalating wait สำหรับ 403 (8-15s → 25-35s → 55-65s)
      const waitMs = is403
        ? (attempts403 === 1 ? _pdJitter(8000, 15000) : attempts403 === 2 ? _pdJitter(25000, 35000) : _pdJitter(55000, 65000))
        : _pdJitter(5000, 10000);
      const waitSec = Math.round(waitMs / 1000);
      showBotOverlay('🔁 retry image gen ' + (totalAttempts + 1) + ' (' + (is403 ? '403' : 'fail') + ')', 'wait ' + waitSec + 's');
      forwardLog(`❌ [Express] สร้างภาพ รอบ ${totalAttempts} เฟล (${is403 ? '403 reCAPTCHA' : 'อื่นๆ'}) — รอ ${waitSec}s แล้วลองใหม่`);
      console.log('[v4.4.7 API img-retry] wait ' + waitMs + 'ms before retry...');
      await new Promise(r => setTimeout(r, waitMs));
    }
  }

  const media = result && result.media && result.media[0];
  if (!media) throw new Error('Express: image gen returned no media');
  const imgUUID = media.name;
  const fifeUrl = media.image && media.image.generatedImage && media.image.generatedImage.fifeUrl;
  console.log('[v4.4.7 API] ✅ Image gen — mediaId=' + imgUUID + ' fife=' + (fifeUrl ? fifeUrl.slice(0, 80) : 'N/A'));
  showBotOverlay('✅ Express: สร้างภาพสำเร็จ', imgUUID.slice(0, 8) + '...');
  forwardLog(`✅ [Express] สร้างภาพเสร็จ — กำลังส่งต่อเข้าระบบสร้างคลิป`);

  window._pdApiImageInfo = {
    mediaId: imgUUID,
    workflowId: media.workflowId,
    fifeUrl: fifeUrl,
    setIndex: data.autoSetIndex || 0,
    ts: Date.now(),
  };

  try {
    chrome.runtime.sendMessage({
      action: 'autoImageComplete',
      imageUrl: fifeUrl,
      imageUrls: [fifeUrl],
      setIndex: data.autoSetIndex || 0,
      apiDirectMode: true,
      apiImageMediaId: imgUUID,
      apiImageWorkflowId: media.workflowId,
    });
    console.log('[v4.4.7 API] image done — sent autoImageComplete; waiting popup to drive createAutoVideo');
  } catch (e) {
    console.error('[v4.4.7] sendMessage autoImageComplete failed:', e);
  }

  isProcessing = false;
  return { mediaId: imgUUID, fifeUrl: fifeUrl };
}

// v4.4.4: ฟัง event เมื่อ runVideoFxConcatenation ล้มเหลว (Flow ใหม่: "Failed to export scene")
window.addEventListener('__flow_concatenation_failed__', (e) => {
  const { status, error } = e.detail || {};
  console.log(`[v4.4.4] 🚨 Concatenation FAILED (status=${status}) — ตั้ง flag`);
  window._flowConcatFailed = {
    status: status,
    error: error,
    timestamp: Date.now()
  };
});

// v4.2.2: ฟัง event เมื่อ Flow API ตอบ 403/error — bot ไม่ต้องรอ timeout
// v4.4.4: เพิ่ม handler พิเศษสำหรับ quota-exceeded (Error 253)
window.addEventListener('__flow_generate_failed__', (e) => {
  const { status, api, error, source } = e.detail || {};
  // v4.4.4: ตรวจ quota error — Google account-level limit (ไม่ใช่ retry ได้)
  const errStr = String(error || '').toLowerCase();
  const isQuotaError = errStr.includes('quota-exceeded')
    || errStr.includes('error code 253')
    || errStr.includes('exceeds the quota')
    || errStr.includes('quota.*exceeded')
    || errStr.includes('daily limit reached')
    || errStr.includes('rate limit exceeded')
    || /\b253\b/.test(errStr);

  if (isQuotaError) {
    console.log(`[v4.4.4] 🚫 Flow QUOTA EXCEEDED — Google account-level limit (${error})`);
    window._flowGenerateFailed = {
      status: status,
      api: api,
      error: error,
      source: source,
      isQuotaError: true,
      timestamp: Date.now()
    };
    // Notify popup ทันที — ให้แสดง modal/banner เด่นๆ
    try {
      chrome.runtime.sendMessage({
        action: 'flowQuotaExceeded',
        message: 'Google Flow quota หมด — รอ reset เที่ยงคืน Pacific (~14:00 ของไทย พรุ่งนี้) หรือใช้ account อื่น',
        timestamp: Date.now()
      }).catch(() => {});
    } catch (e) {}
  } else {
    console.log(`[v4.2.2] 🚨 Flow generate failed (${status}) — ตั้ง flag ให้ monitor abort`);
    window._flowGenerateFailed = {
      status: status,
      api: api,
      error: error,
      timestamp: Date.now()
    };
  }
});

window.addEventListener('__flow_final_video__', (e) => {
  const { base64, size, filename, source } = e.detail;
  // v0.6.1 (port VIP v4.6.7): นับทุก event ที่ hook ยิงมา (diagnostic — fallback ใช้บอกว่า hook ยิงแต่ไฟล์เล็ก หรือไม่ยิงเลย)
  try { const _s = window.__pdFinalVideoSeen__ || { count: 0 }; _s.count++; _s.lastSize = size; _s.lastSource = source; window.__pdFinalVideoSeen__ = _s; } catch (_) {}
  // เก็บเฉพาะ video ที่ใหญ่พอ (> 1MB) เพื่อกรอง preview blob เล็กๆ ออก
  if (size < 1024 * 1024) {
    console.log(`[v3.5 Hook] Skip small blob: ${Math.round(size / 1024)} KB (source: ${source})`);
    return;
  }
  console.log(`[v3.5 Hook] ✅ Received Final video: ${filename || 'unnamed'} (${Math.round(size / 1024 / 1024 * 10) / 10} MB, source: ${source})`);

  // เก็บไว้ใน window scope
  window.__flowFinalVideoData__ = { base64, size, filename, source, timestamp: Date.now() };

  // ส่ง base64 ไป popup ทันที (push model — ก่อนที่ tab จะ navigate ไป)
  chrome.runtime.sendMessage({
    action: 'flowFinalVideoReady',
    base64, size, filename, source
  }).catch(() => {});
});


// State - v8.2: ใช้ window scope สำหรับ state สำคัญเพื่อรักษาข้าม injection
// v4.2.2: ใช้ var แทน let/const ทุกตัวที่ top-level — กัน SyntaxError ตอน Chrome inject content.js ซ้ำ
var isProcessing = window._flowVeoState?.isProcessing || false;
var currentData = window._flowVeoState?.currentData || null;
var clipCountBeforeGenerate = window._flowVeoState?.clipCountBeforeGenerate || 0;
var failedCountBeforeGenerate = window._flowVeoState?.failedCountBeforeGenerate || 0;
var currentBatchId = window._flowVeoState?.currentBatchId || 0;
var retryCount = 0; // จำนวนครั้งที่ retry
var MAX_RETRIES = 3; // retry สูงสุด 3 ครั้ง
var currentFailedRetryCount = 0; // v7.3: จำนวน retry ที่ผ่านมาหลัง refresh (รับจาก popup)
var currentMode = 'video'; // 'video' หรือ 'image' - ใช้กำหนดความเร็ว delay
var clickedButtonPositions = []; // เก็บตำแหน่งปุ่มที่กดไปแล้ว {left, top} (ไม่กดซ้ำตำแหน่งเดิม)
var usedImageUrls = new Set(); // เก็บ URL รูปทั้งหมดที่ใช้ไปแล้ว (ข้ามชุด) เพื่อไม่ให้ดึงรูปเก่ามาใช้ซ้ำ

// v10.2: ฟังก์ชันจัดการ usedImageUrls ใน chrome.storage.session (คงอยู่แม้รีเฟรชหน้า)
async function loadUsedImageUrls() {
  try {
    const result = await chrome.storage.session.get('usedImageUrls');
    if (result.usedImageUrls && Array.isArray(result.usedImageUrls)) {
      usedImageUrls = new Set(result.usedImageUrls);
      console.log(`[Auto] Loaded ${usedImageUrls.size} usedImageUrls from storage`);
    }
  } catch (e) {
    console.log('[Auto] Could not load usedImageUrls from storage:', e.message);
  }
}

async function saveUsedImageUrls() {
  try {
    await chrome.storage.session.set({ usedImageUrls: Array.from(usedImageUrls) });
    console.log(`[Auto] Saved ${usedImageUrls.size} usedImageUrls to storage`);
  } catch (e) {
    console.log('[Auto] Could not save usedImageUrls to storage:', e.message);
  }
}

async function clearUsedImageUrls() {
  usedImageUrls.clear();
  try {
    await chrome.storage.session.remove('usedImageUrls');
    console.log('[Auto] Cleared usedImageUrls from storage');
  } catch (e) {
    console.log('[Auto] Could not clear usedImageUrls from storage:', e.message);
  }
}

async function addToUsedImageUrls(urls) {
  urls.forEach(url => usedImageUrls.add(url));
  await saveUsedImageUrls();
}

// โหลด usedImageUrls เมื่อ content script เริ่มทำงาน
loadUsedImageUrls();

// v8.5.1: Helper function สำหรับ delay
// v4.2.2: var แทน const — กัน redeclaration error
var sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

// Extend Scene State (ต่อฉาก)
var extendSceneEnabled = false; // เปิดใช้ต่อฉากหรือไม่
var extendScenePrompt = ''; // prompt สำหรับฉาก 2
var extendSceneSetIndex = -1; // v5.8.3: setIndex ที่กำลังทำต่อฉาก
var extendSceneCancelled = false; // v5.8.3: ถูกยกเลิกหรือไม่

// v6.3.1: Fast Mode - ลดเวลารอจาก 150 วิ เป็น 100 วิ
var fastModeEnabled = false;

// v8.2: Save state to window (สำหรับ Multi-Set ที่ไม่ refresh)
function saveStateToWindow() {
  window._flowVeoState = {
    isProcessing,
    currentData,
    clipCountBeforeGenerate,
    failedCountBeforeGenerate,
    currentBatchId
  };
}

// Listen for messages from popup
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  // v11.0: Ping - ใช้เช็คว่า content script ยัง active อยู่
  if (message.action === 'ping') {
    sendResponse({ success: true, message: 'pong' });
    return true;
  }

  // สร้างวิดีโอ
  if (message.action === 'createVideo') {
    if (message.forceReset) {
      isProcessing = false;
    }

    if (isProcessing) {
      sendResponse({ success: false, error: 'กำลังดำเนินการอยู่ กรุณารอสักครู่' });
      return true;
    }

    currentData = message.data;
    isProcessing = true;
    currentMode = 'video'; // ตั้งโหมดเป็น video

    // v6.3.1: รับค่า Fast Mode
    fastModeEnabled = message.fastMode || false;
    console.log('[Fast Mode] Enabled:', fastModeEnabled);

    // เก็บ Extend Scene settings
    extendSceneEnabled = message.extendScene?.enabled || false;
    extendScenePrompt = message.extendScene?.prompt || '';
    extendSceneSetIndex = message.extendScene?.setIndex ?? -1; // v5.8.3: รับ setIndex
    extendSceneCancelled = false; // v5.8.3: reset cancelled flag
    console.log('[Extend Scene] Enabled:', extendSceneEnabled, 'SetIndex:', extendSceneSetIndex, 'Prompt:', extendScenePrompt?.substring(0, 50));

    startVideoCreation(message.data)
      .then(() => {
        sendResponse({ success: true });
        isProcessing = false;
      })
      .catch((error) => {
        console.error('Error:', error);
        sendResponse({ success: false, error: error.message });
        isProcessing = false;
      });

    return true;
  }

  // สร้างรูปภาพ
  if (message.action === 'createImage') {
    if (message.forceReset) {
      isProcessing = false;
    }
    currentMode = 'image'; // ตั้งโหมดเป็น image (เร็วกว่า video)

    if (isProcessing) {
      sendResponse({ success: false, error: 'กำลังดำเนินการอยู่ กรุณารอสักครู่' });
      return true;
    }

    currentData = message.data;
    isProcessing = true;

    // v6.3.1: รับค่า Fast Mode
    fastModeEnabled = message.fastMode || false;

    startImageCreation(message.data)
      .then(() => {
        sendResponse({ success: true });
        isProcessing = false;
      })
      .catch((error) => {
        console.error('Error:', error);
        sendResponse({ success: false, error: error.message });
        isProcessing = false;
      });

    return true;
  }

  // Auto Pipeline: สร้างภาพ
  if (message.action === 'createAutoImage') {
    if (message.forceReset) {
      isProcessing = false;
    }
    currentMode = 'image';

    if (isProcessing) {
      sendResponse({ success: false, error: 'กำลังดำเนินการอยู่ กรุณารอสักครู่' });
      return true;
    }

    currentData = message.data;
    isProcessing = true;

    // v6.3.1: รับค่า Fast Mode
    fastModeEnabled = message.fastMode || false;

    // v13.2: รับค่า isPodcast สำหรับ retry logic ของ "Something went wrong"
    const isPodcast = message.isPodcast || false;

    // v7.0.1: ส่ง response ทันทีก่อนเริ่มสร้างภาพ
    sendResponse({ success: true });

    // v4.4.7: API Direct Mode branch — bypass UI clicks ทั้งหมด
    if (message.data && message.data.apiDirectMode === true) {
      console.log('[v4.4.7] 🚀 API Direct Mode ON — bypass UI clicks');
      startAutoImageCreationViaAPI(message.data)
        .catch((error) => {
          console.error('[v4.4.7] API Direct error:', error);
          if (error && error.status) console.error('[v4.4.7] HTTP status:', error.status);
          if (error && error.body) console.error('[v4.4.7] Response body:', error.body);
          const errMsg = (error.message || String(error)).substring(0, 150);
          showBotOverlay('❌ สร้างภาพเฟล: ' + errMsg, 'Error');
          // v4.4.8: ม่านเบลอคงไว้ + แสดง error ในม่าน → auto-hide หลัง 8s (กว่า popup จะ kick next set)
          try { updateApiDirectCurtain('❌ สร้างภาพเฟล — กำลังข้ามไปชุดถัดไป...'); } catch (e) {}
          setTimeout(() => { try { hideApiDirectCurtain(); } catch (e) {} }, 8000);
          isProcessing = false;
          try {
            chrome.runtime.sendMessage({
              action: 'autoImageFailed',
              error: error.message,
              setIndex: message.data.autoSetIndex || 0
            });
          } catch (e) {}
        });
      return true;
    }

    // v17 FIX: เช็คก่อนว่าหน้า Flow โหลดจริงหรือเป็น Application Error
    if (!checkPageHealth()) {
      console.log('[Auto] 🚨 Application Error — ส่ง retry แล้ว reload');
      isProcessing = false;
      showBotOverlay('หน้า Flow crash — กำลัง refresh...', 'Application Error');
      chrome.runtime.sendMessage({
        action: 'autoImageFailed_NeedRetry',
        setIndex: message.data?.autoSetIndex || 0,
        retryCount: 1,
        maxRetries: 3
      });
      setTimeout(() => window.location.reload(), 1000);
      return true;
    }

    startAutoImageCreation(message.data, isPodcast)
      .catch((error) => {
        console.error('Auto Image Error:', error);
        isProcessing = false;
      });

    return true;
  }

  // v3.9: Viral Mode — สร้างภาพจาก prompt ล้วนๆ (ไม่ upload รูป ไม่แนบ reference)
  if (message.action === 'createViralImage') {
    if (message.forceReset) isProcessing = false;
    currentMode = 'image';

    if (isProcessing) {
      sendResponse({ success: false, error: 'กำลังดำเนินการอยู่' });
      return true;
    }

    currentData = message.data;
    isProcessing = true;
    fastModeEnabled = message.fastMode || false;
    sendResponse({ success: true });

    if (!checkPageHealth()) {
      isProcessing = false;
      showBotOverlay('หน้า Flow crash — กำลัง refresh...', 'Application Error');
      setTimeout(() => window.location.reload(), 1000);
      return true;
    }

    // Viral pipeline: settings → พิมพ์ prompt → generate (ไม่ upload/แนบรูป)
    (async () => {
      try {
        const data = message.data;
        showBotOverlay('🔥 Viral Mode: สร้างภาพ...', 'เตรียมความพร้อม');

        await closeAnyOpenPanels();
        await clickSidebarFilter('images');
        await clickGridViewButton();

        // นับภาพก่อนสร้าง
        const imageCountBefore = countAllGeneratedImages();

        // Step 1-2: เลือก Image mode + ตั้งค่า
        updateBotOverlay('ตั้งค่า Image mode...', 'Viral Pipeline');
        await step1_SelectImageMode();
        await step2_ConfigureSettings({
          mode: 'image',
          clipCount: 1,
          aspectRatio: data.aspectRatio || '9:16',
          imageModel: data.imageModel || 'nano_banana_pro'
        });

        // Step 5: กรอก prompt (ไม่ upload/แนบรูปอะไรเลย)
        updateBotOverlay('กรอก prompt...', 'Viral Pipeline');
        await step5_EnterPrompt(data.prompt);

        // Step 6: Generate
        updateBotOverlay('กำลังสร้างภาพ...', 'Viral Pipeline');
        await step6_Generate();

        // รอภาพสร้างเสร็จ
        updateBotOverlay('รอ AI สร้างภาพ...', 'Viral Pipeline');
        const imageResult = await monitorAutoImageProgress(imageCountBefore, 1);

        if (imageResult && imageResult.success) {
          showBotOverlay('✅ สร้างภาพสำเร็จ!', 'Viral Pipeline');
          isProcessing = false;
          // ส่งผลกลับ popup.js เหมือน Auto Mode
          chrome.runtime.sendMessage({
            action: 'autoImageComplete',
            imageUrl: imageResult.imageUrl || null,
            setIndex: data.autoSetIndex || 0
          });
        } else {
          throw new Error(imageResult?.error || 'สร้างภาพไม่สำเร็จ');
        }
      } catch (error) {
        console.error('[Viral] Image creation error:', error);
        isProcessing = false;
        showBotOverlay(`❌ ${error.message}`, 'Viral Pipeline');
        chrome.runtime.sendMessage({
          action: 'autoImageFailed',
          error: error.message,
          setIndex: message.data?.autoSetIndex || 0
        });
      }
    })();

    return true;
  }

  // Auto Pipeline: สร้างวิดีโอจาก URL ภาพ
  if (message.action === 'createAutoVideo') {
    if (message.forceReset) {
      isProcessing = false;
    }
    currentMode = 'video';

    if (isProcessing) {
      sendResponse({ success: false, error: 'กำลังดำเนินการอยู่ กรุณารอสักครู่' });
      return true;
    }

    currentData = message.data;
    isProcessing = true;

    // v4.4.7: API Direct Mode branch — bypass UI clicks ทั้งหมด
    if (message.apiDirectMode === true) {
      console.log('[v4.4.7] 🚀 createAutoVideo: API Direct Mode ON — using API path');
      sendResponse({ success: true });
      const imageInfo = message.apiImageInfo || window._pdApiImageInfo;
      if (!imageInfo || !imageInfo.mediaId) {
        console.error('[v4.4.7] API path: missing apiImageInfo — fallback to UI flow');
      } else {
        // v4.5.x fix: popup ส่ง saveClipQuality ที่ top-level ของ message — inject เข้า data
        // เพื่อให้ startAutoVideoCreationViaAPI_v2 → wantUpscale check (data.saveClipQuality) เห็น
        // ก่อน fix นี้ data.saveClipQuality = undefined ตลอด → upscale path ไม่เคย fire → 1080p/4K ไม่ทำงาน
        const dataWithQuality = Object.assign({}, message.data, {
          saveClipQuality: message.saveClipQuality || (message.data && message.data.saveClipQuality) || null,
        });
        startAutoVideoCreationViaAPI_v2(dataWithQuality, message.extendScene, imageInfo)
          .catch((error) => {
            console.error('[v4.4.7] API video path error:', error);
            if (error && error.status) console.error('[v4.4.7] HTTP status:', error.status);
            if (error && error.body) console.error('[v4.4.7] Response body:', error.body);
            const errMsg = (error.message || String(error)).substring(0, 150);
            showBotOverlay('❌ สร้างวิดีโอเฟล: ' + errMsg, 'Error');
            // v4.4.8: ม่านเบลอคงไว้ + แสดง error → auto-hide หลัง 8s (รอ popup รับ autoVideoFailed + processAutoSet ชุดถัดไปจะ show curtain ใหม่)
            try { updateApiDirectCurtain('❌ สร้างวิดีโอเฟล — กำลังข้ามไปชุดถัดไป...'); } catch (e) {}
            setTimeout(() => { try { hideApiDirectCurtain(); } catch (e) {} }, 8000);
            isProcessing = false;
            try {
              chrome.runtime.sendMessage({
                action: 'autoVideoFailed',
                error: error.message,
                setIndex: message.data?.autoSetIndex || 0,
              });
            } catch (e) {}
          });
        return true;
      }
    }

    // v6.3.1: รับค่า Fast Mode
    fastModeEnabled = message.fastMode || false;

    // v7.3: รับค่า failedRetryCount จาก popup (เพื่อนับต่อจาก retry ก่อนหน้าหลัง refresh)
    currentFailedRetryCount = message.failedRetryCount || 0;
    console.log(`[Auto] Received failedRetryCount: ${currentFailedRetryCount}`);

    // v17.1: รับค่า autoPostTiktok เพื่อ save sessionStorage สำหรับ video capture หลัง extend reload
    window._autoPostTiktok = message.autoPostTiktok || false;

    // v4.0.1: ไม่เซฟคลิปลงเครื่อง (ใช้ apiIntercept แทน download)
    // ส่ง flag ไป MAIN world ผ่าน CustomEvent (content.js = ISOLATED, flow-hook.js = MAIN)
    if (message.skipVideoDownload) {
      console.log('[v4.0.1] Skip video download enabled — sending flag to MAIN world');
      window.dispatchEvent(new CustomEvent('__flow_skip_download__', { detail: { enabled: true } }));
    } else {
      window.dispatchEvent(new CustomEvent('__flow_skip_download__', { detail: { enabled: false } }));
    }

    // v5.3.2: รับค่า extend scene
    if (message.extendScene && message.extendScene.enabled) {
      extendSceneEnabled = true;
      extendScenePrompt = message.extendScene.prompt || '';
      extendSceneSetIndex = message.extendScene.setIndex ?? -1; // v5.8.3
      extendSceneCancelled = false; // v5.8.3
      // v16.1: รับ scenes array สำหรับหลายฉาก
      window._extendScenesList = message.extendScene.scenes || [extendScenePrompt];
      window._extendSceneCount = message.extendScene.sceneCount || 2;
      // v4.3.2: รับโมเดลวีดีโอแยกสำหรับ extend (Flow ถอด Fast Lower 2026-05-10 — Lite Lower ต่อฉากได้แล้ว ฟรี 0 เครดิต)
      window._extendVideoModel = message.extendScene.videoModel || 'veo_lite_lower';
      console.log(`[Extend Scene Auto] SetIndex: ${extendSceneSetIndex}, Scenes: ${window._extendScenesList.length}, SceneCount: ${window._extendSceneCount}, ExtendModel: ${window._extendVideoModel}`);
      console.log(`🔧 [v16.2 Debug] Received scenes from popup:`, window._extendScenesList.map((s, i) => `[${i}] ${s.substring(0, 60)}...`));
      chrome.runtime.sendMessage({ action: 'extendSceneLog', text: `Received from popup: scenes=${window._extendScenesList.length}, count=${window._extendSceneCount}` });
    } else {
      extendSceneEnabled = false;
      extendScenePrompt = '';
      extendSceneSetIndex = -1;
      extendSceneCancelled = false; // v5.8.4: reset ด้วยเมื่อไม่ได้เปิด extend scene
      window._extendScenesList = [];
      window._extendSceneCount = 1;
    }

    // v13: บันทึก Podcast scene config สำหรับฉาก 3+
    if (message.isPodcast && message.podcastSceneCount > 2) {
      sessionStorage.setItem('podcastSceneCount', message.podcastSceneCount.toString());
      sessionStorage.setItem('podcastScenes', JSON.stringify(message.podcastScenes || []));
      console.log(`[Podcast v13] Saved scene config: ${message.podcastSceneCount} scenes`);
    } else {
      sessionStorage.removeItem('podcastSceneCount');
      sessionStorage.removeItem('podcastScenes');
    }

    // v13: บันทึก isPodcast flag
    if (message.isPodcast) {
      sessionStorage.setItem('isPodcastMode', 'true');
    }

    // v7.0.1: ส่ง response ทันทีก่อนเริ่มสร้างวิดีโอ
    sendResponse({ success: true });

    // v17 FIX: เช็คก่อนว่าหน้า Flow โหลดจริงหรือเป็น Application Error
    if (!checkPageHealth()) {
      console.log('[Auto] 🚨 Application Error — ส่ง retry แล้ว reload');
      isProcessing = false;
      showBotOverlay('หน้า Flow crash — กำลัง refresh...', 'Application Error');
      chrome.runtime.sendMessage({
        action: 'autoVideoFailed_NeedRetry',
        setIndex: message.data?.autoSetIndex || 0,
        retryCount: 1,
        maxRetries: 3
      });
      setTimeout(() => window.location.reload(), 1000);
      return true;
    }

    startAutoVideoCreation(message.data)
      .catch((error) => {
        console.error('Auto Video Error:', error);
        isProcessing = false;
      });

    return true;
  }

  // Reset state
  if (message.action === 'resetState') {
    isProcessing = false;
    currentData = null;
    sendResponse({ success: true });
    return true;
  }

  // v5.8.4: ล้าง fingerprints เมื่อเริ่ม Auto Pipeline ใหม่
  if (message.action === 'clearAutoFingerprints') {
    clearClipFingerprints();
    sendResponse({ success: true });
    return true;
  }

  // v5.9: เคลียร์แคชทั้งหมด (เรียกจากหน้า Settings)
  if (message.action === 'clearAllCache') {
    console.log('[Content] Clearing all cache...');
    try {
      // เคลียร์ sessionStorage ทั้งหมด
      sessionStorage.clear();

      // เคลียร์ localStorage เฉพาะที่เกี่ยวกับ Flow (ไม่ลบ license)
      const keysToRemove = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && (key.includes('flow') || key.includes('clip') || key.includes('video') || key.includes('extend'))) {
          keysToRemove.push(key);
        }
      }
      keysToRemove.forEach(key => localStorage.removeItem(key));

      // เคลียร์ IndexedDB ของ Flow (ถ้ามี)
      if (indexedDB && indexedDB.databases) {
        indexedDB.databases().then(dbs => {
          dbs.forEach(db => {
            if (db.name && db.name.includes('flow')) {
              indexedDB.deleteDatabase(db.name);
            }
          });
        }).catch(e => console.warn('IndexedDB clear skipped:', e));
      }

      console.log('[Content] Cache cleared successfully!');
      sendResponse({ success: true, message: 'Cache cleared' });
    } catch (error) {
      console.error('[Content] Clear cache error:', error);
      sendResponse({ success: false, error: error.message });
    }
    return true;
  }

  // Ping - ใช้ตรวจสอบว่า content script ทำงานอยู่
  if (message.action === 'ping') {
    console.log('[Content] Ping received - script is active');
    sendResponse({ success: true, pong: true, url: window.location.href });
    return true;
  }

  // v5.8.3: ยกเลิก extend scene เมื่อ timeout
  if (message.action === 'cancelExtendScene') {
    const cancelSetIndex = message.setIndex;
    console.log(`[Extend Scene] Cancel received for setIndex: ${cancelSetIndex}, current: ${extendSceneSetIndex}`);

    // ยกเลิกเฉพาะถ้า setIndex ตรงกัน
    if (extendSceneSetIndex === cancelSetIndex) {
      extendSceneCancelled = true;
      console.log('[Extend Scene] Cancelled! Will skip extend scene for this set.');
      // Clear sessionStorage ด้วย
      sessionStorage.removeItem('extendSceneInProgress');
      sessionStorage.removeItem('extendScenePrompt');
      sessionStorage.removeItem('extendSceneSetIndex');

      // v5.8.3: ลบคลิปที่ค้างใน scene builder (ถ้ามี)
      console.log('[Extend Scene] Trying to delete leftover clips...');
      deleteAllSceneClips().then(result => {
        console.log('[Extend Scene] Delete result:', result);
      }).catch(err => {
        console.log('[Extend Scene] Delete error (may not be in scene builder):', err);
      });
    }
    sendResponse({ success: true });
    return true;
  }

  // v3.5: ดึง Final video ที่ hook เก็บไว้ใน window scope
  if (message.action === 'getFlowFinalVideo') {
    const data = window.__flowFinalVideoData__;
    if (data && data.base64) {
      console.log(`[v3.5] Sending Final video: ${Math.round(data.size / 1024 / 1024 * 10) / 10} MB`);
      sendResponse({ base64: data.base64, size: data.size, filename: data.filename, source: data.source });
      // ล้างหลังส่ง
      window.__flowFinalVideoData__ = null;
    } else {
      sendResponse({ base64: null });
    }
    return true;
  }

  // v4.5 Merge Mode: ping check — orchestrator ใช้ verify content script alive
  if (message.action === 'mergePing') {
    sendResponse({ success: true, version: '4.5.0', timestamp: Date.now() });
    return true;
  }

  // v4.5 Merge Mode: ควบคุม overlay จาก orchestrator (popup) ให้แสดงตลอด
  if (message.action === 'mergeUpdateOverlay') {
    try {
      if (message.hide) {
        if (typeof hideBotOverlay === 'function') hideBotOverlay();
      } else {
        if (typeof showBotOverlay === 'function') {
          showBotOverlay(message.text || 'Merge Mode', message.subtext || '');
        }
      }
    } catch (e) { console.warn('[Merge v4.5] overlay update error:', e.message); }
    sendResponse({ success: true });
    return true;
  }

  // v4.5 Merge Mode: ตั้ง flag skip-download (ISOLATED → MAIN ผ่าน CustomEvent)
  if (message.action === 'setSkipDownload') {
    window.dispatchEvent(new CustomEvent('__flow_skip_download__', {
      detail: { enabled: !!message.enabled }
    }));
    console.log('[Merge v4.5] Skip download flag →', !!message.enabled);
    sendResponse({ success: true });
    return true;
  }

  // v4.5 Merge Mode: ล้าง cached final video ก่อนเริ่มฉากใหม่
  if (message.action === 'clearFlowFinalVideo') {
    window.__flowFinalVideoData__ = null;
    sendResponse({ success: true });
    return true;
  }

  // v4.5.0 Story v2 RESCUE: force download clip ล่าสุดจาก gallery (bypass monitor)
  //   ใช้กรณี createStoryClip_v17 monitor false-fail แต่ clip จริงเสร็จใน Flow gallery
  //   เรียก mergeTriggerLatestClipDownload_v45 ตรงๆ (ของเดิม Auto Merge ใช้) → hook ดักได้
  //   ⚠️ ไม่เปลี่ยน Story v1 (function shared เดิม) — แค่เพิ่ม action ใหม่
  if (message.action === 'mergeForceDownloadLatest') {
    (async () => {
      const { sceneIndex = 0, quality = '720p' } = message.data || {};
      try {
        chrome.runtime.sendMessage({ action: 'cdpAmbientPause' }); // v4.5.7: หยุด ambient ตอน download
        window.__flowFinalVideoData__ = null; // เคลียร์ hook ก่อน
        const ok = await mergeTriggerLatestClipDownload_v45(sceneIndex, quality);
        sendResponse({ success: !!ok });
      } catch (e) {
        sendResponse({ success: false, error: e.message });
      } finally {
        chrome.runtime.sendMessage({ action: 'cdpAmbientResume' });
      }
    })();
    return true;
  }

  // v4.5.7: 🎲 retry วิธีที่ 2 — กดปุ่ม Retry บนกรอบ Failed (humanized) → รอ regen → download/capture
  //   (วิธีที่คน "กดปุ่มรีทายเอง" แล้วผ่าน — ต่างจากวิธีเดิมที่ refresh หน้า + animate ใหม่)
  if (message.action === 'mergeCardRetryAndCapture') {
    (async () => {
      const { sceneIndex = 0, quality = '720p' } = message.data || {};
      try {
        chrome.runtime.sendMessage({ action: 'cdpAmbientPause' }); // v4.5.7: หยุด ambient ตอนกดปุ่ม+download
        const btn = findFailedCardRetryButton();
        if (!btn) { sendResponse({ success: false, error: 'หาปุ่ม Retry บนกรอบ fail ไม่เจอ' }); return; }
        const rect = btn.getBoundingClientRect();
        const cx = Math.round(rect.left + rect.width / 2);
        const cy = Math.round(rect.top + rect.height / 2);
        const baseFailed = (typeof countAllFailedGenerations === 'function') ? countAllFailedGenerations() : 0;
        const baseVideo = (typeof countVideoCards === 'function') ? countVideoCards() : -1;
        window.__flowFinalVideoData__ = null;

        // คลิกแบบ humanized (CDP) — fallback realClick ถ้า CDP พัง
        const clickRes = await new Promise((res) => chrome.runtime.sendMessage({ action: 'cdpHumanClick', x: cx, y: cy }, res));
        if (!clickRes || !clickRes.success) { try { realClick(btn); } catch (_) {} }
        mergeForwardLog('🔁 กดปุ่ม Retry บนกรอบ fail (เหมือนคน) — รอ regen...', 'info');

        // v4.5.7: รอแบบ 2 เฟส — ออกเร็วถ้าเฟลซ้ำ (ไม่รอ 3 นาทีเปล่าๆ เหมือนเดิม)
        //   เฟส 1: รอ card เริ่ม regen (failed ลด) สูงสุด 20s — ไม่เริ่ม = กดไม่ติด/เฟลทันที
        let loadingStarted = false;
        { const t1 = Date.now();
          while (Date.now() - t1 < 20000) {
            await new Promise((r) => setTimeout(r, 2000));
            const nf = (typeof countAllFailedGenerations === 'function') ? countAllFailedGenerations() : 0;
            if (nf < baseFailed) { loadingStarted = true; break; }
          } }
        if (!loadingStarted) { sendResponse({ success: false, error: 'กด Retry แล้วไม่เริ่ม regen (เฟลทันที)' }); return; }

        //   เฟส 2: รอเสร็จ (video เพิ่ม) หรือ เฟลซ้ำ (failed กลับมา) สูงสุด 110s
        let done = false;
        { const t2 = Date.now();
          while (Date.now() - t2 < 110000) {
            await new Promise((r) => setTimeout(r, 3000));
            const nf = (typeof countAllFailedGenerations === 'function') ? countAllFailedGenerations() : 0;
            if (nf >= baseFailed) { sendResponse({ success: false, error: 'กด Retry แล้วเฟลซ้ำ' }); return; } // ออกเร็ว!
            const nv = (typeof countVideoCards === 'function') ? countVideoCards() : -1;
            if (baseVideo >= 0 && nv > baseVideo) { done = true; break; } // มี video ใหม่ = เสร็จ
          } }
        // ถ้านับ video card ไม่ได้ → ถือว่าเสร็จถ้าไม่เฟลซ้ำจนจบ loop
        if (!done && baseVideo < 0) done = true;
        if (!done) { sendResponse({ success: false, error: 'กด Retry แล้วรอ video timeout' }); return; }

        // เสร็จ → download clip ล่าสุด → hook จับ video
        await new Promise((r) => setTimeout(r, 1500));
        const dl = await mergeTriggerLatestClipDownload_v45(sceneIndex, quality);
        sendResponse({ success: !!dl });
      } catch (e) {
        sendResponse({ success: false, error: e.message });
      } finally {
        chrome.runtime.sendMessage({ action: 'cdpAmbientResume' });
      }
    })();
    return true;
  }

  // v4.5 Merge Mode: สร้าง 1 ฉาก (image + animate + รอ video ผ่าน hook)
  if (message.action === 'mergeGenerateScene') {
    (async () => {
      try {
        chrome.runtime.sendMessage({ action: 'cdpAmbientPause' }); // v4.5.7: หยุด ambient ตอนทำงาน UI (กัน download พัง)
        //   🌐 อยู่แอป Flow ใหม่ = เดินเส้นใหม่ (selector คนละชุด) · แอปเก่าเดินเส้นเดิม 100%
        const r = pdIsNewFlow()
          ? await runMergeGenerateSceneNewApp(message.data)
          : await runMergeGenerateScene_v1(message.data);
        sendResponse(r);
      } catch (err) {
        console.error('[Merge v4.5] generateScene error:', err);
        sendResponse({ success: false, error: err.message });
      } finally {
        chrome.runtime.sendMessage({ action: 'cdpAmbientResume' });
      }
    })();
    return true;
  }

  // v3.5: Fetch blob URL แล้วเก็บเป็น base64 ใน chrome.storage.session
  // ใช้สำหรับดึงวิดีโอ extend scene ก่อนหน้า navigate away
  if (message.action === 'fetchBlobAndStore') {
    (async () => {
      try {
        const { blobUrl, setIndex, filename } = message;
        console.log(`[v3.5] Fetching blob: ${blobUrl}`);

        const response = await fetch(blobUrl);
        if (!response.ok) throw new Error(`Fetch failed: ${response.status}`);

        const blob = await response.blob();
        console.log(`[v3.5] Blob fetched: ${blob.size} bytes, type: ${blob.type}`);

        // แปลง blob เป็น base64
        const base64 = await new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve(reader.result);
          reader.onerror = reject;
          reader.readAsDataURL(blob);
        });

        // เก็บใน chrome.storage.session (หายเมื่อปิด browser)
        const storageKey = `extendVideo_set${setIndex}`;
        await chrome.storage.session.set({
          [storageKey]: {
            base64: base64,
            filename: filename,
            size: blob.size,
            type: blob.type,
            setIndex: setIndex,
            timestamp: Date.now()
          }
        });

        console.log(`[v3.5] ✅ Blob stored in session: ${storageKey} (${Math.round(blob.size / 1024 / 1024 * 10) / 10} MB)`);
        sendResponse({ success: true, size: blob.size });
      } catch (err) {
        console.error(`[v3.5] ❌ Blob fetch error:`, err);
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v3.0: Prompt Viewer Auto Gen — ใช้ Animate flow (ดัดแปลงจาก Auto Mode "Video Only")
  // เหตุผลที่ rewrite: flow เก่า v16.3 ใช้ step1-6 แบบ manual ที่พังกับ Google Flow UI ใหม่
  // (step4_HandleCrop ไม่มีจริงแล้ว, step1_SelectMode เป็น no-op)
  // Flow ใหม่: upload base64 เข้า Library → Animate → enter prompt → Generate → monitor
  // อ้างอิง: startAutoVideoCreation() branch data.imageUrl.startsWith('data:') ที่ content.js:9352
  // v3.1: เช็คว่า Upscaling complete หรือยัง (Prompt Viewer save clip)
  if (message.action === 'checkUpscaleComplete') {
    const bodyText = document.body.innerText || '';
    const complete = bodyText.includes('Upscaling complete') || bodyText.includes('Download complete');
    sendResponse({ complete });
    return true;
  }

  if (message.action === 'promptViewerAutoGen') {
    const vPrompt = message.videoPrompt || '';
    console.log('[PromptViewer AutoGen v3.0] Received:', {
      sceneNumber: message.sceneNumber,
      videoModel: message.videoModel,
      aspectRatio: message.aspectRatio,
      hasImage: !!message.imageBase64,
      promptLen: vPrompt.length
    });

    (async () => {
      // ส่ง progress กลับ popup (safe — ไม่ crash ถ้า popup ปิด)
      const pvLog = (text, type = 'info') => {
        try { chrome.runtime.sendMessage({ action: 'promptViewerProgress', text, type }).catch(() => {}); } catch(e) {}
      };

      // เก็บ mode ปัจจุบันไว้คืนให้แม้ error (Prompt Viewer ใช้ shared currentMode กับ Auto Mode)
      const savedMode = currentMode;
      let responded = false;

      try {
        const aspect = message.aspectRatio || '9:16';
        const videoModel = message.videoModel || 'veo_lite_lower'; // Prompt Viewer ใช้ฉากเดียว ไม่ extend → Lite OK
        const fname = `pv-scene-${message.sceneNumber}-${Date.now()}.png`;

        // Data shape เหมือนที่ startAutoVideoCreation() ใช้
        const cfgData = {
          mode: 'image',
          aspectRatio: aspect,
          videoModel: videoModel,
          clipCount: 1,
          imageModel: message.imageModel || 'nano_banana_pro'
        };

        showBotOverlay(`Prompt Viewer Auto Gen`, `เตรียมสร้างคลิปฉากที่ ${message.sceneNumber}...`);
        pvLog(`🚀 v3.0: ใช้ Animate flow (เหมือน Auto Mode คลิปอย่างเดียว)`, 'info');

        // [1/8] ปิด popups/panels ค้าง + สลับ image mode
        pvLog(`[1/8] เตรียม upload รูปเข้า Library...`, 'step');
        updateBotOverlay(`เตรียม upload รูป...`, `ฉาก ${message.sceneNumber}`);
        await closeAnyOpenPanels();
        currentMode = 'image';
        await clickSidebarFilter('images');
        await clickGridViewButton();

        // [2/8] เปิด settings panel โหมด Image + ตั้ง aspect ratio
        pvLog(`[2/8] ตั้งค่า Image mode + ${aspect}...`, 'step');
        await step1_SelectImageMode();
        await step2_ConfigureSettings(cfgData);

        // [3/8] Upload base64 → Library
        pvLog(`[3/8] อัพโหลดรูปฉาก ${message.sceneNumber} เข้า Library...`, 'step');
        updateBotOverlay(`อัพโหลดรูป...`, `ฉาก ${message.sceneNumber}`);
        await step3_UploadImage(message.imageBase64, fname);
        await waitForUploadComplete(15000);
        await delay(2000);

        // [4/8] เช็ค media error (รูปอัพโหลดล้มเหลว)
        await handleFailedMediaCards();

        // คืน mode → video สำหรับ Animate
        currentMode = 'video';

        // [5/8] ปิด settings panel ด้วย chip click (ห้ามใช้ Escape เพราะจะ navigate กลับหน้าหลัก)
        pvLog(`[5/8] ปิด settings panel...`, 'step');
        const settingsChip = findSettingsChip();
        if (settingsChip && settingsChip.getAttribute('data-state') === 'open') {
          realClick(settingsChip);
          await delay(500);
        }
        await delay(1000);

        // [6/8] Animate รูปที่เพิ่ง upload (สลับ Video mode + แนบ Start frame อัตโนมัติ)
        pvLog(`[6/8] Animate รูป (สลับ Video mode + แนบ Start frame)...`, 'step');
        updateBotOverlay(`Animate รูป...`, `ฉาก ${message.sceneNumber}`);
        try {
          await animateGeneratedImage(null);
          await delay(1000);
        } catch (animateError) {
          pvLog(`⚠️ Animate ล้มเหลว: ${animateError.message} — ลอง fallback`, 'warning');
          // Fallback: ตั้ง video mode ผ่าน settings panel
          await step1_SelectMode();
          await step2_ConfigureSettings({ ...cfgData, mode: 'video' });
        }

        // [7/8] กรอก Video Prompt
        pvLog(`[7/8] กรอก Video Prompt...`, 'step');
        updateBotOverlay(`กรอก Prompt...`, `${vPrompt.substring(0, 40)}...`);
        await step5_EnterPrompt(vPrompt);
        await delay(500);

        // [8/8] กด Generate
        pvLog(`[8/8] กด Generate...`, 'step');
        updateBotOverlay(`กด Generate...`, `ฉาก ${message.sceneNumber}`);
        const genOk = await step6_Generate();
        if (!genOk) throw new Error('ไม่พบปุ่ม Generate');
        pvLog(`✅ กด Generate แล้ว — รอสร้างวิดีโอ...`, 'success');

        // ตอบ popup ก่อนเข้า monitor (long-running)
        try { sendResponse({ success: true }); responded = true; } catch(e) {}

        // Monitor ผลลัพธ์ (ใช้ฟังก์ชันเดิม v16.4 ที่ทำงานได้ดี)
        const monitorResult = await monitorPromptViewerVideoProgress(message.sceneNumber);
        hideBotOverlay();
        currentMode = savedMode;

        // ส่งผลกลับ popup (popup จะ log เอง — ไม่ pvLog ซ้ำ)
        if (monitorResult.success) {
          try { chrome.runtime.sendMessage({ action: 'promptViewerResult', success: true, sceneNumber: message.sceneNumber, elapsed: monitorResult.elapsed }).catch(() => {}); } catch(e) {}
        } else {
          try { chrome.runtime.sendMessage({ action: 'promptViewerResult', success: false, sceneNumber: message.sceneNumber, error: monitorResult.error }).catch(() => {}); } catch(e) {}
        }
      } catch (error) {
        console.error('[PromptViewer AutoGen v3.0] Error:', error);
        hideBotOverlay();
        currentMode = savedMode; // คืน mode แม้ error
        pvLog(`❌ Error: ${error.message}`, 'error');
        try { chrome.runtime.sendMessage({ action: 'promptViewerResult', success: false, sceneNumber: message.sceneNumber, error: error.message }).catch(() => {}); } catch(e) {}
        if (!responded) {
          try { sendResponse({ success: false, error: error.message }); } catch(e) {}
        }
      }
    })();

    return true; // async response
  }

  // v3.1: Monitor Prompt Viewer — ใช้ detection เดียวกับ Auto Mode (video cards + failed badges + loading)
  async function monitorPromptViewerVideoProgress(sceneNumber) {
    const maxWaitTime = 200000; // v4.3: 150→200s (เผื่อ Flow ช้าหลัง update)
    const checkInterval = 2000;
    const startTime = Date.now();
    const GRACE_MS = 15000; // 15 วิ grace period
    let noLoadingCount = 0;
    let retryCount = 0;
    const maxRetries = 3; // v3.1: retry 3 ครั้งก่อนยอมแพ้

    // Baselines (เหมือน Auto Mode เป๊ะ)
    const failedBaseline = countAllFailedGenerations();
    const failedBadgeBaseline = typeof countVisibleFailedBadges === 'function' ? countVisibleFailedBadges() : 0;
    const videoCardsBefore = typeof countVideoCards === 'function' ? countVideoCards() : 0;
    const mediaCardsBefore = document.querySelectorAll('.sc-5923b123-0').length;

    // v3.1: เก็บ error message baseline (กัน error เก่าค้างจากรอบก่อน)
    const initialErrorMsg = detectErrorMessage();
    const initialBodyErrors = (document.body.innerText || '').match(/SOMETHING_WENT_WRONG|Something went wrong/g) || [];

    console.log(`[PV Monitor v3.1] Start: scene ${sceneNumber}, videoCards: ${videoCardsBefore}, mediaCards: ${mediaCardsBefore}, failed: ${failedBaseline}, badges: ${failedBadgeBaseline}, initialErrors: ${initialBodyErrors.length}`);

    const pvLog = (text, type = 'info') => {
      try { chrome.runtime.sendMessage({ action: 'promptViewerProgress', text, type }).catch(() => {}); } catch(e) {}
    };

    while (Date.now() - startTime < maxWaitTime) {
      const elapsed = Math.round((Date.now() - startTime) / 1000);
      const gracePassed = elapsed >= (GRACE_MS / 1000);

      // === Early Failed: badge detection (ไม่ต้องรอ grace) ===
      if (typeof countVisibleFailedBadges === 'function') {
        const currentBadges = countVisibleFailedBadges();
        if (currentBadges > failedBadgeBaseline) {
          console.log(`[PV Monitor v3.1] ❌ EARLY FAILED! badges: ${failedBadgeBaseline} → ${currentBadges}`);
          pvLog(`❌ คลิป Failed! (${elapsed}s)`, 'error');
          if (retryCount < maxRetries) {
            retryCount++;
            pvLog(`🔄 Retry ${retryCount}/${maxRetries}...`, 'warning');
            updateBotOverlay(`Failed — Retry ${retryCount}/${maxRetries}...`, `ฉาก ${sceneNumber}`);
            await delay(3000);
            await step6_Generate();
            noLoadingCount = 0;
            continue;
          }
          return { success: false, error: 'Failed Generation', elapsed };
        }
      }

      // === Error message detection (เฉพาะ error ใหม่ ไม่ใช่ค้างจากรอบก่อน) ===
      if (gracePassed) {
        const errorMsg = detectErrorMessage();
        // เช็คว่า error นี้ใหม่จริง (ไม่มีตอนเริ่ม)
        const isNewError = errorMsg && (!initialErrorMsg || errorMsg !== initialErrorMsg);
        // เช็คจำนวน error ใน body เพิ่มขึ้นจาก baseline
        const currentBodyErrors = (document.body.innerText || '').match(/SOMETHING_WENT_WRONG|Something went wrong/g) || [];
        const hasMoreErrors = currentBodyErrors.length > initialBodyErrors.length;

        if (isNewError || hasMoreErrors) {
          const errText = errorMsg || 'Something went wrong';
          console.log(`[PV Monitor v3.1] NEW Error: ${errText} (initial: ${initialBodyErrors.length}, now: ${currentBodyErrors.length})`);
          if (retryCount < maxRetries) {
            retryCount++;
            pvLog(`⚠️ ${errText} — Retry ${retryCount}/${maxRetries}...`, 'warning');
            await delay(3000);
            await step6_Generate();
            noLoadingCount = 0;
            continue;
          }
          return { success: false, error: errText, elapsed };
        }
      }

      // === Failed count detection (หลัง grace) ===
      if (gracePassed) {
        const currentFailed = countAllFailedGenerations();
        const newFailed = currentFailed - failedBaseline;
        if (newFailed > 0) {
          console.log(`[PV Monitor v3.1] ❌ New failed: ${newFailed}`);
          pvLog(`❌ สร้างล้มเหลว! (${elapsed}s)`, 'error');
          if (retryCount < maxRetries) {
            retryCount++;
            pvLog(`🔄 Retry ${retryCount}/${maxRetries}...`, 'warning');
            await delay(3000);
            await step6_Generate();
            noLoadingCount = 0;
            continue;
          }
          return { success: false, error: 'Failed Generation', elapsed };
        }
      }

      // === PRIMARY SIGNAL: video cards + prompt cleared (เหมือน Auto Mode เป๊ะ!) ===
      const currentVideoCards = typeof countVideoCards === 'function' ? countVideoCards() : 0;
      const currentMediaCards = document.querySelectorAll('.sc-5923b123-0').length;
      const newVideoCards = currentVideoCards - videoCardsBefore;
      const newMediaCards = currentMediaCards - mediaCardsBefore;
      const loadingCount = countLoadingIndicators();

      // เช็ค prompt cleared (เหมือน Auto Mode)
      const allTextboxes = document.querySelectorAll('[role="textbox"][contenteditable="true"]');
      let promptEl = null;
      let maxTop = -1;
      for (const tb of allTextboxes) {
        const rect = tb.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0 && rect.top > maxTop) { maxTop = rect.top; promptEl = tb; }
      }
      const promptText = promptEl ? (promptEl.textContent || '').trim() : '';
      const promptCleared = promptText === '' || promptText.includes('What do you want');

      const hasNewContent = newVideoCards > 0 || newMediaCards > 0;

      // Update overlay
      const pct = hasNewContent && promptCleared ? 'เสร็จแล้ว!' : (loadingCount > 0 ? 'กำลังสร้าง...' : 'รอ...');
      updateBotOverlay(`สร้างคลิป (${elapsed}s)`, `ฉาก ${sceneNumber}: ${pct}`);

      if (elapsed > 0 && elapsed % 15 === 0) {
        pvLog(`⏳ ${elapsed}s (videoCards: +${newVideoCards}, media: +${newMediaCards}, prompt: "${promptText.substring(0, 30)}", loading: ${loadingCount})`, 'info');
      }

      // === SUCCESS: ต้องครบ 2 เงื่อนไข (เหมือน Auto Mode) ===
      // 1. prompt cleared (กด Generate แล้ว prompt หาย)
      // 2. loading === 0 (ไม่มี spinner = คลิปเสร็จจริง) หรือ video cards เพิ่ม
      if (gracePassed && promptCleared && (loadingCount === 0 || newVideoCards > 0)) {
        noLoadingCount++;
        if (noLoadingCount >= 3) {
          // เช็คว่าไม่ใช่ Failed card
          const chkFailed = countAllFailedGenerations() - failedBaseline;
          const chkBadges = typeof countVisibleFailedBadges === 'function' ? countVisibleFailedBadges() - failedBadgeBaseline : 0;
          if (chkFailed > 0 || chkBadges > 0) {
            console.log(`[PV Monitor v3.1] ⚠️ New card is FAILED! (${chkFailed}/${chkBadges})`);
            noLoadingCount = 0;
          } else {
            console.log(`[PV Monitor v3.1] ✅✅ COMPLETE! VideoCards +${newVideoCards}, loading: ${loadingCount}, prompt cleared, stable ${noLoadingCount}x, ${elapsed}s`);
            pvLog(`✅ สร้างคลิปเสร็จ! (${elapsed}s)`, 'success');
            return { success: true, elapsed, videoCount: Math.max(newVideoCards, 1) };
          }
        }
      } else {
        noLoadingCount = 0;
      }

      await delay(checkInterval);
    }

    // Final check ก่อน timeout
    const finalVideoCards = typeof countVideoCards === 'function' ? countVideoCards() : 0;
    if (finalVideoCards > videoCardsBefore) {
      const elapsed = Math.round((Date.now() - startTime) / 1000);
      pvLog(`✅ สร้างคลิปเสร็จ! (timeout but found video, ${elapsed}s)`, 'success');
      return { success: true, elapsed };
    }

    return { success: false, error: 'Timeout — ไม่พบวิดีโอใหม่หลัง 2.5 นาที', elapsed: 150 };
  }

  // v8.6.1: Force cleanup Scenebuilder (เรียกจาก popup เมื่อ timeout)
  if (message.action === 'forceCleanupScenebuilder') {
    console.log('[v8.6.1] Force cleanup Scenebuilder received');

    (async () => {
      try {
        // เช็คว่าอยู่ใน Scenebuilder หรือไม่
        if (isInScenebuilderPage()) {
          console.log('[v8.6.1] In Scenebuilder - cleaning up...');
          showBotOverlay('เคลียร์คลิปค้าง...', 'กำลังลบ');

          // ลบคลิปจนหมด
          await deleteAllSceneClipsUntilEmpty();
          console.log('[v8.6.1] Cleanup complete');

          // กลับหน้าหลัก
          const backResult = await goBackToFlow();
          console.log('[v8.6.1] Go back result:', backResult);

          hideBotOverlay();
          sendResponse({ success: true, wasInScenebuilder: true });
        } else {
          console.log('[v8.6.1] Not in Scenebuilder - skipping cleanup');
          sendResponse({ success: true, wasInScenebuilder: false });
        }
      } catch (error) {
        console.error('[v8.6.1] Force cleanup error:', error);
        sendResponse({ success: false, error: error.message });
      }
    })();

    return true; // async response
  }

  // ===== EXTEND SCENE (ต่อฉาก) HANDLERS =====

  // หาปุ่ม + ใน Timeline (Scenebuilder)
  if (message.action === 'findPlusButton') {
    const result = findPlusButtonInTimeline();
    sendResponse(result);
    return true;
  }

  // กดปุ่ม Extend...
  if (message.action === 'clickExtendOption') {
    clickExtendOption().then(result => {
      sendResponse(result);
    });
    return true;
  }

  // v4.4.4 DEV: Test Extend v18 — ทดสอบ flow ใหม่ของ Flow update 2026-05-20
  if (message.action === 'testExtendV18') {
    testExtendV18Flow(message.customPrompt).then(result => {
      sendResponse(result);
    }).catch(err => {
      sendResponse({ success: false, error: err.message });
    });
    return true;
  }

  // กรอก prompt ในช่อง Extend
  if (message.action === 'fillExtendPrompt') {
    fillExtendPromptField(message.prompt).then(result => {
      sendResponse(result);
    });
    return true;
  }

  // v12: กรอก prompt สำหรับ Podcast (Creator Mode)
  if (message.action === 'fillPodcastPrompt') {
    (async () => {
      try {
        console.log('[Podcast] Received fillPodcastPrompt:', message.prompt?.substring(0, 50));

        // เก็บ scene2Script ไว้ใช้ต่อฉาก 2
        if (message.scene2Script) {
          window.podcastScene2Script = message.scene2Script;
          console.log('[Podcast] Saved scene2Script for later use');
        }

        // หา textarea ของ prompt (หน้า create)
        const promptField = document.querySelector('textarea[placeholder*="Describe"], textarea[placeholder*="prompt"], textarea.prompt-input');

        if (promptField) {
          // กรอก prompt
          promptField.value = message.prompt;
          promptField.dispatchEvent(new Event('input', { bubbles: true }));
          promptField.dispatchEvent(new Event('change', { bubbles: true }));

          // ถ้ามีรูปตัวละคร ให้อัพโหลด (TODO: implement later)
          if (message.characterImage) {
            console.log('[Podcast] Character image provided - manual upload required');
          }

          sendResponse({ success: true, message: 'Prompt filled successfully' });
        } else {
          // ลองหา textarea ทั่วไป
          const textareas = document.querySelectorAll('textarea');
          if (textareas.length > 0) {
            textareas[0].value = message.prompt;
            textareas[0].dispatchEvent(new Event('input', { bubbles: true }));
            sendResponse({ success: true, message: 'Prompt filled in first textarea' });
          } else {
            sendResponse({ success: false, error: 'ไม่พบช่อง prompt - กรุณาเปิดหน้า Create' });
          }
        }
      } catch (error) {
        console.error('[Podcast] Error:', error);
        sendResponse({ success: false, error: error.message });
      }
    })();
    return true;
  }

  // กดปุ่ม "Add to scene" บนคลิปที่สร้างเสร็จ
  // v8.7.1: ตรวจสอบ failed ก่อนเลือกคลิป
  if (message.action === 'clickAddToScene') {
    (async () => {
      try {
        // ถ้าไม่ได้ระบุ index มา หรือระบุ 0 ให้หาคลิปที่ใช้ได้อัตโนมัติ
        let targetIndex = message.index;
        if (targetIndex === undefined || targetIndex === 0) {
          const usableClip = findFirstUsableClipIndex();
          if (usableClip.hasUsable && usableClip.index >= 0) {
            targetIndex = usableClip.index;
            console.log(`[clickAddToScene] Auto-selected usable clip at index ${targetIndex}`);
          } else {
            targetIndex = 0; // fallback
          }
        }
        const result = await clickAddToSceneButton(targetIndex);
        sendResponse(result);
      } catch (err) {
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // ไปหน้า Scenebuilder
  if (message.action === 'goToScenebuilder') {
    goToScenebuilderPage().then(result => {
      sendResponse(result);
    });
    return true;
  }

  // กดปุ่ม + และเลือก Extend (รวม 2 ขั้นตอน)
  if (message.action === 'clickExtend') {
    clickPlusAndExtend().then(result => {
      sendResponse(result);
    });
    return true;
  }

  // กดปุ่ม Generate ใน Extend form
  if (message.action === 'clickExtendGenerate') {
    clickExtendGenerateButton().then(result => {
      sendResponse(result);
    });
    return true;
  }

  // v13: ต่อฉาก 3+ สำหรับ Podcast (ต้องคลิกฉากก่อนหน้าก่อน + รอให้เสร็จ)
  if (message.action === 'extendPodcastScene') {
    (async () => {
      try {
        const currentScene = message.currentScene; // ฉากปัจจุบัน (2, 3, 4, ...)
        const targetScene = message.targetScene; // ฉากที่จะต่อ (3, 4, 5, ...)
        const prompt = message.prompt;

        console.log(`[Podcast Scene ${targetScene}] Starting extend from scene ${currentScene}...`);
        showBotOverlay(`ต่อฉาก ${targetScene}`, 'กำลังเตรียม...');

        // Step 0: คลิกฉากที่อยู่ก่อนปุ่ม + (ฉากสุดท้าย)
        updateBotOverlay(`ต่อฉาก ${targetScene}`, 'คลิกฉากสุดท้าย...');
        const clickResult = await clickSceneBeforePlusButton();
        if (clickResult.success) {
          console.log(`[Podcast] Clicked scene before + button`);
        } else {
          console.log(`[Podcast] Could not click scene, continuing anyway: ${clickResult.error}`);
        }
        await new Promise(r => setTimeout(r, 1000));

        // Step 1: กดปุ่ม + และเลือก Extend
        updateBotOverlay(`ต่อฉาก ${targetScene}`, 'กดปุ่ม +...');
        const extendResult = await clickPlusAndExtend();
        if (!extendResult.success) {
          throw new Error(`ไม่สามารถกด Extend: ${extendResult.error}`);
        }
        console.log(`[Podcast] Clicked + and Extend`);
        await new Promise(r => setTimeout(r, 2000));

        // Step 2: กรอก prompt
        updateBotOverlay(`ต่อฉาก ${targetScene}`, 'กรอก prompt...');
        const fillResult = await fillExtendPromptField(prompt);
        if (!fillResult.success) {
          throw new Error(`ไม่สามารถกรอก prompt: ${fillResult.error}`);
        }
        console.log(`[Podcast] Filled prompt`);
        await new Promise(r => setTimeout(r, 1000));

        // Step 3: กด Generate
        updateBotOverlay(`ต่อฉาก ${targetScene}`, 'กด Generate...');
        const genResult = await clickExtendGenerateButton();
        if (!genResult.success) {
          throw new Error(`ไม่สามารถกด Generate: ${genResult.error}`);
        }

        console.log(`[Podcast] Scene ${targetScene} extend started, waiting for completion...`);

        // v13: รอให้ฉากสร้างเสร็จ (ใช้ logic เดียวกับ Creator Mode)
        updateBotOverlay(`ต่อฉาก ${targetScene}`, 'รอสร้างเสร็จ...');
        const expectedDuration = calculateExpectedDuration(targetScene);
        const waitResult = await waitForPodcastSceneComplete(targetScene, expectedDuration);

        if (waitResult.success) {
          console.log(`[Podcast] Scene ${targetScene} completed!`);
          hideBotOverlay();

          // ส่ง message กลับไป popup.js บอกว่าฉากเสร็จแล้ว
          chrome.runtime.sendMessage({
            action: 'autoVideoComplete',
            extended: true,
            extendedToScene: targetScene
          });

          sendResponse({ success: true, sceneCompleted: targetScene });
        } else {
          console.error(`[Podcast] Scene ${targetScene} failed:`, waitResult.error);
          hideBotOverlay();

          // v13.1: ส่ง error กลับ พร้อม flag wasStuckAt99 ถ้ามี
          chrome.runtime.sendMessage({
            action: 'autoVideoComplete',
            extended: true,
            extendedToScene: targetScene,
            error: waitResult.error,
            wasStuckAt99: waitResult.wasStuckAt99 || false // v13.1: flag สำหรับ refresh ก่อน retry
          });

          sendResponse({ success: false, error: waitResult.error, wasStuckAt99: waitResult.wasStuckAt99 });
        }

      } catch (err) {
        console.error('[Podcast Scene Extend] Error:', err);
        hideBotOverlay();

        // v13: ส่ง error กลับไป popup.js ด้วย (ไม่ใช่แค่ sendResponse)
        chrome.runtime.sendMessage({
          action: 'autoVideoComplete',
          extended: true,
          extendedToScene: message.targetScene,
          error: err.message
        });

        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v12: Creator Mode - Multi-Scene Extension (ต่อฉาก 3+)
  if (message.action === 'creatorMultiSceneExtend') {
    (async () => {
      try {
        const result = await runCreatorMultiSceneExtend({
          currentSceneCount: message.currentSceneCount,
          targetSceneCount: message.targetSceneCount,
          prompt: message.prompt,
          maxRetries: message.maxRetries || 3
        });
        sendResponse(result);
      } catch (err) {
        console.error('[Creator Multi-Scene] Error:', err);
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v12: Creator Mode - Get current scene info (duration, scene count)
  if (message.action === 'getCreatorSceneInfo') {
    const duration = getSceneVideoDuration();
    const sceneCount = calculateSceneCountFromDuration(duration);
    const hasLoading = hasSceneLoading();
    sendResponse({
      duration,
      sceneCount,
      hasLoading,
      isInScenebuilder: isInScenebuilderPage()
    });
    return true;
  }

  // v12: Creator Mode - Export และ Download (retry 5 ครั้ง)
  if (message.action === 'creatorExportAndDownload') {
    (async () => {
      try {
        const result = await runCreatorExportAndDownload();
        sendResponse(result);
      } catch (err) {
        console.error('[Creator Export] Error:', err);
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v13.2: Clear usedImageUrls (ป้องกันรูปซ้ำจาก session ก่อน)
  if (message.action === 'clearUsedImageUrls') {
    (async () => {
      await clearUsedImageUrls();
      console.log('[Podcast v13.2] Cleared usedImageUrls for new session');
      sendResponse({ success: true });
    })();
    return true;
  }

  // v13: Clear Podcast scene config from sessionStorage
  if (message.action === 'clearPodcastSceneConfig') {
    sessionStorage.removeItem('podcastSceneCount');
    sessionStorage.removeItem('podcastScenes');
    sessionStorage.removeItem('isPodcastMode');
    console.log('[Podcast v13] Cleared scene config from sessionStorage');
    sendResponse({ success: true });
    return true;
  }

  // ===============================================
  // v14: STORY MODE ACTIONS
  // ===============================================

  // v14: สร้างรูปสำหรับ Story Scene (v15: รองรับ reference images)
  if (message.action === 'createStoryImage') {
    // v14 fix: ตอบ popup ทันทีว่าเริ่มทำงานแล้ว
    sendResponse({ started: true, sceneNumber: message.sceneNumber });

    // v17: set currentMode ก่อนเรียก function (safety)
    currentMode = 'image';

    (async () => {
      try {
        // v17.3: ไม่เช็ค checkPageHealth() ตรงนี้ — ให้ createStorySceneImage catch block จัดการ
        // เพราะต้องรอ 60 วินาทีให้ backend เสร็จก่อน reload (ไม่ใช่ fail ทันที)

        console.log(`[Story v14] Creating image for scene ${message.sceneNumber}...`);
        console.log(`[Story v14] Image Prompt: ${message.imagePrompt?.substring(0, 100)}...`);
        // v15: Log reference images
        if (message.referenceImages && message.referenceImages.length > 0) {
          console.log(`[Story v15] With ${message.referenceImages.length} reference images`);
        }

        // เรียกใช้ function สร้างรูป (v15: ส่ง referenceImages ไปด้วย)
        // v4.6.1: ส่งต่อ options (เช่น attachPreviousSceneRef:false ตอนใช้ character anchor)
        //   ไม่ส่งมา → {} → default เดิมทุกอย่าง (attachPreviousSceneRef = true)
        const result = await createStorySceneImage(
          message.imagePrompt,
          message.aspectRatio || '9:16',
          message.sceneNumber,
          message.referenceImages || [], // v15: reference images
          message.imageModel || 'nano_banana_pro', // v17.4: image model
          message.options || {}
        );

        // v14 fix: เก็บ result ไว้ใน storage (เพราะ sendResponse อาจ disconnect แล้ว)
        const storageKey = `storyImageResult_${message.sceneNumber}`;
        await chrome.storage.local.set({ [storageKey]: result });

        console.log(`[Story v14] 📤 Result saved to storage:`, {
          key: storageKey,
          success: result?.success,
          hasImageUrl: !!result?.imageUrl,
          hasBase64: !!result?.imageBase64,
          base64Length: result?.imageBase64?.length || 0
        });

        // ส่ง message ไป popup ว่าเสร็จแล้ว (ผ่าน runtime)
        try {
          chrome.runtime.sendMessage({
            action: 'storyImageComplete',
            sceneNumber: message.sceneNumber,
            success: result?.success,
            imageUrl: result?.imageUrl,
            imageBase64: result?.imageBase64
          });
          console.log(`[Story v14] ✅ Notified popup via runtime.sendMessage`);
        } catch (e) {
          console.log(`[Story v14] Could not notify popup:`, e.message);
        }

      } catch (err) {
        console.error('[Story v14] Create image error:', err);
        const storageKey = `storyImageResult_${message.sceneNumber}`;
        await chrome.storage.local.set({ [storageKey]: { success: false, error: err.message } });
      }
    })();
    return true;
  }

  // =====================================================
  // v17.2: ตรวจสอบว่า editor พร้อมหรือยัง (หลังกด New Project)
  // ใช้ได้ทั้ง Auto Mode + Story Mode — เช็คว่าช่อง prompt ปรากฏแล้ว
  // =====================================================
  if (message.action === 'checkEditorReady') {
    const promptInput = document.querySelector('div[role="textbox"][contenteditable="true"]');
    const isReady = !!promptInput;
    console.log(`[v17.2] checkEditorReady: ${isReady ? 'READY' : 'NOT READY'}`);
    sendResponse({ ready: isReady });
    return true;
  }

  // =====================================================
  // v17.3: เช็ครูปหลัง reload (กรณีหน้าแสดงผลพังแต่ backend สร้างรูปสำเร็จ)
  // =====================================================
  if (message.action === 'checkStoryImageAfterReload') {
    (async () => {
      try {
        const previousCount = message.previousImageCount || 0;

        // วิธี 1: findGeneratedImagesDirectly (เดิม)
        let currentImages = findGeneratedImagesDirectly();
        console.log(`[Story v17.3] checkAfterReload: Method1 findGeneratedImagesDirectly=${currentImages.length}, previous=${previousCount}`);

        // วิธี 2: หาจาก media cards (.sc-5923b123-0)
        if (currentImages.length === 0) {
          const mediaCards = document.querySelectorAll('.sc-5923b123-0');
          console.log(`[Story v17.3] checkAfterReload: Method2 mediaCards=${mediaCards.length}`);
          for (const card of mediaCards) {
            const img = card.querySelector('img');
            if (img && img.src) {
              const altText = (img.getAttribute('alt') || '').toLowerCase();
              if (!altText.includes('video thumbnail')) {
                currentImages.push(img);
              }
            }
          }
        }

        // วิธี 3: หาจาก img ขนาดใหญ่ในหน้า (ครอบคลุมที่สุด)
        if (currentImages.length === 0) {
          const allImgs = document.querySelectorAll('img');
          for (const img of allImgs) {
            if (!img.src || img.src.startsWith('data:') || img.src.includes('icon')) continue;
            const rect = img.getBoundingClientRect();
            if (rect.width >= 80 && rect.height >= 80 && rect.top < window.innerHeight * 0.85) {
              currentImages.push(img);
            }
          }
          console.log(`[Story v17.3] checkAfterReload: Method3 largeImages=${currentImages.length}`);
        }

        const currentCount = currentImages.length;

        if (currentCount > previousCount && currentImages.length > 0) {
          // มีรูปใหม่! ดึง base64 ด้วย
          const latestImage = currentImages[currentImages.length - 1];
          console.log(`[Story v17.3] IMAGE_FOUND! src=${latestImage.src?.substring(0, 80)}`);
          let imageBase64 = null;
          try {
            imageBase64 = await convertImageToBase64(latestImage);
          } catch (e) {
            console.log('[Story v17.3] Could not convert to base64:', e.message);
          }
          sendResponse({
            status: 'IMAGE_FOUND',
            imageUrl: latestImage.src,
            imageBase64: imageBase64,
            currentCount: currentCount
          });
          return;
        }

        // เช็ค 2: มี loading indicator ไหม? (ยังสร้างอยู่)
        const loadingCount = countLoadingIndicators();
        if (loadingCount > 0) {
          console.log(`[Story v17.3] checkAfterReload: Still loading (${loadingCount} indicators)`);
          sendResponse({
            status: 'STILL_LOADING',
            loadingCount: loadingCount,
            currentCount: currentCount
          });
          return;
        }

        // ไม่มีรูปใหม่ ไม่มี loading
        console.log(`[Story v17.3] checkAfterReload: NO_IMAGE found (count=${currentCount}, previous=${previousCount})`);
        sendResponse({
          status: 'NO_IMAGE',
          currentCount: currentCount
        });
      } catch (err) {
        sendResponse({ status: 'ERROR', error: err.message });
      }
    })();
    return true;
  }

  // =====================================================
  // v17: Story Mode — Animate on Main Page (NEW handlers)
  // =====================================================

  // v17: สร้างคลิป Story ด้วย Animate บนหน้าหลัก
  if (message.action === 'createStoryClip_v17') {
    sendResponse({ started: true });
    (async () => {
      try {
        const result = await createStoryClip_v17(message);
        chrome.storage.local.set({
          [`storyClipResult_${message.sceneNumber}`]: result
        });
        try {
          chrome.runtime.sendMessage({
            action: 'storyClipComplete',
            ...result
          });
        } catch (e) {
          console.log(`[Story v17] Could not notify popup:`, e.message);
        }
      } catch (err) {
        console.error(`[Story v17] createStoryClip_v17 handler error:`, err);
        chrome.storage.local.set({
          [`storyClipResult_${message.sceneNumber}`]: { success: false, error: err.message }
        });
      }
    })();
    return true;
  }

  // v2.1: Story Mode — เริ่มต่อฉากด้วย Extend (ใช้ระบบเดียวกับ Auto Mode)
  // v2.3: กลับหน้า Flow หลัก
  if (message.action === 'navigateToFlowMain') {
    console.log('[v2.3] 🏠 Navigating back to Flow main page...');
    hideBotOverlay();
    try { sessionStorage.removeItem('pdFootageOverlayActive'); } catch (e) {}
    setTimeout(() => {
      window.location.href = 'https://labs.google/fx/tools/flow';
    }, 500);
    sendResponse({ ok: true });
    return true;
  }

  // v4.5.2: ลบ Flow project ผ่าน API (port จาก dev branch — verified 2026-05-26)
  //   ใช้คู่กับ UI checkbox "🗑️ ลบโปรเจคหลังบอททำเสร็จ" ใน Auto Mode
  if (message.action === 'deleteFlowProject') {
    (async () => {
      try {
        const projectId = message.projectId;
        if (!projectId) {
          sendResponse({ success: false, error: 'No projectId provided' });
          return;
        }
        console.log('[v4.5.2 DeleteProject] 🗑️ Deleting project:', projectId);
        const result = await callFlowAPI('deleteProject', projectId);
        console.log('[v4.5.2 DeleteProject] ✅ Delete success:', result);
        sendResponse({ success: true, result });
      } catch (e) {
        console.error('[v4.5.2 DeleteProject] ❌ Delete failed:', e);
        sendResponse({ success: false, error: e.message || String(e) });
      }
    })();
    return true; // async response
  }

  // v2.2: อัพเดต overlay progress จาก popup
  if (message.action === 'updateOverlayProgress') {
    const { current, total, setName, loopInfo } = message;
    updateBotProgress(current, total, `📦 ${setName} (${current}/${total}) ${loopInfo}`);
    // คำนวณ ETA (ประมาณจากเวลาเฉลี่ย)
    if (!window._pipelineStartTime) window._pipelineStartTime = Date.now();
    if (current > 1) {
      const elapsed = (Date.now() - window._pipelineStartTime) / 1000;
      const avgPerSet = elapsed / (current - 1);
      const remaining = Math.round(avgPerSet * (total - current + 1));
      const mins = Math.floor(remaining / 60);
      const secs = remaining % 60;
      updateBotETA(`⏱️ เหลือประมาณ ${mins > 0 ? mins + ' นาที ' : ''}${secs} วินาที`);
    }
    sendResponse({ ok: true });
    return true;
  }

  if (message.action === 'startStoryExtendScene') {
    sendResponse({ started: true });
    console.log(`[Story v2.1] startStoryExtendScene: scenes=${message.scenes?.length}, sceneCount=${message.sceneCount}`);

    // Set extend variables (เหมือน Auto Mode)
    extendSceneEnabled = true;
    extendScenePrompt = message.scenes?.[0] || '';
    extendSceneSetIndex = -1; // Story Mode ไม่มี setIndex
    extendSceneCancelled = false;
    window._extendScenesList = message.scenes || [];
    window._extendSceneCount = message.sceneCount || 2;
    window._extendVideoModel = message.videoModel || 'veo_lite_lower'; // v4.3.2: Flow ถอด Fast Lower — Lite Lower ต่อฉากได้แล้ว

    // เริ่ม Extend (รอ 3 วินาทีให้ DOM พร้อม)
    setTimeout(() => {
      runExtendSceneInContentScript();
    }, 3000);
    return true;
  }

  // v17: เพิ่มคลิปล่าสุดลง Scene
  if (message.action === 'addStoryClipToScene_v17') {
    (async () => {
      try {
        const result = await addLatestClipToScene_v17();
        sendResponse(result);
      } catch (err) {
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v17: Navigate ไปหน้า Scene page
  if (message.action === 'navigateToScenePage_v17') {
    (async () => {
      try {
        const result = await navigateToScenePage_v17();
        sendResponse(result);
      } catch (err) {
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v14: สร้างวิดีโอสำหรับ Story Scene (Frames to Video mode) (OLD)
  if (message.action === 'createStoryVideo') {
    (async () => {
      try {
        console.log(`[Story v14] Creating video for scene ${message.sceneNumber}...`);
        console.log(`[Story v14] Video Prompt: ${message.videoPrompt?.substring(0, 100)}...`);
        console.log(`[Story v14] Mode: ${message.mode}`);

        // เรียกใช้ function สร้างวิดีโอ (Frames to Video)
        const result = await createStorySceneVideo(
          message.videoPrompt,
          message.sceneNumber,
          message.mode || 'frames_to_video',
          message.videoModel || 'veo_lite_lower'
        );

        sendResponse(result);
      } catch (err) {
        console.error('[Story v14] Create video error:', err);
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v14: สร้างวิดีโอใน Scene Builder (Frames to Video mode)
  if (message.action === 'createStoryVideoInSceneBuilder') {
    (async () => {
      try {
        console.log(`[Story v14] Creating video in Scene Builder for scene ${message.sceneNumber}...`);
        console.log(`[Story v14] Scene Index: ${message.sceneIndex}`);
        console.log(`[Story v14] Video Prompt: ${message.videoPrompt?.substring(0, 100)}...`);
        console.log(`[Story v14] Has imageBase64: ${!!message.imageBase64}`);

        // เรียกใช้ function สร้างวิดีโอใน Scene Builder
        const result = await createStoryVideoInSceneBuilder(
          message.videoPrompt,
          message.sceneNumber,
          message.sceneIndex,
          message.aspectRatio,
          message.imageUrl,
          message.imageBase64, // v14: รับ base64 มาด้วย
          message.videoModel || 'veo_lite_lower'
        );

        sendResponse(result);
      } catch (err) {
        console.error('[Story v14] Create video in Scene Builder error:', err);
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // ===============================================
  // END v14: STORY MODE ACTIONS
  // ===============================================

  // v13: ทดสอบคลิกฉากก่อนปุ่ม + (Debug)
  if (message.action === 'testClickSceneBeforePlus') {
    (async () => {
      try {
        console.log('='.repeat(50));
        console.log('🧪 [Test] Starting clickSceneBeforePlusButton test...');
        console.log('='.repeat(50));

        const result = await clickSceneBeforePlusButton();

        console.log('='.repeat(50));
        console.log('🧪 [Test] Result:', result);
        console.log('='.repeat(50));

        sendResponse(result);
      } catch (err) {
        console.error('[Test Click Scene] Error:', err);
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v12: Creator Mode - Full Pipeline (สร้างทุกฉาก + Export + Download)
  if (message.action === 'creatorFullPipeline') {
    (async () => {
      try {
        const result = await runCreatorFullPipeline({
          targetSceneCount: message.targetSceneCount,
          prompts: message.prompts,
          startFromScene: message.startFromScene || 2
        });
        sendResponse(result);
      } catch (err) {
        console.error('[Creator Pipeline] Error:', err);
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // ===== POST EXTEND SCENE HANDLERS =====

  // กดปุ่ม Export (รวมคลิป)
  if (message.action === 'clickExport') {
    clickExportButton().then(result => {
      sendResponse(result);
    });
    return true;
  }

  // รอ Export เสร็จ
  if (message.action === 'waitExportComplete') {
    waitForExportComplete(message.timeout || 120000).then(result => {
      sendResponse(result);
    });
    return true;
  }

  // v11.0: ปิด popup "Export failed!" หรือ "Video exported!"
  if (message.action === 'dismissExportPopup') {
    console.log('🔄 Dismissing export popup...');
    // พยายามกดปุ่ม Dismiss หรือ Close
    const dismissBtn = Array.from(document.querySelectorAll('button, span, div')).find(el => {
      const text = (el.textContent || '').toLowerCase().trim();
      return text === 'dismiss' || text === 'close' || text === 'ปิด';
    });
    if (dismissBtn) {
      dismissBtn.click();
      console.log('✅ Clicked Dismiss button');
      sendResponse({ success: true, message: 'Dismissed popup' });
    } else {
      // ลองคลิกที่พื้นที่ว่าง
      document.body.click();
      console.log('⚠️ Dismiss button not found, clicked body');
      sendResponse({ success: true, message: 'Clicked body to dismiss' });
    }
    return true;
  }

  // กด Download link
  if (message.action === 'clickDownload') {
    clickDownloadLink().then(result => {
      sendResponse(result);
    });
    return true;
  }

  // เปิด Scene menu (3 ขีด)
  if (message.action === 'openSceneMenu') {
    openSceneMenu().then(result => {
      sendResponse(result);
    });
    return true;
  }

  // ลบคลิปทั้งหมด
  if (message.action === 'deleteAllClips') {
    deleteAllSceneClips().then(result => {
      sendResponse(result);
    });
    return true;
  }

  // กลับไปหน้าเดิม
  if (message.action === 'goBackToFlow') {
    goBackToFlow().then(result => {
      sendResponse(result);
    });
    return true;
  }

  // ===== REFRESH & FAILED DETECTION HANDLERS =====

  // v13.1: ดึงค่า duration ของ scene ปัจจุบัน (สำหรับเช็ค 99% stuck)
  if (message.action === 'getSceneDuration') {
    const duration = getSceneVideoDuration();
    const totalSeconds = getTotalSecondsInScenebuilder();
    console.log(`[Flow] getSceneDuration: ${duration}s | total: ${totalSeconds}s`);
    sendResponse({ duration, totalSeconds });
    return true;
  }

  // รีเฟรชหน้าเว็บ
  if (message.action === 'refreshPage') {
    console.log('[Flow] Refreshing page...');
    sendResponse({ success: true, message: 'Refreshing...' });
    setTimeout(() => {
      window.location.reload();
    }, 100);
    return true;
  }

  // === v6.8: ตรวจจับและ cleanup หน้า Scenebuilder ก่อนเริ่มชุดใหม่ ===
  if (message.action === 'checkAndCleanupScenebuilder') {
    const isInScenebuilder = isInScenebuilderPage();
    console.log(`[Flow] Checking Scenebuilder page: ${isInScenebuilder}`);

    if (isInScenebuilder) {
      console.log('[Flow] พบว่าค้างอยู่ใน Scenebuilder - กำลัง cleanup...');
      // ทำ cleanup และรอให้เสร็จก่อน sendResponse
      cleanupScenebuilderAndGoBack().then((result) => {
        console.log('[Flow] Cleanup Scenebuilder เสร็จสิ้น:', result);
        sendResponse({ wasInScenebuilder: true, cleanupDone: true, result: result });
      }).catch(err => {
        console.error('[Flow] Cleanup Scenebuilder error:', err);
        sendResponse({ wasInScenebuilder: true, cleanupDone: false, error: err.message });
      });
      // return true เพื่อบอกว่าจะ sendResponse แบบ async
      return true;
    } else {
      sendResponse({ wasInScenebuilder: false });
    }
    return true;
  }

  // v17.2: สร้าง New Project (popup.js navigate มาหน้า Flow แล้ว + refresh แล้ว)
  if (message.action === 'startNewProject') {
    (async () => {
      try {
        console.log('[Flow v17.2] Starting new project...');
        /* 🌐 แอปใหม่ไม่มีปุ่ม New project แบบเดิม → สร้างผ่าน API แล้วเด้งเข้าโปรเจ็คนั้น */
        if (pdIsNewFlow()) {
          const pjNew = await callFlowAPI('createProject');
          const pidNew = pjNew && (pjNew.projectId || pjNew.id);
          if (!pidNew) throw new Error('สร้างโปรเจ็คใหม่ (Flow แบบใหม่) ไม่สำเร็จ');
          sendResponse({ ok: true, success: true, projectId: pidNew, newApp: true });
          setTimeout(() => { window.location.href = 'https://flow.google.com/project/' + pidNew; }, 400);
          return;
        }
        showBotOverlay('กำลังสร้างโปรเจ็คใหม่...', 'หาปุ่ม New project');

        // v17.2: หาปุ่ม New project ทันที (popup.js navigate + refresh มาแล้ว)
        // ลองหาทันทีก่อน → ถ้าไม่เจอ ลอง poll รอ 15 วินาที
        let newProjectBtn = findNewProjectButton();

        if (newProjectBtn) {
          console.log('[Flow v17.2] Found New project button immediately!');
        } else {
          // ยังไม่เจอ → poll รอจนเจอ (หน้าอาจยังโหลดไม่เสร็จ)
          console.log('[Flow v17.2] Button not found yet, polling...');
          updateBotOverlay('รอปุ่ม New project...', 'หน้ากำลังโหลด');

          const maxWait = 60000; // v1.1.2: เพิ่มจาก 20s → 60s (รองรับคอมช้า — มี early break)
          const startTime = Date.now();

          while (Date.now() - startTime < maxWait) {
            await delay(500); // v17.4: เช็คทุก 0.5s แทน 1s (เจอเร็วขึ้น)
            newProjectBtn = findNewProjectButton();
            if (newProjectBtn) {
              console.log('[Flow v17.2] Found New project button after polling!');
              break;
            }
            const elapsed = Math.floor((Date.now() - startTime) / 1000);
            if (elapsed % 2 === 0) { // อัพเดต overlay ทุก 2 วิ
              updateBotOverlay(`รอปุ่ม New project... ${elapsed}s`, 'หน้ากำลังโหลด');
            }
          }
        }

        if (!newProjectBtn) {
          // Fallback: ลองหา Flow link แล้ว navigate (กรณีอยู่หน้าอื่น)
          console.log('[Flow v17.2] Button not found, trying Flow link fallback...');
          const flowBtn = document.querySelector('a[href="/fx/tools/flow"], a[href*="/flow"]');
          if (flowBtn) {
            flowBtn.click();
            await delay(3000);
            newProjectBtn = findNewProjectButton();
          }
          if (!newProjectBtn) {
            // ลองหาจากข้อความ
            const allLinks = document.querySelectorAll('a');
            for (const link of allLinks) {
              if (link.textContent?.trim() === 'Flow') {
                link.click();
                await delay(3000);
                newProjectBtn = findNewProjectButton();
                break;
              }
            }
          }
        }

        if (!newProjectBtn) {
          throw new Error('ไม่พบปุ่ม New project');
        }

        // กดปุ่ม New project
        console.log('[Flow v17.2] Clicking New project button...');
        updateBotOverlay('กดปุ่ม New project...', 'สร้างโปรเจ็คใหม่');
        await delay(500);
        realClick(newProjectBtn);

        // รอให้หน้าพร้อม
        await delay(3000);

        // v4.5.9: ปิด Flow AI Agent ที่อาจเปิดมาเอง (ครอบทุกโหมด) ก่อนเริ่มทำงาน
        updateBotOverlay('ตรวจสอบโปรเจ็ค...', 'เตรียมเริ่มทำงาน');
        await ensureFlowAgentDisabled();

        hideBotOverlay();
        console.log('[Flow v17.2] ✅ New project created successfully!');
        sendResponse({ success: true, message: 'New project created' });

      } catch (err) {
        console.error('[Flow v17.2] Error creating new project:', err);
        hideBotOverlay();
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v14.5.2: ตรวจสอบว่าอยู่หน้า Flow หลัก (ยังไม่ได้เข้าโปรเจ็ค) และกด New project อัตโนมัติ
  if (message.action === 'checkAndCreateNewProject') {
    (async () => {
      try {
        console.log('[Flow v14.5.2] Checking if on main Flow page (no project)...');

        // ตรวจสอบว่าอยู่หน้า Flow หลักหรือไม่ (URL pattern: /fx/tools/flow หรือ /flow ไม่มี project ID)
        const currentUrl = window.location.href;
        const isMainFlowPage = currentUrl.match(/\/fx\/tools\/flow\/?$/) ||
                               currentUrl.match(/\/flow\/?$/) ||
                               (currentUrl.includes('/flow') && !currentUrl.includes('/scenes/'));

        // หาปุ่ม New project
        let newProjectBtn = null;
        const allBtns = document.querySelectorAll('button');
        for (const btn of allBtns) {
          const text = btn.textContent || '';
          if (text.includes('New project') || text.includes('add_2')) {
            newProjectBtn = btn;
            break;
          }
        }

        // ถ้าเจอปุ่ม New project = อยู่หน้า Flow หลัก ยังไม่ได้เข้าโปรเจ็ค
        if (newProjectBtn) {
          console.log('[Flow v14.5.2] Found New project button - on main Flow page!');
          showBotOverlay('สร้างโปรเจ็คใหม่...', 'เตรียมเริ่มทำงาน');

          await delay(500);
          newProjectBtn.click();
          console.log('[Flow v14.5.2] Clicked New project button');

          // รอให้หน้าโปรเจ็คโหลด
          await delay(4000);

          // v4.5.9: ปิด Flow AI Agent ที่อาจเปิดมาเอง (ครอบทุกโหมด)
          await ensureFlowAgentDisabled();

          hideBotOverlay();
          console.log('[Flow v14.5.2] ✅ New project created!');
          sendResponse({ success: true, createdNewProject: true, message: 'สร้างโปรเจ็คใหม่แล้ว' });
        } else {
          // ไม่เจอปุ่ม New project = อาจอยู่ในโปรเจ็คแล้ว หรืออยู่หน้าอื่น
          console.log('[Flow v14.5.2] No New project button found - already in a project or different page');
          sendResponse({ success: true, createdNewProject: false, message: 'อยู่ในโปรเจ็คแล้ว' });
        }

      } catch (err) {
        console.error('[Flow v14.5.2] Error:', err);
        sendResponse({ success: false, error: err.message });
      }
    })();
    return true;
  }

  // v15.2: ตรวจสอบและเตรียมโปรเจ็คใหม่สำหรับ Story Mode
  // - ถ้าอยู่ในโปรเจ็คที่มีรูป/คลิปอยู่แล้ว → กลับไปหน้า Flow หลัก → สร้างโปรเจ็คใหม่
  // - ถ้าอยู่หน้า Flow หลัก → สร้างโปรเจ็คใหม่
  // - ถ้าอยู่ในโปรเจ็คเปล่า → พร้อมใช้งาน
  if (message.action === 'ensureCleanProject') {
    (async () => {
      try {
        console.log('[Flow v15.2] ensureCleanProject: Checking project state...');
        showBotOverlay('ตรวจสอบโปรเจ็ค...', 'เตรียมเริ่มงาน');

        const currentUrl = window.location.href;

        // === Step 1: เช็คว่าอยู่หน้า Flow หลักหรือไม่ ===
        const newProjectBtn = findNewProjectButton();
        if (newProjectBtn) {
          console.log('[Flow v15.2] On main Flow page - creating new project...');
          showBotOverlay('สร้างโปรเจ็คใหม่...', 'เตรียมเริ่มงาน');
          await delay(500);
          newProjectBtn.click();
          await delay(4000);
          await ensureFlowAgentDisabled(); // v4.5.9: ปิด Flow AI Agent ที่อาจเปิดมาเอง
          hideBotOverlay();
          sendResponse({ success: true, action: 'created_new', message: 'สร้างโปรเจ็คใหม่แล้ว' });
          return;
        }

        // === Step 2: เช็คว่าอยู่ใน Scene Builder หรือไม่ ===
        const isInScenebuilder = isInScenebuilderPage();
        if (isInScenebuilder) {
          console.log('[Flow v15.2] In Scene Builder - need to go back and create new project...');
          showBotOverlay('กำลังออกจาก Scene Builder...', 'เตรียมโปรเจ็คใหม่');

          // ลบคลิปก่อน
          await deleteAllSceneClipsUntilEmpty();
          await delay(2000);

          // กลับหน้า Flow หลัก
          await goBackToFlow();
          await delay(3000);

          // เช็คว่ากลับมาสำเร็จไหม
          const stillInScenebuilder = isInScenebuilderPage();
          if (stillInScenebuilder) {
            hideBotOverlay();
            sendResponse({ success: false, needsRefresh: true, message: 'ยังค้างใน Scene Builder' });
            return;
          }

          // กลับมาหน้าโปรเจ็คแล้ว ต้องกลับไปหน้า Flow หลักอีกที
          console.log('[Flow v15.2] Back to project page - going to main Flow...');
          await goBackToMainFlow();
          await delay(3000);

          // สร้างโปรเจ็คใหม่
          const newBtn = findNewProjectButton();
          if (newBtn) {
            showBotOverlay('สร้างโปรเจ็คใหม่...', 'เตรียมเริ่มงาน');
            newBtn.click();
            await delay(4000);
            await ensureFlowAgentDisabled(); // v4.5.9: ปิด Flow AI Agent ที่อาจเปิดมาเอง
            hideBotOverlay();
            sendResponse({ success: true, action: 'exited_scenebuilder_created_new', message: 'ออกจาก Scene Builder และสร้างโปรเจ็คใหม่แล้ว' });
          } else {
            hideBotOverlay();
            sendResponse({ success: false, needsRefresh: true, message: 'หา New project button ไม่เจอ' });
          }
          return;
        }

        // === Step 3: อยู่ในโปรเจ็ค - เช็คว่ามีรูป/คลิปอยู่แล้วหรือไม่ ===
        console.log('[Flow v15.2] In a project - checking for existing content...');

        // หา image cards หรือ clip cards
        const hasExistingContent = checkForExistingContent();

        if (hasExistingContent) {
          console.log('[Flow v15.2] Project has existing content - going back to create new project...');
          showBotOverlay('พบเนื้อหาเก่า...', 'กำลังสร้างโปรเจ็คใหม่');

          // กลับไปหน้า Flow หลัก
          await goBackToMainFlow();
          await delay(3000);

          // สร้างโปรเจ็คใหม่
          const newBtn = findNewProjectButton();
          if (newBtn) {
            showBotOverlay('สร้างโปรเจ็คใหม่...', 'เตรียมเริ่มงาน');
            newBtn.click();
            await delay(4000);
            hideBotOverlay();
            sendResponse({ success: true, action: 'had_content_created_new', message: 'พบเนื้อหาเก่า - สร้างโปรเจ็คใหม่แล้ว' });
          } else {
            hideBotOverlay();
            sendResponse({ success: false, needsRefresh: true, message: 'หา New project button ไม่เจอ' });
          }
          return;
        }

        // === Step 4: โปรเจ็คเปล่า - พร้อมใช้งาน ===
        console.log('[Flow v15.2] Empty project - ready to use!');
        hideBotOverlay();
        sendResponse({ success: true, action: 'ready', message: 'โปรเจ็คเปล่า พร้อมใช้งาน' });

      } catch (err) {
        console.error('[Flow v15.2] ensureCleanProject error:', err);
        hideBotOverlay();
        sendResponse({ success: false, error: err.message, needsRefresh: true });
      }
    })();
    return true;
  }

  // v14.1: ตรวจสอบว่าอยู่หน้าหลัก Flow หรือไม่ (ไม่ใช่ Scene Builder)
  if (message.action === 'ensureMainFlowPage') {
    (async () => {
      const isInScenebuilder = isInScenebuilderPage();
      console.log(`[Flow v14.1] ensureMainFlowPage: isInScenebuilder=${isInScenebuilder}`);

      if (isInScenebuilder) {
        console.log('[Flow v14.1] ⚠️ อยู่ใน Scene Builder - กำลังกลับหน้าหลัก...');
        showBotOverlay('กำลังกลับหน้าหลัก...', 'เตรียมสร้างรูป');

        try {
          // ลบคลิปทั้งหมดก่อน
          await deleteAllSceneClipsUntilEmpty();
          await delay(2000);

          // กลับหน้าหลัก
          const backResult = await goBackToFlow();
          console.log('[Flow v14.1] goBackToFlow result:', backResult);

          await delay(3000);

          // ตรวจสอบอีกครั้ง
          const stillInScenebuilder = isInScenebuilderPage();
          if (stillInScenebuilder) {
            console.log('[Flow v14.1] ⚠️ ยังค้างอยู่ - ลอง refresh');
            hideBotOverlay();
            sendResponse({ success: false, wasInScenebuilder: true, needsRefresh: true });
            return;
          }

          hideBotOverlay();
          sendResponse({ success: true, wasInScenebuilder: true, backToMain: true });
        } catch (err) {
          console.error('[Flow v14.1] Error going back:', err);
          hideBotOverlay();
          sendResponse({ success: false, error: err.message, needsRefresh: true });
        }
      } else {
        console.log('[Flow v14.1] ✅ อยู่หน้าหลักแล้ว พร้อมสร้างรูป');
        sendResponse({ success: true, wasInScenebuilder: false, readyForImages: true });
      }
    })();
    return true;
  }

  // ตรวจสอบ Failed Generation ก่อนเริ่มงาน
  // v8.6.2: เพิ่ม audioFailedCount และ usableClips เพื่อตัดสินใจได้ดีขึ้น
  if (message.action === 'checkFailedGeneration') {
    const failedCount = countAllFailedGenerations();
    const audioFailedCount = countAudioFailedGenerations();
    const clipInfo = countUsableClips();

    console.log(`[Flow] Checking failed: total=${failedCount}, audio=${audioFailedCount}, clips=${JSON.stringify(clipInfo)}`);

    // v8.6.2: ใช้ clipInfo.videoFailed เป็นตัวตัดสิน
    // ถ้ามี videoFailed = 0 และมีคลิปใช้ได้ → ทำงานต่อได้เลย
    const hasRealVideoFailed = clipInfo.videoFailed > 0;
    const canContinue = clipInfo.hasUsableClips && !hasRealVideoFailed;

    sendResponse({
      success: true,
      hasFailedGeneration: failedCount > 0 || hasRealVideoFailed,
      count: failedCount,
      audioFailedCount: audioFailedCount,
      onlyAudioFailed: !hasRealVideoFailed && failedCount > 0,
      clipInfo: clipInfo,
      canContinue: canContinue
    });
    return true;
  }

  // v7.4: ลบ Failed Generation ทั้งหมด (กดปุ่ม 3 จุด แล้วกด Delete)
  if (message.action === 'deleteFailedGenerations') {
    deleteAllFailedGenerations().then(result => {
      console.log(`[Flow] Delete failed generations result:`, result);
      sendResponse(result);
    }).catch(err => {
      console.error(`[Flow] Delete failed generations error:`, err);
      sendResponse({ success: false, deleted: 0, error: err.message });
    });
    return true;
  }

  // v9.0.2: ลบ Audio Fail โดยเฉพาะ (คลิปที่มีวิดีโอแต่เสียงเฟล - ปุ่ม 3 จุดอยู่ถัดจาก Extend)
  if (message.action === 'deleteAudioFail') {
    deleteAudioFailGeneration().then(result => {
      console.log(`[Flow] Delete audio fail result:`, result);
      sendResponse(result);
    }).catch(err => {
      console.error(`[Flow] Delete audio fail error:`, err);
      sendResponse({ success: false, deleted: 0, error: err.message });
    });
    return true;
  }

  // v9.3: ตรวจสอบ Quota Error (Error code 253, quota limit exceeded)
  if (message.action === 'checkQuotaError') {
    const quotaError = checkQuotaLimitError();
    console.log(`[Flow] Quota error check:`, quotaError);
    sendResponse(quotaError);
    return true;
  }

  // v12: ทดสอบ Export Retry (ต่อฉาก)
  if (message.action === 'testExportRetry') {
    testExportRetryFlow().then(result => {
      console.log(`[Flow] Test export retry result:`, result);
      sendResponse(result);
    }).catch(err => {
      console.error(`[Flow] Test export retry error:`, err);
      sendResponse({ success: false, error: err.message });
    });
    return true;
  }

  // v6.9: ตรวจสอบว่าคลิปมีเสียงหรือไม่ ก่อนนำไปใช้
  if (message.action === 'checkClipAudio') {
    const clipIndex = message.index || 0;
    const hasNoAudio = checkClipHasNoAudio(clipIndex);
    const noAudioCount = countClipsWithNoAudio();
    const firstClipWithAudio = findFirstClipWithAudio();

    console.log(`[Flow] Audio check: clipIndex=${clipIndex}, hasNoAudio=${hasNoAudio}, totalNoAudio=${noAudioCount}, firstWithAudio=${firstClipWithAudio}`);

    sendResponse({
      success: true,
      hasNoAudio: hasNoAudio,
      noAudioCount: noAudioCount,
      firstClipWithAudio: firstClipWithAudio,
      allClipsNoAudio: firstClipWithAudio === -1
    });
    return true;
  }

  // Toggle debug mode - ม่านโปร่งใส
  if (message.action === 'toggleDebugMode') {
    window._flowVeoDebugMode = !window._flowVeoDebugMode;
    const overlay = document.getElementById('pd-bot-overlay');
    if (overlay) {
      if (window._flowVeoDebugMode) {
        overlay.style.background = 'rgba(15, 15, 26, 0.3)';
        overlay.style.pointerEvents = 'none';
      } else {
        overlay.style.background = 'rgba(15, 15, 26, 0.9)';
        overlay.style.pointerEvents = 'auto';
      }
    }
    sendResponse({ success: true, debugMode: window._flowVeoDebugMode });
    return true;
  }

  // v6.9: Handler สำหรับอัพเดทม่านแสดง countdown
  if (message.action === 'updateOverlay') {
    const title = message.title || 'กำลังรอ...';
    const subtitle = message.subtitle || '';
    updateBotOverlay(title, subtitle);
    sendResponse({ success: true });
    return true;
  }

  // v6.9: Handler สำหรับซ่อนม่าน
  if (message.action === 'hideOverlay') {
    hideBotOverlay();
    sendResponse({ success: true });
    return true;
  }
});

// Main function to create video
async function startVideoCreation(data) {
  try {
    // แสดง overlay เริ่มต้น
    showBotOverlay('กำลังเริ่มต้น...', 'เตรียมความพร้อม');
    updateStatus('กำลังเตรียมการ...');

    // ปิด popups/panels ที่อาจค้างอยู่จากรอบก่อน
    await closeAnyOpenPanels();

    // กดปุ่ม Grid View ก่อนเริ่มทำงาน (ช่วยให้บอทเลือกรูปได้ง่ายขึ้น)
    await clickGridViewButton();

    // Step 1: Open mode selection and choose "เปลี่ยนเฟรมเป็นวิดีโอ"
    updateBotOverlay('กำลังเลือกโหมด...', 'ขั้นตอนที่ 1/6');
    await step1_SelectMode();

    // Step 2: Configure settings (aspect ratio, clip count, model)
    updateBotOverlay('กำลังตั้งค่า...', 'ขั้นตอนที่ 2/6');
    await step2_ConfigureSettings(data);

    // Step 3: Upload image
    updateBotOverlay('กำลังอัพโหลดรูป...', 'ขั้นตอนที่ 3/6');
    await step3_UploadImage(data.image);

    // Step 4: Handle crop if appears (pass data for aspect ratio)
    updateBotOverlay('กำลังครอบตัดรูป...', 'ขั้นตอนที่ 4/6');
    await step4_HandleCrop(data);

    // Step 5: Enter prompt
    updateBotOverlay('กำลังกรอก Prompt...', 'ขั้นตอนที่ 5/6');
    await step5_EnterPrompt(data.prompt);

    // Step 6: Click generate button
    updateBotOverlay('กำลังเริ่มสร้างวิดีโอ...', 'ขั้นตอนที่ 6/6');

    // จำจำนวนคลิปและ Failed ก่อนกดสร้าง (เพื่อนับเฉพาะของใหม่)
    clipCountBeforeGenerate = countAllClipElements();
    failedCountBeforeGenerate = countAllFailedGenerations();

    // เพิ่ม batch ID สำหรับชุดนี้ (เพื่อแยกแต่ละรอบการสร้าง)
    currentBatchId++;
    retryCount = 0; // รีเซ็ต retry สำหรับชุดใหม่

    console.log(`📊 [Batch ${currentBatchId}] Before generate: clips=${clipCountBeforeGenerate}, failed=${failedCountBeforeGenerate}`);

    const generateSuccess = await step6_Generate();
    if (!generateSuccess) {
      updateStatus('❌ ไม่พบปุ่ม Generate - กรุณากดปุ่มสร้างเอง');
      throw new Error('ไม่พบปุ่ม Generate - กรุณากดปุ่มสร้างเอง');
    }

    updateBotOverlay('กำลังสร้างวิดีโอ...', 'รอระบบประมวลผล');
    updateStatus('กำลังสร้างวิดีโอ... รอสักครู่');

    // ไม่ซ่อน overlay - ให้แสดงตลอดเวลาที่ bot ทำงาน
    // user จะได้รู้ว่า bot ยังทำงานอยู่

    // ปลดล็อคให้ผู้ใช้สร้างรอบต่อไปได้ทันที (ไม่ต้องรอคลิปเสร็จ)
    isProcessing = false;
    chrome.runtime.sendMessage({ action: 'readyForNext' });

    // Monitor progress (ทำงาน background ไม่บล็อคการสร้างรอบต่อไป)
    await monitorProgress();

    // ซ่อน overlay เมื่อเสร็จสมบูรณ์
    hideBotOverlay();
    chrome.runtime.sendMessage({ action: 'complete' });

  } catch (error) {
    isProcessing = false;
    hideBotOverlay(); // ซ่อน overlay เมื่อเกิด error
    chrome.runtime.sendMessage({ action: 'error', error: error.message });
    throw error;
  }
}

// Main function to create image (คล้าย video แต่เลือกโหมด Create Image)
async function startImageCreation(data) {
  try {
    // แสดง overlay เริ่มต้น
    showBotOverlay('กำลังเริ่มต้น...', 'เตรียมสร้างรูปภาพ');
    updateStatus('กำลังเตรียมการ...');

    // Reset ตำแหน่งปุ่มที่กดไปแล้ว (สำหรับ multi-image)
    clickedButtonPositions = [];

    // ปิด popups/panels ที่อาจค้างอยู่จากรอบก่อน
    await closeAnyOpenPanels();

    // กดปุ่ม Grid View ก่อนเริ่มทำงาน (ช่วยให้บอทเลือกรูปได้ง่ายขึ้น)
    await clickGridViewButton();

    // นับจำนวนรูปที่ต้องแนบ
    const imagesToUpload = data.images || [data.image];
    const totalImages = imagesToUpload.length;
    const totalSteps = 4 + totalImages + 1; // mode + settings + (upload+crop) * images + prompt + generate

    // Step 1: เลือกโหมด "สร้างรูปภาพ" / "Create Image"
    updateBotOverlay('กำลังเลือกโหมด...', `ขั้นตอนที่ 1/${totalSteps}`);
    updateStatus(`📌 ขั้นตอน 1/${totalSteps}: เลือกโหมดสร้างรูป`);
    await step1_SelectImageMode();

    // v16.3: Workaround Google Flow bug — ปุ่มแนบภาพไม่ทำงานหลังสร้างโปรเจ็คใหม่
    // แก้โดยสลับไป Frames to Video แล้วกลับ Create Image เพื่อ reinitialize UI
    await fixFlowUploadButtonBug();

    // Step 2: ตั้งค่า (aspect ratio, จำนวนรูป)
    updateBotOverlay('กำลังตั้งค่า...', `ขั้นตอนที่ 2/${totalSteps}`);
    updateStatus(`📌 ขั้นตอน 2/${totalSteps}: ตั้งค่า Aspect Ratio & จำนวนรูป`);
    await step2_ConfigureSettings(data);

    // Step 3-N: อัพโหลดรูปทีละรูป (แนบรูปแรก แล้วกดปุ่ม + แนบรูปถัดไป)
    for (let i = 0; i < totalImages; i++) {
      const stepNum = 3 + i;
      const imageNum = i + 1;

      if (i === 0) {
        // รูปแรก: อัพโหลดตามปกติ
        updateBotOverlay(`กำลังอัพโหลดรูป ${imageNum}/${totalImages}...`, `ขั้นตอนที่ ${stepNum}/${totalSteps}`);
        updateStatus(`📌 ขั้นตอน ${stepNum}/${totalSteps}: อัพโหลดรูป ${imageNum}/${totalImages}`);
        await step3_UploadImage(imagesToUpload[i]);

        // จัดการ crop สำหรับรูปแรก
        updateBotOverlay(`กำลังครอบตัดรูป ${imageNum}/${totalImages}...`, `ขั้นตอนที่ ${stepNum}/${totalSteps}`);
        updateStatus(`📌 ขั้นตอน ${stepNum}/${totalSteps}: ครอบตัดรูป ${imageNum}/${totalImages}`);
        await step4_HandleCrop(data);

        // ถ้ามีรูปเพิ่มเติม รอให้รูปแรกอัพโหลดเสร็จและปุ่ม + ขึ้นมา
        if (totalImages > 1) {
          console.log('Waiting for first image to finish uploading and + button to appear...');
          updateBotOverlay('รอรูปแรกอัพโหลดเสร็จ...', 'รอ 1.5 วินาที');
          await delay(1500); // รอ 1.5 วินาทีให้รูปอัพโหลดเสร็จและปุ่ม + ขึ้นมา
        }
      } else {
        // รูปที่ 2+ : กดปุ่ม + แล้วแนบรูป
        updateBotOverlay(`กำลังเพิ่มรูป ${imageNum}/${totalImages}...`, `ขั้นตอนที่ ${stepNum}/${totalSteps}`);
        updateStatus(`📌 ขั้นตอน ${stepNum}/${totalSteps}: เพิ่มรูป ${imageNum}/${totalImages}`);
        await step3_AddAdditionalImage(imagesToUpload[i], i);

        // จัดการ crop สำหรับรูปเพิ่มเติม
        updateBotOverlay(`กำลังครอบตัดรูป ${imageNum}/${totalImages}...`, `ขั้นตอนที่ ${stepNum}/${totalSteps}`);
        updateStatus(`📌 ขั้นตอน ${stepNum}/${totalSteps}: ครอบตัดรูป ${imageNum}/${totalImages}`);
        await step4_HandleCrop(data);

        // รอให้ UI พร้อมก่อนแนบรูปถัดไป (ถ้ายังมี)
        if (i < totalImages - 1) {
          console.log(`Waiting for UI to be ready for image ${imageNum + 1}...`);
          await delay(2000);
        }
      }
    }

    // Step N+1: กรอก prompt
    const promptStep = 3 + totalImages;
    updateBotOverlay('กำลังกรอก Prompt...', `ขั้นตอนที่ ${promptStep}/${totalSteps}`);
    updateStatus(`📌 ขั้นตอน ${promptStep}/${totalSteps}: กรอก Prompt`);
    await step5_EnterPrompt(data.prompt);

    // Step N+2: กด Generate
    const generateStep = promptStep + 1;
    updateBotOverlay('กำลังเริ่มสร้างรูปภาพ...', `ขั้นตอนที่ ${generateStep}/${totalSteps}`);
    updateStatus(`📌 ขั้นตอน ${generateStep}/${totalSteps}: กดปุ่ม Generate`);

    // v6.9: FIX BUG - จำจำนวนรูปก่อนกดสร้าง (ใช้ countImageElements สำหรับ Image mode!)
    // ก่อนหน้านี้ใช้ countAllClipElements() ซึ่งผิด เพราะนับ video thumbnail แทนที่จะนับรูปที่สร้าง
    clipCountBeforeGenerate = countImageElements();
    failedCountBeforeGenerate = countAllFailedGenerations();
    currentBatchId++;
    retryCount = 0;
    // v8.2: Save state for Multi-Set
    saveStateToWindow();

    console.log(`🖼️ [Image Batch ${currentBatchId}] Before generate: images=${clipCountBeforeGenerate} (using countImageElements), failed=${failedCountBeforeGenerate}, uploaded=${totalImages} images`);

    const generateSuccess = await step6_Generate();
    if (!generateSuccess) {
      updateStatus('❌ ไม่พบปุ่ม Generate - กรุณากดปุ่มสร้างเอง');
      throw new Error('ไม่พบปุ่ม Generate - กรุณากดปุ่มสร้างเอง');
    }

    // v6.9: แสดงม่านระหว่างรอสร้างรูป (ไม่ซ่อน)
    showBotOverlay('กำลังสร้างรูปภาพ...', 'รอระบบประมวลผล');
    updateStatus('กำลังสร้างรูปภาพ... รอสักครู่');

    isProcessing = false;
    chrome.runtime.sendMessage({ action: 'readyForNext' });

    // Monitor progress (ม่านจะถูกอัพเดทใน monitorProgress)
    await monitorProgress();

    chrome.runtime.sendMessage({ action: 'complete' });

  } catch (error) {
    isProcessing = false;
    hideBotOverlay();
    chrome.runtime.sendMessage({ action: 'error', error: error.message });
    throw error;
  }
}

// Step 3 เพิ่มเติม: กดปุ่ม + แล้วแนบรูปเพิ่มเติม (สำหรับรูปที่ 2+)
async function step3_AddAdditionalImage(imageBase64, imageIndex) {
  updateStatus(`กำลังเพิ่มรูปที่ ${imageIndex + 1}...`);

  // ฟังก์ชันเช็คว่าตำแหน่งนี้เคยกดไปแล้วหรือยัง (tolerance 20px)
  function isPositionClicked(left, top) {
    for (const pos of clickedButtonPositions) {
      if (Math.abs(pos.left - left) < 20 && Math.abs(pos.top - top) < 20) {
        return true;
      }
    }
    return false;
  }

  let plusBtn = null;

  console.log(`=== Looking for + button to add image ${imageIndex + 1} ===`);
  console.log(`Already clicked positions: ${JSON.stringify(clickedButtonPositions)}`);

  // หา prompt area container ก่อน
  const promptArea = findPromptAreaContainer();

  if (promptArea) {
    console.log('Found prompt area container');

    // หาปุ่มใน prompt area เท่านั้น
    const buttonsInPromptArea = promptArea.querySelectorAll('button');

    // Sort by position (left to right)
    const sortedButtons = Array.from(buttonsInPromptArea).sort((a, b) => {
      const rectA = a.getBoundingClientRect();
      const rectB = b.getBoundingClientRect();
      return rectA.left - rectB.left;
    });

    console.log(`Found ${sortedButtons.length} buttons in prompt area`);

    // หาปุ่มเล็ก (< 80px) ที่ยังไม่เคยกดตำแหน่งนี้
    for (const btn of sortedButtons) {
      const rect = btn.getBoundingClientRect();
      console.log(`Button: left=${Math.round(rect.left)}, top=${Math.round(rect.top)}, size=${Math.round(rect.width)}x${Math.round(rect.height)}`);

      if (rect.width < 80 && rect.height < 80 && btn.offsetParent !== null) {
        // เช็คว่าเคยกดตำแหน่งนี้ไปแล้วหรือยัง
        if (isPositionClicked(rect.left, rect.top)) {
          console.log(`  -> Already clicked this position before, skipping`);
          continue;
        }

        plusBtn = btn;
        console.log(`Found new + button at left=${Math.round(rect.left)}, top=${Math.round(rect.top)}`);
        break;
      }
    }
  }

  // Fallback 1: หาจาก google-symbols icon ที่มีข้อความ "add"
  if (!plusBtn) {
    console.log('Trying fallback 1: google-symbols icon with "add"...');
    const addIcons = document.querySelectorAll('i.google-symbols, i[class*="google-symbols"]');
    for (const icon of addIcons) {
      const text = icon.textContent.trim().toLowerCase();
      if (text === 'add' || text === 'add_photo_alternate') {
        // หา parent ที่เป็น button หรือ clickable
        let clickable = icon.closest('button') || icon.closest('[role="button"]') || icon.parentElement;
        if (clickable) {
          const rect = clickable.getBoundingClientRect();
          if (!isPositionClicked(rect.left, rect.top) && rect.top > window.innerHeight * 0.5) {
            plusBtn = clickable;
            console.log('Found + button via google-symbols icon "add"');
            break;
          }
        }
      }
    }
  }

  // Fallback 2: หาจากตำแหน่งล่างสุดของหน้าจอ
  if (!plusBtn) {
    console.log('Trying fallback 2: bottom of screen...');
    const allButtons = Array.from(document.querySelectorAll('button'));

    // Filter buttons ที่อยู่ล่างสุด (85% ของหน้าจอ)
    const bottomButtons = allButtons.filter(btn => {
      const rect = btn.getBoundingClientRect();
      return btn.offsetParent !== null && rect.top > window.innerHeight * 0.85;
    });

    // Sort by position (left to right)
    bottomButtons.sort((a, b) => {
      const rectA = a.getBoundingClientRect();
      const rectB = b.getBoundingClientRect();
      return rectA.left - rectB.left;
    });

    // หาปุ่มเล็กที่ยังไม่เคยกดตำแหน่งนี้
    for (const btn of bottomButtons) {
      const rect = btn.getBoundingClientRect();
      if (rect.width < 80 && rect.height < 80) {
        if (!isPositionClicked(rect.left, rect.top)) {
          plusBtn = btn;
          console.log('Found new + button (bottom of screen)');
          break;
        }
      }
    }
  }

  if (!plusBtn) {
    console.error(`Could not find + button for image ${imageIndex + 1}`);
    return;
  }

  // จำตำแหน่งที่กดไว้ ไม่กดซ้ำตำแหน่งเดิม
  const btnRect = plusBtn.getBoundingClientRect();
  clickedButtonPositions.push({ left: btnRect.left, top: btnRect.top });
  console.log(`Clicking + button for image ${imageIndex + 1} at (${Math.round(btnRect.left)}, ${Math.round(btnRect.top)})`);
  plusBtn.click();
  await delay(1500); // รอนานขึ้นให้ menu/dropdown ปรากฏ

  // หา dropdown/menu ที่เพิ่งปรากฏหลังกด +
  await delay(500);

  // เช็คว่ามี file input อยู่แล้วหรือยัง
  let fileInput = document.querySelector('input[type="file"]');
  if (fileInput) {
    console.log('Found file input immediately after clicking +');
  }

  // ถ้ายังไม่มี file input ให้หา dropdown/menu และปุ่ม Upload
  if (!fileInput) {
    console.log('Looking for dropdown menu or upload option...');

    // หา dropdown/menu/popover ที่เพิ่งปรากฏ
    const dropdowns = document.querySelectorAll('[role="menu"], [role="listbox"], [class*="dropdown"], [class*="menu"], [class*="popover"], [class*="popup"], [class*="overlay"]');

    let uploadBtn = null;

    // หาใน dropdown ก่อน
    for (const dropdown of dropdowns) {
      if (dropdown.offsetParent === null) continue;

      const items = dropdown.querySelectorAll('button, div[role="button"], div[role="menuitem"], li, a, span');
      for (const item of items) {
        const text = (item.textContent || '').trim().toLowerCase();
        if (text.includes('upload') || text.includes('อัปโหลด') || text.includes('อัพโหลด') ||
            text.includes('from computer') || text.includes('จากคอมพิวเตอร์')) {
          uploadBtn = item;
          console.log('Found upload option in dropdown:', item.textContent.trim());
          break;
        }
      }
      if (uploadBtn) break;
    }

    // ถ้าไม่เจอใน dropdown ให้หาทั้งหน้า
    if (!uploadBtn) {
      const allClickables = document.querySelectorAll('button, div[role="button"], div[class*="upload"], a, span, li');
      const uploadTexts = ['อัปโหลด', 'Upload', 'อัพโหลด', 'Upload image', 'Upload file', 'From computer', 'จากคอมพิวเตอร์'];

      for (const el of allClickables) {
        const text = (el.textContent || '').trim();
        if (uploadTexts.some(t => text === t || text.toLowerCase() === t.toLowerCase())) {
          uploadBtn = el;
          console.log('Found upload button:', text);
          break;
        }
      }
    }

    // Fallback: หาจาก icon upload
    if (!uploadBtn) {
      const uploadIcons = document.querySelectorAll('i.google-symbols, i[class*="google-symbols"], i.material-icons');
      for (const icon of uploadIcons) {
        const iconText = icon.textContent.trim().toLowerCase();
        if (iconText === 'upload' || iconText === 'cloud_upload' || iconText === 'upload_file') {
          const clickable = icon.closest('button') || icon.closest('[role="button"]') || icon.parentElement;
          if (clickable) {
            uploadBtn = clickable;
            console.log('Found upload button via icon:', iconText);
            break;
          }
        }
      }
    }

    if (uploadBtn) {
      console.log('Clicking upload button');
      uploadBtn.click();
      await delay(1000);
    } else {
      console.log('No upload button found, trying to find file input directly...');
    }
  }

  // หา file input
  await delay(500);

  if (!fileInput) {
    fileInput = document.querySelector('input[type="file"]');
  }

  // รอหา file input หลายครั้ง
  for (let i = 0; i < 10 && !fileInput; i++) {
    await delay(500);
    fileInput = document.querySelector('input[type="file"]') ||
                document.querySelector('input[accept*="image"]') ||
                document.querySelector('input[accept*="video"]');
    console.log(`Looking for file input... attempt ${i + 1}`);
  }

  if (fileInput) {
    console.log(`Found file input for image ${imageIndex + 1}, uploading...`);
    await uploadToFileInput(fileInput, imageBase64);
    console.log(`Uploaded additional image ${imageIndex + 1}`);
  } else {
    // Fallback: ลองหลายวิธีเหมือน step3_UploadImage
    console.log(`No file input found for image ${imageIndex + 1}, trying alternative upload methods...`);

    const uploaded = await tryAlternativeUpload(imageBase64);
    if (!uploaded) {
      console.error(`Could not upload additional image ${imageIndex + 1}`);
      throw new Error(`ไม่สามารถอัพโหลดรูปที่ ${imageIndex + 1} ได้`);
    }
    console.log(`Uploaded additional image ${imageIndex + 1} via alternative method`);
  }
}

