// ===============================================
// v17: NEW UI HELPER FUNCTIONS
// ===============================================

// v17 Global Helper: เช็คว่า element มองเห็นได้จริง
// ห้ามใช้ offsetParent เพราะ prompt bar เป็น position:fixed → offsetParent = null เสมอ
function isVisible(el) {
  if (!el) return false;
  const rect = el.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0;
}

// ⚠️ v17 CRITICAL: Radix UI ไม่ฟัง .click() ธรรมดา — ต้อง dispatch full PointerEvent + MouseEvent chain
// ใช้กับทุกปุ่มใน Settings Panel (tabs, chip, model dropdown, menuitem)
function realClick(element) {
  if (!element) return;
  const rect = element.getBoundingClientRect();
  // v4.4.5: เพิ่ม jitter ±3-5 px ภายในขอบเขต element เพื่อกัน reCAPTCHA detect pattern คลิกซ้ำกัน
  //   ขนาด element เล็ก (< 20px) → jitter น้อย (±1-2px), ขนาดใหญ่ → jitter เต็ม ±5px
  //   ดูแลให้คลิกยังอยู่ใน element แน่ๆ (max = half-size - 1)
  const maxJitterX = Math.max(0, Math.min(5, Math.floor(rect.width / 2) - 1));
  const maxJitterY = Math.max(0, Math.min(5, Math.floor(rect.height / 2) - 1));
  const jx = (Math.random() * 2 - 1) * maxJitterX;
  const jy = (Math.random() * 2 - 1) * maxJitterY;
  const cx = rect.x + rect.width / 2 + jx;
  const cy = rect.y + rect.height / 2 + jy;
  // v4.5.7: เลื่อนเมาส์จริง (CDP trusted) ไปจ่อปุ่มก่อนคลิก — fire-and-forget
  //   ช่วย reCAPTCHA เห็นเคอร์เซอร์อยู่ที่ปุ่มจริง (ทำงานเฉพาะตอน ambient เปิด = Merge Mode)
  //   ยังคง JS-click ด้านล่างไว้ (Radix UI ต้องการ — ไม่เสี่ยงพัง)
  try { chrome.runtime.sendMessage({ action: 'cdpMoveTo', x: Math.round(cx), y: Math.round(cy) }); } catch (_) {}
  const opts = {
    bubbles: true, cancelable: true, view: window,
    clientX: cx, clientY: cy,
    button: 0, buttons: 1,
    pointerId: 1, pointerType: 'mouse'
  };
  element.dispatchEvent(new PointerEvent('pointerover', opts));
  element.dispatchEvent(new PointerEvent('pointerenter', opts));
  element.dispatchEvent(new PointerEvent('pointerdown', opts));
  element.dispatchEvent(new MouseEvent('mousedown', opts));
  element.dispatchEvent(new PointerEvent('pointerup', opts));
  element.dispatchEvent(new MouseEvent('mouseup', opts));
  element.dispatchEvent(new MouseEvent('click', opts));
}

// =====================================================
// v4.5.9: ปิด Flow AI Agent หลัง New Project (ครอบ "ทุกโหมด")
// ปัญหา: บางบัญชีพอเข้า New Project → Flow เปิด "Agent" panel มาเอง
//   → ช่อง prompt หลักเพี้ยน/ถูกบดบัง บอททำงานพัง ต้องปิดก่อนเริ่มทุกครั้ง
// แก้ 2 ชั้น: (1) ยิง API ปิด agent ระดับ server (แน่นอน ครอบทุกโหมด)
//            (2) เก็บกวาด DOM ให้จอสดถูกต้อง (กัน API ไม่ refresh live)
// =====================================================

// ดึง projectId จาก URL ปัจจุบัน (รูปแบบ /fx/tools/flow/project/<uuid>)
function _getFlowProjectIdFromUrl() {
  const m = (location.href || '').match(/\/project\/([0-9a-fA-F-]{16,})/);
  return m ? m[1] : null;
}

// หา toggle "Agent" ที่บาร์ล่าง (span.content === "Agent") → คืน element ที่กดได้
function findBottomAgentToggle() {
  const spans = Array.from(document.querySelectorAll('span.content'))
    .filter(s => (s.textContent || '').trim().toLowerCase() === 'agent' && isVisible(s));
  // เลือกตัวที่อยู่ล่างสุดของจอ (บาร์ composer ล่าง)
  let bestSpan = null, bestY = -1;
  for (const s of spans) {
    const r = s.getBoundingClientRect();
    if (r.top > bestY) { bestY = r.top; bestSpan = s; }
  }
  if (bestSpan) {
    return bestSpan.closest('button') || bestSpan.closest('[role="button"]') || bestSpan.parentElement;
  }
  // fallback: ปุ่มที่ข้อความ === "Agent" แถวล่างสุด
  const btns = Array.from(document.querySelectorAll('button, [role="button"]'))
    .filter(b => (b.textContent || '').trim() === 'Agent' && isVisible(b));
  let fb = null, fy = -1;
  for (const b of btns) { const r = b.getBoundingClientRect(); if (r.top > fy) { fy = r.top; fb = b; } }
  return fb;
}

// เช็คว่า Agent toggle "เปิดอยู่" (ขาว) ไหม
// signal หลัก: wrapper ของ span.content มี <div> ลูก (เอฟเฟกต์ active) = เปิด / มีแต่ span = ปิด
// (ดักจาก DOM จริง 2026-06-10 — ไม่ผูกกับชื่อ class สุ่มที่เปลี่ยนทุก build)
function isBottomAgentToggleOn() {
  const t = findBottomAgentToggle();
  if (!t) return false;
  let span = null;
  try { span = t.querySelector ? t.querySelector('span.content') : null; } catch (_) {}
  if (!span && t.classList && t.classList.contains('content')) span = t;
  const wrapper = span ? span.parentElement : t;
  let hasDecor = false;
  try { hasDecor = !!(wrapper && wrapper.querySelector(':scope > div')); } catch (_) {}
  // เสริม: aria/data-state ถ้า Flow ใส่มา (เผื่ออนาคต)
  const ariaOn = !!(t.getAttribute && (
    t.getAttribute('aria-pressed') === 'true' ||
    t.getAttribute('aria-checked') === 'true' ||
    t.getAttribute('data-state') === 'on'
  ));
  return hasDecor || ariaOn;
}

// ปิด Agent side panel ฝั่งขวา (กดปุ่ม X) ถ้าเปิดอยู่
// ยืนยันว่าเป็น agent panel จริงจาก header ที่มี edit_square (New session)/menu (History) หรือ h2/h3 "session"
function closeAgentSidePanelIfOpen() {
  const closeIcons = Array.from(document.querySelectorAll('i.google-symbols, span.google-symbols'))
    .filter(i => (i.textContent || '').trim() === 'close');
  for (const ic of closeIcons) {
    const btn = ic.closest('button');
    if (!btn || !isVisible(btn)) continue;
    // เดินขึ้นหา header/บรรพบุรุษที่บ่งบอกว่าเป็น agent panel
    let scope = btn.parentElement;
    let isAgentHeader = false;
    for (let hops = 0; scope && hops < 6; hops++, scope = scope.parentElement) {
      const hasEditOrMenu = Array.from(scope.querySelectorAll('i.google-symbols, span.google-symbols'))
        .some(x => { const t = (x.textContent || '').trim(); return t === 'edit_square' || t === 'menu'; });
      const hasSession = Array.from(scope.querySelectorAll('h1,h2,h3'))
        .some(h => /session/i.test(h.textContent || ''));
      if (hasEditOrMenu || hasSession) { isAgentHeader = true; break; }
    }
    if (isAgentHeader) {
      console.log('[v4.5.9 Agent] ปิด Agent side panel (กด X)');
      realClick(btn);
      return true;
    }
  }
  return false;
}

// main: ปิด Flow AI Agent ให้เรียบร้อยหลัง New Project — เรียกได้ทุกโหมด, non-fatal
async function ensureFlowAgentDisabled() {
  // ---------- ชั้น 1: API (server-side, ครอบทุกโหมด รวม Express/Merge API Direct) ----------
  let apiOk = false;
  try {
    // v2.x: 🐛 FIX เน็ตช้า — เดิมอ่าน URL ครั้งเดียว ถ้าหน้ายัง navigate ไม่เสร็จ (URL ยังไม่ใช่ /project/<id>)
    //   → ได้ null → ข้าม API ทันที → agent ไม่ถูกปิด. แก้: รอ projectId โผล่ใน URL สูงสุด ~12s ก่อน
    let projectId = _getFlowProjectIdFromUrl();
    for (let i = 0; i < 12 && !projectId; i++) {
      await delay(1000);
      projectId = _getFlowProjectIdFromUrl();
    }
    if (projectId) {
      // กัน hang: ถ้า bridge ยังไม่พร้อมหลัง navigate ให้ข้ามไป DOM ใน 8s (ไม่รอ 120s)
      await Promise.race([
        callFlowAPI('setAgentToggle', projectId, false),
        new Promise((_, rej) => setTimeout(() => rej(new Error('setAgentToggle timeout 8s')), 8000)),
      ]);
      apiOk = true;
      console.log('[v4.5.9 Agent] ✅ API ปิด agent toggle สำเร็จ:', projectId);
    } else {
      console.log('[v4.5.9 Agent] ⚠️ ไม่พบ projectId ใน URL หลังรอ 12s — ข้าม API ใช้ DOM อย่างเดียว');
    }
  } catch (e) {
    console.log('[v4.5.9 Agent] ⚠️ API setAgentToggle ล้มเหลว (' + (e && e.message || e) + ') — fallback DOM');
  }

  // ---------- ชั้น 2: DOM cleanup (กัน API ไม่ refresh จอสด + รองรับโหมดที่พิมพ์ผ่าน DOM) ----------
  try {
    // 2a) ปิด side panel ถ้าเปิดอยู่ → บาร์ล่างจะ render ตามมา (รอให้ทัน)
    const closedPanel = closeAgentSidePanelIfOpen();
    await delay(closedPanel ? 800 : 300);
    // 2b) ปุ่ม Agent บาร์ล่าง — ถ้ายังขาว(เปิด) กดให้เทา(ปิด) — กดเฉพาะตอนเปิด ป้องกันสลับกลับ
    let toggled = false;
    for (let i = 0; i < 5; i++) {
      const btn = findBottomAgentToggle();
      if (!btn) { await delay(500); continue; } // บาร์ยัง render ไม่ทัน — รอแล้วลองใหม่
      if (!isBottomAgentToggleOn()) { toggled = true; break; } // เทาแล้ว = พร้อม
      console.log('[v4.5.9 Agent] ปุ่ม Agent ยังขาว — กดปิด (รอบ ' + (i + 1) + ')');
      realClick(btn);
      await delay(500);
    }
    if (!toggled && isBottomAgentToggleOn()) {
      console.log('[v4.5.9 Agent] ⚠️ ปุ่ม Agent ยังขาวหลังพยายามปิดครบ');
    }
  } catch (e) {
    console.log('[v4.5.9 Agent] DOM cleanup error (non-fatal):', e && e.message);
  }
  return { apiOk };
}

// v17: คลิก sidebar Videos filter เพื่อกรองเฉพาะวิดีโอ (ไม่ปนกับภาพ)
// DOM verified: <button> → <i class="google-symbols">videocam</i> + <span>View videos</span>
async function clickSidebarVideosFilter() {
  console.log('[v17] Clicking sidebar Videos filter...');

  let videoBtn = null;

  // วิธี 1 (ดีที่สุด): หาจาก i.google-symbols ที่มี text "videocam" แล้วไล่ขึ้นหา button
  const icons = document.querySelectorAll('i.google-symbols');
  for (const icon of icons) {
    if ((icon.textContent || '').trim() === 'videocam') {
      const btn = icon.closest('button');
      if (btn && isVisible(btn)) {
        videoBtn = btn;
        console.log('[v17] Found sidebar Videos button via i.google-symbols "videocam"');
        break;
      }
    }
  }

  // วิธี 2: หาจาก span ที่มี "View videos"
  if (!videoBtn) {
    const spans = document.querySelectorAll('span');
    for (const span of spans) {
      if ((span.textContent || '').trim() === 'View videos') {
        const btn = span.closest('button');
        if (btn) {
          videoBtn = btn;
          console.log('[v17] Found sidebar Videos button via span "View videos"');
          break;
        }
      }
    }
  }

  // วิธี 3 Fallback: ปุ่มฝั่งซ้ายที่มี text videocam/video
  if (!videoBtn) {
    const allButtons = document.querySelectorAll('button');
    for (const btn of allButtons) {
      const rect = btn.getBoundingClientRect();
      if (rect.left > 80 || !isVisible(btn)) continue;
      const text = (btn.textContent || '').toLowerCase();
      if (text.includes('videocam') || text.includes('view videos')) {
        videoBtn = btn;
        console.log('[v17] Found sidebar Videos button via fallback text search');
        break;
      }
    }
  }

  if (!videoBtn) {
    console.log('[v17] ⚠️ Sidebar Videos button not found');
    return false;
  }

  realClick(videoBtn);
  await delay(1500);
  console.log('[v17] ✅ Clicked sidebar Videos filter');
  return true;
}

// v17.5b: กดปุ่ม Back (arrow_back) เพื่อออกจาก Edit View กลับไปหน้า project
// ใช้หลัง Extend Scene เสร็จ — ไม่ navigate กลับหน้าแรก (รักษา project เดิม)
async function clickBackButtonFromEditView() {
  console.log('[v17.5b] Clicking Back button (arrow_back) from Edit View...');

  // วิธี 1: หา i.google-symbols ที่มี text "arrow_back"
  const icons = document.querySelectorAll('i.google-symbols, i[class*="material"], span.google-symbols');
  for (const icon of icons) {
    const iconText = (icon.textContent || '').trim();
    if (iconText === 'arrow_back' && isVisible(icon)) {
      const btn = icon.closest('button') || icon.closest('[role="button"]');
      if (btn && isVisible(btn)) {
        console.log('[v17.5b] Found arrow_back button via icon');
        realClick(btn);
        await delay(1000);
        console.log('[v17.5b] ✅ Clicked Back button — exited Edit View');
        return true;
      }
    }
  }

  // วิธี 2: หา button ที่มี span text "Back"
  const buttons = document.querySelectorAll('button');
  for (const btn of buttons) {
    if (!isVisible(btn)) continue;
    const spans = btn.querySelectorAll('span');
    for (const span of spans) {
      const text = (span.textContent || '').trim().toLowerCase();
      if (text === 'back') {
        console.log('[v17.5b] Found Back button via span text');
        realClick(btn);
        await delay(1000);
        console.log('[v17.5b] ✅ Clicked Back button — exited Edit View');
        return true;
      }
    }
  }

  console.warn('[v17.5b] ⚠️ Back button (arrow_back) not found');
  return false;
}

// v17.3: คลิกปุ่ม Dashboard (All Media) เพื่อกลับไปดูสื่อทั้งหมด
// ใช้หลัง Add to Scene เพื่อให้ฉากถัดไปหาภาพล่าสุดได้ (ไม่ติดอยู่ในหมวด Videos)
async function clickDashboardAllMedia() {
  console.log('[v17.3] Clicking Dashboard (All Media) button...');

  let dashboardBtn = null;

  // วิธี 1: หาจาก i.google-symbols ที่มี text "dashboard"
  const icons = document.querySelectorAll('i.google-symbols');
  for (const icon of icons) {
    if ((icon.textContent || '').trim() === 'dashboard') {
      const btn = icon.closest('button');
      if (btn && isVisible(btn)) {
        dashboardBtn = btn;
        console.log('[v17.3] Found Dashboard button via i.google-symbols "dashboard"');
        break;
      }
    }
  }

  // วิธี 2: หาจาก span ที่มี "View all" หรือ "All media"
  if (!dashboardBtn) {
    const spans = document.querySelectorAll('span');
    for (const span of spans) {
      const text = (span.textContent || '').trim().toLowerCase();
      if (text === 'view all' || text === 'all media') {
        const btn = span.closest('button');
        if (btn) {
          dashboardBtn = btn;
          console.log('[v17.3] Found Dashboard button via span text');
          break;
        }
      }
    }
  }

  // วิธี 3 Fallback: ปุ่มฝั่งซ้ายที่มี text dashboard
  if (!dashboardBtn) {
    const allButtons = document.querySelectorAll('button');
    for (const btn of allButtons) {
      const rect = btn.getBoundingClientRect();
      if (rect.left > 80 || !isVisible(btn)) continue;
      const text = (btn.textContent || '').toLowerCase();
      if (text.includes('dashboard') || text.includes('view all') || text.includes('all media')) {
        dashboardBtn = btn;
        console.log('[v17.3] Found Dashboard button via fallback text search');
        break;
      }
    }
  }

  if (!dashboardBtn) {
    console.log('[v17.3] ⚠️ Dashboard button not found');
    return false;
  }

  realClick(dashboardBtn);
  await delay(1500);
  console.log('[v17.3] ✅ Clicked Dashboard (All Media) — กลับไปหน้ารวม');
  return true;
}

// v17: นับ video cards ใน gallery
// DOM verified: video ใน gallery เป็น <img alt="Video thumbnail"> ไม่ใช่ <video>!
// ใช้ detect Animate flow ที่ image card กลายเป็น video card (total cards ไม่เพิ่ม แต่ video cards เพิ่ม)
function countVideoCards() {
  let count = 0;

  // วิธี A: หา img[alt="Video thumbnail"] ทั้งหน้า (ไม่จำกัดแค่ .sc-5923b123-0)
  const videoThumbnails = document.querySelectorAll('img[alt="Video thumbnail"]');
  for (const img of videoThumbnails) {
    if (isVisible(img)) count++;
  }
  if (count > 0) {
    console.log(`[countVideoCards] Found ${count} via img[alt="Video thumbnail"]`);
    return count;
  }

  // วิธี B: หาใน .sc-5923b123-0 cards
  const mediaCards = document.querySelectorAll('.sc-5923b123-0');
  for (const card of mediaCards) {
    if (!isVisible(card)) continue;

    const text = (card.textContent || '').toLowerCase();
    if (text.includes('play_arrow') || text.includes('play_circle')) {
      count++;
      continue;
    }
    if (card.querySelector('video')) {
      count++;
      continue;
    }
    if (/\d:\d{2}/.test(card.textContent || '')) {
      count++;
      continue;
    }
  }

  // วิธี C: ลบ sidebar icon fallback แล้ว — มันทำให้ baseline inflate (icon ปรากฏก่อน video จริง)

  if (count > 0) console.log(`[countVideoCards] Found ${count} video cards (fallback methods)`);
  return count;
}

// v17: ตรวจว่าหน้า Flow โหลดจริงหรือเป็น Application Error (หน้าดำ)
// return true = หน้าปกติ, false = หน้าพัง (caller ต้อง handle retry + reload เอง)
function checkPageHealth() {
  const bodyText = (document.body?.innerText || '').trim();
  const isAppError = bodyText.includes('Application error') || bodyText.includes('client-side exception');

  if (isAppError) {
    console.log('[PageHealth] 🚨 Application Error detected! Page is broken.');
    return false;
  }

  return true;
}

// v17: หา Settings Chip — ปุ่มข้างๆ Generate (→) ใน prompt bar
// text บน chip เปลี่ยนตาม mode ล่าสุด เช่น "🍌 Nano Banana Pro crop_9_16 x1" หรือ "Veo 3.1 crop_16_9 x1"
// → ห้ามหาจาก text — ต้องหาจาก structure/position แทน
function findSettingsChip() {

  // วิธี 0 (ดีที่สุด): หาจาก textbox → ไล่ขึ้นไปหา prompt bar → หา button[aria-haspopup="menu"] ข้างใน
  // DOM verified: prompt bar = div[class*="c70e41ad-0"], chip อยู่ข้างในนี้
  // ข้อความบน chip เปลี่ยนตาม mode: Image="🍌 Nano Banana Pro crop_9_16 x1", Video="Video crop_9_16 x1"
  // → ห้าม match ด้วย text!
  const textbox = document.querySelector('div[role="textbox"][contenteditable="true"]');
  if (textbox) {
    // ไล่ขึ้นไปหา prompt bar container
    const promptBar = textbox.closest('div[class*="c70e41ad"]') || textbox.closest('form') || textbox.parentElement?.parentElement?.parentElement;
    if (promptBar) {
      const chip = promptBar.querySelector('button[aria-haspopup="menu"]');
      if (chip && isVisible(chip)) {
        console.log(`[v17] Found settings chip (prompt bar scope): "${(chip.textContent || '').trim().substring(0, 50)}"`);
        return chip;
      }
    }
  }

  // วิธี 1: หาจาก class sc-46973129-1 โดยตรง (stable selector)
  const scChips = document.querySelectorAll('button.sc-46973129-1');
  for (const btn of scChips) {
    if (isVisible(btn)) {
      console.log(`[v17] Found settings chip (sc-46973129-1): "${(btn.textContent || '').trim().substring(0, 50)}"`);
      return btn;
    }
  }

  // วิธี 2: sibling ของ Generate button (type="submit")
  const generateBtn = document.querySelector('button[type="submit"]');
  if (generateBtn) {
    const parent = generateBtn.parentElement;
    if (parent) {
      const chip = parent.querySelector('button[aria-haspopup="menu"]');
      if (chip && isVisible(chip)) {
        console.log(`[v17] Found settings chip (sibling of submit): "${(chip.textContent || '').trim().substring(0, 50)}"`);
        return chip;
      }
    }
  }

  // วิธี 3: button ที่มี aria-haspopup="menu" + มี icon google-symbols ข้างใน (crop_9_16/crop_16_9)
  const allMenuBtns = document.querySelectorAll('button[aria-haspopup="menu"]');
  for (const btn of allMenuBtns) {
    if (!isVisible(btn)) continue;
    const icon = btn.querySelector('i.google-symbols');
    if (icon) {
      const iconText = (icon.textContent || '').trim();
      if (iconText.includes('crop_')) {
        console.log(`[v17] Found settings chip (has crop icon): "${(btn.textContent || '').trim().substring(0, 50)}"`);
        return btn;
      }
    }
  }

  console.log('[v17] ❌ Settings chip not found! Debug: textbox=' + !!textbox + ', generateBtn=' + !!generateBtn);
  return null;
}

// v17: เปิด Settings Panel (คลิก chip — Radix DropdownMenu)
async function openSettingsPanel() {
  console.log('[v17] Opening settings panel...');

  // เช็คว่า panel เปิดอยู่แล้วหรือไม่
  let panel = findSettingsPanel();
  if (panel) {
    console.log('[v17] Settings panel already open');
    return panel;
  }

  const chip = findSettingsChip();
  if (!chip) {
    console.log('[v17] Cannot open settings panel - chip not found');
    return null;
  }

  // เช็ค data-state ของ chip
  const currentState = chip.getAttribute('data-state');
  console.log(`[v17] Chip found: "${(chip.textContent || '').trim().substring(0, 40)}", data-state: "${currentState}", aria-expanded: "${chip.getAttribute('aria-expanded')}"`);

  // ถ้า chip ปิดอยู่ → คลิกเปิด ด้วย realClick (Radix ต้องใช้ full event chain)
  if (currentState !== 'open') {
    console.log('[v17] Clicking chip to open panel (realClick)...');
    realClick(chip);
    await delay(500);

    // เช็คว่า chip เปลี่ยน state ไหม
    const afterState = chip.getAttribute('data-state');
    console.log(`[v17] After realClick: data-state="${afterState}", aria-expanded="${chip.getAttribute('aria-expanded')}"`);
  }

  // รอ panel โหลด (retry)
  for (let i = 0; i < 10; i++) {
    panel = findSettingsPanel();
    if (panel) {
      console.log('[v17] Settings panel opened successfully');
      return panel;
    }
    const chipState = chip.getAttribute('data-state');
    if (chipState === 'open') {
      console.log(`[v17] Chip is open but panel not detected yet (attempt ${i + 1}/10), waiting...`);
    } else {
      console.log(`[v17] Chip state is "${chipState}" (attempt ${i + 1}/10)`);
    }
    await delay(400);
  }

  console.log('[v17] Settings panel did not appear after clicking chip');
  return null;
}

// v17: หา Settings Panel (DOM verified: div[role="menu"][data-state="open"].sc-46973129-0)
function findSettingsPanel_v17() {
  // วิธี 0 (DOM verified — เร็วสุด): div[role="menu"][data-state="open"] ที่มี button[role="tab"]
  const menus = document.querySelectorAll('div[role="menu"][data-state="open"]');
  for (const menu of menus) {
    if (!isVisible(menu)) continue;
    // settings panel จะมี tab buttons (Image/Video, Landscape/Portrait, x1/x2 ฯลฯ)
    if (menu.querySelector('button[role="tab"]')) {
      console.log('[v17] Found settings panel (div[role="menu"] + tabs)');
      return menu;
    }
  }

  // วิธี 1: sc-46973129-0 (panel class) + data-state="open"
  const scPanel = document.querySelector('div.sc-46973129-0[data-state="open"]');
  if (scPanel && isVisible(scPanel)) {
    console.log('[v17] Found settings panel (sc-46973129-0)');
    return scPanel;
  }

  // วิธี 2: aria-controls จาก chip button
  const chip = document.querySelector('button.sc-46973129-1[data-state="open"]');
  if (chip) {
    const controlsId = chip.getAttribute('aria-controls');
    if (controlsId) {
      const panel = document.getElementById(controlsId);
      if (panel && isVisible(panel)) {
        console.log(`[v17] Found settings panel (aria-controls="${controlsId}")`);
        return panel;
      }
    }
  }

  // วิธี 3: fallback — หา role="menu" ที่มี keyword settings ข้างใน
  for (const menu of menus) {
    if (!isVisible(menu)) continue;
    const text = (menu.textContent || '').toLowerCase();
    if ((text.includes('image') || text.includes('video')) &&
        (text.includes('landscape') || text.includes('portrait') || text.includes('x1'))) {
      console.log('[v17] Found settings panel (role="menu" + keywords)');
      return menu;
    }
  }

  console.log('[v17] ❌ Settings panel not found');
  return null;
}

// v17: คลิก Tab Button ใน Settings Panel ตาม text
// DOM verified: button[role="tab"] class="sc-2ffe4c3-2", data-state="active"/"inactive"
// textContent ตัวอย่าง: "imageImage", "videocamVideo", "crop_9_16Portrait", "x1" ฯลฯ
// → match ด้วย textContent.includes(targetText)
// ⚠️ v17 FIX: panel parameter เป็น optional!
// ถ้าไม่ส่ง → หา settings panel เองใหม่ทุกครั้ง (ป้องกัน stale DOM reference จาก Radix re-render)
// ถ้าส่ง → ใช้ panel ที่ให้มา (เช่น View Mode panel จาก gear button — ไม่ใช่ settings panel)
async function clickToggleInPanel(panelOrText, targetTextOrUndefined) {
  // รองรับทั้ง 2 แบบ: clickToggleInPanel('Image') หรือ clickToggleInPanel(panel, 'Image')
  let panel, targetText;
  if (typeof panelOrText === 'string') {
    // แบบใหม่: clickToggleInPanel('Image') — หา panel เอง
    targetText = panelOrText;
    panel = null;
  } else {
    // แบบเก่า: clickToggleInPanel(panel, 'Image') — ใช้ panel ที่ส่งมา
    panel = panelOrText;
    targetText = targetTextOrUndefined;
  }

  console.log(`[v17] Looking for tab: "${targetText}"...`);

  // ถ้าไม่ได้ส่ง panel มา → หา settings panel ใหม่ทุกครั้ง
  if (!panel) {
    panel = findSettingsPanel();
    if (!panel) {
      console.log('[v17] No settings panel found (may have been re-rendered), retrying...');
      await delay(300);
      panel = findSettingsPanel();
      if (!panel) {
        console.log('[v17] ❌ Settings panel not found after retry');
        return false;
      }
    }
  }

  return await clickToggleInPanel_inner(panel, targetText);
}

// Inner function ที่ทำงานจริง — รับ panel ที่ fresh
async function clickToggleInPanel_inner(panel, targetText) {
  // DOM verified: ทุก tab ใช้ button[role="tab"] ภายใน panel
  const tabs = panel.querySelectorAll('button[role="tab"]');
  console.log(`[v17] Found ${tabs.length} tab buttons in panel`);

  for (const tab of tabs) {
    const text = (tab.textContent || '').trim();

    // match: textContent includes targetText (case-sensitive ก่อน, แล้ว case-insensitive)
    if (text.includes(targetText) || text.toLowerCase().includes(targetText.toLowerCase())) {
      const state = tab.getAttribute('data-state');

      if (state === 'active') {
        console.log(`[v17] Tab "${targetText}" already active ✓`);
        return true;
      }

      console.log(`[v17] Clicking tab: "${text.substring(0, 30)}" (state: ${state})`);
      realClick(tab);
      await delay(500);

      // ⚠️ Verify ด้วย fresh panel reference (element อาจถูก replace แล้ว)
      const freshPanel = findSettingsPanel();
      if (freshPanel) {
        const freshTabs = freshPanel.querySelectorAll('button[role="tab"]');
        for (const ft of freshTabs) {
          const ftText = (ft.textContent || '').trim();
          if (ftText.includes(targetText) || ftText.toLowerCase().includes(targetText.toLowerCase())) {
            const newState = ft.getAttribute('data-state');
            console.log(`[v17] Tab "${targetText}" → ${newState} ${newState === 'active' ? '✓' : '⚠️'}`);
            break;
          }
        }
      }
      return true;
    }
  }

  console.log(`[v17] ❌ Tab "${targetText}" not found! Available tabs: [${Array.from(tabs).map(t => '"' + (t.textContent || '').trim().substring(0, 20) + '"').join(', ')}]`);
  return false;
}

// v17: คลิก Sidebar Filter (all/images/videos) — 3 icons ทางซ้าย
async function clickSidebarFilter(filterType = 'all') {
  console.log(`[v17] Clicking sidebar filter: ${filterType}`);

  // Sidebar อยู่ทางซ้ายสุด มี 3 ไอคอน stacked vertically
  // บนสุด: all (grid icon), กลาง: images, ล่างสุด: videos
  const sidebar = document.querySelector('nav, [role="navigation"], [role="tablist"]');

  // หาทุกปุ่มที่อยู่ทางซ้ายสุด
  const allButtons = Array.from(document.querySelectorAll('button, [role="tab"], [role="radio"]'));
  const leftButtons = allButtons.filter(btn => {
    if (btn.offsetParent === null) return false;
    const rect = btn.getBoundingClientRect();
    // ต้องอยู่ทางซ้ายมากๆ (sidebar)
    return rect.left < 80 && rect.width < 80 && rect.height < 80;
  });

  // Sort by vertical position
  leftButtons.sort((a, b) => {
    return a.getBoundingClientRect().top - b.getBoundingClientRect().top;
  });

  console.log(`[v17] Found ${leftButtons.length} sidebar buttons`);

  if (leftButtons.length >= 2) {
    let targetIndex;
    switch (filterType) {
      case 'all':
        targetIndex = 0; // บนสุด
        break;
      case 'images':
        targetIndex = 1; // กลาง
        break;
      case 'videos':
        targetIndex = leftButtons.length >= 3 ? 2 : leftButtons.length - 1; // ล่างสุด
        break;
      default:
        targetIndex = 0;
    }

    if (targetIndex < leftButtons.length) {
      const btn = leftButtons[targetIndex];
      const isSelected = btn.getAttribute('aria-selected') === 'true' ||
                         btn.getAttribute('aria-pressed') === 'true' ||
                         btn.getAttribute('data-state') === 'on' ||
                         btn.classList.contains('selected') ||
                         btn.classList.contains('active');

      if (isSelected) {
        console.log(`[v17] Sidebar filter "${filterType}" already selected`);
        return true;
      }

      console.log(`[v17] Clicking sidebar filter[${targetIndex}]: "${(btn.textContent || '').trim().substring(0, 20)}"`);
      btn.click();
      await delay(500);
      return true;
    }
  }

  // Fallback: หาจาก aria-label หรือ title
  for (const btn of allButtons) {
    if (btn.offsetParent === null) continue;
    const rect = btn.getBoundingClientRect();
    if (rect.left > 100) continue;

    const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();
    const title = (btn.getAttribute('title') || '').toLowerCase();
    const text = (ariaLabel + ' ' + title).trim();

    let isMatch = false;
    if (filterType === 'all' && (text.includes('all') || text.includes('ทั้งหมด'))) isMatch = true;
    if (filterType === 'images' && (text.includes('image') || text.includes('รูปภาพ') || text.includes('photo'))) isMatch = true;
    if (filterType === 'videos' && (text.includes('video') || text.includes('วิดีโอ'))) isMatch = true;

    if (isMatch) {
      console.log(`[v17] Clicking sidebar filter (by label): ${text}`);
      btn.click();
      await delay(500);
      return true;
    }
  }

  console.log(`[v17] Sidebar filter "${filterType}" not found`);
  return false;
}

// v17.3: ดึง ID หลักจาก Google image URL (ตัด size params ออก)
// Google ใช้ = แทน ? สำหรับ resize: =w1024-h768, =w200-h200-s-no, =s800 ฯลฯ
function extractGoogleImageId(url) {
  if (!url) return '';
  let clean = url.split('?')[0];           // ตัด ?query
  clean = clean.replace(/=w\d+.*$/, '');    // ตัด =w200-h200...
  clean = clean.replace(/=s\d+.*$/, '');    // ตัด =s800...
  clean = clean.replace(/=h\d+.*$/, '');    // ตัด =h600...
  return clean;
}

// v17: Animate ภาพที่สร้างแล้ว (hover → 3-dot → Animate)
// REWRITTEN: ใช้เทคนิคจาก findThreeDotsMenuNearElement + findDeleteButtonInMenu ที่ทำงานได้ดี
// v17.3: เพิ่ม sceneIndex/totalScenes สำหรับ position fallback (Story Mode)
// v4.5.8: ดักว่า media card เป็น "วิดีโอ" ไหม — ใช้ logic แม่นเท่า countVideoCards
//   เดิม animate ดักแค่ play_arrow/<video> → พลาด UI ใหม่ (img[alt="Video thumbnail"] + duration badge)
//   → card วิดีโอเล็ดลอดมาเป็น "ภาพ" → bot กด 3 จุดบนคลิป → หา Animate ไม่เจอ
function _pdCardIsVideo(card) {
  if (!card) return false;
  try {
    if (card.querySelector('img[alt="Video thumbnail"]')) return true;
    if (card.querySelector('video')) return true;
    const t = (card.textContent || '').toLowerCase();
    if (t.includes('play_arrow') || t.includes('play_circle')) return true;
    if (/\d:\d{2}/.test(card.textContent || '')) return true; // duration badge เช่น 0:08
  } catch (_) {}
  return false;
}

async function animateGeneratedImage(imageUrl, sceneIndex = -1, totalScenes = -1, _fullRetryCount = 0) {
  console.log('[v17] Starting Animate flow...');
  console.log('[v17] Target image URL:', imageUrl ? imageUrl.substring(0, 80) : 'none');

  // === Step 1: หา media card ที่เป็นภาพ (ไม่ใช่ video/failed) ===
  let targetTile = null;
  let targetImg = null;

  // วิธี 1: หาจาก URL ที่ตรงกัน → ไล่ parent ขึ้นไปหา media card
  if (imageUrl) {
    const allImages = document.querySelectorAll('img');
    const imageId = extractGoogleImageId(imageUrl);
    for (const img of allImages) {
      const imgId = extractGoogleImageId(img.src);
      if (img.src === imageUrl || (imageId && imgId && imgId === imageId)) {
        targetImg = img;
        // ใช้ .sc-5923b123-0 (media card class ที่ verified แล้ว) ก่อน
        targetTile = img.closest('.sc-5923b123-0');
        if (!targetTile) {
          // Fallback: ไล่ parent หา element ที่มีขนาดเหมาะสม
          let el = img.parentElement;
          for (let i = 0; i < 8 && el; i++) {
            if (el.className?.includes('sc-5923b123-0')) { targetTile = el; break; }
            const r = el.getBoundingClientRect();
            if (r.width > 80 && r.width < 500 && r.height > 80 && r.height < 700) {
              targetTile = el;
              break;
            }
            el = el.parentElement;
          }
        }
        // v4.5.8: ถ้า card ที่ match เป็น "วิดีโอ" (เช่น video thumbnail ที่ url ใกล้กัน) → ข้าม หาต่อ
        if (targetTile && _pdCardIsVideo(targetTile)) {
          console.log('[v17] URL match เจอ card วิดีโอ → ข้าม หา image card ต่อ');
          targetTile = null; targetImg = null;
          continue;
        }
        if (targetTile) {
          console.log('[v17] Found target image by URL match');
          break;
        }
      }
    }
  }

  // วิธี 2: Story Mode position fallback — ใช้ sceneIndex เลือกภาพที่ถูกตัว
  if (!targetTile && sceneIndex >= 0 && totalScenes > 0) {
    console.log(`[v17] URL match failed, trying Story position fallback (scene ${sceneIndex}/${totalScenes})...`);
    const mediaCards = document.querySelectorAll('.sc-5923b123-0');
    const imageCards = [];
    for (const card of mediaCards) {
      if (!isVisible(card)) continue;
      const text = (card.textContent || '').toLowerCase();
      if (text.includes('failed') || _pdCardIsVideo(card)) continue; // v4.5.8: ดักวิดีโอแม่นขึ้น
      if (card.querySelector('img') && isVisible(card.querySelector('img'))) {
        imageCards.push(card);
      }
    }
    // Gallery: ใหม่สุดซ้าย → เก่าสุดขวา
    // ฉาก 1 = เก่าสุด = ขวาสุด = imageCards[length-1]
    // ฉาก N = imageCards[length - sceneIndex]  (sceneIndex 1-based)
    const idx = imageCards.length - sceneIndex;
    if (idx >= 0 && idx < imageCards.length) {
      targetTile = imageCards[idx];
      targetImg = targetTile.querySelector('img');
      console.log(`[v17] Story position fallback: scene ${sceneIndex}, picked card index ${idx}/${imageCards.length}`);
    }
  }

  // วิธี 2b: หาจาก media cards (.sc-5923b123-0) โดยตรง — เอาภาพแรกที่ไม่ใช่ failed/video
  if (!targetTile) {
    console.log('[v17] URL match failed, trying media cards (.sc-5923b123-0)...');
    const mediaCards = document.querySelectorAll('.sc-5923b123-0');
    for (const card of mediaCards) {
      if (!isVisible(card)) continue;
      const text = (card.textContent || '').toLowerCase();
      // ข้าม Failed cards
      if (text.includes('failed')) continue;
      // ข้าม Video cards — v4.5.8: ดักวิดีโอแม่นขึ้น (รวม img[alt="Video thumbnail"] + duration)
      if (_pdCardIsVideo(card)) continue;
      // ต้องมี img element (และไม่ใช่ video thumbnail)
      const img = card.querySelector('img');
      if (img && isVisible(img)) {
        targetTile = card;
        targetImg = img;
        console.log('[v17] Found image via media card (.sc-5923b123-0)');
        break;
      }
    }
  }

  // วิธี 3: Fallback — หา img ที่ visible แล้วไล่ขึ้นไป
  if (!targetTile) {
    console.log('[v17] Trying visible images fallback...');
    const allImages = document.querySelectorAll('img[src*="blob:"], img[src*="googleusercontent"], img[src*="gstatic"]');
    for (const img of allImages) {
      if (!isVisible(img)) continue;
      const rect = img.getBoundingClientRect();
      if (rect.width < 50 || rect.height < 50) continue;

      let tile = img.closest('.sc-5923b123-0');
      if (!tile) {
        let el = img.parentElement;
        for (let i = 0; i < 8 && el; i++) {
          const r = el.getBoundingClientRect();
          if (r.width > 80 && r.width < 500 && r.height > 80 && r.height < 700) {
            tile = el; break;
          }
          el = el.parentElement;
        }
      }
      if (tile) {
        const tileText = (tile.textContent || '').toLowerCase();
        // v4.5.8: ข้าม video thumbnail + failed + duration
        if (tileText.includes('failed') || img.alt === 'Video thumbnail' || _pdCardIsVideo(tile)) continue;
        targetTile = tile;
        targetImg = img;
        console.log('[v17] Found image tile by visible img fallback');
        break;
      }
    }
  }

  if (!targetTile) {
    console.log('[v17] ❌ No image tile found for Animate');
    throw new Error('ไม่พบภาพสำหรับ Animate');
  }

  console.log('[v17] Found target tile, attempting hover + find 3-dot...');

  // === v2.1: สร้าง overlay ใสบังเม้าส์จริงของผู้ใช้ ===
  // ป้องกัน mouseleave/pointerleave ที่เกิดจากผู้ใช้ขยับเม้าส์ ทำให้เมนู 3-dot หายไป
  let mouseBlockOverlay = document.createElement('div');
  mouseBlockOverlay.id = 'pd-animate-mouse-block';
  mouseBlockOverlay.style.cssText = 'position:fixed;top:0;left:0;width:100vw;height:100vh;z-index:2147483647;cursor:wait;background:rgba(0,0,0,0.01);pointer-events:all;';
  document.body.appendChild(mouseBlockOverlay);
  console.log('[v17] 🛡️ Mouse block overlay created — ป้องกันเม้าส์ผู้ใช้รบกวน');

  // cleanup function — ลบ overlay เมื่อจบ flow
  const removeMouseBlock = () => {
    const overlay = document.getElementById('pd-animate-mouse-block');
    if (overlay) overlay.remove();
    console.log('[v17] 🛡️ Mouse block overlay removed');
  };

  // === Step 2: Hover tile ด้วย PointerEvent chain (สำคัญสำหรับ Radix UI!) ===
  // ห้ามใช้แค่ MouseEvent — Radix ฟัง PointerEvent เป็นหลัก
  const tileRect = targetTile.getBoundingClientRect();
  const cx = tileRect.left + tileRect.width / 2;
  const cy = tileRect.top + tileRect.height / 2;
  const hoverOpts = {
    bubbles: true, cancelable: true, view: window,
    clientX: cx, clientY: cy,
    pointerId: 1, pointerType: 'mouse'
  };

  function dispatchHoverEvents(el) {
    el.dispatchEvent(new PointerEvent('pointerover', hoverOpts));
    el.dispatchEvent(new PointerEvent('pointerenter', { ...hoverOpts, bubbles: false }));
    el.dispatchEvent(new MouseEvent('mouseenter', { ...hoverOpts, bubbles: false }));
    el.dispatchEvent(new MouseEvent('mouseover', hoverOpts));
    el.dispatchEvent(new PointerEvent('pointermove', hoverOpts));
    el.dispatchEvent(new MouseEvent('mousemove', hoverOpts));
  }

  dispatchHoverEvents(targetTile);
  if (targetImg) dispatchHoverEvents(targetImg);
  await delay(600);

  // === Step 3: หาปุ่ม 3-dot (retry หลายรอบ เพราะอาจต้องรอ hover render) ===
  let moreButton = null;

  for (let retry = 0; retry < 6; retry++) {
    // วิธี 1 (ดีที่สุด): button[aria-haspopup="menu"] ใน tile
    // — เดียวกับที่ findThreeDotsMenuNearElement ใช้ได้สำเร็จ
    const menuBtnsInTile = targetTile.querySelectorAll('button[aria-haspopup="menu"]');
    for (const btn of menuBtnsInTile) {
      if (btn.className?.includes('sc-46973129')) continue; // ข้าม settings chip
      moreButton = btn;
      console.log('[v17] Found 3-dot button via aria-haspopup="menu" in tile');
      break;
    }
    if (moreButton) break;

    // วิธี 2: button[aria-haspopup="menu"] ทั้งหน้า ที่อยู่ภายใน tile bounds
    const allMenuBtns = document.querySelectorAll('button[aria-haspopup="menu"]');
    let closestBtn = null;
    let closestDist = Infinity;
    for (const btn of allMenuBtns) {
      const rect = btn.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) continue;
      if (btn.className?.includes('sc-46973129')) continue;
      // เช็คว่าอยู่ภายในขอบเขต tile (±30px)
      const btnCx = rect.left + rect.width / 2;
      const btnCy = rect.top + rect.height / 2;
      if (btnCx >= tileRect.left - 30 && btnCx <= tileRect.right + 30 &&
          btnCy >= tileRect.top - 30 && btnCy <= tileRect.bottom + 30) {
        const dist = Math.abs(btnCx - tileRect.right) + Math.abs(btnCy - tileRect.top);
        if (dist < closestDist) {
          closestDist = dist;
          closestBtn = btn;
        }
      }
    }
    if (closestBtn) {
      moreButton = closestBtn;
      console.log('[v17] Found 3-dot button via position-based search (dist:', closestDist.toFixed(0), ')');
      break;
    }

    // วิธี 3: หาจาก aria-label/text ใน tile
    const tileButtons = targetTile.querySelectorAll('button, [role="button"]');
    for (const btn of tileButtons) {
      const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();
      const text = (btn.textContent || '').trim().toLowerCase();
      const title = (btn.getAttribute('title') || '').toLowerCase();
      if (ariaLabel.includes('more') || ariaLabel.includes('option') || ariaLabel.includes('menu') ||
          text.includes('more_vert') || text.includes('more_horiz') || text === '⋮' || text === '...' ||
          title.includes('more') || title.includes('option')) {
        moreButton = btn;
        console.log('[v17] Found 3-dot button by aria-label/text');
        break;
      }
    }
    if (moreButton) break;

    // วิธี 4: หา button เล็กๆ บน tile (ไม่ check offsetParent — ใช้ getBoundingClientRect แทน)
    for (const btn of tileButtons) {
      const rect = btn.getBoundingClientRect();
      // ข้าม element ที่ไม่มีขนาดเลย (ไม่ได้ render)
      if (rect.width === 0 && rect.height === 0) continue;
      if (rect.width < 50 && rect.height < 50) {
        const btnText = (btn.textContent || '').trim().toLowerCase();
        if (!btnText.includes('favorite') && !btnText.includes('heart') && !btnText.includes('share')) {
          moreButton = btn;
          console.log('[v17] Found 3-dot button (small button on tile)');
          break;
        }
      }
    }
    if (moreButton) break;

    // Retry: dispatch hover อีกครั้ง + รอนานขึ้น
    console.log(`[v17] 3-dot not found, retrying hover (${retry + 1}/6)...`);
    dispatchHoverEvents(targetTile);
    if (targetImg) dispatchHoverEvents(targetImg);
    await delay(600 + retry * 200);
  }

  if (!moreButton) {
    console.log('[v17] ❌ 3-dot button not found after 6 retries');
    removeMouseBlock();
    throw new Error('ไม่พบปุ่ม 3-dot บนภาพ');
  }

  // === Step 4: คลิก 3-dot เพื่อเปิดเมนู (ใช้ realClick สำหรับ Radix UI) ===
  console.log('[v17] Clicking 3-dot button...');
  realClick(moreButton);
  await delay(800);

  // === Step 5: หา "Animate" ในเมนู (retry + ใช้ Radix Popper) ===
  let animateItem = null;

  for (let retry = 0; retry < 6; retry++) {
    // วิธี 1 (ดีที่สุด): หาใน Radix Popper Wrapper — เดียวกับ findDeleteButtonInMenu ที่ทำงานได้
    const radixPoppers = document.querySelectorAll('[data-radix-popper-content-wrapper]');
    for (const popper of radixPoppers) {
      if (popper.getBoundingClientRect().width === 0) continue;
      const menuItems = popper.querySelectorAll('[role="menuitem"]');
      for (const item of menuItems) {
        const text = (item.textContent || '').trim();
        // Animate มักเป็นตัวเลือกแรกในเมนู
        if (text.includes('Animate') || text.includes('animate') || text.includes('แอนิเมชัน')) {
          animateItem = item;
          console.log(`[v17] Found Animate in radix popper: "${text}"`);
          break;
        }
      }
      if (animateItem) break;
    }
    if (animateItem) break;

    // วิธี 2: หาจาก role="menuitem" ทั่วไป
    const menuItems = document.querySelectorAll('[role="menuitem"], [role="option"]');
    for (const item of menuItems) {
      if (!isVisible(item)) continue;
      const text = (item.textContent || '').trim();
      if (text.includes('Animate') || text.includes('animate') || text.includes('แอนิเมชัน')) {
        animateItem = item;
        console.log(`[v17] Found Animate menu item: "${text}"`);
        break;
      }
    }
    if (animateItem) break;

    // วิธี 3: Fallback — หาจากทุก visible element ที่มีข้อความ Animate
    const allElements = document.querySelectorAll('div, span, button, li, a');
    for (const el of allElements) {
      if (!isVisible(el)) continue;
      const text = (el.textContent || '').trim();
      const rect = el.getBoundingClientRect();
      if ((text === 'Animate' || text === 'animate') && rect.width < 300 && rect.height < 60) {
        animateItem = el;
        console.log('[v17] Found Animate option (visible element fallback)');
        break;
      }
    }
    if (animateItem) break;

    console.log(`[v17] Animate not found, retrying (${retry + 1}/6)...`);
    await delay(500);
  }

  if (!animateItem) {
    console.log('[v17] ❌ Animate option not found in menu');
    // ปิดเมนู
    document.body.click();
    await delay(200);
    removeMouseBlock();
    throw new Error('ไม่พบตัวเลือก Animate ในเมนู');
  }

  // === Step 6: คลิก Animate + verify ว่า UI เปลี่ยนจริง (retry ถ้าคลิกไม่ติด) ===
  for (let clickRetry = 0; clickRetry < 3; clickRetry++) {
    console.log(`[v17] Clicking Animate... (attempt ${clickRetry + 1}/3)`);
    realClick(animateItem);
    await delay(2000);

    // Verify: เช็คว่า UI เปลี่ยนไป video mode จริง
    // สัญญาณ: settings chip แสดง "Video" / มี video-related UI / เมนู Animate หายไป
    const settingsChip = findSettingsChip();
    const chipText = settingsChip ? (settingsChip.textContent || '').toLowerCase() : '';
    const menuStillOpen = document.querySelector('[data-radix-popper-content-wrapper]');
    const hasVideoIndicator = chipText.includes('video') || chipText.includes('veo') ||
                              chipText.includes('fast') || chipText.includes('quality');

    if (hasVideoIndicator) {
      console.log('[v17] ✅ Animate confirmed — UI switched to video mode');
      removeMouseBlock();
      return true;
    }

    // เมนูหายไปแล้ว (ปิดตัว) → น่าจะสำเร็จ
    if (!menuStillOpen) {
      console.log('[v17] ✅ Animate clicked — menu closed (assuming success)');
      removeMouseBlock();
      return true;
    }

    // เมนูยังเปิดอยู่ → คลิกไม่ติด → ลองอีก
    console.log(`[v17] ⚠️ Animate click may not have registered (menu still open), retrying...`);
    // ปิดเมนูก่อน แล้วเปิดใหม่
    document.body.click();
    await delay(500);

    // ลอง hover + กด 3-dot + หา Animate ใหม่
    dispatchHoverEvents(targetTile);
    if (targetImg) dispatchHoverEvents(targetImg);
    await delay(800);

    // v17.6: Re-find 3-dot button (DOM อาจเปลี่ยนหลัง close/re-hover — ห้ามใช้ reference เก่า)
    const refreshedBtns = targetTile.querySelectorAll('button[aria-haspopup="menu"]');
    for (const btn of refreshedBtns) {
      if (btn.className?.includes('sc-46973129')) continue;
      moreButton = btn;
      break;
    }
    realClick(moreButton);
    await delay(800);

    // หา Animate อีกครั้ง
    const radixPoppers = document.querySelectorAll('[data-radix-popper-content-wrapper]');
    for (const popper of radixPoppers) {
      if (popper.getBoundingClientRect().width === 0) continue;
      const menuItems = popper.querySelectorAll('[role="menuitem"]');
      for (const item of menuItems) {
        const text = (item.textContent || '').trim();
        if (text.includes('Animate') || text.includes('animate')) {
          animateItem = item;
          break;
        }
      }
      if (animateItem) break;
    }
  }

  // v17.6: Full retry — เริ่มใหม่ทั้ง flow (หารูป → hover → 3-dot → Animate) ไม่ใช่แค่ retry click
  removeMouseBlock(); // ลบ overlay ก่อน retry
  if (_fullRetryCount < 2) {
    console.log(`[v17] 🔄 Animate full retry (${_fullRetryCount + 1}/2) — เริ่มหารูปใหม่ทั้งหมด...`);
    document.body.click(); // ปิดเมนูค้าง
    await delay(2000);
    return animateGeneratedImage(imageUrl, sceneIndex, totalScenes, _fullRetryCount + 1);
  }
  console.log('[v17] ❌ Animate click failed after all full retries');
  throw new Error('Animate click ไม่สำเร็จหลังลองใหม่ทั้งหมด 3 รอบ');
}

// ===============================================
// v17: REWRITTEN STEP FUNCTIONS
// ===============================================

// Step 1 สำหรับ Image Mode: เปิด settings panel → คลิก "Image" toggle
// v17: step1_SelectImageMode — ไม่ต้องเปิด panel แยกอีกแล้ว
// รวมเข้า step2_ConfigureSettings() ที่เปิด panel ครั้งเดียวแล้วเซ็ทค่าทุกอย่าง
async function step1_SelectImageMode() {
  console.log('=== [v17] Step 1: Image mode — will be set in step2 (single panel open) ===');
  // ไม่ต้องทำอะไร — step2_ConfigureSettings() จะเลือก mode ให้
}

// ปิด popups/panels ที่อาจค้างอยู่ (ก่อนเริ่มสร้างคลิปใหม่)
async function closeAnyOpenPanels() {
  console.log('🧹 Cleaning up before starting...');

  // ตรวจสอบว่ามี settings panel เปิดอยู่ไหม
  const settingsPanel = findSettingsPanel();
  if (settingsPanel) {
    console.log('📋 Settings panel is open, closing it...');
    // คลิกนอก panel เพื่อปิด
    document.body.click();
    await delay(300);
  }

  // ตรวจสอบว่ามี crop dialog เปิดอยู่ไหม (v17: เพิ่ม Crop frame)
  const cropDialogTexts = ['ครอบตัดส่วนผสม', 'Crop ingredient', 'ครอบตัดเฟรม', 'Crop frame', 'Crop start', 'Crop'];
  const hasCropDialog = Array.from(document.querySelectorAll('*')).some(el => {
    const text = el.textContent || '';
    return cropDialogTexts.some(t => text.includes(t)) && el.offsetParent !== null;
  });

  if (hasCropDialog) {
    console.log('✂️ Crop dialog is open, pressing Escape...');
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    await delay(300);
  }

  // ตรวจสอบว่ามี image picker/upload dialog เปิดอยู่ไหม
  const uploadDialogTexts = ['อัปโหลด', 'Upload', 'แกลเลอรี', 'Gallery'];
  const hasUploadDialog = Array.from(document.querySelectorAll('[role="dialog"], [class*="modal"], [class*="popup"]')).some(el => {
    const text = el.textContent || '';
    return uploadDialogTexts.some(t => text.includes(t)) && el.offsetParent !== null;
  });

  if (hasUploadDialog) {
    console.log('📤 Upload dialog is open, closing...');
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    await delay(300);
  }

  // ตรวจสอบว่ามี dropdown เปิดอยู่ไหม
  const openDropdowns = document.querySelectorAll('[role="listbox"], [role="menu"], [class*="dropdown-menu"]');
  for (const dropdown of openDropdowns) {
    if (dropdown.offsetParent !== null) {
      console.log('📜 Dropdown is open, clicking outside...');
      document.body.click();
      await delay(200);
      break;
    }
  }

  // ตรวจสอบว่ามี backdrop/overlay ค้างอยู่ไหม
  const backdrops = document.querySelectorAll('[class*="backdrop"], [class*="overlay"]:not(#pd-bot-overlay)');
  for (const backdrop of backdrops) {
    if (backdrop.offsetParent !== null) {
      const rect = backdrop.getBoundingClientRect();
      // backdrop มักจะเป็น full screen
      if (rect.width > window.innerWidth * 0.8 && rect.height > window.innerHeight * 0.8) {
        console.log('🎭 Backdrop found, clicking...');
        backdrop.click();
        await delay(200);
      }
    }
  }

  // สุดท้าย คลิกที่ body อีกครั้งเพื่อให้แน่ใจ
  document.body.click();
  await delay(100);

  console.log('🧹 Cleanup complete');
}

// v15: ฟังก์ชันลบ reference images ที่ค้างอยู่ในพื้นที่ prompt (สำหรับ Story Mode ฉากที่ 2+)
async function clearReferenceImages() {
  console.log('[v15] 🗑️ Clearing existing reference images...');

  // Reset clickedButtonPositions เพื่อให้หาปุ่ม + ใหม่ได้
  clickedButtonPositions = [];

  // หา prompt area container
  const promptArea = findPromptAreaContainer();
  if (!promptArea) {
    console.log('[v15] No prompt area found, nothing to clear');
    return 0;
  }

  let clearedCount = 0;

  // หาปุ่มลบรูป (X, close, delete icons) ภายใน prompt area
  // รูป reference มักจะมีปุ่ม X อยู่มุมบนขวา
  const closeIconNames = ['close', 'cancel', 'delete', 'remove', 'clear'];
  const removeButtons = [];

  // วิธี 1: หาจาก google-symbols icon ที่มีชื่อ close/delete
  const allIcons = promptArea.querySelectorAll('i.google-symbols, i[class*="google-symbols"]');
  for (const icon of allIcons) {
    const text = (icon.textContent || '').trim().toLowerCase();
    if (closeIconNames.includes(text)) {
      const clickable = icon.closest('button') || icon.closest('[role="button"]') || icon.parentElement;
      if (clickable) {
        removeButtons.push(clickable);
      }
    }
  }

  // วิธี 2: หาปุ่มเล็กๆ ที่มี aria-label เป็น remove/close/delete
  const allButtons = promptArea.querySelectorAll('button, [role="button"]');
  for (const btn of allButtons) {
    const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();
    const title = (btn.getAttribute('title') || '').toLowerCase();
    if (closeIconNames.some(name => ariaLabel.includes(name) || title.includes(name))) {
      if (!removeButtons.includes(btn)) {
        removeButtons.push(btn);
      }
    }
  }

  // วิธี 3: หา container ที่มีรูป thumbnail และมีปุ่ม X
  const thumbnailContainers = promptArea.querySelectorAll('[class*="thumbnail"], [class*="preview"], [class*="image-container"]');
  for (const container of thumbnailContainers) {
    const img = container.querySelector('img');
    if (img && img.src && img.src.length > 0) {
      // หาปุ่มลบในนี้
      const closeBtn = container.querySelector('button');
      if (closeBtn && !removeButtons.includes(closeBtn)) {
        const rect = closeBtn.getBoundingClientRect();
        // ปุ่มลบมักจะเล็ก (<50px)
        if (rect.width < 50 && rect.height < 50) {
          removeButtons.push(closeBtn);
        }
      }
    }
  }

  console.log(`[v15] Found ${removeButtons.length} potential remove buttons`);

  // กดปุ่มลบทุกอัน (กดจากขวาไปซ้ายเพื่อไม่ให้ index เลื่อน)
  for (let i = removeButtons.length - 1; i >= 0; i--) {
    const btn = removeButtons[i];
    try {
      console.log(`[v15] Clicking remove button ${i + 1}...`);
      btn.click();
      clearedCount++;
      await delay(300);
    } catch (e) {
      console.log(`[v15] Could not click remove button: ${e.message}`);
    }
  }

  // กด Escape เพื่อปิด dialog ที่อาจค้างอยู่
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  await delay(200);

  console.log(`[v15] Cleared ${clearedCount} reference images`);
  return clearedCount;
}

// v17.2: หาและกดปุ่ม "Reuse prompt" บนรูปที่สร้างล่าสุด
// ปุ่มนี้อยู่ข้างปุ่ม 3 จุด (kebab menu)
// เมื่อกดแล้วจะข้ามขั้นตอนอัพโหลดรูป+crop ไปหน้า prompt เลย (ref images + settings คงอยู่)
// สำคัญ: ต้องใช้ realClick() สำหรับ Radix UI!
async function clickReusePromptButton() {
  console.log('[v17.2] 🔄 Looking for Reuse Prompt button...');

  // หารูปที่สร้างล่าสุด — ใช้ media card container (.sc-5923b123-0) เหมือน animateGeneratedImage
  const mediaCards = document.querySelectorAll('.sc-5923b123-0');
  const generatedImages = [];

  // วิธี 1: หาจาก media card (Radix UI)
  for (const card of mediaCards) {
    const img = card.querySelector('img');
    if (!img) continue;
    const rect = card.getBoundingClientRect();
    if (rect.width > 80 && rect.height > 80 && rect.top < window.innerHeight) {
      // ข้าม video thumbnails
      const altText = (img.getAttribute('alt') || '').toLowerCase();
      if (altText.includes('video thumbnail')) continue;
      generatedImages.push({ img, parent: card, rect, isMediaCard: true });
    }
  }

  // วิธี 2: fallback หาจาก img ขนาดใหญ่ (เหมือนเดิม)
  if (generatedImages.length === 0) {
    const allImages = document.querySelectorAll('img');
    for (const img of allImages) {
      const rect = img.getBoundingClientRect();
      if (rect.width > 100 && rect.height > 100 && rect.top < window.innerHeight) {
        const parent = img.closest('[class*="card"], [class*="item"], [class*="gallery"], [class*="generated"]') || img.parentElement?.parentElement;
        if (parent) {
          generatedImages.push({ img, parent, rect, isMediaCard: false });
        }
      }
    }
  }

  console.log(`[v17.2] Found ${generatedImages.length} potential generated images`);

  // เรียงจากล่างสุด (ใหม่สุด) ไปบนสุด
  generatedImages.sort((a, b) => b.rect.top - a.rect.top);

  // === ต้อง hover ก่อน เพื่อให้ปุ่มปรากฏ (Radix UI ซ่อนปุ่มจน hover) ===
  for (const { img, parent, rect, isMediaCard } of generatedImages) {
    const container = isMediaCard ? parent : (parent.parentElement || parent);

    // Hover card เพื่อให้ปุ่มปรากฏ (pattern จาก animateGeneratedImage)
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    const hoverOpts = {
      bubbles: true, cancelable: true, view: window,
      clientX: cx, clientY: cy,
      pointerId: 1, pointerType: 'mouse'
    };

    function dispatchHoverForReuse(el) {
      el.dispatchEvent(new PointerEvent('pointerover', hoverOpts));
      el.dispatchEvent(new PointerEvent('pointerenter', { ...hoverOpts, bubbles: false }));
      el.dispatchEvent(new MouseEvent('mouseenter', { ...hoverOpts, bubbles: false }));
      el.dispatchEvent(new MouseEvent('mouseover', hoverOpts));
      el.dispatchEvent(new PointerEvent('pointermove', hoverOpts));
      el.dispatchEvent(new MouseEvent('mousemove', hoverOpts));
    }

    dispatchHoverForReuse(container);
    dispatchHoverForReuse(img);
    let hoverParent = container.parentElement;
    for (let i = 0; i < 3 && hoverParent; i++) {
      dispatchHoverForReuse(hoverParent);
      hoverParent = hoverParent.parentElement;
    }
    await delay(800);

    // หาปุ่มในบริเวณใกล้รูป
    const buttons = container.querySelectorAll('button, [role="button"]');

    for (const btn of buttons) {
      const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();
      const title = (btn.getAttribute('title') || '').toLowerCase();
      const text = (btn.textContent || '').toLowerCase().trim();

      // หาจาก aria-label หรือ title ที่มีคำว่า reuse, use prompt, copy prompt ฯลฯ
      const reuseKeywords = ['reuse', 'use prompt', 'copy prompt', 'use in', 'new prompt', 'use settings'];
      const isReuseButton = reuseKeywords.some(kw =>
        ariaLabel.includes(kw) || title.includes(kw) || text.includes(kw)
      );

      if (isReuseButton) {
        console.log(`[v17.2] ✅ Found Reuse button via keyword: "${ariaLabel || title || text}"`);
        realClick(btn);
        await delay(1500);
        return true;
      }

      // หาจาก icon (tune / settings_backup_restore)
      const icon = btn.querySelector('i, svg, [class*="icon"]');
      if (icon) {
        const iconText = (icon.textContent || '').toLowerCase();
        const iconClass = (icon.className || '').toLowerCase();
        if (iconText.includes('tune') || iconText.includes('settings_backup_restore') ||
            iconClass.includes('tune') || iconClass.includes('restore')) {
          console.log(`[v17.2] ✅ Found Reuse button via icon: "${iconText || iconClass}"`);
          realClick(btn);
          await delay(1500);
          return true;
        }
      }
    }

    // หาปุ่มข้างๆ kebab menu (3 จุด)
    // ปุ่ม Reuse มักอยู่ติดกับปุ่ม 3 จุด
    let kebabMenu = container.querySelector('button[aria-haspopup="menu"]');
    if (kebabMenu && kebabMenu.className?.includes('sc-46973129')) kebabMenu = null; // skip settings gear

    if (!kebabMenu) {
      kebabMenu = container.querySelector('[aria-label*="more"], [aria-label*="menu"], [aria-label*="options"]');
    }

    if (kebabMenu) {
      // หาปุ่มที่อยู่ข้างๆ kebab menu
      const siblingBtn = kebabMenu.previousElementSibling || kebabMenu.nextElementSibling;
      if (siblingBtn && (siblingBtn.tagName === 'BUTTON' || siblingBtn.getAttribute('role') === 'button')) {
        const siblingLabel = (siblingBtn.getAttribute('aria-label') || '').toLowerCase();
        // ถ้าไม่ใช่ปุ่มที่รู้จัก (download, like, share, favorite, heart) → น่าจะเป็น reuse
        const knownButtons = ['download', 'like', 'share', 'delete', 'favorite', 'heart'];
        if (!knownButtons.some(kw => siblingLabel.includes(kw))) {
          console.log(`[v17.2] ✅ Found Reuse button next to kebab menu: "${siblingLabel}"`);
          realClick(siblingBtn);
          await delay(1500);
          return true;
        }
      }
    }
  }

  // Debug: Log all buttons found for manual inspection
  console.log('[v17.2] ❌ Reuse button not found. Dumping buttons for debug:');
  for (const { parent } of generatedImages.slice(0, 2)) {
    const container = parent.parentElement || parent;
    const buttons = container.querySelectorAll('button, [role="button"]');
    buttons.forEach((btn, i) => {
      console.log(`  [${i}] aria-label="${btn.getAttribute('aria-label')}" title="${btn.getAttribute('title')}" text="${btn.textContent?.substring(0, 30)}"`);
    });
  }

  return false;
}

