// v18: บังคับ "Clear prompt on submit" = On
// ถ้า Off → prompt เก่าค้างหลัง Generate → บอทวาง prompt ใหม่ซ้อน → พัง
async function ensureClearPromptOnSubmit(panel) {
  console.log('🧹 [v18] Checking "Clear prompt on submit"...');

  // หาทุก row/container ใน panel ที่มี text "Clear prompt"
  const allElements = panel.querySelectorAll('*');
  let clearPromptRow = null;

  for (const el of allElements) {
    // หา element ที่มี text ตรงๆ (ไม่ใช่ nested children ที่ text ยาว)
    const directText = Array.from(el.childNodes)
      .filter(n => n.nodeType === Node.TEXT_NODE)
      .map(n => n.textContent.trim())
      .join('');
    const fullText = (el.textContent || '').trim();

    if (directText.toLowerCase().includes('clear prompt') ||
        (fullText.toLowerCase().includes('clear prompt') && fullText.length < 80)) {
      clearPromptRow = el;
      break;
    }
  }

  if (!clearPromptRow) {
    // Fallback: หา parent ที่มี "Clear prompt on submit" text
    const spans = panel.querySelectorAll('span, div, p, label');
    for (const span of spans) {
      const text = (span.textContent || '').trim().toLowerCase();
      if (text.includes('clear prompt') && text.length < 50) {
        // ใช้ parent row (อาจเป็น container ที่มี Off/On buttons)
        clearPromptRow = span.closest('div[class]') || span.parentElement;
        break;
      }
    }
  }

  if (!clearPromptRow) {
    console.log('🧹 [v18] ⚠️ "Clear prompt on submit" row not found in panel');
    return false;
  }

  console.log(`🧹 [v18] Found "Clear prompt" row: tag=${clearPromptRow.tagName}, text="${(clearPromptRow.textContent || '').trim().substring(0, 60)}"`);

  // หา Off/On toggle buttons ใน row นี้ (หรือ parent ที่ใกล้ที่สุด)
  // ลองหาใน element + parent chain
  let searchContainer = clearPromptRow;
  let onButton = null;
  let offButton = null;

  for (let depth = 0; depth < 4; depth++) {
    const buttons = searchContainer.querySelectorAll('button[role="tab"], button');
    for (const btn of buttons) {
      const btnText = (btn.textContent || '').trim().toLowerCase();
      if (btnText === 'on') onButton = btn;
      if (btnText === 'off') offButton = btn;
    }
    if (onButton) break;
    searchContainer = searchContainer.parentElement;
    if (!searchContainer || searchContainer === panel.parentElement) break;
  }

  if (!onButton) {
    console.log('🧹 [v18] ⚠️ "On" button not found near "Clear prompt on submit"');
    return false;
  }

  // เช็คว่า On active อยู่แล้วหรือยัง
  const onState = onButton.getAttribute('data-state');
  if (onState === 'active') {
    console.log('🧹 [v18] ✅ "Clear prompt on submit" already On');
    return true;
  }

  // ไม่ active → คลิก On
  console.log(`🧹 [v18] "Clear prompt on submit" is Off → clicking On...`);
  realClick(onButton);
  await delay(400);

  // Verify
  const newState = onButton.getAttribute('data-state');
  if (newState === 'active') {
    console.log('🧹 [v18] ✅ "Clear prompt on submit" → On (switched!)');
  } else {
    // อาจ re-render → หาใหม่
    console.log(`🧹 [v18] ⚠️ data-state=${newState} — may have re-rendered, checking fresh...`);
  }

  return true;
}

// v17: กดปุ่ม Grid View — คลิก Gear icon (ขวาบน) → เลือก Grid ใน View Mode panel
async function clickGridViewButton() {
  console.log('🔲 [v17] Looking for Gear icon to set Grid View...');

  // หาปุ่ม Gear (settings icon) ที่อยู่มุมขวาบน
  // ตาม UI ใหม่: +, Scene Builder, Gear, ⋮ — เรียงจากซ้ายไปขวา
  let gearButton = null;

  const allButtons = Array.from(document.querySelectorAll('button'));

  // วิธี 1: หาจาก icon text "settings"
  for (const btn of allButtons) {
    if (btn.offsetParent === null) continue;
    const rect = btn.getBoundingClientRect();
    // ต้องอยู่มุมขวาบน
    if (rect.top > 120 || rect.right < window.innerWidth * 0.6) continue;

    const iconText = (btn.textContent || '').trim().toLowerCase();
    const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();

    if (iconText.includes('settings') || iconText.includes('gear') || iconText === '⚙' ||
        ariaLabel.includes('settings') || ariaLabel.includes('view') || ariaLabel.includes('ตั้งค่า')) {
      gearButton = btn;
      console.log(`🔲 [v17] Found gear button by icon/label: "${iconText.substring(0, 20)}"`);
      break;
    }
  }

  // วิธี 2: หาจากตำแหน่ง (ปุ่มที่ 3 จากขวาในแถวบนสุด)
  if (!gearButton) {
    const topRightButtons = allButtons.filter(btn => {
      if (btn.offsetParent === null) return false;
      const rect = btn.getBoundingClientRect();
      return rect.top < 100 && rect.right > window.innerWidth * 0.6 && rect.width < 60 && rect.height < 60;
    });

    // Sort by position (right to left)
    topRightButtons.sort((a, b) => b.getBoundingClientRect().right - a.getBoundingClientRect().right);

    // Gear ควรอยู่ตำแหน่งที่ 2-3 จากขวา (⋮ อยู่ขวาสุด)
    if (topRightButtons.length >= 3) {
      // ลองหาปุ่มที่มี icon ที่ดูเหมือน gear
      for (const btn of topRightButtons) {
        const text = (btn.textContent || '').trim().toLowerCase();
        if (text.includes('settings') || text.includes('gear') || text.includes('tune')) {
          gearButton = btn;
          console.log('🔲 [v17] Found gear button by position + icon');
          break;
        }
      }
      // ถ้ายังไม่เจอ ลองปุ่มที่ 3 จากขวา
      if (!gearButton && topRightButtons.length >= 3) {
        gearButton = topRightButtons[2]; // index 0=⋮, 1=gear, 2=scene builder... ต้องลอง
        // ตรวจสอบว่าเป็น gear จริงไหม โดยดูว่าคลิกแล้วมี "View Mode" panel
      }
    }
  }

  if (!gearButton) {
    console.log('🔲 [v17] Gear button not found');
    return false;
  }

  // คลิก Gear เพื่อเปิด View Mode panel (ใช้ realClick กัน Radix)
  console.log('🔲 [v17] Clicking gear button...');
  realClick(gearButton);
  await delay(600);

  // หา "Grid" toggle ใน View Mode panel
  // Panel จะมี: View Mode → Grid | Batch
  let viewModePanel = null;
  const allDivs = document.querySelectorAll('div');

  for (const div of allDivs) {
    if (div.offsetParent === null) continue;
    const text = div.textContent || '';
    const rect = div.getBoundingClientRect();

    if (rect.width > 100 && rect.width < 600 && rect.height > 80 && rect.height < 500) {
      // View Mode panel มีคำว่า "View Mode" + "Grid" + "Batch"
      if (text.includes('View Mode') && text.includes('Grid') && text.includes('Batch')) {
        viewModePanel = div;
        break;
      }
      // หรือมีคำว่า "Grid Size" + "Grid" + "Batch"
      if (text.includes('Grid Size') && text.includes('Grid') && text.includes('Batch')) {
        viewModePanel = div;
        break;
      }
    }
  }

  if (viewModePanel) {
    console.log('🔲 [v17] Found View Mode panel, selecting Grid...');

    // หา "Grid" toggle button
    const gridClicked = await clickToggleInPanel(viewModePanel, 'Grid');
    if (gridClicked) {
      console.log('🔲 [v17] Grid view selected!');
    }

    // v18: บังคับ "Clear prompt on submit" = On (มือใหม่อาจกด Off → prompt เก่าไม่ถูกลบ → บอทพัง)
    await ensureClearPromptOnSubmit(viewModePanel);

    // ปิด panel (คลิก gear อีกครั้ง)
    await delay(300);
    realClick(gearButton);
    await delay(300);
  } else {
    console.log('🔲 [v17] View Mode panel not found after clicking gear');
    // ปิด (คลิก gear อีกครั้ง)
    realClick(gearButton);
    await delay(200);
  }

  return true;
}

// Step 1: Select Video mode + Frames toggle (v17: ใช้ toggle แทน dropdown)
// v17: step1_SelectMode — ไม่ต้องเปิด panel แยกอีกแล้ว
// รวมเข้า step2_ConfigureSettings() ที่เปิด panel ครั้งเดียวแล้วเซ็ทค่าทุกอย่าง
async function step1_SelectMode() {
  console.log('=== [v17] Step 1: Video + Ingredients — will be set in step2 (single panel open) ===');
  // ไม่ต้องทำอะไร — step2_ConfigureSettings() จะเลือก mode ให้
}

// Step 2: Configure settings (v17: ใช้ toggle buttons แทน dropdown)
// v17: step2 ทำทุกอย่างใน panel ครั้งเดียว — เปิด → mode → sub-mode → orientation → count → model → ปิด
// ลำดับสำคัญ: Mode ก่อน → sub-mode (ถ้า Video) → Orientation → Count → Model → ปิด
async function step2_ConfigureSettings(data) {
  updateStatus('กำลังตั้งค่า...');
  console.log('=== [v17] Step 2: Configure All Settings (single panel open) ===');
  console.log('[v17] Data:', JSON.stringify({ mode: currentMode, clipCount: data.clipCount, aspectRatio: data.aspectRatio, videoModel: data.videoModel, imageModel: data.imageModel }));

  await delay(300);

  // เปิด settings panel
  let panel = await openSettingsPanel();
  if (!panel) {
    console.log('[v17] ⚠️ Settings panel not found, using default settings');
    return;
  }

  // ⚠️ v17 FIX: ไม่ส่ง panel variable ไป clickToggleInPanel อีกแล้ว
  // เพราะ Radix UI อาจ re-render DOM หลังคลิก tab → panel reference เก่า stale
  // clickToggleInPanel() จะหา panel เองใหม่ทุกครั้ง

  // 1. เลือก Mode (Image / Video) — ต้องทำก่อนอื่น!
  if (currentMode === 'image') {
    console.log('[v17] → Setting mode: Image');
    await clickToggleInPanel('Image');
    await delay(400);
  } else if (currentMode === 'video') {
    console.log('[v17] → Setting mode: Video');
    await clickToggleInPanel('Video');
    await delay(400);

    // 1.5. เลือก sub-mode: Frames (เพราะ Animate แนบภาพเป็น Start frame แล้ว)
    console.log('[v17] → Setting sub-mode: Frames');
    await clickToggleInPanel('Frames');
    await delay(300);
  }

  // 2. ตั้ง Aspect Ratio
  // v2.1 FIX: Google Flow เปลี่ยน UI จาก "Portrait"/"Landscape" → "9:16"/"16:9"/"1:1"/"3:4"/"4:3"
  // ใช้ค่า aspectRatio ตรงๆ เป็น tab text (เช่น "9:16") + fallback เป็นชื่อเก่า
  if (data.aspectRatio) {
    const arText = data.aspectRatio; // "9:16", "16:9", "1:1", "3:4", "4:3"
    console.log(`[v17] → Setting aspect ratio: ${arText}`);
    let arSet = await clickToggleInPanel(arText);
    if (!arSet) {
      // Fallback: ลองชื่อเก่า (Portrait/Landscape) กรณี UI ยังไม่ update
      const wantPortrait = data.aspectRatio === '9:16';
      const fallbackName = wantPortrait ? 'Portrait' : 'Landscape';
      console.log(`[v17] → Aspect ratio "${arText}" not found — trying fallback "${fallbackName}"`);
      await clickToggleInPanel(fallbackName);
    }
    await delay(300);
  }

  // 3. ตั้ง Output count (1x/x2/x3/x4)
  // v4.1.1: Flow เปลี่ยนจาก "x1" เป็น "1x" — ลองทั้ง 2 แบบ
  if (data.clipCount) {
    const count = data.clipCount;
    const formats = count === 1 ? ['1x', 'x1'] : [`x${count}`, `${count}x`];
    console.log(`[v4.1.1] → Setting count: ${formats[0]} (fallback: ${formats[1]})`);
    let countSet = await clickToggleInPanel(formats[0]);
    if (!countSet) {
      console.log(`[v4.1.1] → Trying fallback: ${formats[1]}`);
      countSet = await clickToggleInPanel(formats[1]);
    }
    await delay(300);
  }

  // 4. ตั้ง Model (dropdown ซ้อน — ใช้ PointerEvent เปิด)
  if (currentMode === 'image') {
    const imageModelMap = { 'nano_banana_pro': 'Nano Banana Pro', 'nano_banana_2': 'Nano Banana 2', 'imagen_4': 'Imagen 4' };
    const targetImageModel = imageModelMap[data.imageModel] || 'Nano Banana Pro';
    console.log(`[v17] → Setting Image model: ${targetImageModel}`);
    await selectModelInPanel(targetImageModel);
    await delay(300);
  } else if (currentMode === 'video') {
    // v4.3.2: Flow ถอด Fast Lower (2026-05-10) — เหลือ 4 ตัว: Lite, Lite Lower, Fast, Quality
    const videoModelMap = {
      'veo_lite_lower': 'Veo 3.1 - Lite [Lower Priority]',  // ฟรี 0 เครดิต — default
      'veo_lite': 'Veo 3.1 - Lite',                         // 5 เครดิต
      'veo_fast': 'Veo 3.1 - Fast',                         // 10 เครดิต
      'veo_quality': 'Veo 3.1 - Quality',                   // 100 เครดิต
      'veo_fast_lower': 'Veo 3.1 - Lite [Lower Priority]',  // v4.3.2: legacy → redirect ไป Lite Lower (Fast Lower ไม่มีแล้ว)
      'omni_flash': 'Omni Flash',                           // Omni Flash (8 วิ ~12 เครดิต) — คลิกเลือกในหน้า Flow
    };
    const targetModel = videoModelMap[data.videoModel] || 'Veo 3.1 - Lite [Lower Priority]';
    console.log(`[v3.0] → Setting Video model: ${targetModel} (from ${data.videoModel})`);
    await selectModelInPanel(targetModel);
    await delay(300);
    // ⏱️ Omni Flash: หลังเลือกโมเดลแล้ว → คลิกแท็บจำนวนวิ (4s/6s/8s/10s) — backup สำหรับ UI-click path
    if (data.videoModel === 'omni_flash') {
      const secTab = (Number(data.omniSeconds) === 10 ? 10 : 8) + 's';
      console.log(`[omni] → click duration tab: ${secTab}`);
      try { await clickToggleInPanel(secTab); } catch (e) { console.warn('[omni] duration tab click failed:', e.message); }
      await delay(300);
    }
  }

  // 5. ปิด settings panel
  await closeSettingsPanel();

  console.log('=== [v17] Step 2 completed: All settings configured ===');
}

