// v17: ปิด settings panel (คลิก chip อีกครั้งเพื่อ toggle ปิด / Escape / คลิกนอก)
async function closeSettingsPanel() {
  console.log('[v17] Closing settings panel...');

  hideOverlayForClick();

  for (let attempt = 1; attempt <= 3; attempt++) {
    let panel = findSettingsPanel();
    if (!panel) {
      // เช็ค chip data-state ด้วย
      const chip = findSettingsChip();
      if (!chip || chip.getAttribute('data-state') !== 'open') {
        console.log('[v17] Settings panel closed successfully');
        showOverlayAfterClick();
        return;
      }
    }

    console.log(`[v17] Attempt ${attempt} to close settings panel...`);

    // วิธี 1: คลิก chip อีกครั้ง ด้วย realClick (toggle ปิด — data-state: open → closed)
    const chip = findSettingsChip();
    if (chip && chip.getAttribute('data-state') === 'open') {
      realClick(chip);
      await delay(400);
      if (chip.getAttribute('data-state') === 'closed') {
        console.log('[v17] Chip toggled to closed');
        showOverlayAfterClick();
        return;
      }
    }

    // วิธี 2: กด Escape
    document.dispatchEvent(new KeyboardEvent('keydown', {
      key: 'Escape',
      code: 'Escape',
      keyCode: 27,
      bubbles: true
    }));
    await delay(300);

    panel = findSettingsPanel();
    if (!panel) continue;

    // วิธี 3: คลิกนอก panel
    console.log('[v17] Panel still open, clicking outside...');
    const promptArea = document.querySelector('textarea, [contenteditable="true"]');
    if (promptArea) {
      promptArea.click();
    } else {
      document.body.click();
    }
    await delay(300);
  }

  showOverlayAfterClick();

  const panel = findSettingsPanel();
  if (panel) {
    console.log('[v17] Warning: Settings panel may still be open after 3 attempts');
  } else {
    console.log('[v17] Settings panel closed successfully');
  }
}

