// v17: Generic model selector สำหรับ Settings Panel
async function selectModelInPanel(targetModelText) {
  // หา settings panel (ต้องเปิดอยู่)
  const panel = findSettingsPanel();
  if (!panel) {
    console.log('[v17] No settings panel open for model selection');
    return false;
  }

  // v4.5.2: หา model dropdown แบบ robust — รองรับ Flow DOM ใหม่ (sc-3f41cc92 + button-based)
  let modelBtn = null;

  // วิธี 1 (NEW priority): หา <button> ที่มี text เป็น model name pattern
  //   safer than grabbing div — button ต้อง clickable แน่นอน
  const allBtnsInPanel = panel.querySelectorAll('button');
  for (const b of allBtnsInPanel) {
    const role = b.getAttribute('role');
    if (role === 'tab' || role === 'menuitem') continue;
    const text = (b.textContent || '').trim();
    if (text.length >= 80) continue;
    // model pattern: "Veo 3.1 ...", "Nano Banana ...", "Imagen ...", หรือ มี arrow_drop_down icon
    if (/Veo\s*\d/.test(text) || /Nano\s*Banana/i.test(text) ||
        /Imagen/i.test(text) || text.includes('arrow_drop_down')) {
      modelBtn = b;
      console.log(`[v4.5.2] Found model dropdown button (<button> + pattern): "${text.substring(0, 50)}"`);
      break;
    }
  }

  // วิธี 2 (legacy): partial class match — เผื่อ Flow รุ่นเก่า
  if (!modelBtn) {
    modelBtn = panel.querySelector('[class*="sc-a0dcecfb"]');
    if (modelBtn && (modelBtn.getAttribute('role') === 'tab' || modelBtn.getAttribute('role') === 'menuitem')) {
      modelBtn = null;
    }
    if (modelBtn) console.log('[v4.5.2] Found model dropdown via legacy sc-a0dcecfb');
  }

  // วิธี 3 (broad fallback): button/div ที่มี text รวม model name
  if (!modelBtn) {
    const allEls = panel.querySelectorAll('button, div, [class*="sc-a0dcecfb"]');
    for (const el of allEls) {
      if (el.getAttribute('role') === 'tab' || el.getAttribute('role') === 'menuitem') continue;
      const text = (el.textContent || '').trim();
      if ((text.includes('arrow_drop_down') || text.includes('Nano Banana') ||
          text.includes('Imagen') || text.includes('Veo')) && text.length < 80) {
        modelBtn = el;
        console.log(`[v17] Found model dropdown (broad fallback): "${text.substring(0, 40)}"`);
        break;
      }
    }
  }

  if (!modelBtn) {
    console.log('[v17] ❌ Model dropdown button not found in panel');
    return false;
  }
  // Diagnostic: log outerHTML snippet ของ modelBtn เพื่อ debug ตอน user ส่ง console log มา
  console.log(`[v4.5.2] modelBtn tag=<${modelBtn.tagName}> class="${modelBtn.className?.toString?.().substring(0, 80) || ''}"`);

  const currentText = (modelBtn.textContent || '').trim();
  console.log(`[v17] Model dropdown current: "${currentText.substring(0, 40)}"`);

  // เช็คว่าเป็น model ที่ต้องการอยู่แล้วหรือเปล่า
  if (currentText.includes(targetModelText)) {
    console.log(`[v17] Already set to "${targetModelText}" ✓`);
    return true;
  }

  // เปิด model dropdown ด้วย realClick (Radix ต้อง full event chain)
  console.log('[v17] Opening model dropdown with realClick...');
  realClick(modelBtn);
  await delay(700);

  // v4.5.2: เช็คว่า popover เปิดจริงไหม — ถ้าไม่เปิด ลองคลิกใหม่ 2 ครั้ง
  //   วัด: มี Radix popover state=open ที่ไม่ใช่ panel ปรากฏใหม่ + มี text "Veo" / "Nano" / "Imagen"
  function _isMenuOpen() {
    const opened = document.querySelectorAll('[role="menu"][data-state="open"], [id^="radix-"][data-state="open"]');
    for (const o of opened) {
      if (o === panel || panel.contains(o)) continue;
      const t = (o.textContent || '').trim();
      if (t.includes('Veo') || t.includes('Nano') || t.includes('Imagen')) return true;
    }
    return false;
  }
  for (let attempt = 1; attempt <= 2 && !_isMenuOpen(); attempt++) {
    console.log(`[v4.5.2] Popover ไม่เปิด — ลองคลิกซ้ำ #${attempt}`);
    realClick(modelBtn);
    await delay(700);
  }

  // v4.5.2: หา sub-menu ที่เปิดขึ้นมา — รองรับ Flow DOM ใหม่ (sc-3f41cc92 + button items แทน role=menuitem)
  let subMenu = null;

  // วิธี 1: old class — sc-a0dcecfb[role=menu]
  subMenu = document.querySelector('[class*="sc-a0dcecfb"][role="menu"][data-state="open"]') ||
            document.querySelector('[class*="sc-a0dcecfb"][role="menu"]');

  // วิธี 2: role=menu state=open ที่ไม่ใช่ settings panel
  if (!subMenu) {
    const allMenus = document.querySelectorAll('[role="menu"][data-state="open"]');
    for (const m of allMenus) {
      if (m === panel || panel.contains(m)) continue;
      if (m.querySelector('button, [role="menuitem"]')) {
        subMenu = m;
        break;
      }
    }
  }

  // วิธี 3: Radix popover ใหม่ (Flow 2026-05) — id^="radix-" data-state="open" + มี button ที่มีชื่อ model
  if (!subMenu) {
    const radixPopovers = document.querySelectorAll('[id^="radix-"][data-state="open"]');
    for (const p of radixPopovers) {
      if (p === panel || panel.contains(p)) continue;
      const btns = p.querySelectorAll('button');
      let hasModel = false;
      for (const b of btns) {
        const t = (b.textContent || '').trim();
        if (t.includes('Veo') || t.includes('Nano') || t.includes('Imagen')) {
          hasModel = true;
          break;
        }
      }
      if (hasModel) {
        subMenu = p;
        console.log('[v4.5.2] Found sub-menu via Radix popover fallback');
        break;
      }
    }
  }

  // วิธี 4: scan global หา button ที่มี target text → ขึ้นไปหา container
  if (!subMenu) {
    const allBtns = document.querySelectorAll('button');
    for (const b of allBtns) {
      const t = (b.textContent || '').trim();
      if (!t.includes(targetModelText)) continue;
      let container = b.closest('[role="menu"], [id^="radix-"], [data-state="open"]');
      if (!container || container === panel || panel.contains(container)) continue;
      subMenu = container;
      console.log('[v4.5.2] Found sub-menu via button-text scan');
      break;
    }
  }

  // Retry click ถ้ายังไม่เจอ
  if (!subMenu) {
    console.log('[v17] ❌ Model sub-menu did not open, retrying realClick...');
    realClick(modelBtn);
    await delay(600);
    subMenu = document.querySelector('[class*="sc-a0dcecfb"][role="menu"]') ||
              document.querySelector('[id^="radix-"][data-state="open"]:not(:has(textarea))');
  }

  if (!subMenu) {
    console.log('[v17] ❌ Model sub-menu still not found after retry');
    return false;
  }

  // v4.5.2: เลือก model — รองรับทั้ง div[role=menuitem] เก่า และ button ใหม่
  const items = subMenu.querySelectorAll('div[role="menuitem"], [role="menuitem"], button');
  console.log(`[v17] Model sub-menu has ${items.length} clickable items`);

  // v4.5.2 Diagnostic: log ทุก item ที่หาเจอ (text + cleaned text) — จะช่วย debug ถ้ายังเลือกผิด
  const itemDebug = [];

  // v4.5.2: strip icon prefix (Material Symbols: volume_up, videocam, etc.) ก่อน match
  //         text = "volume_upVeo 3.1 - Fast" → cleaned = "Veo 3.1 - Fast"
  //   regex: lowercase + underscores ที่ขึ้นต้น ตามด้วย UPPERCASE หรือ whitespace
  //          (\b ใช้ไม่ได้เพราะ "p" → "V" ไม่มี word boundary — ตัวอักษรเหมือนกันทั้งคู่)
  function _cleanText(t) {
    return t.replace(/^[a-z][a-z_]*(?=[A-Z\s])/, '').trim();
  }

  let found = null;

  // วิธี 1 (NEW best): exact match หลัง strip icon prefix — ปลอดภัยที่สุด
  for (const item of items) {
    const rawText = (item.textContent || '').trim();
    const cleaned = _cleanText(rawText);
    itemDebug.push({ raw: rawText.substring(0, 50), clean: cleaned.substring(0, 50) });
    if (cleaned === targetModelText) {
      found = item;
      console.log(`[v4.5.2] ✓ Match (clean exact): "${cleaned}" === "${targetModelText}"`);
      break;
    }
  }

  // วิธี 2: หา <span> ที่มี text เป็น target พอดี (รองรับ DOM nested ที่ user ส่งมา)
  if (!found) {
    for (const item of items) {
      const spans = item.querySelectorAll('span');
      for (const sp of spans) {
        if ((sp.textContent || '').trim() === targetModelText) {
          found = item;
          console.log(`[v4.5.2] ✓ Match (nested span): "${targetModelText}"`);
          break;
        }
      }
      if (found) break;
    }
  }

  // วิธี 3 (legacy): endsWith
  if (!found) {
    for (const item of items) {
      const t = (item.textContent || '').trim();
      if (t.endsWith(targetModelText) || t === targetModelText) {
        found = item;
        console.log(`[v4.5.2] ✓ Match (endsWith): "${t.substring(0, 50)}"`);
        break;
      }
    }
  }

  // วิธี 4 (loose): includes — last resort
  if (!found) {
    for (const item of items) {
      const t = (item.textContent || '').trim();
      if (t.includes(targetModelText)) {
        found = item;
        console.log(`[v4.5.2] ⚠️ Match (loose includes): "${t.substring(0, 50)}"`);
        break;
      }
    }
  }

  if (found) {
    const ft = (found.textContent || '').trim();
    console.log(`[v17] Clicking model: "${ft.substring(0, 50)}"`);
    realClick(found);
    await delay(300);
    return true;
  }

  // ถ้าหาไม่เจอ — dump items ทั้งหมดให้ user copy ส่งมา
  console.log(`[v17] ❌ Model "${targetModelText}" not found in sub-menu`);
  console.log(`[v4.5.2] All items found in sub-menu:`, JSON.stringify(itemDebug, null, 2));
  document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  await delay(200);
  return false;
}

// v4.3.2: ตั้งค่า Video Model — รองรับ Lite, Lite Lower, Fast, Quality (Flow ถอด Fast Lower 2026-05-10)
// videoModel: 'veo_lite_lower' | 'veo_lite' | 'veo_fast' | 'veo_quality'
