// v17: findDropdownContainersInPanel — removed (ไม่ใช้แล้ว ใช้ toggle แทน)
// v17: setOutputsDirectly — removed (ใช้ clickToggleInPanel(panel, 'x1'/'x2'/'x3'/'x4') แทน)

// คลิก dropdown และเลือกค่า
async function clickDropdownAndSelect(dropdownElement, values) {
  console.log(`Clicking dropdown to select: ${values.join('/')}`);

  // คลิกเปิด dropdown
  await clickWithOverlay(dropdownElement);
  await delay(300);

  // หา options
  const menuItems = document.querySelectorAll('[role="option"], [role="menuitem"], li, div[class*="option"], div[class*="item"]');

  let clicked = false;

  // หา exact match ก่อน
  for (const item of menuItems) {
    const itemText = (item.textContent || '').trim();
    if (values.some(v => itemText === v)) {
      await clickWithOverlay(item);
      console.log(`Clicked exact match: "${itemText}"`);
      clicked = true;
      break;
    }
  }

  // ถ้าไม่เจอ exact match ลอง includes
  if (!clicked) {
    for (const item of menuItems) {
      const itemText = (item.textContent || '').trim();
      if (values.some(v => itemText.includes(v) || v.includes(itemText))) {
        // ข้ามถ้า itemText มีตัวอักษรอื่นปนกับตัวเลข (เช่น "22%")
        if (values.some(v => /^\d+$/.test(v)) && !/^\d+$/.test(itemText)) {
          continue;
        }
        await clickWithOverlay(item);
        console.log(`Clicked partial match: "${itemText}"`);
        clicked = true;
        break;
      }
    }
  }

  if (!clicked) {
    console.log(`No matching option found for: ${values.join('/')}`);
  }

  await delay(200);
  return clicked;
}

// Helper function to set dropdown value by label (multilang support)
async function setDropdownByLabelMultilang(labelTexts, values) {
  console.log(`Setting ${labelTexts.join('/')} to ${values.join('/')}`);

  // Find all elements that might be labels
  const allElements = document.querySelectorAll('*');
  let targetDropdown = null;
  let foundLabel = null;
  let foundLabelElement = null;

  // หา label element ที่เล็กที่สุด (เฉพาะเจาะจงที่สุด)
  let bestLabelEl = null;
  let bestLabelLength = Infinity;

  for (const el of allElements) {
    const text = (el.textContent || '').trim();
    // เช็คว่าตรงกับ label ไหนบ้าง (ไทย หรือ อังกฤษ)
    for (const lt of labelTexts) {
      // ใช้ exact match หรือ element ที่มี text สั้นที่สุด
      if ((text === lt || text.includes(lt)) && text.length < bestLabelLength && el.offsetParent !== null) {
        // เลือก element ที่มี text ตรงกับ label มากที่สุด
        bestLabelEl = el;
        bestLabelLength = text.length;
        foundLabel = text;
        console.log(`Found label candidate: "${text}" (length: ${text.length})`);
      }
    }
  }

  if (bestLabelEl) {
    foundLabelElement = bestLabelEl;
    console.log(`Selected label: "${foundLabel}"`);

    // หา dropdown ใกล้กับ label นี้
    // ลองหาจาก parent หลายระดับ
    let parent = foundLabelElement.parentElement;
    let searchLevels = 0;
    while (parent && searchLevels < 5) {
      // หา sibling หรือ child ที่เป็น dropdown
      const dropdown = parent.querySelector('select, [role="listbox"], [role="combobox"]');
      if (dropdown && dropdown !== foundLabelElement) {
        targetDropdown = dropdown;
        console.log(`Found dropdown (select/listbox) at level ${searchLevels}`);
        break;
      }

      // หา clickable element ที่ไม่ใช่ label
      const allClickables = parent.querySelectorAll('button, div[role="button"], [class*="trigger"]');
      for (const clickable of allClickables) {
        // ข้าม element ที่เป็น label เอง
        if (clickable.contains(foundLabelElement) || foundLabelElement.contains(clickable)) {
          continue;
        }
        if (clickable.offsetParent !== null) {
          const clickableText = (clickable.textContent || '').trim();
          // ถ้ามี svg/icon หรือ text สั้นๆ (เช่น "4", "Portrait")
          const hasIcon = clickable.querySelector('svg');
          const isShortText = clickableText.length < 20;
          if (hasIcon || isShortText) {
            targetDropdown = clickable;
            console.log(`Found clickable dropdown: "${clickableText}" at level ${searchLevels}`);
            break;
          }
        }
      }
      if (targetDropdown) break;
      parent = parent.parentElement;
      searchLevels++;
    }
  }

  if (targetDropdown) {
    console.log(`Found dropdown for: ${foundLabel}`);

    if (targetDropdown.tagName === 'SELECT') {
      const options = Array.from(targetDropdown.options);
      const option = options.find(opt => values.some(v => opt.text.includes(v) || opt.value.includes(v)));
      if (option) {
        targetDropdown.value = option.value;
        targetDropdown.dispatchEvent(new Event('change', { bubbles: true }));
        console.log(`Set SELECT to ${option.value}`);
      }
    } else {
      // Click dropdown to open
      await clickWithOverlay(targetDropdown);
      await delay(300);

      // Find and click the option
      const menuItems = document.querySelectorAll('[role="option"], [role="menuitem"], li, div[class*="option"], div[class*="item"]');
      let found = false;
      let exactMatchItem = null;
      let partialMatchItem = null;

      for (const item of menuItems) {
        const itemText = (item.textContent || '').trim();
        // ค้นหา exact match ก่อน
        if (values.some(v => itemText === v)) {
          exactMatchItem = item;
          console.log(`Found exact match: "${itemText}"`);
          break; // exact match เจอแล้วหยุดเลย
        }
        // เก็บ partial match ไว้ใช้ถ้าไม่เจอ exact
        if (!partialMatchItem && values.some(v => itemText.includes(v))) {
          // ข้าม partial match ที่มีตัวอักษรอื่นปนถ้าค่าที่หาเป็นตัวเลข
          if (!/^\d+$/.test(itemText) && values.some(v => /^\d+$/.test(v))) {
            continue;
          }
          partialMatchItem = item;
          console.log(`Found partial match: "${itemText}"`);
        }
      }

      const itemToClick = exactMatchItem || partialMatchItem;
      if (itemToClick) {
        await clickWithOverlay(itemToClick);
        console.log(`Clicked option: ${(itemToClick.textContent || '').trim()}`);
        found = true;
        await delay(200);
      }

      if (!found) {
        console.log(`Option not found for values: ${values.join('/')}`);
      }
      return found;
    }
    return true;
  } else {
    console.log(`Dropdown for "${labelTexts.join('/')}" not found`);
    return false;
  }
}

// Helper function to set dropdown value by label (single lang - legacy)
async function setDropdownByLabel(labelText, value) {
  console.log(`Setting ${labelText} to ${value}`);

  // Find all elements that might be labels
  const allElements = document.querySelectorAll('*');
  let targetDropdown = null;

  for (const el of allElements) {
    const text = (el.textContent || '').trim();
    if (text.includes(labelText) && el.offsetParent !== null) {
      // Found the label, now find the nearby dropdown
      const parent = el.closest('div');
      if (parent) {
        // Look for select or clickable dropdown near this label
        const dropdown = parent.querySelector('select, [role="listbox"], [role="combobox"], [class*="dropdown"], [class*="select"]');
        if (dropdown) {
          targetDropdown = dropdown;
          break;
        }
        // Or find a button/div that acts as dropdown
        const clickable = parent.querySelector('button, div[role="button"]');
        if (clickable && clickable !== el) {
          targetDropdown = clickable;
          break;
        }
      }
    }
  }

  if (targetDropdown) {
    if (targetDropdown.tagName === 'SELECT') {
      // Native select element
      const options = Array.from(targetDropdown.options);
      const option = options.find(opt => opt.text.includes(value) || opt.value.includes(value));
      if (option) {
        targetDropdown.value = option.value;
        targetDropdown.dispatchEvent(new Event('change', { bubbles: true }));
        console.log(`Set SELECT to ${value}`);
      }
    } else {
      // Custom dropdown - click to open
      targetDropdown.click();
      await delay(400);

      // Find and click the option
      const menuItems = document.querySelectorAll('[role="option"], [role="menuitem"], li, div[class*="option"], div[class*="item"]');
      for (const item of menuItems) {
        const itemText = (item.textContent || '').trim();
        if (itemText.includes(value)) {
          item.click();
          console.log(`Clicked option: ${itemText}`);
          await delay(300);
          break;
        }
      }
    }
  } else {
    console.log(`Dropdown for "${labelText}" not found`);
  }
}

// Step 3: Upload image
// v17 Flow: 2 ขั้นตอนแยกกัน
//   ขั้น A: Upload ภาพเข้า Asset Library (ผ่าน file input)
//   ขั้น B: กด + → เลือกภาพจาก Library → auto-attach เข้า prompt + dialog ปิดเอง
async function step3_UploadImage(imageBase64, filename = 'product.png') {
  updateStatus(`กำลังอัพโหลด ${filename} เข้า Library...`);
  console.log(`[v17.4] Uploading "${filename}" to Library via hidden file input...`);

  // DOM verified: input[type="file"][accept="image/*"] ซ่อนอยู่ในหน้าตลอด (display:none)
  // ไม่ต้องกดปุ่มอะไรก่อน — ใส่ไฟล์ตรงๆ ได้เลย
  // upload แล้วรูปเข้า library เท่านั้น ไม่ auto-แนบเข้า prompt
  let fileInput = document.querySelector('input[type="file"][accept="image/*"]');

  if (!fileInput) {
    // Fallback: หา input[type="file"] ทั่วไป
    fileInput = document.querySelector('input[type="file"][accept*="image"]') ||
                document.querySelector('input[type="file"]');
  }

  if (!fileInput) {
    console.log('[v17] No hidden file input found, trying alternative upload...');
    const uploaded = await tryAlternativeUpload(imageBase64, filename);
    if (!uploaded) {
      throw new Error('ไม่พบช่องอัพโหลดรูป กรุณาลองใหม่อีกครั้ง');
    }
    return;
  }

  console.log(`[v17.4] Found hidden file input, uploading as "${filename}"...`);
  await uploadToFileInput(fileInput, imageBase64, filename);

  // รอ upload เสร็จจริงๆ (ไม่ใช่แค่ delay — ต้องเช็ค progress)
  console.log('[v17] Waiting for upload to complete...');
  await waitForUploadComplete();
  console.log('[v17] ✅ Upload complete — image should be in library');
}

// v17: รอจนการอัพโหลดเสร็จ — ตรวจ progress %, spinner, uploading text
async function waitForUploadComplete(maxWaitMs = 30000) {
  const startTime = Date.now();
  let lastProgress = '';

  // รอขั้นต่ำ 2 วิก่อน เพื่อให้ progress indicator ปรากฏ
  await delay(2000);

  while (Date.now() - startTime < maxWaitMs) {
    // เช็ค 1: หา progress bar / percentage text ในหน้า
    const allText = document.body.innerText || '';
    const progressMatch = allText.match(/(\d{1,3})%/);

    // เช็ค 2: หา progress bar elements
    const progressBars = document.querySelectorAll(
      '[role="progressbar"], [class*="progress"], [class*="upload"], ' +
      '[class*="Progress"], [class*="Upload"]'
    );

    // เช็ค 3: หา spinner / loading indicators ใกล้ๆ prompt area
    const spinners = document.querySelectorAll(
      '[class*="spinner"], [class*="loading"], [class*="Spinner"], [class*="Loading"], ' +
      'circle[class*="progress"], svg[class*="circular"]'
    );

    // เช็ค 4: หา text "Uploading" / "Processing"
    const uploadingElements = [];
    document.querySelectorAll('span, div, p').forEach(el => {
      const t = (el.textContent || '').trim().toLowerCase();
      if ((t.includes('uploading') || t.includes('processing') || t.includes('loading')) && t.length < 50) {
        if (isVisible(el)) uploadingElements.push(el);
      }
    });

    // เช็ค 5: หา percentage badge ใกล้ thumbnails (เช่น "99%", "50%")
    const percentElements = [];
    document.querySelectorAll('span, div').forEach(el => {
      const t = (el.textContent || '').trim();
      if (/^\d{1,3}%$/.test(t) && isVisible(el)) {
        percentElements.push(el);
      }
    });

    const hasProgress = progressBars.length > 0 || uploadingElements.length > 0 || percentElements.length > 0;
    const activeSpinners = Array.from(spinners).filter(s => isVisible(s));

    if (progressMatch) {
      const pct = parseInt(progressMatch[1]);
      if (pct !== parseInt(lastProgress)) {
        console.log(`[v17] Upload progress: ${pct}%`);
        lastProgress = progressMatch[1];
      }
    }

    if (percentElements.length > 0) {
      console.log(`[v17] Found % indicators: ${percentElements.map(e => e.textContent.trim()).join(', ')}`);
    }

    // ถ้าไม่มี progress indicator เลย → upload น่าจะเสร็จแล้ว
    if (!hasProgress && activeSpinners.length === 0 && percentElements.length === 0) {
      // รอเพิ่มอีกนิดเพื่อ confirm ว่าเสร็จจริง (ไม่ใช่แค่ยังไม่เริ่ม)
      if (Date.now() - startTime > 3000) {
        console.log('[v17] No upload progress indicators found — upload complete');
        await delay(1000); // buffer เพิ่ม
        return;
      }
    }

    await delay(1000);
  }

  console.log(`[v17] Upload wait timed out after ${maxWaitMs}ms — proceeding anyway`);
  await delay(1000);
}

// v17.5: ตรวจจับ & แก้ "Something went wrong loading your media" cards
// กด refresh ในกรอบ หรือ reload ทั้งหน้า
async function handleFailedMediaCards() {
  console.log('[v17.5] Checking for failed media cards...');

  // หา cards ที่แสดง "Something went wrong loading your media"
  function findFailedMediaCards() {
    const failed = [];
    const cards = document.querySelectorAll('.sc-5923b123-0');
    for (const card of cards) {
      const text = (card.innerText || '').toLowerCase();
      if (text.includes('something went wrong') && text.includes('loading')) {
        failed.push(card);
      }
    }
    // fallback: หา element ที่มีข้อความ "Something went wrong loading your media"
    if (failed.length === 0) {
      const allEls = document.querySelectorAll('div, span, p');
      for (const el of allEls) {
        const text = (el.textContent || '').trim();
        if (text.includes('Something went wrong loading your media') && el.offsetWidth > 0) {
          const card = el.closest('.sc-5923b123-0') || el.closest('[class*="sc-"]');
          if (card && !failed.includes(card)) failed.push(card);
        }
      }
    }
    return failed;
  }

  const failedCards = findFailedMediaCards();
  if (failedCards.length === 0) {
    console.log('[v17.5] ✅ No failed media cards found');
    return true;
  }

  console.log(`[v17.5] ⚠️ Found ${failedCards.length} failed media cards, clicking refresh buttons...`);

  // พยายามกด refresh button ในแต่ละ card
  let refreshed = 0;
  for (const card of failedCards) {
    // หาปุ่ม refresh ใน card — อาจเป็น button/div ที่มี icon "refresh" หรือ "sync" หรือ 🔄
    let refreshBtn = null;

    // วิธี 1: หา Google Symbols icon "refresh" / "sync" / "autorenew"
    const icons = card.querySelectorAll('i.google-symbols, i[class*="material"], span.google-symbols');
    for (const icon of icons) {
      const iconText = (icon.textContent || '').trim().toLowerCase();
      if (iconText === 'refresh' || iconText === 'sync' || iconText === 'autorenew' || iconText === 'replay') {
        refreshBtn = icon.closest('button') || icon.closest('[role="button"]') || icon;
        break;
      }
    }

    // วิธี 2: หา SVG/button ที่เป็น circular arrow (ดูจาก class หรือ aria)
    if (!refreshBtn) {
      const btns = card.querySelectorAll('button, [role="button"], [type="button"]');
      for (const btn of btns) {
        const text = (btn.textContent || '').trim().toLowerCase();
        if (text.includes('refresh') || text.includes('retry') || text.includes('reload') || text === '🔄') {
          refreshBtn = btn;
          break;
        }
      }
    }

    // วิธี 3: หา clickable element ใน failed overlay (ปุ่มอาจไม่มี text)
    if (!refreshBtn) {
      const clickables = card.querySelectorAll('button, [role="button"], div[class*="sc-"][tabindex], svg');
      for (const el of clickables) {
        // skip ปุ่มที่เป็น favorite/like
        if (el.closest('[aria-label*="favorite"]') || el.closest('[aria-label*="like"]')) continue;
        const rect = el.getBoundingClientRect();
        if (rect.width > 10 && rect.width < 60 && rect.height > 10 && rect.height < 60) {
          refreshBtn = el;
          break;
        }
      }
    }

    if (refreshBtn) {
      console.log(`[v17.5] Clicking refresh button on failed card: ${refreshBtn.tagName}${refreshBtn.className ? '.' + (refreshBtn.className.toString().substring(0,30)) : ''}`);
      realClick(refreshBtn);
      refreshed++;
      await delay(1000);
    } else {
      console.log('[v17.5] ⚠️ No refresh button found in failed card');
    }
  }

  // รอ 3 วินาทีให้ media reload
  if (refreshed > 0) {
    console.log(`[v17.5] Clicked refresh on ${refreshed} cards, waiting 3s for reload...`);
    await delay(3000);

    // เช็คอีกรอบ — ยังมี failed อยู่ไหม
    const stillFailed = findFailedMediaCards();
    if (stillFailed.length === 0) {
      console.log('[v17.5] ✅ All failed media cards recovered!');
      return true;
    }
    console.log(`[v17.5] ⚠️ Still ${stillFailed.length} failed cards after refresh`);
  }

  // ถ้ายังไม่หายหรือไม่เจอปุ่ม refresh → reload ทั้งหน้า
  console.log('[v17.5] 🔄 Failed media still present — reloading page...');
  updateBotOverlay('Media load failed — กำลัง refresh หน้า...', 'Auto Pipeline');
  window.location.reload();
  return false; // caller จะ handle หลัง reload
}

// v17: หาปุ่ม + (Asset Picker trigger)
// v17.3 FIX: สลับลำดับ — ใช้วิธีเจาะจงก่อน + เช็ค text content
// เพราะหลังแนบรูป มี button[aria-haspopup="dialog"] อื่นเพิ่มมา (เช่น ปุ่มจัดการ attachment)
function findPlusButton() {
  // DOM verified: button.sc-addd5871-0[aria-haspopup="dialog"]
  // textContent: "add_2Create", อยู่ใน div.sc-c70e41ad-2 (left side ของ action row)

  // วิธี 1 (เจาะจงสุด): sc-addd5871 class — ปุ่ม + ตัวจริง
  const btn1 = document.querySelector('button[class*="sc-addd5871"]');
  if (btn1 && isVisible(btn1)) {
    console.log('[v17] Found + button (sc-addd5871 class)');
    return btn1;
  }

  // วิธี 2: หาใน prompt bar wrapper — ปุ่มที่อยู่ใน div.sc-c70e41ad-2
  const wrapper = document.querySelector('div[class*="sc-c70e41ad-2"]');
  if (wrapper) {
    const btn = wrapper.querySelector('button');
    if (btn && isVisible(btn)) {
      console.log('[v17] Found + button (in wrapper sc-c70e41ad-2)');
      return btn;
    }
  }

  // วิธี 3 (fallback): aria-haspopup="dialog" แต่ต้องมี text "add" ข้างใน
  // กัน false positive จากปุ่ม attachment/menu อื่นที่มี aria-haspopup เหมือนกัน
  const allHaspopup = document.querySelectorAll('button[aria-haspopup="dialog"]');
  for (const btn of allHaspopup) {
    if (!isVisible(btn)) continue;
    const text = (btn.textContent || '').toLowerCase();
    if (text.includes('add') || text.includes('create')) {
      console.log('[v17] Found + button (aria-haspopup + text "add/create")');
      return btn;
    }
  }

  // วิธี 4 (last resort): aria-haspopup="dialog" ตัวแรกที่ไม่อยู่ใน attachment area
  for (const btn of allHaspopup) {
    if (!isVisible(btn)) continue;
    // ข้ามปุ่มที่อยู่ใน attachment container (.sc-d9d2dca3)
    if (btn.closest('[class*="sc-d9d2dca3"]')) {
      console.log('[v17] Skipping aria-haspopup button inside attachment area');
      continue;
    }
    console.log('[v17] Found + button (aria-haspopup, not in attachment area)');
    return btn;
  }

  console.log('[v17] + button not found');
  return null;
}

// v3.0 HELPER: หา gallery items ใน Asset Picker dialog (ไม่พึ่ง class ที่เปลี่ยนบ่อย)
// ⚠️ สำคัญ: return inner clickable element (ไม่ใช่ virtuoso wrapper)
// เพราะ React onClick อยู่ที่ child — dispatch event บน parent จะไม่ trigger
function findGalleryItems(dialog) {
  // วิธี 1 (เสถียรสุด): ใช้ data-testid="virtuoso-item-list" → หา child ที่มี data-item-index → เอา firstElementChild (inner div)
  const virtuosoList = dialog.querySelector('[data-testid="virtuoso-item-list"]');
  if (virtuosoList) {
    const wrappers = virtuosoList.querySelectorAll('[data-item-index]');
    const items = [];
    for (const wrapper of wrappers) {
      // เอา inner div (ลูกตรงของ wrapper) ที่มี img ข้างใน — นี่คือตัวที่มี onClick handler
      const inner = wrapper.querySelector('div') || wrapper;
      items.push(inner);
    }
    if (items.length > 0) return items;
  }

  // วิธี 2: หา img[alt] → เอา parentElement (inner div ที่รวม img + filename)
  const imgAlts = dialog.querySelectorAll('img[alt]');
  const itemsFromImg = [];
  for (const img of imgAlts) {
    const alt = img.alt || '';
    if (alt && !alt.startsWith('http') && alt !== 'icon') {
      // เอา parent ที่ใกล้ img ที่สุด (inner div) — ไม่ใช่ data-item-index wrapper
      const clickable = img.parentElement || img;
      if (!itemsFromImg.includes(clickable)) {
        itemsFromImg.push(clickable);
      }
    }
  }
  if (itemsFromImg.length > 0) return itemsFromImg;

  // วิธี 3 (fallback): div ที่มี cursor:pointer + img
  const result = [];
  const allDivs = dialog.querySelectorAll('div');
  for (const d of allDivs) {
    if (!isVisible(d)) continue;
    const style = window.getComputedStyle(d);
    if (style.cursor === 'pointer' && d.querySelector('img')) {
      result.push(d);
    }
  }
  return result;
}

// v3.0 HELPER: นับ attachment ที่แนบอยู่ (ใช้หลาย selector เพื่อกันปัญหา class เปลี่ยน)
function countAttachments() {
  // วิธี 1: ใช้ partial class match (sc-d9d2dca3 ยังอาจใช้ได้แต่ suffix เปลี่ยน)
  let count = document.querySelectorAll('[class*="sc-d9d2dca3"]').length;
  if (count > 0) {
    console.log(`[countAttachments] Found ${count} via sc-d9d2dca3`);
    return count;
  }

  // วิธี 2: หา img ในบริเวณ prompt bar ที่มี crossorigin="anonymous" + ขนาดเล็ก (thumbnail)
  // Attachment thumbnail ใน Google Flow มี crossorigin + อยู่ใกล้ prompt
  const textbox = document.querySelector('[role="textbox"]');
  if (textbox) {
    // ไล่หา parent container ที่ครอบทั้ง attachments + textbox
    let container = textbox.parentElement;
    for (let i = 0; i < 5 && container; i++) {
      const imgs = container.querySelectorAll('img[crossorigin]');
      let attachCount = 0;
      for (const img of imgs) {
        const rect = img.getBoundingClientRect();
        // Attachment thumbnails มีขนาด ~40x40 ถึง ~80x80 อยู่ใต้จอ (ใกล้ prompt bar)
        if (rect.width >= 20 && rect.height >= 20 && rect.width <= 120 && rect.top > window.innerHeight * 0.7) {
          attachCount++;
        }
      }
      if (attachCount > 0) return attachCount;
      container = container.parentElement;
    }
  }

  // วิธี 3: หา div ที่มี img + ปุ่ม close (structure ของ attachment card)
  const allSmallImgs = document.querySelectorAll('img[crossorigin="anonymous"]');
  let attachCount = 0;
  for (const img of allSmallImgs) {
    const rect = img.getBoundingClientRect();
    if (rect.width >= 20 && rect.width <= 120 && rect.top > window.innerHeight * 0.6) {
      // เช็คว่า parent มี button (ปุ่มลบ)
      const parent = img.parentElement;
      if (parent && (parent.querySelector('button') || parent.querySelector('svg'))) {
        attachCount++;
      }
    }
  }

  return attachCount;
}

// v3.0 HELPER: หา attachment elements (สำหรับลบ/จัดการ)
function findAttachmentElements() {
  // วิธี 1: partial class match
  let attachments = document.querySelectorAll('[class*="sc-d9d2dca3"]');
  if (attachments.length > 0) return Array.from(attachments);

  // วิธี 2: หา img[crossorigin] ใกล้ prompt ที่มี parent กับ button (close)
  const result = [];
  const allSmallImgs = document.querySelectorAll('img[crossorigin="anonymous"]');
  for (const img of allSmallImgs) {
    const rect = img.getBoundingClientRect();
    if (rect.width >= 20 && rect.width <= 120 && rect.top > window.innerHeight * 0.6) {
      const parent = img.parentElement;
      if (parent && (parent.querySelector('button') || parent.querySelector('svg'))) {
        result.push(parent);
      }
    }
  }
  return result;
}

// v17: กด + → เปิด Asset Picker → คลิกเลือกภาพล่าสุด → auto-attach + dialog ปิดเอง
// expectedAttachCount = จำนวน attachment ที่คาดหวังหลังแนบ (เช่น แนบรูปที่ 2 → expectedAttachCount = 2)
async function selectImageFromLibrary(expectedAttachCount = 0) {
  // จำ attachment count ก่อนเริ่ม
  const attachBefore = countAttachments();
  console.log(`[v17] Attachments before: ${attachBefore}`);

  const plusBtn = findPlusButton();
  if (!plusBtn) {
    console.log('[v17] Cannot find + button for selecting image');
    return false;
  }

  console.log('[v17] Clicking + to open Asset Picker...');
  plusBtn.click();

  // Step 1: รอ dialog เปิด
  let dialog = null;
  for (let i = 0; i < 15; i++) {
    dialog = document.querySelector('div[role="dialog"][data-state="open"]');
    if (dialog && isVisible(dialog)) break;
    await delay(500);
  }

  if (!dialog) {
    console.log('[v17] Asset Picker dialog not found');
    return false;
  }

  console.log('[v17] Asset Picker opened, looking for image items...');

  // Step 2: รอ thumbnails ปรากฏ → ใช้ findGalleryItems (v3.0)
  let itemRow = null;
  for (let i = 0; i < 15; i++) {
    const items = findGalleryItems(dialog);
    if (items.length > 0) {
      itemRow = items[0]; // เลือกรูปแรกสุด (ล่าสุดใน library)
      console.log(`[v17] Found ${items.length} items in library, selecting first`);
      break;
    }

    console.log(`[v17] Waiting for thumbnails... attempt ${i + 1}`);
    await delay(1000);
  }

  if (!itemRow) {
    console.log('[v17] No image items found in dialog');
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, bubbles: true }));
    return false;
  }

  // Step 3: คลิกเลือกภาพ — ลองหลายระดับ: img ก่อน → inner div → itemRow
  const imgInItem = itemRow.querySelector('img');
  const clickTarget = imgInItem || itemRow;
  console.log(`[v17] Clicking image item to select and attach... target: ${clickTarget.tagName}, class: "${(clickTarget.className || '').substring(0, 40)}", alt: "${clickTarget.alt || ''}"`);  realClick(clickTarget);
  await delay(500);
  // ถ้า dialog ยังเปิดอยู่ → ลอง click ที่ parent level
  if (document.querySelector('div[role="dialog"][data-state="open"]')) {
    console.log('[v17] Dialog still open after click — trying parent...');
    realClick(itemRow);
    await delay(500);
    // ยังเปิดอีก → ลอง data-item-index wrapper
    if (document.querySelector('div[role="dialog"][data-state="open"]')) {
      const wrapper = itemRow.closest('[data-item-index]') || itemRow.parentElement;
      if (wrapper && wrapper !== itemRow) {
        console.log('[v17] Still open — trying wrapper...');
        realClick(wrapper);
      }
    }
  }

  // Step 4: รอ dialog ปิด + attachment เพิ่มขึ้น (verified signal)
  const expectedCount = expectedAttachCount > 0 ? expectedAttachCount : attachBefore + 1;
  const attached = await waitForAttachment(expectedCount, 8000);

  if (attached) {
    const attachNow = countAttachments();
    console.log(`[v17] ✅ Image attached! Attachments: ${attachBefore} → ${attachNow}`);
    return true;
  }

  // Fallback: ถ้ายังไม่ได้ → ลอง Escape + เช็คอีกที
  const stillOpen = document.querySelector('div[role="dialog"][data-state="open"]');
  if (stillOpen) {
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, bubbles: true }));
    await delay(500);
  }

  const attachFinal = countAttachments();
  console.log(`[v17] After fallback: attachments = ${attachFinal} (expected ${expectedCount})`);
  return attachFinal >= expectedCount;
}

// v1.1: พิมพ์ชื่อไฟล์ในช่อง "Search for Assets" เพื่อกรองรูปที่ต้องการ
// DOM verified: <input type="text" placeholder="Search for Assets" class="sc-dbfb6b4a-7 eWBcld">
async function searchAssetByName(dialog, searchText) {
  console.log(`[v1.1-search] Searching for "${searchText}" in Asset Picker...`);
  try {
    // หา search input ใน dialog
    let searchInput = dialog.querySelector('input[placeholder*="Search"]');
    if (!searchInput) {
      searchInput = dialog.querySelector('input[class*="sc-903adef0"]');
    }
    if (!searchInput) {
      // fallback: หา input ที่ไม่ใช่ file input
      const inputs = dialog.querySelectorAll('input[type="text"], input:not([type])');
      for (const inp of inputs) {
        const ph = (inp.placeholder || '').toLowerCase();
        if (ph.includes('search') || ph.includes('asset') || ph.includes('find')) {
          searchInput = inp;
          break;
        }
      }
    }

    if (!searchInput) {
      console.log('[v1.1-search] ❌ Search input NOT found in dialog!');
      console.log('[v1.1-search] Dialog innerHTML preview:', dialog.innerHTML.substring(0, 500));
      // v1.1.2: ลองหา input ทุกตัวใน dialog
      const allInputs = dialog.querySelectorAll('input');
      console.log(`[v1.1-search] All inputs in dialog: ${allInputs.length}`);
      allInputs.forEach((inp, idx) => {
        console.log(`[v1.1-search]   input[${idx}]: type="${inp.type}" placeholder="${inp.placeholder}" class="${inp.className}"`);
      });
      return false;
    }

    console.log(`[v1.1-search] ✅ Found search input (placeholder="${searchInput.placeholder}", class="${searchInput.className}"), typing "${searchText}"...`);

    // Focus + clear + type
    searchInput.focus();
    await delay(200);

    // Clear existing text
    searchInput.value = '';
    searchInput.dispatchEvent(new Event('input', { bubbles: true }));
    await delay(200);

    // Type the search text using native setter (React/Radix compatible)
    const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    nativeSetter.call(searchInput, searchText);
    searchInput.dispatchEvent(new Event('input', { bubbles: true }));
    searchInput.dispatchEvent(new Event('change', { bubbles: true }));
    await delay(800); // รอ filter ทำงาน

    console.log(`[v1.1-search] ✅ Typed "${searchText}" in search — waiting for results...`);
    return true;

  } catch (err) {
    console.log('[v1.1-search] Search error:', err.message);
    return false;
  }
}

// v1.1: Clear search input (reset กลับเป็นปกติ หลังเลือกรูปเสร็จ)
async function clearAssetSearch(dialog) {
  try {
    let searchInput = dialog?.querySelector('input[placeholder*="Search"]');
    if (!searchInput) searchInput = dialog?.querySelector('input[class*="sc-903adef0"]');
    if (searchInput) {
      const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
      nativeSetter.call(searchInput, '');
      searchInput.dispatchEvent(new Event('input', { bubbles: true }));
      await delay(300);
    }
  } catch (e) { /* ignore */ }
}

// v3.0: Sort library เป็น Oldest — ใช้ text-based search แทน class
async function sortLibraryOldest(dialog) {
  console.log('[v1.1-sort] Sorting library by Oldest...');
  try {
    // v3.0: หา sort label จาก text content แทน class (กันปัญหา class เปลี่ยน)
    const allDivs = dialog.querySelectorAll('div, span');
    let currentSort = null;
    for (const label of allDivs) {
      const text = (label.textContent || '').trim();
      if (text === 'Oldest' || text === 'Newest' || text === 'Recently Used') {
        currentSort = label;
        console.log(`[v1.1-sort] Current sort: "${text}"`);
        break;
      }
    }

    // ถ้าเป็น Oldest อยู่แล้ว → ไม่ต้องทำอะไร
    if (currentSort && currentSort.textContent.trim() === 'Oldest') {
      console.log('[v1.1-sort] Already sorted by Oldest');
      return true;
    }

    // กด dropdown arrow (อยู่ข้างๆ sort label)
    // DOM: <i class="google-symbols">arrow_drop_down</i>
    let dropdownBtn = null;
    if (currentSort) {
      // หาปุ่มหรือ icon ข้างๆ
      dropdownBtn = currentSort.parentElement?.querySelector('i, button, [role="button"]');
      if (!dropdownBtn) dropdownBtn = currentSort.closest('button') || currentSort.closest('[role="button"]');
      if (!dropdownBtn) dropdownBtn = currentSort; // กด label ตรงๆ
    }

    if (!dropdownBtn) {
      console.log('[v1.1-sort] Sort dropdown not found');
      return false;
    }

    realClick(dropdownBtn);
    await delay(500);

    // หา "Oldest" ใน dropdown menu
    // ลองหาทั่ว DOM เพราะ menu อาจ render นอก dialog
    const allEls = document.querySelectorAll('div, button, [role="menuitem"], [role="option"]');
    for (const el of allEls) {
      const t = (el.textContent || '').trim();
      if (t === 'Oldest') {
        realClick(el);
        console.log('[v1.1-sort] ✅ Clicked "Oldest"');
        await delay(800);
        return true;
      }
    }

    console.log('[v1.1-sort] "Oldest" option not found');
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, bubbles: true }));
    await delay(300);
    return false;

  } catch (err) {
    console.log('[v1.1-sort] Sort error:', err.message);
    return false;
  }
}

// v3.0: ค้นหา item ใน library dialog ตามชื่อไฟล์ — ใช้ img[alt] แทน class ที่เปลี่ยนบ่อย
function findItemByFilename(dialog, targetName) {
  const target = targetName.toLowerCase();
  const targetNoExt = target.replace(/\.png$/i, '');

  // วิธี 1 (เสถียรสุด): หา img ที่มี alt ตรงกับชื่อไฟล์
  const allImgs = dialog.querySelectorAll('img[alt]');
  for (const img of allImgs) {
    const alt = (img.alt || '').toLowerCase();
    if (alt.includes(target) || alt.includes(targetNoExt)) {
      // ⚠️ เอา parentElement (inner div ที่มี onClick) ไม่ใช่ data-item-index (virtuoso wrapper)
      const clickable = img.parentElement || img;
      console.log(`[v3.0] ✅ Found "${targetName}" by img[alt="${img.alt}"], clicking: ${clickable.tagName}.${(clickable.className || '').substring(0, 30)}`);
      return clickable;
    }
  }

  // วิธี 2: หาจาก textContent ของ gallery items
  const galleryItems = findGalleryItems(dialog);
  for (const item of galleryItems) {
    const itemText = (item.textContent || '').trim().toLowerCase();
    if (itemText.includes(target) || itemText.includes(targetNoExt)) {
      console.log(`[v3.0] ✅ Found "${targetName}" by item textContent: "${itemText.substring(0, 60)}"`);
      return item;
    }
  }

  // วิธี 3: หลัง search กรองแล้ว → เลือก item แรก (น่าจะเป็นตัวที่ถูก)
  if (galleryItems.length > 0) {
    console.log(`[v3.0] Using first item after search/sort (${galleryItems.length} items visible)`);
    return galleryItems[0];
  }

  return null;
}

// v1.1 REWRITE: เลือกรูปจาก Library — Search First + Sort Oldest Fallback + items[0] Last Resort
// Fallback Chain:
//   1. Search input "pd-product.png" → กรองเหลือตัวเดียว → คลิก
//   2. Sort Oldest → หาตามชื่อ → คลิก
//   3. items[0] → คลิก
async function selectImageFromLibraryByName(targetName, expectedAttachCount = 0) {
  const attachBefore = countAttachments();
  console.log(`[v1.1] selectByName: looking for "${targetName}", attachBefore=${attachBefore}`);

  const plusBtn = findPlusButton();
  if (!plusBtn) {
    console.log('[v1.1] Cannot find + button');
    return false;
  }

  plusBtn.click();

  // รอ dialog เปิด
  let dialog = null;
  for (let i = 0; i < 15; i++) {
    dialog = document.querySelector('div[role="dialog"][data-state="open"]');
    if (dialog && isVisible(dialog)) break;
    await delay(500);
  }
  if (!dialog) {
    console.log('[v1.1] Asset Picker dialog not found');
    return false;
  }

  // รอ items โหลด
  await delay(500);

  // === Strategy 1: Search by filename (แม่นสุด) ===
  // พิมพ์ชื่อไฟล์ในช่อง Search → กรองเหลือตัวที่ต้องการ → คลิก
  // v1.1.2 FIX: ค้นหาด้วยชื่อไม่ต้องมี .png — Google Flow search ไม่ match extension
  const searchName = targetName.replace(/\.png$/i, '');
  console.log(`[v1.1.2] Searching library for: "${searchName}" (original: "${targetName}")`);
  const searched = await searchAssetByName(dialog, searchName);

  let targetItem = null;
  if (searched) {
    // รอ filter ทำงาน แล้วหา item
    for (let attempt = 0; attempt < 10; attempt++) {
      dialog = document.querySelector('div[role="dialog"][data-state="open"]');
      if (!dialog) break;
      targetItem = findItemByFilename(dialog, targetName);
      if (targetItem) {
        console.log(`[v1.1] ✅ Found "${targetName}" via Search!`);
        break;
      }
      await delay(500);
    }

    // ถ้า search แล้วไม่เจอ → ลองค้นหาแค่ส่วน "setN" (unique part)
    if (!targetItem && searchName.includes('set')) {
      const shortSearch = searchName.match(/set\d+/)?.[0];
      if (shortSearch) {
        console.log(`[v1.1.2] Full name search failed — trying short search: "${shortSearch}"`);
        await clearAssetSearch(dialog);
        await delay(300);
        dialog = document.querySelector('div[role="dialog"][data-state="open"]');
        if (dialog) {
          await searchAssetByName(dialog, shortSearch);
          for (let attempt = 0; attempt < 8; attempt++) {
            dialog = document.querySelector('div[role="dialog"][data-state="open"]');
            if (!dialog) break;
            targetItem = findItemByFilename(dialog, targetName);
            if (targetItem) {
              console.log(`[v1.1.2] ✅ Found "${targetName}" via short search "${shortSearch}"!`);
              break;
            }
            await delay(500);
          }
        }
      }
    }

    // ถ้า search แล้วไม่เจอ → clear search + ลอง fallback
    if (!targetItem) {
      console.log(`[v1.1.2] Search returned no match — clearing search, trying Sort Oldest...`);
      await clearAssetSearch(dialog);
      await delay(500);
    }
  }

  // === Strategy 2: Sort Oldest + find by filename ===
  if (!targetItem) {
    dialog = document.querySelector('div[role="dialog"][data-state="open"]');
    if (dialog) {
      const sorted = await sortLibraryOldest(dialog);
      if (sorted) {
        await delay(500);
        dialog = document.querySelector('div[role="dialog"][data-state="open"]');
        if (dialog) {
          for (let attempt = 0; attempt < 10; attempt++) {
            targetItem = findItemByFilename(dialog, targetName);
            if (targetItem) {
              console.log(`[v1.1] ✅ Found "${targetName}" via Sort Oldest!`);
              break;
            }
            await delay(500);
          }
        }
      }
    }
  }

  // === Strategy 3: Last resort — items[0] ===
  if (!targetItem) {
    dialog = document.querySelector('div[role="dialog"][data-state="open"]');
    if (dialog) {
      const allItems = findGalleryItems(dialog);
      if (allItems.length > 0) {
        targetItem = allItems[0];
        console.log(`[v1.1] ⚠️ "${targetName}" — last resort: selecting items[0]`);
      }
    }
  }

  if (!targetItem) {
    console.log(`[v1.1] ❌ No items found — closing dialog`);
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, bubbles: true }));
    await delay(500);
    return false;
  }

  // คลิกเลือก — ลองหลายระดับ: img ก่อน → inner div → targetItem
  const imgTarget = targetItem.querySelector('img') || targetItem;
  console.log(`[v1.1] Clicking: ${imgTarget.tagName}.${(imgTarget.className || '').substring(0, 40)}, alt="${imgTarget.alt || ''}"`);
  realClick(imgTarget);
  await delay(500);
  // ถ้า dialog ยังเปิดอยู่ → ลอง click ที่ parent level
  if (document.querySelector('div[role="dialog"][data-state="open"]')) {
    console.log('[v1.1] Dialog still open after img click — trying parent...');
    realClick(targetItem);
  }

  const expectedCount = expectedAttachCount > 0 ? expectedAttachCount : attachBefore + 1;
  const attached = await waitForAttachment(expectedCount, 8000);

  if (attached) {
    console.log(`[v1.1] ✅ "${targetName}" attached!`);
    return true;
  }

  // Fallback close
  const stillOpen = document.querySelector('div[role="dialog"][data-state="open"]');
  if (stillOpen) {
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, bubbles: true }));
    await delay(500);
  }
  const attachFinal = countAttachments();
  return attachFinal >= expectedCount;
}

// v17 Helper: รอจน dialog ปิด + attachment count ครบ
async function waitForAttachment(expectedCount, timeout = 5000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    const dialogOpen = !!document.querySelector('[role="dialog"][data-state="open"]');
    const currentCount = countAttachments();
    if (!dialogOpen && currentCount >= expectedCount) return true;
    await delay(200);
  }
  return false;
}

// ลองหลายวิธีอัพโหลดรูป (v17.4: รับ filename parameter)
async function tryAlternativeUpload(imageBase64, filename = 'product.png') {
  const file = base64ToFile(imageBase64, filename);

  // หา target elements ที่อาจรับ drop/paste ได้
  const targets = [];

  // 1. contenteditable
  const editableDiv = document.querySelector('[contenteditable="true"]');
  if (editableDiv) targets.push({ el: editableDiv, name: 'contenteditable' });

  // 2. textarea
  const textarea = document.querySelector('textarea');
  if (textarea) targets.push({ el: textarea, name: 'textarea' });

  // 3. prompt area ด้านล่าง (หา div ที่มี placeholder text เกี่ยวกับ prompt)
  const allDivs = document.querySelectorAll('div');
  for (const div of allDivs) {
    const text = (div.textContent || '').toLowerCase();
    const rect = div.getBoundingClientRect();
    if ((text.includes('generate') || text.includes('type') || text.includes('prompt')) &&
        rect.bottom > window.innerHeight * 0.6 && rect.width > 200) {
      targets.push({ el: div, name: 'prompt-div' });
      break;
    }
  }

  // 4. document body
  targets.push({ el: document.body, name: 'body' });

  // ลองแต่ละ target
  for (const target of targets) {
    console.log(`Trying upload to ${target.name}...`);

    // Focus element ก่อน (ถ้าทำได้)
    try {
      target.el.focus();
      await delay(100);
    } catch (e) { }

    // วิธี 1: Paste event
    const pasteSuccess = await tryPasteUpload(target.el, file);
    if (pasteSuccess) {
      console.log(`Paste upload success to ${target.name}`);
      await waitForUploadComplete();
      return true;
    }

    // วิธี 2: Drag & Drop
    const dropSuccess = await tryDragDropUpload(target.el, file);
    if (dropSuccess) {
      console.log(`Drag-drop upload success to ${target.name}`);
      await waitForUploadComplete();
      return true;
    }
  }

  return false;
}

// ลอง paste upload
async function tryPasteUpload(element, file) {
  try {
    console.log('Trying paste event...');

    // สร้าง ClipboardEvent
    const clipboardData = new DataTransfer();
    clipboardData.items.add(file);

    const pasteEvent = new ClipboardEvent('paste', {
      bubbles: true,
      cancelable: true,
      clipboardData: clipboardData
    });

    element.dispatchEvent(pasteEvent);
    await delay(500);

    // เช็คว่ามีรูปปรากฏในหน้าหรือไม่
    const hasImage = checkIfImageAppeared();
    return hasImage;
  } catch (e) {
    console.log('Paste failed:', e.message);
    return false;
  }
}

// ลอง drag & drop upload
async function tryDragDropUpload(element, file) {
  try {
    console.log('Trying drag-drop event...');

    const dataTransfer = new DataTransfer();
    dataTransfer.items.add(file);

    // Fire drag events sequence
    const events = ['dragenter', 'dragover', 'drop'];
    for (const eventType of events) {
      const event = new DragEvent(eventType, {
        bubbles: true,
        cancelable: true,
        dataTransfer: dataTransfer
      });
      element.dispatchEvent(event);
      await delay(100);
    }

    await delay(500);

    // เช็คว่ามีรูปปรากฏในหน้าหรือไม่
    const hasImage = checkIfImageAppeared();
    return hasImage;
  } catch (e) {
    console.log('Drag-drop failed:', e.message);
    return false;
  }
}

// เช็คว่ามีรูปปรากฏในหน้าหรือไม่ (หลัง upload)
function checkIfImageAppeared() {
  // หา img ใหม่ที่เพิ่งปรากฏ หรือ thumbnail หรือ preview
  const images = document.querySelectorAll('img[src*="blob:"], img[src*="data:"], [class*="thumbnail"], [class*="preview"], [class*="uploaded"]');
  if (images.length > 0) {
    console.log('Image appeared in page');
    return true;
  }

  // หา file input ที่มี files แล้ว
  const fileInputs = document.querySelectorAll('input[type="file"]');
  for (const input of fileInputs) {
    if (input.files && input.files.length > 0) {
      console.log('File input has files');
      return true;
    }
  }

  return false;
}

// รอให้ upload เสร็จ
async function waitForUploadComplete() {
  const uploadWait = currentMode === 'image' ? 8 : 12;
  updateStatus(`กำลังอัพโหลดรูป... รอ ${uploadWait} วินาที`);
  await delay(uploadWait * 1000);
}

// หา chat input area สำหรับ drag & drop
function findChatInputArea() {
  // หา contenteditable div (ช่อง prompt)
  const editableDiv = document.querySelector('[contenteditable="true"]');
  if (editableDiv) {
    console.log('Found contenteditable for drag-drop');
    return editableDiv;
  }

  // หา textarea
  const textarea = document.querySelector('textarea');
  if (textarea) {
    console.log('Found textarea for drag-drop');
    return textarea;
  }

  // หา prompt area container
  const promptAreas = document.querySelectorAll('[class*="prompt"], [class*="input"], [class*="chat"], [class*="compose"]');
  for (const area of promptAreas) {
    const rect = area.getBoundingClientRect();
    // ต้องอยู่ด้านล่างและมีขนาดพอสมควร
    if (rect.bottom > window.innerHeight * 0.7 && rect.width > 200 && rect.height > 30) {
      console.log('Found prompt area for drag-drop');
      return area;
    }
  }

  // หา bing/chat container ที่อยู่ล่างสุด
  const allDivs = document.querySelectorAll('div');
  for (const div of allDivs) {
    const rect = div.getBoundingClientRect();
    // ต้องอยู่ล่าง, กว้างพอ, และไม่เล็กเกินไป
    if (rect.bottom > window.innerHeight * 0.85 &&
        rect.width > window.innerWidth * 0.3 &&
        rect.height > 50 && rect.height < 300) {
      // เช็คว่าไม่ใช่ปุ่ม
      if (!div.closest('button') && !div.getAttribute('role')?.includes('button')) {
        console.log('Found bottom area div for drag-drop');
        return div;
      }
    }
  }

  return null;
}

// หา drop zone สำหรับ drag & drop
function findDropZone() {
  // หา popup/modal ที่เพิ่งเปิด (มักมี "อัปโหลด" / "Upload" / "Gallery" text)
  const modals = document.querySelectorAll('[role="dialog"], [class*="modal"], [class*="popup"], [class*="overlay"]');

  for (const modal of modals) {
    if (modal.offsetParent !== null) {
      const text = modal.textContent || '';
      if (text.includes('อัปโหลด') || text.includes('Upload') || text.includes('แกลเลอรี') || text.includes('Gallery')) {
        console.log('Found modal as drop zone');
        return modal;
      }
    }
  }

  // หา div ที่มี drop zone characteristics
  const dropAreas = document.querySelectorAll('[class*="drop"], [class*="upload"], [class*="drag"]');
  for (const area of dropAreas) {
    if (area.offsetParent !== null) {
      return area;
    }
  }

  return null;
}

// อัพโหลดผ่าน drag & drop (ไม่เปิด file dialog) (v17.4: รับ filename)
async function uploadViaDragDrop(dropZone, imageBase64, filename = 'product.png') {
  console.log('Uploading via drag & drop...');

  const file = base64ToFile(imageBase64, filename);

  // สร้าง DataTransfer object
  const dataTransfer = new DataTransfer();
  dataTransfer.items.add(file);

  // สร้าง drag events
  const dragEnterEvent = new DragEvent('dragenter', {
    bubbles: true,
    cancelable: true,
    dataTransfer: dataTransfer
  });

  const dragOverEvent = new DragEvent('dragover', {
    bubbles: true,
    cancelable: true,
    dataTransfer: dataTransfer
  });

  const dropEvent = new DragEvent('drop', {
    bubbles: true,
    cancelable: true,
    dataTransfer: dataTransfer
  });

  // Fire events
  dropZone.dispatchEvent(dragEnterEvent);
  await modeDelay(100, 50);
  dropZone.dispatchEvent(dragOverEvent);
  await modeDelay(100, 50);
  dropZone.dispatchEvent(dropEvent);

  console.log('Drag & drop events dispatched');

  // รอให้อัพโหลดเสร็จ
  // Video: 12 วินาที / Image: 8 วินาที
  const uploadWait = currentMode === 'image' ? 8 : 12;
  updateStatus(`กำลังอัพโหลดรูป... รอ ${uploadWait} วินาที`);
  await delay(uploadWait * 1000);
}

// Helper function to upload file to input (v17.4: รับ filename)
async function uploadToFileInput(fileInput, imageBase64, filename = 'product.png') {
  console.log(`Uploading to file input as "${filename}"...`);

  // Create file from base64
  const file = base64ToFile(imageBase64, filename);

  // Create DataTransfer to set files
  const dataTransfer = new DataTransfer();
  dataTransfer.items.add(file);
  fileInput.files = dataTransfer.files;

  // Trigger change event
  fileInput.dispatchEvent(new Event('change', { bubbles: true }));
  fileInput.dispatchEvent(new Event('input', { bubbles: true }));

  console.log('File upload events dispatched');

  // รอให้อัพโหลดเสร็จ
  // Video: 12 วินาที / Image: 8 วินาที
  const uploadWait = currentMode === 'image' ? 8 : 12;
  updateStatus(`กำลังอัพโหลดรูป... รอ ${uploadWait} วินาที`);
  await delay(uploadWait * 1000);
}

// Step 4: Handle crop dialog
async function step4_HandleCrop(data) {
  updateStatus('กำลังครอบตัดรูป...');

  // Wait for crop dialog to appear (ลดเหลือ 300ms / 150ms สำหรับ image)
  await modeDelay(300, 150);

  // Check if crop dialog exists (รองรับทั้งไทยและอังกฤษ + v17 terminology)
  const cropDialogTexts = ['ครอบตัดส่วนผสม', 'Crop ingredient', 'ครอบตัดเฟรม', 'Crop frame', 'Crop start', 'Crop'];
  const cropDialog = Array.from(document.querySelectorAll('*')).find(el => {
    const text = el.textContent || '';
    return cropDialogTexts.some(t => text.includes(t));
  });

  if (!cropDialog) {
    console.log('No crop dialog found, skipping...');
    return;
  }

  console.log('Crop dialog found');

  // Step 4.1: Select aspect ratio (แนวตั้ง/แนวนอน / Portrait/Landscape)
  const aspectButtons = document.querySelectorAll('button[role="combobox"], button, div[role="button"]');
  let aspectDropdown = null;

  // รองรับทั้งไทยและอังกฤษ + icons
  const verticalTexts = ['แนวตั้ง', 'Portrait'];
  const horizontalTexts = ['แนวนอน', 'Landscape'];
  const verticalIcons = ['crop_9_16', 'crop_portrait'];
  const horizontalIcons = ['crop_16_9', 'crop_landscape'];

  for (const btn of aspectButtons) {
    const text = (btn.textContent || '').trim();
    const html = btn.innerHTML || '';
    // หาจาก text หรือ icon
    if (verticalTexts.some(t => text.includes(t)) || horizontalTexts.some(t => text.includes(t)) ||
        verticalIcons.some(i => html.includes(i)) || horizontalIcons.some(i => html.includes(i))) {
      aspectDropdown = btn;
      console.log('Found aspect ratio dropdown:', text);
      break;
    }
  }

  if (aspectDropdown && data) {
    const wantVertical = data.aspectRatio === '9:16';
    const targetTexts = wantVertical ? verticalTexts : horizontalTexts;
    const targetIcons = wantVertical ? verticalIcons : horizontalIcons;

    // ลองเปลี่ยน aspect ratio สูงสุด 3 ครั้ง
    for (let attempt = 0; attempt < 3; attempt++) {
      const currentAspect = aspectDropdown.textContent || '';
      const currentHtml = aspectDropdown.innerHTML || '';
      // เช็คจาก text หรือ icon
      const isCurrentlyVertical = verticalTexts.some(t => currentAspect.includes(t)) ||
                                  verticalIcons.some(i => currentHtml.includes(i));

      // ถ้าถูกแล้ว ไม่ต้องเปลี่ยน
      if (wantVertical === isCurrentlyVertical) {
        console.log('Aspect ratio is already correct:', currentAspect);
        break;
      }

      console.log(`Changing aspect ratio... (attempt ${attempt + 1}/3)`);
      console.log(`Looking for: ${wantVertical ? 'Portrait/แนวตั้ง' : 'Landscape/แนวนอน'}`);
      await clickWithOverlay(aspectDropdown);
      await delay(1500); // รอ dropdown เปิดให้เต็มที่

      // Find and click the correct option - ค้นหาหลายวิธี
      let found = false;

      // วิธี 1: หาจาก role="option" หรือ listbox items
      const optionSelectors = [
        '[role="option"]',
        '[role="menuitem"]',
        '[role="listbox"] > *',
        'ul[role="listbox"] li',
        'div[role="listbox"] > div',
        'mat-option',
        '[class*="option"]',
        '[class*="menu-item"]',
        '[class*="dropdown-item"]'
      ];

      let options = [];
      for (const selector of optionSelectors) {
        const found = document.querySelectorAll(selector);
        if (found.length > 0) {
          options = Array.from(found);
          console.log(`Found ${options.length} options with selector: ${selector}`);
          break;
        }
      }

      // วิธี 2: ถ้าไม่เจอจาก role ให้หาจาก element ที่มี text Portrait/Landscape
      if (options.length === 0) {
        console.log('No options found by role, searching by text...');
        const allElements = document.querySelectorAll('*');
        const searchTexts = [...targetTexts, ...verticalTexts, ...horizontalTexts];

        for (const el of allElements) {
          const elText = (el.textContent || '').trim();
          const elHtml = el.innerHTML || '';
          // element ต้องมีขนาดเล็ก (เป็น option ไม่ใช่ container ใหญ่)
          const rect = el.getBoundingClientRect();
          if (rect.width > 0 && rect.width < 400 && rect.height > 0 && rect.height < 100) {
            if (searchTexts.some(t => elText.includes(t)) ||
                verticalIcons.some(i => elHtml.includes(i)) ||
                horizontalIcons.some(i => elHtml.includes(i))) {
              // ไม่เอาตัว dropdown button เอง
              if (el !== aspectDropdown && !aspectDropdown.contains(el)) {
                options.push(el);
              }
            }
          }
        }
        console.log(`Found ${options.length} options by text search`);
      }

      // Log ทุก option ที่เจอ
      console.log('All options found:');
      options.forEach((opt, i) => {
        console.log(`  [${i}] "${(opt.textContent || '').trim().substring(0, 50)}"`);
      });

      // เลือก option ที่ตรงกับ target
      for (const opt of options) {
        const optText = (opt.textContent || '').trim();
        const optHtml = opt.innerHTML || '';

        // เช็คจาก text หรือ icon
        const matchesTarget = targetTexts.some(t => optText.includes(t)) ||
                             targetIcons.some(i => optHtml.includes(i));

        if (matchesTarget) {
          console.log(`Clicking option: "${optText}"`);
          await clickWithOverlay(opt);
          found = true;
          await delay(2000);
          break;
        }
      }

      // ถ้าไม่เจอ option ให้กด Escape ปิด dropdown แล้วลองใหม่
      if (!found) {
        console.log('Target option not found in dropdown, pressing Escape...');
        document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
        await delay(500);
      }

      // ตรวจสอบว่าเปลี่ยนสำเร็จหรือยัง (เช็คจาก icon ด้วย)
      await delay(500);
      const newAspect = aspectDropdown.textContent || '';
      const newHtml = aspectDropdown.innerHTML || '';
      const isNowVertical = verticalTexts.some(t => newAspect.includes(t)) ||
                           verticalIcons.some(i => newHtml.includes(i));
      if (wantVertical === isNowVertical) {
        console.log('Aspect ratio changed successfully');
        break;
      } else if (attempt < 2) {
        console.log('Aspect ratio change failed, retrying...');
        await delay(1000);
      }
    }
  }

  // Step 4.2: Click "ครอบตัดและบันทึก" / "Crop and Save" button
  await delay(1000);

  let saveBtn = null;
  const allButtons = document.querySelectorAll('button');

  // รองรับทั้งไทยและอังกฤษ (Crop and Save - S ตัวใหญ่!)
  const saveButtonTexts = ['ครอบตัดและบันทึก', 'Crop and Save', 'Crop and save', 'บันทึก', 'Save'];

  for (const btn of allButtons) {
    const text = (btn.textContent || '').trim();
    const html = btn.innerHTML || '';
    // หาจาก text
    if (saveButtonTexts.some(t => text.includes(t))) {
      saveBtn = btn;
      console.log('Found save button:', text);
      break;
    }
    // หาจาก icon crop + text
    if (html.includes('>crop<') && (text.toLowerCase().includes('save') || text.toLowerCase().includes('crop'))) {
      saveBtn = btn;
      console.log('Found save button by icon:', text);
      break;
    }
  }

  if (saveBtn) {
    console.log('Clicking save button');
    await clickWithOverlay(saveBtn);

    // Step 4.3: Wait for processing (18 วินาที - รอรูปอัพโหลดเสร็จ)
    const waitTime = 18;
    updateBotOverlay('กำลังประมวลผลรูป...', `รอ ${waitTime} วินาที`);
    await delay(waitTime * 1000);
  } else {
    console.log('Save button not found, waiting anyway...');
    await delay(10000);
  }
}

// Step 5: Enter prompt
// v17: prompt input เป็น div[role="textbox"][contenteditable="true"] (Radix)
async function step5_EnterPrompt(prompt) {
  updateStatus('กำลังกรอก Prompt...');

  await delay(500);

  let promptInput = null;

  // DOM verified: div[role="textbox"][contenteditable="true"].sc-f60f777e-0
  // Parent: div.sc-c70e41ad-3, Placeholder: child span → "What do you want to create?"
  promptInput = document.querySelector('div[role="textbox"][contenteditable="true"]');
  if (promptInput) {
    console.log('[v17] Found prompt input (role="textbox" contenteditable)');
  }

  // วิธี 2: หา contenteditable ที่อยู่ด้านล่างจอ
  if (!promptInput) {
    const editables = document.querySelectorAll('[contenteditable="true"]');
    for (const ed of editables) {
      const rect = ed.getBoundingClientRect();
      if (rect.top > window.innerHeight * 0.5 && isVisible(ed)) {
        promptInput = ed;
        console.log('[v17] Found prompt contenteditable at bottom');
        break;
      }
    }
  }

  // วิธี 3: textarea (กรณี UI อื่น)
  if (!promptInput) {
    const textareas = document.querySelectorAll('textarea');
    for (const ta of textareas) {
      const rect = ta.getBoundingClientRect();
      if (rect.top > window.innerHeight * 0.5 && isVisible(ta)) {
        promptInput = ta;
        console.log('[v17] Found prompt textarea at bottom');
        break;
      }
    }
  }

  if (!promptInput) {
    throw new Error('ไม่พบช่องกรอก Prompt');
  }

  promptInput.focus();
  await delay(100);

  // Clear existing text + ใส่ prompt ใหม่
  if (promptInput.getAttribute('contenteditable') === 'true') {
    // v17.5b: ยกระบบจาก storyStep5_EnterPrompt — ป้องกัน Slate.js crash
    // ห้ามใช้ execCommand เด็ดขาด! ใช้ Clipboard Paste retry + InputEvent insertFromPaste

    // === Clipboard Paste — retry สูงสุด 3 ครั้ง (เว้น delay ให้ editor settle) ===
    let pasteSuccess = false;
    const checkStr = prompt.substring(0, Math.min(20, prompt.length));

    for (let attempt = 1; attempt <= 3; attempt++) {
      promptInput.focus();
      await delay(attempt === 1 ? 200 : 500); // ครั้งแรกรอน้อย, ครั้งต่อไปรอมากขึ้น

      // Select all existing text → จะถูกแทนที่ด้วย paste
      const selection = window.getSelection();
      const range = document.createRange();
      range.selectNodeContents(promptInput);
      selection.removeAllRanges();
      selection.addRange(range);
      await delay(50);

      // Dispatch ClipboardEvent paste
      const dt = new DataTransfer();
      dt.setData('text/plain', prompt);
      const pasteEvent = new ClipboardEvent('paste', {
        clipboardData: dt,
        bubbles: true,
        cancelable: true
      });
      promptInput.dispatchEvent(pasteEvent);
      await delay(400);

      // เช็คว่า paste ติดหรือยัง
      const currentText = (promptInput.textContent || promptInput.innerText || '').trim();
      console.log(`[v17.5b] Paste attempt ${attempt}: text="${currentText.substring(0, 50)}..." (len=${currentText.length})`);

      if (currentText.includes(checkStr)) {
        pasteSuccess = true;
        console.log(`[v17.5b] ✅ Clipboard paste สำเร็จ (attempt ${attempt})`);
        break;
      }

      console.log(`[v17.5b] ⚠️ Paste attempt ${attempt} ไม่ติด — ${attempt < 3 ? 'blur+focus แล้วลองอีก...' : 'ลอง InputEvent...'}`);

      // blur + focus ใหม่ ก่อน retry (reset editor state)
      promptInput.blur();
      await delay(300);
    }

    // === Fallback: InputEvent insertFromPaste (Slate.js รองรับ — ปลอดภัยกว่า execCommand) ===
    if (!pasteSuccess) {
      console.log('[v17.5b] 🔄 Trying InputEvent insertFromPaste fallback...');

      promptInput.focus();
      await delay(300);

      // Select all
      const selection = window.getSelection();
      const range = document.createRange();
      range.selectNodeContents(promptInput);
      selection.removeAllRanges();
      selection.addRange(range);
      await delay(50);

      // Delete existing content via InputEvent
      promptInput.dispatchEvent(new InputEvent('beforeinput', {
        inputType: 'deleteContentBackward',
        bubbles: true,
        cancelable: true
      }));
      promptInput.dispatchEvent(new InputEvent('input', {
        inputType: 'deleteContentBackward',
        bubbles: true
      }));
      await delay(100);

      // Insert text via InputEvent insertFromPaste
      const dt2 = new DataTransfer();
      dt2.setData('text/plain', prompt);

      promptInput.dispatchEvent(new InputEvent('beforeinput', {
        inputType: 'insertFromPaste',
        data: prompt,
        dataTransfer: dt2,
        bubbles: true,
        cancelable: true
      }));
      promptInput.dispatchEvent(new InputEvent('input', {
        inputType: 'insertFromPaste',
        data: prompt,
        dataTransfer: dt2,
        bubbles: true
      }));
      await delay(400);

      // เช็คอีกครั้ง
      const text2 = (promptInput.textContent || promptInput.innerText || '').trim();
      if (text2.includes(checkStr)) {
        console.log('[v17.5b] ✅ InputEvent insertFromPaste สำเร็จ');
        pasteSuccess = true;
      } else {
        // Last resort: textContent ตรงๆ (ไม่ crash แต่ Slate อาจไม่รู้)
        console.log('[v17.5b] ⚠️ InputEvent ก็ไม่ติด — ใส่ textContent ตรงๆ');
        promptInput.textContent = prompt;
        await delay(100);
      }
    }

    // v18: Fire generic events เพื่อ notify Slate ว่ามีการเปลี่ยนแปลง
    // ⚠️ ห้ามใช้ inputType: 'insertText' + data: prompt เพราะ Slate จะ insert ซ้ำอีกรอบ!
    // (เดิมใช้ insertText ทำให้ prompt ซ้ำ 2 เท่า — "soft light2 คน พูดขายสินค้า..." bug)
    promptInput.dispatchEvent(new Event('input', { bubbles: true }));
    promptInput.dispatchEvent(new Event('change', { bubbles: true }));

  } else {
    // textarea/input
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
      window.HTMLTextAreaElement?.prototype || window.HTMLInputElement?.prototype,
      'value'
    )?.set;

    if (nativeInputValueSetter) {
      nativeInputValueSetter.call(promptInput, '');
      promptInput.dispatchEvent(new Event('input', { bubbles: true }));
      await delay(50);
      nativeInputValueSetter.call(promptInput, prompt);
    } else {
      promptInput.value = prompt;
    }
    promptInput.dispatchEvent(new Event('input', { bubbles: true }));
  }

  await delay(500);
  console.log(`[v17] Prompt entered: "${prompt.substring(0, 50)}..."`);
}

// Step 6: Click generate (ใช้วิธีเดียวกับ v1.1 ที่ทำงานได้)
// v6.2.1: เพิ่ม retry loop เพราะบางครั้งปุ่มยังไม่พร้อม
async function step6_Generate() {
  updateStatus('กำลังหาปุ่ม Generate...');

  const maxRetries = 5; // ลองสูงสุด 5 ครั้ง

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    console.log(`🔄 [Attempt ${attempt}/${maxRetries}] Looking for Generate button...`);

    // รอก่อนหาปุ่ม (attempt แรกรอ 1 วิ, attempt ถัดไปรอ 1.5 วิ)
    await delay(attempt === 1 ? 1000 : 1500);

    let generateBtn = null;
    const allButtons = Array.from(document.querySelectorAll('button'));
    const promptArea = findPromptAreaContainer();
    console.log('📍 Prompt area found:', !!promptArea);

    // v4.2.2 NEW PRIMARY: หา button ที่มี <i>arrow_forward</i> + accessible name "Create"/"Generate"
    // (Flow update 2026-05-07: button class เปลี่ยน sc-c70e41ad-4 → sc-e8425ea6-0 + ไม่มี type="submit"
    //  + ใช้ hidden span "Create" สำหรับ accessibility — visually เห็นแค่ icon arrow_forward)
    for (const btn of allButtons) {
      if (!isVisible(btn)) continue;
      const icon = btn.querySelector('i.google-symbols, span.google-symbols');
      if (!icon || icon.textContent.trim() !== 'arrow_forward') continue;

      const text = (btn.textContent || '').toLowerCase();
      const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();
      // accessible name (รวม textContent ที่ครอบทั้ง icon + hidden span)
      if (/create|generate/.test(text) || /create|generate/.test(ariaLabel)) {
        if (!btn.disabled && btn.getAttribute('aria-disabled') !== 'true') {
          generateBtn = btn;
          console.log('✅ [v4.2.2] Found Create/Generate button via arrow_forward icon + "Create" name');
          break;
        }
      }
    }

    // Legacy: button[type="submit"] (Flow ก่อน 2026-05-07)
    if (!generateBtn) {
      const submitBtn = document.querySelector('button[type="submit"].sc-c70e41ad-4') ||
                        document.querySelector('button[type="submit"]');
      if (submitBtn && isVisible(submitBtn)) {
        if (!submitBtn.disabled && submitBtn.getAttribute('aria-disabled') !== 'true') {
          generateBtn = submitBtn;
          console.log('✅ [legacy] Found generate button (type="submit")');
        }
      }
    }

    // Legacy fallback: หาจาก sc-c70e41ad-4 class อย่างเดียว
    if (!generateBtn) {
      const scBtn = document.querySelector('button[class*="sc-c70e41ad-4"]');
      if (scBtn && isVisible(scBtn) && !scBtn.disabled) {
        generateBtn = scBtn;
        console.log('✅ [legacy] Found generate button (sc-class)');
      }
    }

    // วิธีที่ 1 (v17): หาปุ่มใน prompt area ที่มี arrow_forward icon
    if (!generateBtn && promptArea) {
      console.log('📍 Method 1: Looking in prompt area for arrow_forward...');
      const buttonsInPromptArea = Array.from(promptArea.querySelectorAll('button'));
      console.log(`📍 Buttons in prompt area: ${buttonsInPromptArea.length}`);

      for (const btn of buttonsInPromptArea) {
        const text = btn.textContent || '';
        if (text.includes('arrow_forward') && isVisible(btn)) {
          generateBtn = btn;
          console.log('✅ Found generate button in prompt area (arrow_forward)');
          break;
        }
      }
    }

    // วิธีที่ 2: หาจากตำแหน่งล่างขวา (arrow_forward)
    if (!generateBtn) {
      console.log('📍 Method 2: Bottom buttons with arrow_forward...');
      const bottomButtons = allButtons.filter(btn => {
        const rect = btn.getBoundingClientRect();
        return isVisible(btn) && rect.top > window.innerHeight * 0.70;
      });
      console.log(`📍 Bottom buttons found: ${bottomButtons.length}`);

      for (const btn of bottomButtons) {
        const text = btn.textContent || '';
        if (text.includes('arrow_forward') &&
            !text.includes('arrow_drop_down') && !text.includes('settings')) {
          generateBtn = btn;
          console.log('✅ Found generate button (bottom with arrow_forward)');
          break;
        }
      }
    }

    // วิธีที่ 3 (สำรอง): ปุ่มขวาสุดใน prompt area ที่ไม่ใช่ Settings/Chip
    if (!generateBtn && promptArea) {
      console.log('📍 Method 3: Rightmost non-Settings button...');
      const buttons = Array.from(promptArea.querySelectorAll('button'));

      buttons.sort((a, b) => b.getBoundingClientRect().right - a.getBoundingClientRect().right);

      for (const btn of buttons) {
        if (!isVisible(btn)) continue;
        const text = btn.textContent || '';
        // ข้ามปุ่ม Settings/Chip, Expand, dropdown, + button
        if (!text.includes('tune') && !text.includes('Settings') &&
            !text.includes('Expand') && !text.includes('arrow_drop_down') &&
            !text.includes('Video') && !text.includes('Image') &&
            text !== '+' && text !== 'add') {
          const rect = btn.getBoundingClientRect();
          if (rect.width < 80) { // ปุ่ม Generate มักเล็ก
            generateBtn = btn;
            console.log('✅ Found generate button (rightmost non-Settings, small)');
            break;
          }
        }
      }
    }

    if (generateBtn) {
      const rect = generateBtn.getBoundingClientRect();
      const btnText = (generateBtn.textContent || '').trim().substring(0, 30);
      const ariaLabel = generateBtn.getAttribute('aria-label') || '';
      console.log(`✅ [Attempt ${attempt}] Clicking generate button at: ${rect.left.toFixed(0)}, ${rect.top.toFixed(0)}, size: ${rect.width.toFixed(0)}x${rect.height.toFixed(0)}`);
      console.log(`   Button text: "${btnText}", aria-label: "${ariaLabel}"`);
      console.log(`   Current mode: ${currentMode}`);

      // v6.2.1: ตรวจสอบว่าปุ่ม disabled หรือไม่
      if (generateBtn.disabled || generateBtn.getAttribute('aria-disabled') === 'true') {
        console.log(`⚠️ [Attempt ${attempt}] Generate button is disabled`);
        // v17: ลอง re-focus prompt แล้วกด Enter เพื่อ trigger generate
        if (attempt >= 3) {
          console.log(`🔄 [Attempt ${attempt}] Trying Enter key in prompt field...`);
          const promptField = document.querySelector('div[role="textbox"][contenteditable="true"]');
          if (promptField) {
            promptField.focus();
            await delay(200);
            promptField.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: ' ' }));
            await delay(300);
          }
        }
        continue; // ลองรอบถัดไป
      }

      updateStatus('กำลังกดปุ่ม Generate...');

      // v4.2.2 SMART VERIFY: เช็ค card count + prompt cleared (signals จริง)
      // v4.2.2 Flow update 2026-05-07: ใช้ multi-selector รับ Flow ใหม่ (labs.google trpc)
      // และ Flow เก่า (ai-sandbox-videofx, storage.googleapis.com)
      const promptInputCheck = document.querySelector('div[role="textbox"][contenteditable="true"]') ||
                               document.querySelector('[contenteditable="true"]');
      const captureState = () => {
        // signal 1: img tag with generated content (Flow ใหม่+เก่า+blob)
        const newImgs = document.querySelectorAll('img[src*="labs.google/fx/api/trpc/media"], img[src*="media.getMediaUrl"]').length;
        const oldImgs = document.querySelectorAll('img[src*="ai-sandbox-videofx"], img[src*="storage.googleapis.com"], img[alt="Generated image"]').length;
        const blobImgs = document.querySelectorAll('img[src*="blob:"]').length;
        // signal 2: media card containers (Flow สร้าง container ภายใน 1-2s หลังคลิก แม้ภาพยังไม่ตำสำเร็จ)
        const cardContainers = document.querySelectorAll('.sc-5923b123-0, [class*="sc-5923b123"]').length;
        return {
          imgs: newImgs + oldImgs + blobImgs,
          containers: cardContainers,
          promptLen: (promptInputCheck?.textContent || '').trim().length
        };
      };
      const baseline = captureState();
      console.log(`[v4.2.2] Baseline: imgs=${baseline.imgs}, containers=${baseline.containers}, promptLen=${baseline.promptLen}`);
      // v4.2.2 BUGFIX: poll หลายรอบ — เช็ค 3 signals (container, img, prompt)
      // Flow สร้าง card container ภายใน 1-2s → detect ได้ไว
      // เก่า: wait 1500ms รอ img เท่านั้น → ไม่ทันเพราะ img ใช้เวลา 30-60s
      const verifyReal = async (totalMs = 15000, pollMs = 800) => {
        const startWait = Date.now();
        while (Date.now() - startWait < totalMs) {
          await delay(pollMs);
          const now = captureState();
          const elapsedSec = Math.round((Date.now()-startWait)/1000);
          // ANY signal → click ถูก register
          const containerIncreased = now.containers > baseline.containers;
          const imgIncreased = now.imgs > baseline.imgs;
          const promptCleared = baseline.promptLen > 10 && now.promptLen < 5;
          if (containerIncreased) {
            console.log(`[v4.2.2] ✅ Card container +${now.containers - baseline.containers} (${baseline.containers}→${now.containers}) at ${elapsedSec}s`);
            return true;
          }
          if (imgIncreased) {
            console.log(`[v4.2.2] ✅ Img +${now.imgs - baseline.imgs} (${baseline.imgs}→${now.imgs}) at ${elapsedSec}s`);
            return true;
          }
          if (promptCleared) {
            console.log(`[v4.2.2] ✅ Prompt cleared (${baseline.promptLen}→${now.promptLen}) at ${elapsedSec}s`);
            return true;
          }
        }
        console.log(`[v4.2.2] ❌ Verify timeout (${totalMs/1000}s) — no signal change`);
        return false;
      };

      // ===== v4.3: MAIN world click (default) → fallback CDP click =====
      // Default behavior: ลอง MAIN world ก่อน (ไม่มี yellow bar) → ถ้า fail → fallback CDP
      // Toggle "forceLegacyClickEnabled" ON → ข้าม MAIN, ใช้ CDP ตรงๆ (สำหรับลูกค้าที่ MAIN เจอปัญหา)
      // v4.2.2: ล้าง fail flag เก่าก่อน click — ไม่ให้ trigger abort จาก attempt ก่อน
      window._flowGenerateFailed = null;

      // อ่าน toggle: ถ้าเปิด → force CDP, ถ้าปิด (default) → ใช้ MAIN
      const forceLegacy = await new Promise(resolve => {
        try {
          chrome.storage.local.get(['forceLegacyClickEnabled'], (r) => {
            resolve(!!(r && r.forceLegacyClickEnabled));
          });
        } catch (e) { resolve(false); }
      });
      const useMainWorld = !forceLegacy; // default = ใช้ MAIN

      const btnRect = generateBtn.getBoundingClientRect();
      const btnCx = Math.round(btnRect.left + btnRect.width / 2);
      const btnCy = Math.round(btnRect.top + btnRect.height / 2);

      // === v4.3 MAIN world click (default) ===
      if (useMainWorld) {
        console.log(`[v4.3 MAIN-click] ลอง MAIN world click ที่ (${btnCx}, ${btnCy})...`);
        try {
          const requestId = Date.now() + Math.random();
          const mainResult = await new Promise((resolve) => {
            const handler = (e) => {
              if (e.detail && e.detail.requestId === requestId) {
                window.removeEventListener('__flow_main_click_result__', handler);
                resolve(e.detail);
              }
            };
            window.addEventListener('__flow_main_click_result__', handler);
            window.dispatchEvent(new CustomEvent('__flow_main_click__', {
              detail: { x: btnCx, y: btnCy, requestId }
            }));
            setTimeout(() => {
              window.removeEventListener('__flow_main_click_result__', handler);
              resolve({ success: false, error: 'timeout (3s)' });
            }, 3000);
          });

          if (mainResult.success) {
            console.log(`✅ [Attempt ${attempt}] MAIN world click work via ${mainResult.method} — ไม่มี yellow bar`);
            return true;
          }
          console.warn(`⚠️ [Attempt ${attempt}] MAIN world click failed: ${mainResult.error || 'no method work'} — fallback CDP`);
        } catch (mainErr) {
          console.warn(`⚠️ [Attempt ${attempt}] MAIN world exception:`, mainErr.message);
        }
      }

      // === CDP click (default หรือ fallback) ===
      // v4.4.5: ใช้ cdpHumanClick (bezier mouse path + jitter + hover) แทน cdpClick ตรง
      //   เพื่อลดโอกาส reCAPTCHA detect bot signature (ทุก mode ที่กดปุ่ม Generate ใน Flow)
      try {
        console.log(`[v4.4.5 CDP Human] กำลังคลิก humanize ที่ (${btnCx}, ${btnCy})...`);
        const cdpResult = await new Promise((resolve) => {
          chrome.runtime.sendMessage({ action: 'cdpHumanClick', x: btnCx, y: btnCy }, (response) => {
            resolve(response || { success: false, error: 'no response' });
          });
        });
        if (cdpResult.success) {
          console.log(`✅ [Attempt ${attempt}] CDP Human click ส่งสำเร็จ — ปล่อยให้ monitor รอภาพ`);
          return true; // trust the click — monitor จะรอภาพและตรวจ timeout เอง
        }
        console.warn(`⚠️ [Attempt ${attempt}] CDP Human click failed: ${cdpResult.error} — fallback to plain cdpClick`);
        // Fallback: cdpClick ตรง (กัน cdpHumanClick พัง)
        const fallback = await new Promise((resolve) => {
          chrome.runtime.sendMessage({ action: 'cdpClick', x: btnCx, y: btnCy }, (response) => {
            resolve(response || { success: false, error: 'no response' });
          });
        });
        if (fallback.success) {
          console.log(`✅ [Attempt ${attempt}] CDP plain click (fallback) สำเร็จ`);
          return true;
        }
        console.warn(`⚠️ [Attempt ${attempt}] CDP fallback failed: ${fallback.error}`);
      } catch (cdpErr) {
        console.warn(`⚠️ [Attempt ${attempt}] CDP click exception:`, cdpErr.message);
      }

      // CDP click failed → retry next attempt
      if (attempt === maxRetries) {
        console.log(`🆘 [v4.2.2] ลอง CDP ${maxRetries} attempts แล้วไม่ติด — ขอ user ช่วยคลิก`);
        const userClicked = await waitForUserGenerateClick(baseline);
        if (userClicked) {
          console.log(`✅ User helped click — generate started`);
          return true;
        }
        console.log(`⏱️ User ไม่กดในเวลาที่กำหนด — fail`);
        return false;
      }
      continue;
    }

    console.log(`⚠️ [Attempt ${attempt}] Generate button not found, will retry...`);
  }

  console.log('❌ Generate button NOT found after all retry attempts!');
  return false;
}

// v4.2.2: รอ user ช่วยกดปุ่ม Create (เมื่อ bot click ไม่ได้เพราะ Flow's abuse detection)
// แสดง overlay สีส้มกลางจอ + countdown + poll card count → ถ้าเพิ่ม = user กดสำเร็จ
async function waitForUserGenerateClick(baseline) {
  const TIMEOUT_MS = 5 * 60 * 1000; // 5 นาที
  const POLL_MS = 1500;
  const startTime = Date.now();

  // สร้าง overlay เด่นๆ บนหน้า Flow
  let overlay = document.getElementById('pd-user-help-overlay');
  if (overlay) overlay.remove();
  overlay = document.createElement('div');
  overlay.id = 'pd-user-help-overlay';
  overlay.style.cssText = `
    position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);
    z-index: 999999; pointer-events: auto;
    background: linear-gradient(135deg, #ff9800, #ff5722);
    color: #fff; padding: 24px 32px; border-radius: 16px;
    box-shadow: 0 12px 48px rgba(0, 0, 0, 0.6); border: 2px solid #fff;
    font-size: 16px; font-weight: 700; text-align: center;
    max-width: 480px; min-width: 380px;
    animation: pdHelpPulse 1.5s ease-in-out infinite;
  `;
  overlay.innerHTML = `
    <style>
      @keyframes pdHelpPulse {
        0%, 100% { transform: translate(-50%, -50%) scale(1); box-shadow: 0 12px 48px rgba(255, 152, 0, 0.5); }
        50% { transform: translate(-50%, -50%) scale(1.03); box-shadow: 0 16px 64px rgba(255, 152, 0, 0.8); }
      }
    </style>
    <div style="font-size: 36px; margin-bottom: 8px;">🖱️</div>
    <div style="font-size: 18px; margin-bottom: 8px;">บอทขอความช่วยเหลือ!</div>
    <div style="font-size: 14px; opacity: 0.95; margin-bottom: 12px; line-height: 1.5;">
      Flow ตรวจจับว่าบอทกด Create ไม่ได้<br>
      <b>กรุณากดปุ่ม Create (ลูกศร →) ในหน้า Flow ให้บอท</b><br>
      <span style="font-size: 11px; opacity: 0.8;">บอทจะทำงานต่อทันทีหลังคุณกด</span>
    </div>
    <div id="pd-help-countdown" style="
      background: rgba(255,255,255,0.2); padding: 6px 14px; border-radius: 8px;
      display: inline-block; font-size: 13px; font-weight: 600;
    ">⏱️ เหลือเวลา 5:00</div>
  `;
  document.body.appendChild(overlay);

  console.log(`[v4.2.2] 🆘 User-help overlay shown — waiting up to 5 min for user click`);

  while (Date.now() - startTime < TIMEOUT_MS) {
    // เช็ค card count + prompt cleared
    // v4.2.2: multi-selector รับ Flow ใหม่ (labs.google trpc) + Flow เก่า
    const newImgs = document.querySelectorAll('img[src*="labs.google/fx/api/trpc/media"], img[src*="media.getMediaUrl"]').length;
    const oldImgs = document.querySelectorAll('img[src*="ai-sandbox-videofx"], img[src*="storage.googleapis.com"], img[alt="Generated image"]').length;
    const blobImgs = document.querySelectorAll('img[src*="blob:"]').length;
    const currentCards = newImgs + oldImgs + blobImgs;
    const promptInput = document.querySelector('div[role="textbox"][contenteditable="true"]') ||
                        document.querySelector('[contenteditable="true"]');
    const currentPromptLen = (promptInput?.textContent || '').trim().length;
    const cardIncreased = currentCards > baseline.cards;
    const promptCleared = baseline.promptLen > 10 && currentPromptLen < 5;

    if (cardIncreased || promptCleared) {
      console.log(`[v4.2.2] ✅ User helped! cards: ${baseline.cards}→${currentCards}, prompt: ${baseline.promptLen}→${currentPromptLen}`);
      overlay.remove();
      return true;
    }

    // อัพเดต countdown
    const elapsed = Date.now() - startTime;
    const remaining = Math.max(0, TIMEOUT_MS - elapsed);
    const mins = Math.floor(remaining / 60000);
    const secs = Math.floor((remaining % 60000) / 1000);
    const countdownEl = document.getElementById('pd-help-countdown');
    if (countdownEl) {
      countdownEl.textContent = `⏱️ เหลือเวลา ${mins}:${String(secs).padStart(2, '0')}`;
    }

    await delay(POLL_MS);
  }

  console.log(`[v4.2.2] ⏱️ Timeout — user ไม่ได้กดใน 5 นาที`);
  overlay.remove();
  return false;
}

// v6.2.1: ตรวจสอบว่าการกด Generate สำเร็จหรือไม่
async function verifyGenerateClicked() {
  await delay(500);

  // วิธีที่ 1: เช็คว่ามี loading spinner/progress
  const loadingIndicators = document.querySelectorAll(
    '[class*="loading"], [class*="progress"], [class*="spinner"], ' +
    '[class*="generating"], [aria-busy="true"], [role="progressbar"]'
  );
  if (loadingIndicators.length > 0) {
    console.log('✅ Detected loading indicator after click');
    return true;
  }

  // วิธีที่ 2: เช็คว่า prompt field ถูก disabled หรือ readonly
  const promptField = document.querySelector('textarea');
  if (promptField && (promptField.disabled || promptField.readOnly)) {
    console.log('✅ Prompt field is now disabled (generating)');
    return true;
  }

  // วิธีที่ 3: เช็คว่ามี "Generating" text ปรากฏ
  const bodyText = document.body.innerText || '';
  if (bodyText.includes('Generating') || bodyText.includes('Creating') || bodyText.includes('กำลังสร้าง')) {
    console.log('✅ Detected "Generating" text on page');
    return true;
  }

  // วิธีที่ 4: เช็คว่าปุ่ม Generate เปลี่ยนไป (หายไป หรือ disabled)
  const allButtons = document.querySelectorAll('button');
  let foundActiveGenerateBtn = false;
  for (const btn of allButtons) {
    const text = (btn.textContent || '').toLowerCase();
    if ((text.includes('create') || text.includes('generate')) && !btn.disabled && isVisible(btn)) {
      foundActiveGenerateBtn = true;
      break;
    }
  }
  if (!foundActiveGenerateBtn) {
    console.log('✅ Generate button is no longer active (generation started)');
    return true;
  }

  console.log('⚠️ No clear indication that generation started');
  return false;
}

// Monitor progress - ตรวจจับว่าคลิปสร้างเสร็จหรือยัง
// ใช้ clipCountBeforeGenerate เพื่อนับเฉพาะคลิปใหม่
async function monitorProgress() {
  let attempts = 0;

  // v6.9: ปรับ timeout - Image 90 วินาที, Video 2.5 นาที
  // v6.3.1: Fast Mode ลดเวลาเป็น 100 วินาที (Video) / 60 วินาที (Image)
  // v7.5: เพิ่ม timeout รูปจาก 60 → 90 วิ, Fast Mode ใช้ 60 วิ
  const isImageMode = currentMode === 'image';
  const normalVideoTimeout = 150;
  const fastVideoTimeout = 100;
  const normalImageTimeout = 90; // v7.5: เพิ่มจาก 60 เป็น 90
  const fastImageTimeout = 60;   // v7.5: Fast Mode ใช้ 60
  const videoTimeout = fastModeEnabled ? fastVideoTimeout : normalVideoTimeout;
  const imageTimeout = fastModeEnabled ? fastImageTimeout : normalImageTimeout;
  const maxAttempts = isImageMode ? imageTimeout : videoTimeout; // Image: 90 วิ (Fast: 60), Video: 2.5 นาที (Fast: 100)
  const checkInterval = isImageMode ? 1000 : 1000; // ตรวจทุก 1 วินาที

  // จำนวนคลิป/รูปที่ต้องการสร้าง (จาก currentData)
  const targetClipCount = currentData?.clipCount || 4;
  const batchId = currentBatchId; // จำ batch ID ของรอบนี้

  let lastNewClipCount = 0;
  let stableCount = 0;
  const stableThreshold = 2; // ถ้าคงที่ 2 ครั้ง ถือว่าเสร็จ
  let noLoadingCount = 0; // นับครั้งที่ไม่มี loading
  const noLoadingThreshold = 3; // ถ้าไม่มี loading 3 ครั้งติดกัน = เสร็จ
  let hasSeenLoading = false; // เคยเห็น loading หรือยัง (ป้องกันจบก่อนเริ่ม)
  let lastErrorCheck = 0;
  let errorRetryInProgress = false;

  const itemName = isImageMode ? 'รูป' : 'คลิป';
  console.log(`🎬 [Batch ${batchId}] Starting progress monitor (${isImageMode ? 'Image' : 'Video'} mode)`);
  console.log(`📊 [Batch ${batchId}] ${itemName} before generate:`, clipCountBeforeGenerate);
  console.log(`🎯 [Batch ${batchId}] Target new ${itemName}:`, targetClipCount);

  // รอสักครู่ก่อนเริ่มตรวจ (Image mode รอน้อยกว่า)
  await delay(isImageMode ? 2000 : 3000);

  while (attempts < maxAttempts) {
    await delay(checkInterval);
    attempts++;

    // ตรวจสอบว่ายังเป็น batch เดิมอยู่ไหม (ถ้าผู้ใช้กดสร้างรอบใหม่ ให้หยุด monitor รอบนี้)
    if (currentBatchId !== batchId) {
      console.log(`🔄 [Batch ${batchId}] New batch started, stopping this monitor`);
      return;
    }

    // ตรวจจับ error message (rate limit) - เช็คทุก 5 วินาที
    if (!errorRetryInProgress && Date.now() - lastErrorCheck > 5000) {
      lastErrorCheck = Date.now();
      const errorMessage = detectErrorMessage();

      if (errorMessage) {
        console.log(`⚠️ [Batch ${batchId}] Error detected: ${errorMessage}`);

        if (retryCount < MAX_RETRIES) {
          errorRetryInProgress = true;
          retryCount++;
          console.log(`🔄 [Batch ${batchId}] Retrying immediately... (${retryCount}/${MAX_RETRIES})`);
          updateStatus(`ชุด ${batchId}: พบ Error - กำลัง retry ทันที (${retryCount}/${MAX_RETRIES})`);

          // รอแค่ 2 วินาทีแล้ว retry ทันที
          await delay(2000);

          // ตรวจสอบว่ายังเป็น batch เดิมอยู่ไหม
          if (currentBatchId !== batchId) {
            console.log(`🔄 [Batch ${batchId}] Batch changed, stopping retry`);
            return;
          }

          // v6.9: อัพเดท baseline (ใช้ countElementsByMode เพื่อให้ตรงกับ mode)
          const currentClips = countElementsByMode();
          const currentFailed = countAllFailedGenerations();
          console.log(`🔄 [Batch ${batchId}] Updating baseline: elements=${currentClips}, failed=${currentFailed}, mode=${currentMode}`);
          clipCountBeforeGenerate = currentClips;
          failedCountBeforeGenerate = currentFailed;

          // ทำขั้นตอนใหม่ตั้งแต่ต้น (เผื่อ prompt/รูปหายไป)
          console.log(`🔄 [Batch ${batchId}] Re-running full process...`);
          updateStatus(`ชุด ${batchId}: กำลัง retry... (${retryCount}/${MAX_RETRIES})`);

          // แสดงม่าน overlay ระหว่าง retry
          showBotOverlay(`กำลัง Retry (${retryCount}/${MAX_RETRIES})`, 'พบ Error - กำลังลองใหม่');

          try {
            // Step 2: ตรวจสอบและตั้งค่า settings
            updateBotOverlay('กำลังตั้งค่า...', `Retry ${retryCount}/${MAX_RETRIES}`);
            await step2_ConfigureSettings(currentData);
            await delay(500);

            // Step 3: อัพโหลดรูป
            updateBotOverlay('กำลังอัพโหลดรูป...', `Retry ${retryCount}/${MAX_RETRIES}`);
            await step3_UploadImage(currentData.image);
            await delay(500);

            // Step 4: จัดการ crop
            updateBotOverlay('กำลังครอบตัดรูป...', `Retry ${retryCount}/${MAX_RETRIES}`);
            await step4_HandleCrop(currentData);
            await delay(500);

            // Step 5: กรอก prompt
            updateBotOverlay('กำลังกรอก Prompt...', `Retry ${retryCount}/${MAX_RETRIES}`);
            await step5_EnterPrompt(currentData.prompt);
            await delay(500);

            // Step 6: กด Generate
            updateBotOverlay('กำลังสร้างวิดีโอ...', `Retry ${retryCount}/${MAX_RETRIES}`);
            const clickSuccess = await step6_Generate();
            if (!clickSuccess) {
              console.log(`❌ [Batch ${batchId}] Failed to click Generate button!`);
              updateStatus(`ชุด ${batchId}: ไม่พบปุ่ม Generate - กรุณากดเอง`);
              hideBotOverlay();
              errorRetryInProgress = false;
              continue;
            }
          } catch (retryError) {
            console.error(`❌ [Batch ${batchId}] Retry process error:`, retryError);
            updateStatus(`ชุด ${batchId}: retry ล้มเหลว - ${retryError.message}`);
            hideBotOverlay();
            errorRetryInProgress = false;
            continue;
          }

          // ซ่อนม่านหลัง retry สำเร็จ
          hideBotOverlay();
          await delay(2000);

          errorRetryInProgress = false;
          attempts = 0;
          stableCount = 0;
          lastNewClipCount = 0;
          continue;
        } else {
          updateStatus(`retry ครบ ${MAX_RETRIES} ครั้งแล้ว - กรุณาลองใหม่ภายหลัง`);
          chrome.runtime.sendMessage({
            action: 'generationFailed',
            batchId: batchId,
            error: errorMessage
          });
          return;
        }
      }
    }

    // นับ elements ทั้งหมดในหน้า (ใช้ฟังก์ชันที่เหมาะกับ mode)
    const totalElements = countElementsByMode();

    // คำนวณ elements ใหม่ = elements ทั้งหมด - elements ก่อนสร้าง
    const newElementCount = Math.max(0, totalElements - clipCountBeforeGenerate);

    // ตรวจสอบ loading indicators
    const loadingCount = countLoadingIndicators();

    // ตรวจสอบ Failed Generation (เฉพาะใหม่ ไม่รวมของเก่า)
    const newFailedCount = countNewFailedGenerations();

    console.log(`📊 [Batch ${batchId}] #${attempts}: new=${newElementCount}/${targetClipCount} ${itemName}, loading=${loadingCount}, newFailed=${newFailedCount}`);

    // อัพเดทสถานะ + overlay progress ทุกรอบ
    if (loadingCount > 0 || newElementCount < targetClipCount) {
      const timeElapsed = attempts; // วินาทีที่ผ่านไป
      const timeRemaining = maxAttempts - attempts; // วินาทีที่เหลือ
      const progressText = `สร้าง${itemName}... (${newElementCount}/${targetClipCount})`;
      const subText = `เวลาผ่านไป ${timeElapsed} วินาที | เหลือ ${timeRemaining} วินาที`;

      updateBotOverlay(progressText, subText);
      updateStatus(`ชุด ${batchId}: กำลังสร้าง... (${newElementCount}/${targetClipCount} ${itemName})`);
    }

    // v3.0 FIX: ตรวจ Failed Generation — เจอ "Failed" = retry ทันที
    // ก่อนหน้า: ต้องครบ 3 เงื่อนไข (newFailed>0 && element===0 && loading===0) → ทำให้ไม่เข้าเพราะ Failed card ถูกนับเป็น element
    // แก้: เจอ Failed badge + ผ่าน grace 15 วิ = retry เลย (ไม่สน element/loading)
    if (newFailedCount > 0 && attempts > 15 && !errorRetryInProgress) {
      console.log(`❌ [Batch ${batchId}] New failed generation detected: ${newFailedCount}`);

      if (retryCount < MAX_RETRIES) {
        errorRetryInProgress = true;
        retryCount++;
        console.log(`🔄 [Batch ${batchId}] Retrying after failed... (${retryCount}/${MAX_RETRIES})`);
        updateStatus(`ชุด ${batchId}: สร้างล้มเหลว - กำลัง retry ทันที (${retryCount}/${MAX_RETRIES})`);

        // รอแค่ 2 วินาทีแล้ว retry ทันที
        await delay(2000);

        if (currentBatchId !== batchId) return;

        // v6.9: อัพเดท baseline (ใช้ countElementsByMode เพื่อให้ตรงกับ mode)
        const currentClips2 = countElementsByMode();
        const currentFailed2 = countAllFailedGenerations();
        console.log(`🔄 [Batch ${batchId}] Updating baseline after failed: elements=${currentClips2}, failed=${currentFailed2}, mode=${currentMode}`);
        clipCountBeforeGenerate = currentClips2;
        failedCountBeforeGenerate = currentFailed2;

        // ทำขั้นตอนใหม่ตั้งแต่ต้น
        console.log(`🔄 [Batch ${batchId}] Re-running full process after failed...`);
        updateStatus(`ชุด ${batchId}: กำลัง retry หลัง failed... (${retryCount}/${MAX_RETRIES})`);

        // แสดงม่าน overlay ระหว่าง retry
        showBotOverlay(`กำลัง Retry (${retryCount}/${MAX_RETRIES})`, 'สร้างล้มเหลว - กำลังลองใหม่');

        try {
          updateBotOverlay('กำลังตั้งค่า...', `Retry ${retryCount}/${MAX_RETRIES}`);
          await step2_ConfigureSettings(currentData);
          await delay(500);

          updateBotOverlay('กำลังอัพโหลดรูป...', `Retry ${retryCount}/${MAX_RETRIES}`);
          await step3_UploadImage(currentData.image);
          await delay(500);

          updateBotOverlay('กำลังครอบตัดรูป...', `Retry ${retryCount}/${MAX_RETRIES}`);
          await step4_HandleCrop(currentData);
          await delay(500);

          updateBotOverlay('กำลังกรอก Prompt...', `Retry ${retryCount}/${MAX_RETRIES}`);
          await step5_EnterPrompt(currentData.prompt);
          await delay(500);

          updateBotOverlay('กำลังสร้างวิดีโอ...', `Retry ${retryCount}/${MAX_RETRIES}`);
          const clickSuccess2 = await step6_Generate();
          if (!clickSuccess2) {
            console.log(`❌ [Batch ${batchId}] Failed to click Generate button after failed!`);
            updateStatus(`ชุด ${batchId}: ไม่พบปุ่ม Generate - กรุณากดเอง`);
            hideBotOverlay();
            errorRetryInProgress = false;
            continue;
          }
        } catch (retryError2) {
          console.error(`❌ [Batch ${batchId}] Retry after failed error:`, retryError2);
          updateStatus(`ชุด ${batchId}: retry ล้มเหลว - ${retryError2.message}`);
          hideBotOverlay();
          errorRetryInProgress = false;
          continue;
        }

        // ซ่อนม่านหลัง retry สำเร็จ
        hideBotOverlay();
        await delay(2000);
        errorRetryInProgress = false;
        attempts = 0;
        stableCount = 0;
        lastNewClipCount = 0;
        continue;
      }
    }

    // ตรวจสอบว่าเสร็จหรือยัง
    const isComplete = loadingCount === 0 && newElementCount > 0;
    const isFullyComplete = newElementCount >= targetClipCount;

    // v6.9: ถ้าครบ target แล้ว จบทันทีเลย! (เหมือนโหมดออโต้)
    if (isFullyComplete && isImageMode) {
      console.log(`🎉 [Batch ${batchId}] Target reached! ${newElementCount}/${targetClipCount} ${itemName} - finishing immediately`);

      updateStatus(`ชุด ${batchId}: สร้างเสร็จ ${newElementCount} ${itemName} ✓`, 100);
      updateBotOverlay(`สร้าง${itemName}เสร็จแล้ว!`, `${newElementCount}/${targetClipCount} ${itemName}`);
      setTimeout(() => hideBotOverlay(), 2000);

      retryCount = 0;
      chrome.runtime.sendMessage({
        action: 'generationComplete',
        batchId: batchId,
        newClipCount: newElementCount,
        targetClipCount: targetClipCount,
        totalClips: totalElements,
        isPartial: false
      });
      return;
    }

    // จำว่าเคยเห็น loading (แสดงว่าเริ่มสร้างแล้ว)
    if (loadingCount > 0) {
      hasSeenLoading = true;
      noLoadingCount = 0;
    }

    // เช็คแบบใหม่: ถ้าไม่มี loading หลายครั้งติดกัน = น่าจะเสร็จแล้ว
    // แต่ต้อง: 1) เคยเห็น loading ก่อน หรือ 2) มี element ใหม่ หรือ 3) ผ่านไป 15 วินาทีแล้ว
    if (loadingCount === 0) {
      noLoadingCount++;

      const canFinish = hasSeenLoading || newElementCount > 0 || attempts >= 15;

      if (canFinish) {
        console.log(`✓ [Batch ${batchId}] No loading: ${noLoadingCount}/${noLoadingThreshold} (seenLoading=${hasSeenLoading}, newElements=${newElementCount})`);

        if (noLoadingCount >= noLoadingThreshold) {
          console.log(`🎉 [Batch ${batchId}] Complete (no loading detected)! ${newElementCount} ${itemName}`);

          const statusMsg = newElementCount > 0
            ? `ชุด ${batchId}: สร้างเสร็จ ${newElementCount} ${itemName} ✓`
            : `ชุด ${batchId}: สร้างเสร็จแล้ว ✓`;
          updateStatus(statusMsg, 100);

          updateBotOverlay(`สร้าง${itemName}เสร็จแล้ว!`, `${newElementCount} ${itemName}`);
          setTimeout(() => hideBotOverlay(), 2000);

          retryCount = 0;

          chrome.runtime.sendMessage({
            action: 'generationComplete',
            batchId: batchId,
            newClipCount: Math.max(newElementCount, targetClipCount),
            targetClipCount: targetClipCount,
            totalClips: totalElements,
            isPartial: false
          });

          // ===== EXTEND SCENE: ทำต่อฉากอัตโนมัติ =====
          if (extendSceneEnabled && currentMode === 'video') {
            console.log('🎬 [Extend Scene] Starting extend scene flow (no loading path)...');
            setTimeout(() => {
              runExtendSceneInContentScript();
            }, 3000);
          }

          return;
        }
      }
    }

    if (isComplete) {
      if (newElementCount === lastNewClipCount) {
        stableCount++;
        console.log(`✓ [Batch ${batchId}] Stable: ${stableCount}/${stableThreshold}`);

        if (stableCount >= stableThreshold) {
          // เสร็จแล้ว!
          console.log(`🎉 [Batch ${batchId}] Complete! ${newElementCount}/${targetClipCount} ${itemName}`);

          const statusMsg = isFullyComplete
            ? `ชุด ${batchId}: สร้างเสร็จ ${newElementCount} ${itemName} ✓`
            : `ชุด ${batchId}: สร้างได้ ${newElementCount}/${targetClipCount} ${itemName}`;
          updateStatus(statusMsg, 100);

          // แสดง overlay ว่าเสร็จแล้ว
          updateBotOverlay(`สร้าง${itemName}เสร็จแล้ว!`, `${newElementCount}/${targetClipCount} ${itemName}`);

          // รอ 2 วินาทีแล้วซ่อน overlay
          setTimeout(() => {
            hideBotOverlay();
          }, 2000);

          // Reset retry count เมื่อสำเร็จ
          retryCount = 0;

          chrome.runtime.sendMessage({
            action: 'generationComplete',
            batchId: batchId,
            newClipCount: newElementCount,
            targetClipCount: targetClipCount,
            totalClips: totalElements,
            isPartial: !isFullyComplete
          });

          // ===== EXTEND SCENE: ทำต่อฉากอัตโนมัติ =====
          if (extendSceneEnabled && currentMode === 'video' && isFullyComplete) {
            console.log('🎬 [Extend Scene] Starting extend scene flow in content script...');
            console.log('🎬 [Extend Scene] Prompt:', extendScenePrompt);
            setTimeout(() => {
              runExtendSceneInContentScript();
            }, 3000); // รอ 3 วินาทีก่อนเริ่มต่อฉาก
          } else {
            console.log('[Extend Scene] Not triggered. enabled:', extendSceneEnabled, 'mode:', currentMode, 'isFullyComplete:', isFullyComplete);
          }

          return;
        }
      } else {
        stableCount = 0;
      }
    } else {
      stableCount = 0;
    }

    lastNewClipCount = newElementCount;
  }

  // Timeout
  console.log(`⏱️ [Batch ${batchId}] Monitor timeout`);
  updateStatus(`ชุด ${batchId}: หมดเวลารอ (${itemName})`);

  // แสดง overlay ว่าหมดเวลา
  // v6.3.1: ใช้ค่า timeout ตาม Fast Mode
  const timeoutSeconds = isImageMode ? 120 : videoTimeout;
  updateBotOverlay(`หมดเวลารอ`, `ไม่พบ${itemName}ใหม่ใน ${timeoutSeconds} วินาที`);

  // รอ 2 วินาทีแล้วซ่อน overlay
  setTimeout(() => {
    hideBotOverlay();
  }, 2000);

  // ===== EXTEND SCENE: ทำต่อฉากแม้ timeout (ถ้าเปิดไว้) =====
  // เพราะคลิปอาจสร้างเสร็จแล้วแต่ detection ไม่เห็น
  if (extendSceneEnabled && currentMode === 'video') {
    console.log('🎬 [Extend Scene] Triggering extend scene even on timeout...');
    setTimeout(() => {
      runExtendSceneInContentScript();
    }, 3000);
  }
}

// ตรวจจับ error message (rate limit, etc.)
// v17 FIX: นับจำนวน "failed" indicators ที่มีอยู่ใน DOM ตอนนี้
// ใช้เป็น baseline ก่อน generate เพื่อเทียบว่า error เพิ่มขึ้นหรือเปล่า (กัน false positive จาก card เก่า)
// v4.3: ฟังก์ชันเช็คว่า icon/element อยู่ใน "failed card" จริงๆ ไหม
// (กัน false positive: loading state อาจมี warning icon แต่ไม่มีข้อความ failed)
function isInFailedCard(el) {
  if (!el) return false;
  // หา card parent (.sc-5923b123-0 หรือ ใกล้เคียง)
  const card = el.closest('.sc-5923b123-0, [class*="sc-5923b123"]') || el.parentElement;
  if (!card) return false;
  const text = (card.textContent || '').toLowerCase();
  return text.includes('failed') || text.includes('something went wrong') || text.includes('try again') || text.includes('error');
}

function countExistingErrors() {
  let count = 0;
  // v4.3: warning icons — ต้องอยู่ใน card ที่มี text "failed/error" ด้วย
  // (เก่า: นับทุก warning icon → Flow loading state ก็มี icon → false positive)
  const warningIcons = document.querySelectorAll('i.google-symbols');
  for (const icon of warningIcons) {
    if ((icon.textContent || '').trim().toLowerCase() !== 'warning') continue;
    if (!isVisible(icon)) continue;
    if (isInFailedCard(icon)) count++;
  }
  // v4.3: failed overlays — ต้องมี text "failed/error" จริงๆ
  const failedOverlays = document.querySelectorAll('.sc-f112b7ef-0');
  for (const overlay of failedOverlays) {
    if (!isVisible(overlay)) continue;
    const t = (overlay.textContent || '').toLowerCase();
    if (t.includes('failed') || t.includes('error') || t.includes('something went wrong') || t.includes('try again')) {
      count++;
    }
  }
  return count;
}

// detectErrorMessage: ตรวจจับ error ขณะสร้างภาพ/วิดีโอ
// v17 FIX: รับ baseline จำนวน error เก่า เพื่อไม่ให้ไป detect error จาก card เก่าใน gallery
function detectErrorMessage(baselineErrorCount) {
  // ⚠️ baseline = undefined หมายถึงเรียกแบบเก่า (ไม่มี baseline) → ตรวจทุกอย่าง
  const hasBaseline = typeof baselineErrorCount === 'number';

  // === v17.5: APPLICATION ERROR check ก่อนสุด! (จอดำ/crash ต้องจับได้ทันที) ===
  // ย้ายมาก่อน role="alert" เพราะ Next.js error page มี role="alert" + text "error"
  // ซึ่งจะโดนจับเป็น generic error แทน APPLICATION_ERROR
  const bodyText = document.body.innerText || '';
  const bodyTextLower = bodyText.toLowerCase();
  if (bodyTextLower.includes('application error') || bodyTextLower.includes('client-side exception')) {
    console.log('[Error] 🚨 APPLICATION ERROR — page crashed! (early detect)');
    return 'APPLICATION_ERROR - หน้า Flow crash ต้อง refresh';
  }

  // === Toast / Alert / Snackbar errors (เหล่านี้เป็น error ใหม่เสมอ — ไม่ต้องเทียบ baseline) ===

  // Pattern 3: หาจาก role="alert"
  const alerts = document.querySelectorAll('[role="alert"]');
  for (const alert of alerts) {
    if (isVisible(alert)) {
      const text = (alert.textContent || '').trim();
      if (text.includes('daily limit') || text.includes('reached the daily limit')) {
        console.log('[Error] Detected in alert: Daily limit');
        chrome.runtime.sendMessage({
          action: 'dailyLimitReached',
          message: 'ลิมิตการสร้างภาพต่อวันเต็มแล้ว (จาก Google Flow) กรุณารอวันใหม่หรือเปลี่ยนโมเดล'
        });
        return 'DAILY_LIMIT - ลิมิตต่อวันเต็มแล้ว (จาก Google)';
      }
      if (text.includes('too quickly') || text.includes('Please wait') || text.includes('try again')) {
        console.log('[Error] Detected in alert:', text.substring(0, 50));
        return 'Rate limit - กรุณารอสักครู่';
      }
      if (text.includes('Something went wrong') || text.includes('something went wrong')) {
        // v17.5: ข้าม "Something went wrong loading your media" — เป็นแค่ media load fail ไม่ใช่ generation fail
        if (text.includes('loading your media')) {
          console.log('[Error] Skipping "Something went wrong loading your media" (not generation error)');
        } else {
          console.log('[Error] Detected in alert: Something went wrong');
          return 'SOMETHING_WENT_WRONG - Something went wrong';
        }
      }
      if (text.includes('feedback') || text.includes('error') || text.includes('failed')) {
        console.log('[Error] Detected in alert:', text.substring(0, 50));
        return text.length > 50 ? text.substring(0, 50) + '...' : text;
      }
    }
  }

  // Pattern 4: หา snackbar/toast elements
  const toasts = document.querySelectorAll('[class*="snackbar"], [class*="toast"], [class*="notification"]');
  for (const toast of toasts) {
    if (isVisible(toast)) {
      const text = (toast.textContent || '').trim();
      if (text.includes('daily limit') || text.includes('reached the daily limit')) {
        console.log('[Error] Detected in toast: Daily limit');
        chrome.runtime.sendMessage({
          action: 'dailyLimitReached',
          message: 'ลิมิตการสร้างภาพต่อวันเต็มแล้ว'
        });
        return 'DAILY_LIMIT - ลิมิตต่อวันเต็มแล้ว';
      }
      if (text.includes('too quickly') || text.includes('error') || text.includes('failed') || text.includes('feedback')) {
        // v17.5: ข้าม "Something went wrong loading your media"
        if (text.includes('loading your media')) {
          console.log('[Error] Skipping toast "loading your media" (not generation error)');
          continue;
        }
        console.log('[Error] Detected in toast:', text.substring(0, 50));
        if (text.includes('Something went wrong') || text.includes('something went wrong')) {
          return 'SOMETHING_WENT_WRONG - Something went wrong';
        }
        return text.length > 50 ? text.substring(0, 50) + '...' : text;
      }
    }
  }

  // === Gallery / Card errors — เปรียบเทียบกับ baseline! ===
  // v17 FIX: ถ้ามี baseline → เช็คว่า error count เพิ่มขึ้นหรือเปล่า
  // ถ้าจำนวนเท่าเดิมหรือลดลง → error เก่าจากรอบก่อน → ไม่ใช่ error ใหม่!

  // v4.3: warning icons — ต้องอยู่ใน card ที่มี text "failed/error" ด้วย (กัน false positive)
  let currentErrorCount = 0;
  const warningIcons = document.querySelectorAll('i.google-symbols');
  for (const icon of warningIcons) {
    if ((icon.textContent || '').trim().toLowerCase() !== 'warning') continue;
    if (!isVisible(icon)) continue;
    if (isInFailedCard(icon)) currentErrorCount++;
  }
  // v4.3: failed overlays — ต้องมี text "failed/error" จริงๆ
  // (Flow ใช้ class .sc-f112b7ef-0 กับทั้ง failed AND loading overlay → ต้องเช็ค text)
  const failedOverlays = document.querySelectorAll('.sc-f112b7ef-0');
  for (const overlay of failedOverlays) {
    if (!isVisible(overlay)) continue;
    const t = (overlay.textContent || '').toLowerCase();
    if (t.includes('failed') || t.includes('error') || t.includes('something went wrong') || t.includes('try again')) {
      currentErrorCount++;
    }
  }

  // === Warning icons / Failed overlays — เทียบ baseline ===
  if (hasBaseline) {
    if (currentErrorCount > baselineErrorCount) {
      console.log(`[Error v17] NEW errors detected! baseline: ${baselineErrorCount}, now: ${currentErrorCount} (+${currentErrorCount - baselineErrorCount})`);
      return 'SOMETHING_WENT_WRONG - Failed generation (new warning icon/overlay)';
    }
  } else {
    if (currentErrorCount > 0) {
      console.log(`[Error v17] Detected: ${currentErrorCount} warning icons/overlays (no baseline)`);
      return 'SOMETHING_WENT_WRONG - Failed generation (warning icon/overlay)';
    }
  }

  // v2.3: ตรวจจับ "Failed" text บนรูปใน gallery (ไม่ใช่แค่ warning icon)
  // เช็คจาก span/div ที่มีคำว่า "Failed" + visible + ขนาดเล็ก (badge บนรูป)
  const failedTexts = document.querySelectorAll('span, div, p');
  for (const el of failedTexts) {
    const text = (el.textContent || '').trim();
    if (text.toLowerCase() === 'failed' && isVisible(el)) {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.width < 200 && rect.height < 50) {
        // เทียบ baseline
        if (hasBaseline) {
          if (currentErrorCount > baselineErrorCount) {
            console.log(`[Error v2.3] NEW "Failed" text detected on card!`);
            return 'FAILED_GENERATION - Failed (detected from card text)';
          }
        } else {
          console.log(`[Error v2.3] "Failed" text found on card (no baseline)`);
          return 'FAILED_GENERATION - Failed (card text)';
        }
      }
    }
    // v2.3: ตรวจจับ "violate" / "policy" (content policy failure)
    if ((text.toLowerCase().includes('violate') || text.toLowerCase().includes('policy')) && isVisible(el)) {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.width < 400) {
        console.log(`[Error v2.3] Content policy violation detected: "${text.substring(0, 60)}"`);
        return 'CONTENT_POLICY - ' + text.substring(0, 60);
      }
    }
  }

  // === bodyText check — เช็คเสมอทุกกรณี! (หลัง refresh error เก่าหายไปอยู่แล้ว) ===
  // v17.5: bodyText + bodyTextLower ถูกประกาศไว้ข้างบนแล้ว (APPLICATION_ERROR early check)
  // APPLICATION_ERROR ถูกเช็คข้างบนแล้ว ไม่ต้องเช็คซ้ำ

  if (bodyTextLower.includes('daily limit') || bodyTextLower.includes('reached the daily limit')) {
    chrome.runtime.sendMessage({
      action: 'dailyLimitReached',
      message: 'ลิมิตการสร้างภาพต่อวันเต็มแล้ว'
    });
    return 'DAILY_LIMIT - ลิมิตต่อวันเต็มแล้ว (จาก Google)';
  }
  if (bodyTextLower.includes('too quickly') || bodyTextLower.includes('requesting generations too quickly')) {
    return 'Rate limit - กรุณารอสักครู่';
  }
  // v17.1 FIX: เพิ่ม "audio generation failed" / "generation failed" + case-insensitive "send feedback"
  if (bodyTextLower.includes('audio generation failed') || bodyTextLower.includes('generation failed')) {
    console.log('[Error] Detected: Audio/generation failed in body text');
    return 'Error - Audio generation failed (send feedback)';
  }
  if (bodyTextLower.includes('send app feedback') || bodyTextLower.includes('send feedback')) {
    return 'Error - Send app feedback';
  }
  if (bodyTextLower.includes('something went wrong')) {
    return 'SOMETHING_WENT_WRONG - Something went wrong';
  }

  return null;
}

// v9.3: ตรวจสอบ Quota Limit Error (Error code 253)
// เมื่อ Google Veo ส่ง request เกิน quota ต่อวัน/ต่อชั่วโมง
function checkQuotaLimitError() {
  const bodyText = document.body?.innerText || '';
  const bodyTextLower = bodyText.toLowerCase();

  // รูปแบบ error ที่ต้องตรวจจับ
  const errorPatterns = [
    'quota limit',
    'exceeds the quota',
    'error code 253',
    'rate limit',
    'too many requests',
    'request limit exceeded',
    'daily limit reached',
    'usage limit'
  ];

  // เช็คว่าพบ error pattern ไหม
  let hasQuotaError = false;
  let matchedPattern = '';

  for (const pattern of errorPatterns) {
    if (bodyTextLower.includes(pattern)) {
      hasQuotaError = true;
      matchedPattern = pattern;
      break;
    }
  }

  // หา error message จริง (ถ้ามี)
  let errorMessage = '';
  if (hasQuotaError) {
    // หา element ที่มี error message
    const allElements = document.querySelectorAll('div, span, p');
    for (const el of allElements) {
      const text = (el.textContent || '').toLowerCase();
      for (const pattern of errorPatterns) {
        if (text.includes(pattern) && text.length < 200) {
          errorMessage = el.textContent.trim();
          break;
        }
      }
      if (errorMessage) break;
    }
  }

  console.log(`[v9.3] Quota check: hasError=${hasQuotaError}, pattern=${matchedPattern}`);

  return {
    success: true,
    hasQuotaError: hasQuotaError,
    matchedPattern: matchedPattern,
    errorMessage: errorMessage
  };
}

// นับจำนวน Failed Generation ทั้งหมดในหน้า
// v8.6.2: แยก Audio failed ออกจาก Video failed
function countAllFailedGenerations(options = {}) {
  const excludeAudioFailed = options.excludeAudioFailed || false;
  let count = 0;
  let audioFailedCount = 0;
  const foundElements = new Set(); // ป้องกันนับซ้ำ

  // Helper function: ตรวจสอบว่า element นี้นับไปแล้วหรือยัง
  function isAlreadyCounted(el) {
    if (foundElements.has(el)) return true;
    for (const found of foundElements) {
      if (found.contains(el) || el.contains(found)) {
        return true;
      }
    }
    return false;
  }

  // v8.6.2: ตรวจสอบว่าเป็น Audio failed หรือไม่
  function isAudioFailed(el) {
    const text = (el.textContent || '').toLowerCase();
    return text.includes('audio generation failed');
  }

  // Helper function: ตรวจสอบว่าเป็น Failed Generation card หรือไม่
  function isFailedCard(el) {
    const text = (el.textContent || '').toLowerCase();
    // ต้องมีคำว่า "failed generation" หรือ "generation failed"
    return text === 'failed' ||
           text.includes('failed generation') ||
           text.includes('generation failed') ||
           text.includes('audio generation failed');
  }

  // v4.4.5 วิธี Generic: catch-all — ดัก "Failed" ทุก element (ไม่ว่าเหตุผลอะไร)
  //   ครอบทุก fail variant ของ Flow ทั้งภาพและคลิป — ไม่ต้อง maintain keyword list ตาม Flow update
  //   เงื่อนไข: visible + size limit 800x600 (Failed card มี paragraph + buttons) + word "Failed" + ไม่อยู่ใน nav/header
  const genericCandidates = document.querySelectorAll('div, span, p');
  for (const el of genericCandidates) {
    if (isAlreadyCounted(el)) continue;
    const text = (el.textContent || '').trim();
    if (!text) continue;
    // word "Failed" boundary (ไม่ใช่ part of "FailedABC")
    const startsFailed = text.startsWith('Failed');
    if (!startsFailed && !/\bFailed\b/.test(text)) continue;
    // text ไม่ยาวเกิน 250 ตัว เว้นแต่ขึ้นต้นด้วย "Failed" (card ที่มี paragraph อธิบาย)
    if (text.length > 250 && !startsFailed) continue;
    // visible check (หรือมี styled-component class)
    const cls = (el.className || '').toString();
    const hasFlowClass = cls.includes('sc-');
    if (!hasFlowClass && (el.offsetWidth === 0 || el.offsetHeight === 0)) continue;
    // size limit — Failed card มี paragraph + 3 buttons อาจสูงถึง 500-600px
    if (el.offsetWidth > 800 || el.offsetHeight > 600) continue;
    // กัน false positive: skip nav/header/aside/billing/menu
    let p = el.parentElement;
    let skip = false;
    for (let i = 0; i < 12 && p && p !== document.body; i++) {
      const tag = (p.tagName || '').toLowerCase();
      if (tag === 'nav' || tag === 'header' || tag === 'aside') { skip = true; break; }
      const pCls = (p.className || '').toString().toLowerCase();
      if (pCls.includes('billing') || pCls.includes('account-menu') || pCls.includes('user-menu') || pCls.includes('settings-')) { skip = true; break; }
      p = p.parentElement;
    }
    if (skip) continue;
    foundElements.add(el);
    count++;
    console.log('[Failed Generic] +1:', cls.substring(0, 40), '-', text.substring(0, 80));
  }

  // วิธี 0: หาจาก class จริงที่ Flow ใช้ (backward compat — เก็บไว้เผื่อ generic ไม่เจอ)
  const byFlowClass = document.querySelectorAll('[class*="sc-25d34a31"], [class*="sc-101009f9"]');
  for (const el of byFlowClass) {
    const elText = (el.textContent || '').trim().toLowerCase();
    if (elText.includes('failed') && !isAlreadyCounted(el) && el.offsetWidth > 0) {
      foundElements.add(el);
      count++;
      console.log('[Failed] Found by Flow class:', el.className, '-', el.textContent?.trim().substring(0, 50));
    }
  }

  // วิธี 1: หาจาก aria-label หรือ data attribute
  const byAria = document.querySelectorAll('[aria-label*="Failed"], [data-status="failed"]');
  for (const el of byAria) {
    if (!isAlreadyCounted(el)) {
      foundElements.add(el);
      count++;
      console.log('[Failed] Found by aria/data:', el.textContent?.substring(0, 50));
    }
  }

  // วิธี 2: หาจากข้อความ "Failed Generation" (ไม่ exact match แล้ว)
  const allElements = document.querySelectorAll('button, [role="button"], span, div, p');
  for (const el of allElements) {
    const text = (el.textContent || '').trim();
    // v8.5.1: ใช้ includes แทน exact match และเพิ่มเงื่อนไข
    const textLower = text.toLowerCase();

    // v3.0: เจอคำว่า "failed" ใน element เล็กๆ = นับเลย
    const isExactFailed = text === 'Failed Generation' || text === 'Failed';
    // v3.0: element สั้นๆ (< 30 ตัวอักษร) ที่มีคำว่า "failed" → นับเลย
    const isShortFailed = textLower.includes('failed') && text.length < 30 && el.offsetWidth > 0;
    // v3.0: เพิ่ม "couldn't generate" จาก Flow DOM จริง
    // v4.4.5: ไม่ต้อง list keyword ใหม่ — generic catch-all (วิธี Generic ด้านบน) ดักทุก "Failed" variant แล้ว
    const hasFailedError = textLower.includes('audio generation failed') ||
                          textLower.includes('generation failed') ||
                          textLower.includes('failed to generate') ||
                          textLower.includes('something went wrong') ||
                          textLower.includes("couldn't generate");

    if ((isExactFailed || isShortFailed || hasFailedError) && !isAlreadyCounted(el)) {
      // ถ้าเป็น exact match หรือ short element ที่มี "failed" → นับเลย
      if (isExactFailed || isShortFailed) {
        foundElements.add(el);
        count++;
        console.log('[Failed] Found exact match:', text.substring(0, 50));
      }
      // ถ้าเป็น error message ต้องเช็คว่าเป็น element ที่เหมาะสม
      // v3.0: ต้องเล็กกว่า 500px (ป้องกันนับ nav bar/container ใหญ่ที่มีคำ failed ซ่อนอยู่)
      else if (hasFailedError && el.offsetWidth > 0 && el.offsetHeight > 0 && el.offsetWidth < 500) {
        // หา parent container ที่เป็น card
        let cardEl = el;
        for (let i = 0; i < 10; i++) {
          if (!cardEl.parentElement) break;
          cardEl = cardEl.parentElement;
          // หยุดเมื่อเจอ element ที่ดูเหมือน card
          if (cardEl.className?.includes('card') ||
              cardEl.getAttribute('role') === 'listitem' ||
              cardEl.querySelector('button[aria-haspopup="menu"]')) {
            break;
          }
        }
        if (!isAlreadyCounted(cardEl)) {
          foundElements.add(cardEl);
          count++;
          console.log('[Failed] Found error card:', text.substring(0, 80));
        }
      }
    }
  }

  // วิธี 3: ค้นหาแบบ XPath (fallback) - รองรับทั้ง exact และ contains
  try {
    // v15.4: เพิ่ม "Something went wrong" ใน XPath
    // v17.3: เพิ่ม "Failed" เฉยๆ (ไม่มี "Generation" ต่อท้าย)
    const xpaths = [
      "//div[normalize-space(text())='Failed Generation']",
      "//span[normalize-space(text())='Failed Generation']",
      "//span[normalize-space(text())='Failed']",
      "//div[normalize-space(text())='Failed']",
      "//div[contains(text(), 'generation failed')]",
      "//span[contains(text(), 'generation failed')]",
      "//div[contains(text(), 'Audio generation failed')]",
      "//span[contains(text(), 'Audio generation failed')]",
      "//div[contains(text(), 'Something went wrong')]",
      "//span[contains(text(), 'Something went wrong')]",
      "//p[contains(text(), 'Something went wrong')]"
    ];

    for (const xpath of xpaths) {
      const result = document.evaluate(xpath, document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
      for (let i = 0; i < result.snapshotLength; i++) {
        const el = result.snapshotItem(i);
        if (!isAlreadyCounted(el)) {
          foundElements.add(el);
          count++;
          console.log('[Failed] Found by XPath:', el.textContent?.trim().substring(0, 50));
        }
      }
    }
  } catch (e) {
    console.log('[Failed] XPath error:', e.message);
  }

  // v17: วิธี 4: หาจาก warning icon (i.google-symbols ที่มีข้อความ "warning")
  // DOM: <i class="sc-95c4f607-0 grsLJu google-symbols undefined">warning</i>
  const warningIcons = document.querySelectorAll('i.google-symbols');
  for (const icon of warningIcons) {
    const iconText = (icon.textContent || '').trim().toLowerCase();
    if (iconText === 'warning' && isVisible(icon)) {
      // หา parent card
      let cardEl = icon;
      for (let i = 0; i < 10; i++) {
        if (!cardEl.parentElement) break;
        cardEl = cardEl.parentElement;
        if (cardEl.className?.includes('sc-5923b123-0') ||
            cardEl.className?.includes('card') ||
            cardEl.getAttribute('role') === 'listitem') {
          break;
        }
      }
      if (!isAlreadyCounted(cardEl)) {
        foundElements.add(cardEl);
        count++;
        console.log('[Failed v17] Found by warning icon');
      }
    }
  }

  // v17: วิธี 5: หาจาก .sc-f112b7ef-0 container (failed overlay ใหม่)
  const failedOverlays = document.querySelectorAll('.sc-f112b7ef-0');
  for (const overlay of failedOverlays) {
    if (isVisible(overlay) && !isAlreadyCounted(overlay)) {
      // หา parent card
      let cardEl = overlay;
      for (let i = 0; i < 10; i++) {
        if (!cardEl.parentElement) break;
        cardEl = cardEl.parentElement;
        if (cardEl.className?.includes('sc-5923b123-0') ||
            cardEl.className?.includes('card') ||
            cardEl.getAttribute('role') === 'listitem') {
          break;
        }
      }
      if (!isAlreadyCounted(cardEl)) {
        foundElements.add(cardEl);
        count++;
        console.log('[Failed v17] Found by .sc-f112b7ef-0 overlay');
      }
    }
  }

  // v17.3 วิธี 6: หาจาก refresh icon (ปุ่ม retry บน Failed card)
  // ถ้า card มีปุ่ม refresh → แสดงว่าเป็น Failed card แน่นอน
  const refreshIcons = document.querySelectorAll('i.google-symbols');
  for (const icon of refreshIcons) {
    const iconText = (icon.textContent || '').trim().toLowerCase();
    if (iconText === 'refresh' && isVisible(icon)) {
      // ไล่ขึ้น parent จนเจอ card container
      let cardEl = icon;
      for (let i = 0; i < 10; i++) {
        if (!cardEl.parentElement) break;
        cardEl = cardEl.parentElement;
        if (cardEl.className?.includes('sc-5923b123-0') ||
            cardEl.className?.includes('card') ||
            cardEl.getAttribute('role') === 'listitem') {
          break;
        }
      }
      if (!isAlreadyCounted(cardEl)) {
        foundElements.add(cardEl);
        count++;
        console.log('[Failed v17.3] Found by refresh icon (retry button on Failed card)');
      }
    }
  }

  // v17.3 วิธี 7: หาจาก class sc-9a984650-1 ที่มีข้อความ "Failed"
  // DOM: <div class="sc-9a984650-1 dEfdsQ">Failed</div>
  const failedClassDivs = document.querySelectorAll('[class*="sc-9a984650"]');
  for (const el of failedClassDivs) {
    const text = (el.textContent || '').trim();
    if ((text === 'Failed' || text === 'Failed Generation') && !isAlreadyCounted(el)) {
      // ไล่ขึ้น parent จนเจอ card container
      let cardEl = el;
      for (let i = 0; i < 10; i++) {
        if (!cardEl.parentElement) break;
        cardEl = cardEl.parentElement;
        if (cardEl.className?.includes('sc-5923b123-0') ||
            cardEl.className?.includes('card') ||
            cardEl.getAttribute('role') === 'listitem') {
          break;
        }
      }
      if (!isAlreadyCounted(cardEl)) {
        foundElements.add(cardEl);
        count++;
        console.log(`[Failed v17.3] Found by sc-9a984650 class: "${text}"`);
      }
    }
  }

  console.log(`[Failed] Total count: ${count}`);
  return count;
}

// v17.5b: Robust Failed badge counter — ใช้ * selector จับทุก element type
// ปัญหา: Google Flow แสดง icon text ติดหน้า "Failed" เช่น "warningFailed" / "error_outlineFailed"
// ฟังก์ชันเดิม countAllFailedGenerations() เช็คแค่ exact "Failed" → พลาด!
// ฟังก์ชันนี้ port จาก monitorStoryVideoProgress ที่ทำงานได้ดี
function countVisibleFailedBadges() {
  let count = 0;
  const counted = new Set();

  // v4.4.5 วิธี Generic Catch-All: หา word "Failed" boundary ใน element ใดๆ (relax size limit)
  //   ครอบทุก Failed card ที่ Flow render ออกมาทั้งภาพและคลิป — ไม่ต้อง maintain list
  //   - text ขึ้นต้นด้วย "Failed" หรือมี word "Failed" + text สั้น < 250 ตัว
  //   - size ใหญ่ได้ถึง 800x600 (Failed card มี paragraph + buttons)
  //   - skip nav/header/menu/billing (กัน false positive)
  const allGeneric = document.querySelectorAll('div, span, p');
  for (const el of allGeneric) {
    const text = (el.innerText || el.textContent || '').trim();
    if (!text) continue;
    // ต้องขึ้นต้นด้วย "Failed" หรือมี word "Failed" boundary + text ไม่ยาวเกิน
    const startsFailed = text.startsWith('Failed');
    const hasFailedWord = /\bFailed\b/.test(text);
    if (!startsFailed && !hasFailedWord) continue;
    if (text.length > 250 && !startsFailed) continue;
    // visible หรือมี styled-component class
    const cls = (el.className || '').toString();
    const hasFlowClass = cls.includes('sc-');
    if (!hasFlowClass && (el.offsetWidth === 0 || el.offsetHeight === 0)) continue;
    // size limit (Failed card มี paragraph + 3 buttons — อาจสูงถึง 500-600px)
    if (el.offsetWidth > 800 || el.offsetHeight > 600) continue;
    // skip nav/header/aside/billing/account-menu
    let p = el.parentElement;
    let skip = false;
    for (let i = 0; i < 12 && p && p !== document.body; i++) {
      const tag = (p.tagName || '').toLowerCase();
      if (tag === 'nav' || tag === 'header' || tag === 'aside') { skip = true; break; }
      const pCls = (p.className || '').toString().toLowerCase();
      if (pCls.includes('billing') || pCls.includes('account-menu') || pCls.includes('user-menu') || pCls.includes('settings-')) { skip = true; break; }
      p = p.parentElement;
    }
    if (skip) continue;
    // ป้องกันซ้ำ (nested element)
    let dominated = false;
    for (const prev of counted) {
      if (prev.contains(el) || el.contains(prev)) { dominated = true; break; }
    }
    if (!dominated) {
      counted.add(el);
      count++;
      console.log('[FailedBadges Generic] +1:', cls.substring(0, 40), '-', text.substring(0, 80));
    }
  }

  // วิธี 2 (fallback): scan media cards สำหรับ "Failed" text (Flow class เดิม)
  if (count === 0) {
    const cards = document.querySelectorAll('.sc-5923b123-0');
    for (const card of cards) {
      const cardText = (card.innerText || '').trim();
      if (cardText.includes('Failed') && !cardText.includes('Audio generation failed') && !cardText.includes('loading your media')) {
        let alreadyCounted = false;
        for (const prev of counted) {
          if (card.contains(prev) || prev.contains(card)) { alreadyCounted = true; break; }
        }
        if (!alreadyCounted) {
          counted.add(card);
          count++;
        }
      }
    }
  }
  return count;
}

// v17.3: หาและกดปุ่ม Retry บน Failed card (ไม่ต้อง refresh หน้า)
// คืน true ถ้ากดได้, false ถ้าหาปุ่มไม่เจอ
// v4.5.7: หาปุ่ม Retry (icon "refresh" / <span>Retry</span>) บนกรอบ Failed — คืน element เพื่อคลิก humanized
//   DOM: <button>...<i class="google-symbols">refresh</i><span>Retry</span>...</button>
function findFailedCardRetryButton() {
  const warns = document.querySelectorAll('i.google-symbols');
  for (const ic of warns) {
    if ((ic.textContent || '').trim().toLowerCase() !== 'warning' || !isVisible(ic)) continue;
    // ไล่ขึ้น parent หา card ที่มีปุ่มอย่างน้อย 2 ตัว (retry/undo/delete)
    let card = ic;
    for (let i = 0; i < 15 && card.parentElement; i++) {
      card = card.parentElement;
      if (card.querySelectorAll && card.querySelectorAll('button, [role="button"]').length >= 2) break;
    }
    const btns = card.querySelectorAll('button, [role="button"]');
    for (const b of btns) {
      if (!isVisible(b)) continue;
      const span = b.querySelector('span');
      const icon = b.querySelector('i.google-symbols');
      const spanTxt = ((span && span.textContent) || '').trim().toLowerCase();
      const iconTxt = ((icon && icon.textContent) || '').trim().toLowerCase();
      if (spanTxt === 'retry' || iconTxt === 'refresh') return b;
    }
  }
  return null;
}

function clickRetryOnFailedCard() {
  console.log('[Retry] 🔍 Looking for retry button on Failed card...');

  // วิธี 1: หาจาก warning icon → ไล่ขึ้น parent → หาปุ่ม retry ภายใน card
  const warningIcons = document.querySelectorAll('i.google-symbols');
  for (const icon of warningIcons) {
    const iconText = (icon.textContent || '').trim().toLowerCase();
    if (iconText !== 'warning' || !isVisible(icon)) continue;

    // ไล่ขึ้น parent จนเจอ card container
    let cardEl = icon;
    for (let i = 0; i < 15; i++) {
      if (!cardEl.parentElement) break;
      cardEl = cardEl.parentElement;
      if (cardEl.className?.includes('sc-5923b123-0') ||
          cardEl.className?.includes('card') ||
          cardEl.getAttribute('role') === 'listitem') {
        break;
      }
    }

    // หาปุ่ม retry ภายใน card — icon ลูกศรวน (google-symbols)
    const retryIconNames = ['refresh', 'replay', 'autorenew', 'sync', 'loop', 'restart_alt', 'redo', 'rotate_right'];
    const allIcons = cardEl.querySelectorAll('i.google-symbols');
    for (const retryIcon of allIcons) {
      const retryText = (retryIcon.textContent || '').trim().toLowerCase();
      if (retryIconNames.includes(retryText) && isVisible(retryIcon)) {
        // หาปุ่มที่เป็น parent ของ icon
        const btn = retryIcon.closest('button') || retryIcon.closest('[role="button"]') || retryIcon.parentElement;
        if (btn) {
          console.log(`[Retry] ✅ Found retry button with icon "${retryText}" — clicking!`);
          realClick(btn);
          return true;
        }
      }
    }

    // Fallback: หาปุ่มทุกตัวใน card ที่ไม่ใช่ warning icon
    const allButtons = cardEl.querySelectorAll('button, [role="button"]');
    for (const btn of allButtons) {
      if (!isVisible(btn)) continue;
      const btnText = (btn.textContent || '').trim().toLowerCase();
      // ข้ามปุ่มที่เป็น menu/options (3-dot)
      if (btnText === 'more_vert' || btnText === 'more_horiz' || btn.getAttribute('aria-haspopup') === 'menu') continue;
      // ข้ามปุ่มที่มีข้อความ warning
      if (btnText === 'warning') continue;
      // ปุ่มที่เหลือน่าจะเป็น retry
      const innerIcon = btn.querySelector('i.google-symbols');
      if (innerIcon) {
        const innerText = (innerIcon.textContent || '').trim().toLowerCase();
        if (innerText !== 'warning' && innerText !== 'more_vert') {
          console.log(`[Retry] ✅ Found button with icon "${innerText}" in Failed card — clicking!`);
          realClick(btn);
          return true;
        }
      }
    }

    console.log('[Retry] ⚠️ Found warning icon but no retry button in card');
  }

  // วิธี 2: หาจากข้อความ "Failed" หรือ "Failed Generation" → ไล่ขึ้น parent → หาปุ่ม retry
  const failedTexts = document.querySelectorAll('span, div');
  for (const el of failedTexts) {
    const text = (el.textContent || '').trim();
    if ((text === 'Failed' || text === 'Failed Generation') && isVisible(el)) {
      let cardEl = el;
      for (let i = 0; i < 15; i++) {
        if (!cardEl.parentElement) break;
        cardEl = cardEl.parentElement;
        if (cardEl.className?.includes('sc-5923b123-0') ||
            cardEl.className?.includes('card') ||
            cardEl.getAttribute('role') === 'listitem') {
          break;
        }
      }

      const retryIconNames = ['refresh', 'replay', 'autorenew', 'sync', 'loop', 'restart_alt', 'redo', 'rotate_right'];
      const allIcons = cardEl.querySelectorAll('i.google-symbols');
      for (const retryIcon of allIcons) {
        const retryText = (retryIcon.textContent || '').trim().toLowerCase();
        if (retryIconNames.includes(retryText) && isVisible(retryIcon)) {
          const btn = retryIcon.closest('button') || retryIcon.closest('[role="button"]') || retryIcon.parentElement;
          if (btn) {
            console.log(`[Retry] ✅ Found retry button (via Failed text) with icon "${retryText}" — clicking!`);
            realClick(btn);
            return true;
          }
        }
      }
    }
  }

  console.log('[Retry] ❌ No retry button found on any Failed card');
  return false;
}

// v17.3: หาและกดปุ่มลบ (delete/trash) บน Failed card (ใช้คู่กับ clickRetryOnFailedCard สำหรับ Image retry)
// Flow: กดปุ่ม Retry → รอ → กดปุ่ม Delete เพื่อลบ Failed card → baseline reset → ตรวจใหม่
function deleteFailedCardOnMainPage() {
  console.log('[Delete] 🗑️ Looking for delete button on Failed card...');

  // หา Failed card จาก warning icon, "Failed" text, sc-9a984650 class, หรือ refresh icon
  function findFailedCard() {
    // วิธี 1: หาจาก warning icon
    const warningIcons = document.querySelectorAll('i.google-symbols');
    for (const icon of warningIcons) {
      const iconText = (icon.textContent || '').trim().toLowerCase();
      if (iconText === 'warning' && isVisible(icon)) {
        let cardEl = icon;
        for (let i = 0; i < 15; i++) {
          if (!cardEl.parentElement) break;
          cardEl = cardEl.parentElement;
          if (cardEl.className?.includes('sc-5923b123-0') ||
              cardEl.className?.includes('card') ||
              cardEl.getAttribute('role') === 'listitem') {
            return cardEl;
          }
        }
      }
    }

    // วิธี 2: หาจาก "Failed" text (class sc-9a984650 หรือ text match)
    const failedDivs = document.querySelectorAll('[class*="sc-9a984650"], span, div');
    for (const el of failedDivs) {
      const text = (el.textContent || '').trim();
      if ((text === 'Failed' || text === 'Failed Generation') && isVisible(el)) {
        let cardEl = el;
        for (let i = 0; i < 15; i++) {
          if (!cardEl.parentElement) break;
          cardEl = cardEl.parentElement;
          if (cardEl.className?.includes('sc-5923b123-0') ||
              cardEl.className?.includes('card') ||
              cardEl.getAttribute('role') === 'listitem') {
            return cardEl;
          }
        }
      }
    }

    // วิธี 3: หาจาก refresh icon (มีเฉพาะบน Failed card)
    for (const icon of warningIcons) {
      const iconText = (icon.textContent || '').trim().toLowerCase();
      if (iconText === 'refresh' && isVisible(icon)) {
        let cardEl = icon;
        for (let i = 0; i < 15; i++) {
          if (!cardEl.parentElement) break;
          cardEl = cardEl.parentElement;
          if (cardEl.className?.includes('sc-5923b123-0') ||
              cardEl.className?.includes('card') ||
              cardEl.getAttribute('role') === 'listitem') {
            return cardEl;
          }
        }
      }
    }

    return null;
  }

  const cardEl = findFailedCard();
  if (!cardEl) {
    console.log('[Delete] ⚠️ No Failed card found');
    return false;
  }

  // หาปุ่ม delete ภายใน card
  const deleteIconNames = ['delete', 'delete_outline', 'delete_forever', 'close', 'cancel'];
  const allIcons = cardEl.querySelectorAll('i.google-symbols');
  for (const icon of allIcons) {
    const iconText = (icon.textContent || '').trim().toLowerCase();
    if (deleteIconNames.includes(iconText) && isVisible(icon)) {
      const btn = icon.closest('button') || icon.closest('[role="button"]') || icon.parentElement;
      if (btn) {
        console.log(`[Delete] ✅ Found delete button with icon "${iconText}" — clicking!`);
        realClick(btn);
        return true;
      }
    }
  }

  // Fallback: หา button ที่มี aria-label delete
  const deleteButtons = cardEl.querySelectorAll('button[aria-label*="delete" i], button[aria-label*="remove" i], button[aria-label*="Delete" i]');
  for (const btn of deleteButtons) {
    if (isVisible(btn)) {
      console.log(`[Delete] ✅ Found delete button via aria-label — clicking!`);
      realClick(btn);
      return true;
    }
  }

  console.log('[Delete] ❌ No delete button found on Failed card');
  return false;
}

// v8.6.2: นับเฉพาะ Audio Generation Failed (นับจาก video card ไม่ใช่ text element)
function countAudioFailedGenerations() {
  let count = 0;

  // หา video cards ที่มี "Audio generation failed"
  const allCards = document.querySelectorAll('[role="listitem"], [class*="card"], [class*="video"]');
  const countedCards = new Set();

  for (const card of allCards) {
    if (countedCards.has(card)) continue;

    const text = (card.textContent || '').toLowerCase();
    // ต้องมีคำว่า "audio generation failed" แต่ไม่ใช่ "failed generation" เต็มๆ
    if (text.includes('audio generation failed') && !text.includes('failed generation')) {
      // ต้องมี video/image ด้วย (ไม่ใช่ card ว่างเปล่า)
      const hasMedia = card.querySelector('video, img, [class*="thumbnail"]');
      if (hasMedia && card.offsetWidth > 50) {
        countedCards.add(card);
        count++;
      }
    }
  }

  // ถ้าหาจาก card ไม่เจอ ให้นับจาก text โดยตรง (fallback)
  if (count === 0) {
    const audioFailedTexts = document.querySelectorAll('span, div, p');
    for (const el of audioFailedTexts) {
      const text = (el.textContent || '').trim().toLowerCase();
      // ต้องเป็น exact "audio generation failed" ไม่ใช่ nested text
      if (text === 'audio generation failed.' || text === 'audio generation failed') {
        count++;
      }
    }
  }

  console.log(`[Failed] Audio failed count: ${count}`);
  return count;
}

// v8.6.2: นับคลิปที่ใช้ได้ (ไม่มี error)
// v8.6.3: แก้ไขลำดับการเช็ค - ต้องเช็ค audio failed ก่อน failed generation
// v8.6.4: เพิ่มข้อมูลตำแหน่งคลิปและการตัดสินใจ
function countUsableClips() {
  let totalClips = 0;
  let usableClips = 0;
  let audioFailed = 0;
  let videoFailed = 0;

  // เก็บข้อมูลรายคลิปสำหรับการตัดสินใจ
  const clipDetails = [];

  // หาคลิปทั้งหมด
  const clipCards = document.querySelectorAll('[data-video-card], [class*="video-card"], [class*="clip-card"], [role="listitem"]');

  let clipIndex = 0;
  for (const card of clipCards) {
    const text = (card.textContent || '').toLowerCase();

    // ข้ามถ้าเป็น empty card หรือ placeholder
    if (card.offsetWidth < 50 || card.offsetHeight < 50) continue;

    totalClips++;
    const currentIndex = clipIndex;
    clipIndex++;

    // ตรวจสอบ error types - เช็ค audio failed ก่อน!
    if (text.includes('audio generation failed') || text.includes('audio failed')) {
      audioFailed++;
      usableClips++;
      clipDetails.push({
        index: currentIndex,
        status: 'audio_failed',
        usable: true,
        text: 'Audio Failed (วิดีโอยังใช้ได้)'
      });
    } else if (text.includes('failed generation') || text.includes('generation failed') || text.includes('failed to generate')) {
      videoFailed++;
      clipDetails.push({
        index: currentIndex,
        status: 'video_failed',
        usable: false,
        text: 'Video Failed (ใช้ไม่ได้)'
      });
    } else if (card.querySelector('video') || card.querySelector('[data-video]') || card.querySelector('img[src*="thumbnail"]')) {
      usableClips++;
      clipDetails.push({
        index: currentIndex,
        status: 'ok',
        usable: true,
        text: 'ใช้ได้'
      });
    } else {
      clipDetails.push({
        index: currentIndex,
        status: 'unknown',
        usable: false,
        text: 'ไม่พบวิดีโอ'
      });
    }
  }

  // Fallback: นับจากจำนวนวิดีโอ
  if (totalClips === 0) {
    const videos = document.querySelectorAll('video');
    totalClips = videos.length;
    usableClips = videos.length;
    audioFailed = countAudioFailedGenerations();
    videoFailed = countAllFailedGenerations() - audioFailed;
  }

  // v8.6.4: วิเคราะห์การตัดสินใจ
  const decisions = analyzeDecisions(clipDetails);

  console.log(`[ClipCount] Total: ${totalClips}, Usable: ${usableClips}, AudioFailed: ${audioFailed}, VideoFailed: ${videoFailed}`);
  console.log(`[ClipCount] Details:`, clipDetails);
  console.log(`[ClipCount] Decisions:`, decisions);

  return {
    total: totalClips,
    usable: usableClips,
    audioFailed: audioFailed,
    videoFailed: videoFailed,
    hasUsableClips: usableClips > 0,
    clipDetails: clipDetails,
    decisions: decisions
  };
}

// v8.6.4: วิเคราะห์การตัดสินใจว่าจะทำอะไรกับคลิปแต่ละตัว
function analyzeDecisions(clipDetails) {
  const decisions = [];

  for (let i = 0; i < clipDetails.length; i++) {
    const clip = clipDetails[i];

    if (clip.status === 'video_failed') {
      // Video failed → ต้องลบออก
      decisions.push({
        clipIndex: i,
        action: 'DELETE',
        reason: '❌ Video failed - ต้องลบออก',
        color: '#f44336'
      });
    } else if (clip.status === 'audio_failed') {
      // Audio failed → หาคลิปข้างๆที่ดี
      const hasGoodNeighbor = clipDetails.some((c, idx) =>
        idx !== i && c.status === 'ok' && c.usable
      );

      if (hasGoodNeighbor) {
        decisions.push({
          clipIndex: i,
          action: 'USE_NEIGHBOR',
          reason: '🔇 Audio failed - จะใช้คลิปอื่นที่ดีแทน',
          color: '#ff9800'
        });
      } else {
        decisions.push({
          clipIndex: i,
          action: 'DELETE_AND_SKIP',
          reason: '🔇 Audio failed + ไม่มีคลิปดี - ลบแล้วข้ามสินค้า',
          color: '#f44336'
        });
      }
    } else if (clip.status === 'ok') {
      decisions.push({
        clipIndex: i,
        action: 'USE',
        reason: '✅ ใช้ได้ปกติ',
        color: '#4CAF50'
      });
    }
  }

  // สรุปภาพรวม
  const summary = {
    canProceed: decisions.some(d => d.action === 'USE' || d.action === 'USE_NEIGHBOR'),
    needsDelete: decisions.filter(d => d.action === 'DELETE').length,
    willSkip: decisions.filter(d => d.action === 'DELETE_AND_SKIP').length,
    willUseNeighbor: decisions.filter(d => d.action === 'USE_NEIGHBOR').length,
    readyToUse: decisions.filter(d => d.action === 'USE').length
  };

  return {
    perClip: decisions,
    summary: summary
  };
}

// นับจำนวน Failed Generation ใหม่ (หลังจากกดสร้าง)
function countNewFailedGenerations() {
  const totalFailed = countAllFailedGenerations();
  const newFailed = Math.max(0, totalFailed - failedCountBeforeGenerate);
  return newFailed;
}

// v8.7.1: หา index ของคลิปแรกที่ใช้ได้ (ไม่ใช่ video failed)
// v8.7.3: แก้ไขให้จัดการ fallback case (เมื่อ clipDetails ว่างแต่มี videos)
// ใช้สำหรับต่อฉาก เพื่อไม่ให้เลือกคลิปที่ failed ไปต่อฉาก
function findFirstUsableClipIndex() {
  const clipInfo = countUsableClips();

  // v8.7.3: ถ้าไม่มี clipDetails (fallback case) ให้เช็คจาก usable count แทน
  if (!clipInfo.clipDetails || clipInfo.clipDetails.length === 0) {
    // ถ้ามี usable clips (จาก fallback ที่นับ videos โดยตรง)
    if (clipInfo.usable > 0) {
      console.log(`[findFirstUsableClipIndex] No clipDetails but has ${clipInfo.usable} usable clips (fallback), using index 0`);
      return { index: 0, hasUsable: true, status: 'fallback_ok' };
    }
    console.log('[findFirstUsableClipIndex] No clip details and no usable clips');
    return { index: 0, hasUsable: false };
  }

  // หาคลิปแรกที่ usable (ไม่ใช่ video_failed และไม่ใช่ unknown)
  for (let i = 0; i < clipInfo.clipDetails.length; i++) {
    const clip = clipInfo.clipDetails[i];
    if (clip.usable && clip.status !== 'video_failed') {
      console.log(`[findFirstUsableClipIndex] Found usable clip at index ${i}: ${clip.status}`);
      return { index: i, hasUsable: true, status: clip.status };
    }
  }

  // ไม่พบคลิปที่ใช้ได้
  console.log('[findFirstUsableClipIndex] No usable clip found');
  return { index: -1, hasUsable: false };
}

// v7.4: ลบ Failed Generation ทั้งหมด (กดปุ่ม 3 จุด แล้วกด Delete)
// v7.5: ปรับปรุง retry logic และ timing
// v8.7.5: เพิ่ม retry หา element และ log ที่ชัดเจนขึ้น
async function deleteAllFailedGenerations() {
  let deleted = 0;
  const maxAttempts = 10; // ป้องกัน infinite loop

  // v8.7.5: รอให้ DOM พร้อมก่อนเริ่มลบ (2 วินาที)
  console.log('[Delete Failed] Waiting 2s for DOM to be fully ready...');
  await sleep(2000);

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    // v8.7.5: Scroll ไปบนสุดก่อนเพื่อให้เห็น clips ทั้งหมด
    window.scrollTo(0, 0);
    await sleep(300);

    const failedCount = countAllFailedGenerations();
    if (failedCount === 0) {
      console.log(`[Delete Failed] No more failed generations (deleted ${deleted} total)`);
      break;
    }

    console.log(`[Delete Failed] Attempt ${attempt + 1}: Found ${failedCount} failed generation(s)`);

    // v8.7.5: retry หา element หลายครั้งเพราะบางที DOM ยังไม่พร้อม
    let failedEl = null;
    for (let findRetry = 0; findRetry < 8; findRetry++) {
      failedEl = findFailedGenerationElement();
      if (failedEl) break;
      console.log(`[Delete Failed] Retrying find element... (${findRetry + 1}/8)`);
      // v8.7.5: Scroll ลงทีละนิดเผื่อ element อยู่ด้านล่าง
      window.scrollBy(0, 200);
      await sleep(800);
    }

    if (!failedEl) {
      console.log('[Delete Failed] Could not find Failed Generation element after 8 retries');
      // v8.7.5: ลอง refresh แล้ว retry รอบหน้า แทนที่จะ break ทันที
      await sleep(1000);
      continue;
    }

    // v8.7.5: Scroll ไปที่ element ให้มันอยู่ใน view
    console.log('[Delete Failed] Scrolling to element...');
    failedEl.scrollIntoView({ behavior: 'instant', block: 'center' });
    await sleep(500);

    // v9.0.1: ตรวจจับว่าเป็น Audio Fail หรือไม่ (popup ใหญ่กว่าปกติ ปุ่ม 3 จุดอยู่ต่ำกว่า)
    const failedText = (failedEl.textContent || '').toLowerCase();
    const isAudioFail = failedText.includes('audio generation failed') ||
                        failedText.includes('audio failed') ||
                        document.body.innerText.includes('Audio generation failed');
    if (isAudioFail) {
      console.log('[Delete Failed] v9.0.1: Detected AUDIO FAIL - using extended yTolerance (350px)');
    }

    // v8.7.5: retry หาปุ่ม 3 จุดหลายครั้ง
    // v9.0.1: ส่ง isAudioFail เพื่อใช้ yTolerance ที่เหมาะสม
    let menuBtn = null;
    for (let menuRetry = 0; menuRetry < 8; menuRetry++) {
      menuBtn = findThreeDotsMenuNearElement(failedEl, isAudioFail);
      if (menuBtn) break;
      console.log(`[Delete Failed] Retrying find menu button... (${menuRetry + 1}/8)`);
      await sleep(800);
    }

    if (!menuBtn) {
      console.log('[Delete Failed] Could not find 3-dot menu button after 8 retries');
      await sleep(1000);
      continue;
    }

    // v7.5: คลิกปุ่ม 3 จุดด้วย dispatchEvent (robust กว่า .click())
    console.log('[Delete Failed] Clicking 3-dot menu...');
    try {
      // ลองหลายวิธีในการคลิก
      menuBtn.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
    } catch (e) {
      menuBtn.click();
    }

    // v8.4.1: รอให้ menu render ก่อน (500ms แรก)
    await sleep(500);

    // v7.5: รอนานขึ้นให้ menu เปิด + retry หา Delete
    let deleteBtn = null;
    for (let retryFind = 0; retryFind < 8; retryFind++) {
      deleteBtn = findDeleteButtonInMenu();
      if (deleteBtn) {
        console.log(`[Delete Failed] Found Delete button on retry ${retryFind + 1}`);
        break;
      }
      console.log(`[Delete Failed] Delete button not found, retrying (${retryFind + 1}/8)...`);
      await sleep(300); // รอ 300ms ต่อรอบ
    }

    if (!deleteBtn) {
      console.log('[Delete Failed] Could not find Delete button in menu after 8 retries');
      // ปิด menu ถ้าเปิดค้าง
      document.body.click();
      await sleep(200);
      // v7.5: ไม่ break ทันที - ลองรอบถัดไป (อาจจะมี Failed Generation ตัวอื่น)
      continue;
    }

    // v7.5: คลิก Delete ด้วย dispatchEvent
    console.log('[Delete Failed] Clicking Delete...');
    try {
      deleteBtn.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
    } catch (e) {
      deleteBtn.click();
    }
    deleted++;

    // รอให้ลบเสร็จ
    await sleep(1000);
  }

  // อัพเดท baseline หลังลบ
  failedCountBeforeGenerate = countAllFailedGenerations();

  return { success: true, deleted: deleted, remaining: failedCountBeforeGenerate };
}

// v9.0.2: ลบ Audio Fail โดยเฉพาะ (คลิปที่มีวิดีโอแต่เสียงเฟล)
// ปุ่ม 3 จุดอยู่ถัดจาก "Extend" button ไม่ได้อยู่ใกล้ข้อความ error
async function deleteAudioFailGeneration() {
  console.log('[Audio Fail] v9.0.2: Starting delete audio fail...');
  let deleted = 0;
  let debug = '';

  // หา element ที่มีข้อความ "Audio generation failed"
  const audioFailEl = findAudioFailElement();
  if (!audioFailEl) {
    debug += 'ไม่พบข้อความ "Audio generation failed"\n';
    console.log('[Audio Fail] No audio fail element found');
    return { success: true, deleted: 0, debug };
  }

  debug += `พบ Audio Fail element\n`;
  console.log('[Audio Fail] Found audio fail element:', audioFailEl);

  // Scroll to element
  audioFailEl.scrollIntoView({ behavior: 'instant', block: 'center' });
  await sleep(500);

  // หา "Extend" button ในบริเวณเดียวกัน
  const extendBtn = findExtendButtonNear(audioFailEl);
  if (extendBtn) {
    debug += `พบปุ่ม Extend\n`;
    console.log('[Audio Fail] Found Extend button:', extendBtn);
  } else {
    debug += `ไม่พบปุ่ม Extend\n`;
  }

  // หาปุ่ม 3 จุดที่อยู่ใกล้ "Extend" หรือในบริเวณเดียวกัน
  let menuBtn = null;

  // วิธี 1: หาปุ่ม 3 จุดจาก parent ของ Extend (โครงสร้าง: parent > Extend + button container)
  if (extendBtn) {
    // หาจาก parent โดยตรงก่อน
    let parent = extendBtn.parentElement;
    for (let level = 0; level < 3 && parent; level++) {
      // หาปุ่มที่มี more_vert icon หรือ aria-haspopup="menu"
      const btns = parent.querySelectorAll('button[aria-haspopup="menu"], button');
      for (const btn of btns) {
        const icon = btn.querySelector('i');
        if (icon && icon.textContent.trim() === 'more_vert') {
          menuBtn = btn;
          debug += `พบปุ่ม 3 จุด (parent level ${level} ของ Extend)\n`;
          console.log('[Audio Fail] Found menu button in parent level', level, 'of Extend');
          break;
        }
      }
      if (menuBtn) break;
      parent = parent.parentElement;
    }
  }

  // วิธี 2: หาจาก grandparent
  if (!menuBtn && extendBtn) {
    let container = extendBtn.parentElement?.parentElement;
    for (let i = 0; i < 5 && container; i++) {
      const btns = container.querySelectorAll('button');
      for (const btn of btns) {
        const icon = btn.querySelector('i');
        if (icon && icon.textContent.trim() === 'more_vert') {
          const rect = btn.getBoundingClientRect();
          if (rect.width > 0 && rect.height > 0) {
            menuBtn = btn;
            debug += `พบปุ่ม 3 จุด (container level ${i + 1})\n`;
            console.log('[Audio Fail] Found menu button in container level', i + 1);
            break;
          }
        }
      }
      if (menuBtn) break;
      container = container.parentElement;
    }
  }

  // วิธี 3: หาจากตำแหน่ง Y ใกล้เคียงกับ Extend button
  if (!menuBtn && extendBtn) {
    const extendRect = extendBtn.getBoundingClientRect();
    const allMenuBtns = document.querySelectorAll('button');
    let closestBtn = null;
    let closestDist = Infinity;

    for (const btn of allMenuBtns) {
      const icon = btn.querySelector('i');
      if (icon && icon.textContent.trim() === 'more_vert') {
        const rect = btn.getBoundingClientRect();
        if (rect.width === 0 || rect.height === 0) continue;

        // ต้องอยู่ในแถวเดียวกัน (Y ใกล้กัน) และอยู่ทางขวาของ Extend
        const yDiff = Math.abs(rect.top - extendRect.top);
        const xDiff = rect.left - extendRect.right; // ต้องอยู่ทางขวา

        if (yDiff < 30 && xDiff > -50 && xDiff < 200) {
          const dist = Math.abs(xDiff);
          if (dist < closestDist) {
            closestDist = dist;
            closestBtn = btn;
          }
        }
      }
    }

    if (closestBtn) {
      menuBtn = closestBtn;
      debug += `พบปุ่ม 3 จุด (position-based near Extend)\n`;
      console.log('[Audio Fail] Found menu button by position near Extend');
    }
  }

  // วิธี 4: fallback - หาจากตำแหน่ง Y ของ audioFailEl
  if (!menuBtn) {
    const failRect = audioFailEl.getBoundingClientRect();
    const allMenuBtns = document.querySelectorAll('button[aria-haspopup="menu"]');

    for (const btn of allMenuBtns) {
      const rect = btn.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) continue;

      // Audio Fail popup ใหญ่มาก - ปุ่มอยู่ต่ำกว่ามาก (ใช้ 500px tolerance)
      const yDiff = Math.abs(rect.top - failRect.top);
      if (yDiff < 500) {
        menuBtn = btn;
        debug += `พบปุ่ม 3 จุด (fallback: aria-haspopup)\n`;
        console.log('[Audio Fail] Found menu button by aria-haspopup fallback');
        break;
      }
    }
  }

  if (!menuBtn) {
    debug += `❌ ไม่พบปุ่ม 3 จุด\n`;
    console.log('[Audio Fail] Could not find menu button');
    return { success: false, deleted: 0, error: 'ไม่พบปุ่ม 3 จุด', debug };
  }

  // คลิกปุ่ม 3 จุด
  debug += `กำลังคลิกปุ่ม 3 จุด...\n`;
  console.log('[Audio Fail] Clicking menu button...');

  // scroll ให้ปุ่มอยู่ในจอก่อน
  menuBtn.scrollIntoView({ behavior: 'instant', block: 'center' });
  await sleep(300);

  try {
    menuBtn.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
  } catch (e) {
    menuBtn.click();
  }

  // v9.1: รอนานขึ้นให้ menu เปิด + retry หา Delete หลายครั้ง
  let deleteBtn = null;
  for (let retry = 0; retry < 10; retry++) {
    await sleep(400);
    deleteBtn = findDeleteButtonInMenu();
    if (deleteBtn) {
      debug += `พบปุ่ม Delete (retry ${retry + 1})\n`;
      console.log('[Audio Fail] Found Delete button on retry', retry + 1);
      break;
    }
    console.log(`[Audio Fail] Delete button not found, retrying (${retry + 1}/10)...`);
  }

  if (!deleteBtn) {
    // v9.1: ลองหา Delete แบบ alternative
    debug += `ลองหา Delete แบบ alternative...\n`;
    deleteBtn = findDeleteButtonAlternative();
  }

  if (!deleteBtn) {
    debug += `❌ ไม่พบปุ่ม Delete ใน menu\n`;
    console.log('[Audio Fail] Could not find Delete button after 10 retries');
    // ปิด menu
    document.body.click();
    await sleep(200);
    return { success: false, deleted: 0, error: 'ไม่พบปุ่ม Delete ใน menu', debug };
  }

  // คลิก Delete
  debug += `กำลังคลิก Delete...\n`;
  console.log('[Audio Fail] Clicking Delete...');
  try {
    deleteBtn.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
  } catch (e) {
    deleteBtn.click();
  }
  deleted++;

  await sleep(1000);
  debug += `✅ ลบสำเร็จ!\n`;

  return { success: true, deleted, debug };
}

// v9.1: หา Delete button แบบ alternative (fallback)
function findDeleteButtonAlternative() {
  console.log('[Audio Fail] Trying alternative Delete search...');

  // วิธี 1: หาจาก text "Delete" โดยตรง
  const allElements = document.querySelectorAll('button, [role="menuitem"], [role="button"], span, div');
  for (const el of allElements) {
    const text = (el.textContent || '').trim();
    if (text === 'Delete' || text === 'ลบ') {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        console.log('[Audio Fail] Found Delete by text:', el);
        return el;
      }
    }
  }

  // วิธี 2: หา icon delete ที่ visible
  const allIcons = document.querySelectorAll('i, [class*="icon"]');
  for (const icon of allIcons) {
    const text = (icon.textContent || '').trim().toLowerCase();
    if (text === 'delete' || text === 'delete_outline') {
      const rect = icon.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        // หา clickable parent
        let parent = icon.parentElement;
        for (let i = 0; i < 5 && parent; i++) {
          if (parent.tagName === 'BUTTON' || parent.getAttribute('role') === 'menuitem' || parent.getAttribute('role') === 'button') {
            console.log('[Audio Fail] Found Delete via icon parent:', parent);
            return parent;
          }
          parent = parent.parentElement;
        }
        // ถ้าหา parent ไม่เจอ return icon เลย
        console.log('[Audio Fail] Found Delete icon itself:', icon);
        return icon;
      }
    }
  }

  console.log('[Audio Fail] No alternative Delete found');
  return null;
}

// v9.0.2: หา element ที่มี "Audio generation failed"
function findAudioFailElement() {
  // หาจากข้อความโดยตรง
  const allElements = document.querySelectorAll('span, div, p');
  for (const el of allElements) {
    const text = (el.textContent || '').toLowerCase();
    if (text.includes('audio generation failed')) {
      if (el.offsetWidth > 0 && el.offsetHeight > 0) {
        return el;
      }
    }
  }
  return null;
}

// v9.0.2: หา "Extend" button ใกล้ๆ element
// v9.1: ปรับปรุงให้หาได้ดีขึ้น - Extend เป็น div ไม่ใช่ button
function findExtendButtonNear(element) {
  console.log('[Audio Fail] Looking for Extend element...');

  // วิธี 1: หาจาก parent chain - รองรับทั้ง button และ div
  let container = element;
  for (let i = 0; i < 20; i++) {
    container = container.parentElement;
    if (!container || container === document.body) break;

    // หาทุก element ที่มี text "Extend"
    const allEls = container.querySelectorAll('button, [role="button"], div, span');
    for (const el of allEls) {
      const text = (el.textContent || '').trim();
      if (text === 'Extend') {
        const rect = el.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0) {
          console.log('[Audio Fail] Found Extend in parent chain level', i, el);
          return el;
        }
      }
    }
  }

  // วิธี 2: หาจากทุกที่ในหน้า - รองรับทั้ง button และ div
  const allEls = document.querySelectorAll('button, [role="button"], div, span');
  const elemRect = element.getBoundingClientRect();
  let closestExtend = null;
  let closestDist = Infinity;

  for (const el of allEls) {
    const text = (el.textContent || '').trim();
    if (text === 'Extend') {
      const rect = el.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) continue;

      const yDiff = Math.abs(rect.top - elemRect.top);
      if (yDiff < closestDist) {
        closestDist = yDiff;
        closestExtend = el;
      }
    }
  }

  if (closestExtend) {
    console.log('[Audio Fail] Found closest Extend element, yDiff:', closestDist);
    return closestExtend;
  }

  console.log('[Audio Fail] No Extend element found');
  return null;
}

// หา element "Failed Generation" ตัวแรก
// v8.5.1: ปรับปรุงให้หาได้ดีขึ้น รองรับ DOM ที่เปลี่ยน
function findFailedGenerationElement() {
  // วิธี 1: หาจาก exact text "Failed Generation"
  const allElements = document.querySelectorAll('button, [role="button"], span, div, p');
  for (const el of allElements) {
    const text = (el.textContent || '').trim();
    if (text === 'Failed Generation') {
      console.log('[Failed] Found exact element:', el);
      return el;
    }
  }

  // วิธี 2: หาจากข้อความ error (Audio generation failed)
  for (const el of allElements) {
    const text = (el.textContent || '').toLowerCase();
    if (text.includes('audio generation failed') ||
        text.includes('generation failed') ||
        text.includes('failed to generate')) {
      // ต้องมี dimension จริง
      if (el.offsetWidth > 0 && el.offsetHeight > 0) {
        console.log('[Failed] Found error text element:', el.textContent?.substring(0, 50));
        return el;
      }
    }
  }

  // วิธี 3: หาจาก aria-label หรือ data attribute
  const byAria = document.querySelector('[aria-label*="Failed"], [data-status="failed"]');
  if (byAria) {
    console.log('[Failed] Found by aria/data:', byAria);
    return byAria;
  }

  // วิธี 4: XPath fallback
  try {
    const xpaths = [
      "//div[normalize-space(text())='Failed Generation']",
      "//span[normalize-space(text())='Failed Generation']",
      "//div[contains(text(), 'Audio generation failed')]",
      "//span[contains(text(), 'Audio generation failed')]"
    ];

    for (const xpath of xpaths) {
      const result = document.evaluate(xpath, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null);
      if (result.singleNodeValue) {
        console.log('[Failed] Found by XPath:', result.singleNodeValue);
        return result.singleNodeValue;
      }
    }
  } catch (e) {
    console.log('[Failed] XPath error:', e.message);
  }

  console.log('[Failed] No failed element found');
  return null;
}

// หาปุ่ม 3 จุด (more options) ใกล้ๆ element
// v7.5: แก้ไข selectors ให้ตรงกับ DOM จริง
// v8: ปรับปรุงให้ robust มากขึ้น - ใช้ position-based fallback ก่อน
// v9.0.1: เพิ่ม parameter isAudioFail สำหรับ Audio Generation Failed (popup ใหญ่กว่าปกติ ปุ่ม 3 จุดอยู่ต่ำกว่า)
function findThreeDotsMenuNearElement(element, isAudioFail = false) {
  const failedRect = element.getBoundingClientRect();

  // v9.0.1: Audio Fail popup ใหญ่กว่าปกติ → ปุ่ม 3 จุดอยู่ต่ำกว่า → ใช้ yTolerance มากขึ้น (350px แทน 100px)
  const yTolerance = isAudioFail ? 350 : 100;
  console.log(`[Delete Failed] Looking for menu button near: Y=${failedRect.top.toFixed(0)}, X=${failedRect.left.toFixed(0)}, isAudioFail=${isAudioFail}, yTolerance=${yTolerance}`);

  // v8: วิธีที่ 1 (เร็วที่สุด) - หาปุ่มที่ใกล้ที่สุดในแนว Y เดียวกัน
  const allMenuBtns = document.querySelectorAll('button[aria-haspopup="menu"]');
  console.log(`[Delete Failed] Found ${allMenuBtns.length} menu buttons total`);

  let closestBtn = null;
  let closestDist = Infinity;

  for (const btn of allMenuBtns) {
    const rect = btn.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) continue;

    // v9.0.1: ใช้ yTolerance แทน hardcode 100px (รองรับ Audio Fail ที่ popup ใหญ่กว่า)
    const yDiff = Math.abs(rect.top - failedRect.top);
    if (yDiff > yTolerance) continue;

    // คำนวณระยะห่าง (ให้ความสำคัญกับ Y มากกว่า X)
    const xDiff = Math.abs(rect.left - failedRect.left);
    const dist = yDiff * 2 + xDiff; // Y weight มากกว่า

    if (dist < closestDist && dist < 800) {
      closestDist = dist;
      closestBtn = btn;
    }
  }

  if (closestBtn) {
    console.log('[Delete Failed] Found closest menu button (position-based):', closestBtn, 'distance:', closestDist.toFixed(0));
    return closestBtn;
  }

  // v8: วิธีที่ 2 - หาจาก parent chain
  let container = element;
  for (let i = 0; i < 15; i++) {
    container = container.parentElement;
    if (!container || container === document.body) break;

    // หาปุ่ม menu ใน container นี้
    const menuBtn = container.querySelector('button[aria-haspopup="menu"]');
    if (menuBtn) {
      const rect = menuBtn.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        console.log('[Delete Failed] Found menu button in parent container:', menuBtn);
        return menuBtn;
      }
    }
  }

  // v8: วิธีที่ 3 - หา more_vert icon
  // v9.0.1: ใช้ yTolerance ที่กำหนดไว้ด้านบน (รองรับ Audio Fail)
  const allMoreVertBtns = document.querySelectorAll('button');
  for (const btn of allMoreVertBtns) {
    const icon = btn.querySelector('i.material-icons, [class*="material-icons"]');
    if (icon && icon.textContent.trim() === 'more_vert') {
      const rect = btn.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) continue;

      const yDiff = Math.abs(rect.top - failedRect.top);
      if (yDiff <= yTolerance) {
        console.log('[Delete Failed] Found menu button by more_vert icon:', btn);
        return btn;
      }
    }
  }

  console.log('[Delete Failed] No menu button found - avoiding wrong button');
  return null;
}

// หาปุ่ม Delete ใน dropdown menu
// v7.5: ปรับปรุงให้ตรงกับ DOM จริง
// v8.1: เพิ่มวิธีหา Delete button แบบใหม่ที่ครอบคลุมมากขึ้น
// v8.4.1: แก้ไข selector ให้ครอบคลุม material-icons-outlined และ radix popper
function findDeleteButtonInMenu() {
  console.log('[Delete Failed] Searching for Delete button...');

  // v8.4.1: วิธีที่ 0.0 - หาใน Radix Popper Wrapper โดยตรง (ตรงที่สุดสำหรับ Google Flow)
  // ใช้โค้ดที่ทดสอบแล้วว่าทำงานได้
  const radixPoppers = document.querySelectorAll('[data-radix-popper-content-wrapper]');
  for (const popper of radixPoppers) {
    if (popper.getBoundingClientRect().width === 0) continue;

    console.log('[Delete Failed] v8.4.1: Found radix popper wrapper, searching inside...');

    // หา menuitem ที่มี delete icon ใน popper นี้
    const menuItems = popper.querySelectorAll('[role="menuitem"]');
    for (const item of menuItems) {
      // เช็ค icon delete (ตรงกับโค้ดที่ทดสอบแล้ว)
      const icon = item.querySelector('i');
      if (icon && icon.textContent.trim() === 'delete') {
        console.log('[Delete Failed] v8.4.1: Found Delete in radix popper:', item);
        return item;
      }
    }
  }

  // v8.4.1: วิธีที่ 0.1 - หา menuitem ที่มี delete icon โดยตรง (ตรงที่สุด)
  const menuItemsWithDelete = document.querySelectorAll('[role="menuitem"]');
  for (const item of menuItemsWithDelete) {
    const rect = item.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) continue;

    // หา icon ที่มี text "delete" ข้างใน
    const icon = item.querySelector('i');
    if (icon) {
      const iconText = (icon.textContent || '').trim().toLowerCase();
      if (iconText === 'delete') {
        console.log('[Delete Failed] v8.4.1: Found Delete menuitem with delete icon:', item);
        return item;
      }
    }
  }

  // v8.4.1: วิธีที่ 0.2 - หา material-icons-outlined ที่มี text delete (Google Flow ใหม่)
  const outlinedIcons = document.querySelectorAll('.material-icons-outlined, [class*="material-icons"]');
  for (const icon of outlinedIcons) {
    const iconText = (icon.textContent || '').trim().toLowerCase();
    if (iconText === 'delete') {
      // หา parent ที่เป็น menuitem
      let parent = icon.parentElement;
      for (let i = 0; i < 5 && parent; i++) {
        if (parent.getAttribute('role') === 'menuitem' || parent.hasAttribute('data-radix-collection-item')) {
          const rect = parent.getBoundingClientRect();
          if (rect.width > 0 && rect.height > 0) {
            console.log('[Delete Failed] v8.4.1: Found Delete via material-icons-outlined:', parent);
            return parent;
          }
        }
        parent = parent.parentElement;
      }
    }
  }

  // v8.1: วิธีที่ 0 - หา element ที่มี Material Icon "delete" (Google Flow ใช้ Material Icons)
  const materialIcons = document.querySelectorAll('.material-icons, .material-symbols-outlined, i[class*="icon"]');
  for (const icon of materialIcons) {
    const iconText = (icon.textContent || '').trim().toLowerCase();
    if (iconText === 'delete' || iconText === 'delete_forever') {
      // หา parent ที่ clickable
      let parent = icon.parentElement;
      for (let i = 0; i < 5 && parent; i++) {
        const rect = parent.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0) {
          // เช็คว่า parent ปรากฏอยู่ในหน้าจอ (ไม่ใช่ hidden)
          const style = window.getComputedStyle(parent);
          if (style.display !== 'none' && style.visibility !== 'hidden') {
            console.log('[Delete Failed] v8.1: Found Delete via Material Icon:', parent);
            return parent;
          }
        }
        parent = parent.parentElement;
      }
    }
  }

  // v7.5: วิธีที่ 1 - หา div[role="menuitem"] ที่มี icon delete หรือ text Delete
  const menuItems = document.querySelectorAll('[role="menuitem"]');

  for (const item of menuItems) {
    const rect = item.getBoundingClientRect();
    // ต้องมองเห็นบนหน้าจอ
    if (rect.width === 0 || rect.height === 0) continue;

    // เช็ค icon delete
    const deleteIcon = item.querySelector('i');
    if (deleteIcon && deleteIcon.textContent.trim() === 'delete') {
      console.log('[Delete Failed] Found Delete by icon:', item);
      return item;
    }

    // เช็ค text Delete
    const text = (item.textContent || '').toLowerCase();
    if (text.includes('delete') || text.includes('ลบ')) {
      console.log('[Delete Failed] Found Delete by text:', item);
      return item;
    }
  }

  // v7.5: วิธีที่ 2 - หา radix menu items (ใช้ data attribute)
  const radixItems = document.querySelectorAll('[data-radix-collection-item]');
  for (const item of radixItems) {
    const rect = item.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) continue;

    const text = (item.textContent || '').toLowerCase();
    if (text.includes('delete') || text.includes('ลบ')) {
      console.log('[Delete Failed] Found Delete in radix menu:', item);
      return item;
    }
  }

  // v8.1: วิธีที่ 3 - หาจาก aria-label
  const ariaLabeled = document.querySelectorAll('[aria-label*="delete" i], [aria-label*="Delete"]');
  for (const el of ariaLabeled) {
    const rect = el.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0) {
      console.log('[Delete Failed] v8.1: Found Delete by aria-label:', el);
      return el;
    }
  }

  // วิธีที่ 4: หา menu popover ที่เพิ่งเปิด แล้วหา Delete ในนั้น
  const menuPopovers = document.querySelectorAll('[role="menu"], [data-state="open"], .gm3-menu');
  for (const menu of menuPopovers) {
    const rect = menu.getBoundingClientRect();
    if (rect.width === 0 || rect.height === 0) continue;

    console.log('[Delete Failed] Checking menu popover:', menu);

    // หา Delete ใน menu นี้
    const allItems = menu.querySelectorAll('*');
    for (const item of allItems) {
      const text = (item.textContent || '').trim();
      // ต้องเป็น element ที่ clickable และมี text เป็น Delete
      if ((text === 'Delete' || text === 'deleteDelete' || text.includes('Delete')) &&
          (item.matches('div, button, span, a') || item.getAttribute('role'))) {
        const itemRect = item.getBoundingClientRect();
        if (itemRect.width > 0 && itemRect.height > 0) {
          console.log('[Delete Failed] Found Delete in menu popover:', item);
          return item;
        }
      }
    }
  }

  // v8.1: วิธีที่ 5 - หา element ที่มี class มี "delete" (case insensitive)
  const allElements = document.querySelectorAll('*');
  for (const el of allElements) {
    const className = el.className || '';
    if (typeof className === 'string' && className.toLowerCase().includes('delete')) {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        const style = window.getComputedStyle(el);
        if (style.display !== 'none' && style.visibility !== 'hidden') {
          console.log('[Delete Failed] v8.1: Found Delete by class name:', el);
          return el;
        }
      }
    }
  }

  // Fallback: หา button/div ทั่วไปที่มี text "Delete"
  const allClickables = document.querySelectorAll('button, [role="button"], div[tabindex], span[tabindex], div[class*="menu"], li');
  for (const el of allClickables) {
    const text = (el.textContent || '').trim();
    if (text === 'Delete' || text === 'ลบ' || text === 'deleteDelete') {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0) {
        console.log('[Delete Failed] Found Delete by fallback:', el);
        return el;
      }
    }
  }

  console.log('[Delete Failed] No Delete button found in menu');
  return null;
}

// นับจำนวน clip elements ทั้งหมดในหน้า (รวมทั้งที่กำลังสร้างและเสร็จแล้ว)
// ใช้สำหรับเปรียบเทียบก่อน/หลังกดสร้าง
function countAllClipElements() {
  // Flow จะสร้าง container สำหรับแต่ละคลิป
  // ลองหาหลายวิธี แล้วเอาค่าที่มากที่สุด

  let count = 0;

  // วิธี 1: หา video containers (div ที่มี video หรือ canvas ข้างใน)
  // แต่ละคลิปจะมี container แยก
  const videoContainers = findClipContainers();
  count = Math.max(count, videoContainers.length);

  // วิธี 2: นับจาก video elements
  const videos = document.querySelectorAll('video');
  let videoCount = 0;
  for (const video of videos) {
    // ต้องอยู่ในส่วนบนของหน้า (ไม่ใช่ video อื่นๆ)
    const rect = video.getBoundingClientRect();
    if (rect.top < window.innerHeight * 0.85 && rect.width > 50) {
      videoCount++;
    }
  }
  count = Math.max(count, videoCount);

  // วิธี 3: นับจาก thumbnail images ที่เป็นคลิป
  const thumbnails = document.querySelectorAll('img');
  let thumbCount = 0;
  for (const thumb of thumbnails) {
    const rect = thumb.getBoundingClientRect();
    // thumbnail ของคลิปมักมีขนาดใหญ่กว่า 80x80 และอยู่ในส่วนบน
    if (rect.width > 80 && rect.height > 80 && rect.top < window.innerHeight * 0.85) {
      // ตรวจสอบว่าไม่ใช่รูปสินค้าที่อัพโหลด (มักจะอยู่ใน prompt area)
      const promptArea = findPromptAreaContainer();
      if (!promptArea || !promptArea.contains(thumb)) {
        thumbCount++;
      }
    }
  }
  count = Math.max(count, thumbCount);

  console.log(`countAllClipElements: containers=${videoContainers.length}, videos=${videoCount}, thumbs=${thumbCount}, final=${count}`);

  return count;
}

// นับจำนวน Image elements ที่สร้างเสร็จ (สำหรับ Image mode)
// v6.9: ปรับปรุงให้ใช้วิธีเดียวกับโหมดออโต้ (findGeneratedImagesDirectly)
function countImageElements() {
  // ใช้ findGeneratedImagesDirectly() ซึ่งเป็นวิธีที่แม่นที่สุด (เหมือนโหมดออโต้)
  const images = findGeneratedImagesDirectly();
  console.log(`countImageElements: found ${images.length} generated images (using findGeneratedImagesDirectly)`);
  return images.length;
}

// นับ elements ตาม mode (video หรือ image)
function countElementsByMode() {
  if (currentMode === 'image') {
    return countImageElements();
  } else {
    return countAllClipElements();
  }
}

// หา clip containers (div ที่เป็น wrapper ของแต่ละคลิป)
function findClipContainers() {
  const containers = [];

  // หา elements ที่น่าจะเป็น clip container
  // ใน Flow แต่ละคลิปมักจะอยู่ใน div ที่มีขนาดคล้ายๆ กัน
  const allDivs = document.querySelectorAll('div');

  for (const div of allDivs) {
    const rect = div.getBoundingClientRect();

    // Clip container มักมีขนาดประมาณ 150-400px และอยู่ในส่วนบน
    if (rect.width >= 100 && rect.width <= 500 &&
        rect.height >= 100 && rect.height <= 500 &&
        rect.top < window.innerHeight * 0.8 &&
        rect.top > 0) {

      // ต้องมี video หรือ canvas หรือ img ข้างใน
      const hasMedia = div.querySelector('video, canvas') ||
                       (div.querySelector('img') && div.querySelector('img').width > 50);

      // หรือมี loading indicator
      const hasLoading = div.querySelector('[class*="loading"], [class*="spinner"], [class*="progress"]');

      if (hasMedia || hasLoading) {
        // ตรวจสอบว่าไม่ซ้ำกับที่มีอยู่แล้ว (เช็คจากตำแหน่ง)
        const isDuplicate = containers.some(c => {
          const cRect = c.getBoundingClientRect();
          return Math.abs(cRect.left - rect.left) < 20 &&
                 Math.abs(cRect.top - rect.top) < 20;
        });

        if (!isDuplicate) {
          containers.push(div);
        }
      }
    }
  }

  return containers;
}

// นับ loading indicators (คลิปที่กำลังสร้าง)
// v3.3: parameter excludeBotOverlay — ใช้ true เฉพาะ Story Mode เพื่อไม่ให้นับ overlay ของบอทเป็น loading
// Auto Mode ใช้ default (false) เพื่อไม่เปลี่ยน behavior เดิม
function countLoadingIndicators(excludeBotOverlay = false) {
  let count = 0;

  // v3.3: cache overlay element เพื่อ exclude (เฉพาะเมื่อเปิด flag)
  const botOverlay = excludeBotOverlay ? document.getElementById('pd-bot-overlay') : null;

  // helper: เช็คว่า element อยู่ใน overlay ของบอทหรือไม่
  function isInsideBotOverlay(el) {
    return botOverlay && botOverlay.contains(el);
  }

  // หา loading elements ที่อยู่ในพื้นที่คลิป
  const loadingSelectors = [
    '[class*="loading"]',
    '[class*="spinner"]',
    '[class*="generating"]',
    '[class*="processing"]',
    'svg[class*="circular"]',
    '[class*="progress-circle"]',
    '[class*="Loading"]',
    '[class*="Spinner"]',
    '[class*="Progress"]'
  ];

  for (const selector of loadingSelectors) {
    try {
      const elements = document.querySelectorAll(selector);
      for (const el of elements) {
        if (isInsideBotOverlay(el)) continue; // v3.3: ข้าม overlay ของบอท
        const rect = el.getBoundingClientRect();
        // ต้องมองเห็นได้ + อยู่ในส่วนบน (พื้นที่แสดงคลิป ไม่ใช่ prompt bar)
        if (rect.width > 10 && rect.height > 10 && rect.top < window.innerHeight * 0.85) {
          count++;
        }
      }
    } catch (e) {
      // selector ไม่ valid, skip
    }
  }

  // หา animated circles (มักใช้แสดง progress)
  const circles = document.querySelectorAll('circle');
  for (const circle of circles) {
    if (isInsideBotOverlay(circle)) continue; // v3.3
    const hasAnimation = circle.style.animation ||
                         circle.getAttribute('stroke-dasharray') ||
                         circle.closest('[class*="progress"]');
    if (hasAnimation) {
      const rect = circle.getBoundingClientRect();
      if (rect.top < window.innerHeight * 0.85 && rect.width > 10) {
        count++;
      }
    }
  }

  // v17: หา percentage text (เช่น "50%", "99%") ในพื้นที่แสดงผล
  document.querySelectorAll('span, div').forEach(el => {
    if (isInsideBotOverlay(el)) return; // v3.3
    const t = (el.textContent || '').trim();
    if (/^\d{1,3}%$/.test(t)) {
      const rect = el.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0 && rect.top < window.innerHeight * 0.85) {
        count++;
      }
    }
  });

  // v17: หา aria-busy="true" (modern loading state)
  const busyElements = document.querySelectorAll('[aria-busy="true"]');
  for (const el of busyElements) {
    if (isInsideBotOverlay(el)) continue; // v3.3
    const rect = el.getBoundingClientRect();
    if (rect.width > 10 && rect.top < window.innerHeight * 0.85) {
      count++;
    }
  }

  return count;
}

// Legacy function สำหรับ backward compatibility
function countCompletedVideos() {
  return countAllClipElements();
}

// นับจำนวน loading spinners ที่กำลังแสดง
function countLoadingSpinners() {
  let count = 0;

  // หา loading indicators ทั่วไป
  const loadingClasses = [
    '[class*="loading"]',
    '[class*="spinner"]',
    '[class*="progress"]',
    '[class*="generating"]',
    '[class*="processing"]'
  ];

  for (const selector of loadingClasses) {
    const elements = document.querySelectorAll(selector);
    for (const el of elements) {
      const rect = el.getBoundingClientRect();
      // ต้องมองเห็นได้ + อยู่ในส่วนบนของหน้าจอ (ไม่ใช่ prompt area ด้านล่าง)
      if (rect.width > 20 && rect.height > 20 && rect.top < window.innerHeight * 0.8) {
        count++;
      }
    }
  }

  // หา animated elements (SVG หมุน, CSS animation)
  const animatedElements = document.querySelectorAll('[class*="animate"], [class*="spin"], [class*="pulse"]');
  for (const el of animatedElements) {
    const rect = el.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0 && rect.top < window.innerHeight * 0.8) {
      count++;
    }
  }

  // หา circular progress indicators
  const circles = document.querySelectorAll('circle[stroke-dasharray], svg[class*="circular"]');
  for (const circle of circles) {
    if (circle.offsetParent !== null || (circle.closest('svg') && circle.closest('svg').offsetParent !== null)) {
      count++;
    }
  }

  return count;
}

// หา progress text (ถ้ามี)
function getProgressText() {
  const allText = document.body.innerText;

  // หา % ในข้อความ
  const percentMatch = allText.match(/(\d+)\s*%/);
  if (percentMatch) {
    return percentMatch[0];
  }

  // หาข้อความบอกสถานะ
  const statusTexts = ['กำลังสร้าง', 'Generating', 'Processing', 'Creating', 'กำลังประมวลผล'];
  for (const text of statusTexts) {
    if (allText.includes(text)) {
      return text;
    }
  }

  return '';
}

// หาพื้นที่แสดงผลลัพธ์ (ไม่รวม prompt area)
function findResultArea() {
  // พื้นที่ผลลัพธ์มักอยู่ครึ่งบนของหน้าจอ
  const containers = document.querySelectorAll('div');

  for (const container of containers) {
    const rect = container.getBoundingClientRect();

    // ต้องเป็น container ใหญ่พอที่จะแสดงคลิป
    if (rect.width > 300 && rect.height > 200 && rect.top < window.innerHeight * 0.5) {
      // ต้องมี video หรือ canvas หรือ image ข้างใน
      if (container.querySelector('video, canvas, img')) {
        return container;
      }
    }
  }

  return null;
}

// ตรวจสอบว่ามี error หรือไม่
function checkForErrors() {
  const errorSelectors = [
    '[class*="error"]',
    '[class*="failed"]',
    '[class*="fail"]',
    '[role="alert"]'
  ];

  for (const selector of errorSelectors) {
    const elements = document.querySelectorAll(selector);
    for (const el of elements) {
      if (el.offsetParent !== null) {
        const text = (el.textContent || '').toLowerCase();
        // ตรวจสอบว่าเป็น error จริงๆ ไม่ใช่แค่ชื่อ class
        if (text.includes('error') || text.includes('failed') || text.includes('ผิดพลาด') || text.includes('ล้มเหลว')) {
          return true;
        }
      }
    }
  }

  return false;
}

// Helper Functions

function delay(ms) {
  // v4.4.5: เพิ่ม ±15% jitter เพื่อให้ pattern เวลารอไม่ตายตัว (กัน reCAPTCHA detect ลายเซ็น timing)
  //   ค่าน้อย < 100ms → ไม่ jitter (กัน 0 หรือลบ)
  //   ค่ามาก → jitter ±15% (เช่น 1000ms → 850-1150ms / 5000ms → 4250-5750ms)
  if (!ms || ms < 100) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
  const jitter = (Math.random() * 0.3 - 0.15) * ms; // ±15%
  const actual = Math.max(50, Math.round(ms + jitter));
  return new Promise(resolve => setTimeout(resolve, actual));
}

// delay ที่ปรับตามโหมด (Image mode เร็วกว่า Video mode)
function modeDelay(videoMs, imageMs = null) {
  const ms = currentMode === 'image' ? (imageMs || Math.floor(videoMs * 0.5)) : videoMs;
  return delay(ms);
}

async function waitForElement(selector, timeout = 10000) {
  const startTime = Date.now();
  
  while (Date.now() - startTime < timeout) {
    const element = document.querySelector(selector);
    if (element && element.offsetParent !== null) {
      return element;
    }
    await delay(100);
  }
  
  return null;
}

function findElementBySelector(selectors) {
  for (const selector of selectors) {
    try {
      const element = document.querySelector(selector);
      if (element && element.offsetParent !== null) {
        return element;
      }
    } catch (e) {
      // Invalid selector, skip
    }
  }
  return null;
}

function findElementByText(texts) {
  const allElements = document.querySelectorAll('button, a, div[role="button"], span');

  for (const el of allElements) {
    const text = el.textContent.trim();
    for (const searchText of texts) {
      if (text.includes(searchText) && el.offsetParent !== null) {
        return el;
      }
    }
  }

  return null;
}

// หา container ของ prompt area (บริเวณ input ด้านล่าง)
function findPromptAreaContainer() {
  // v17 วิธี 1: หาจาก role="textbox" contenteditable (Radix prompt input)
  const textbox = document.querySelector('div[role="textbox"][contenteditable="true"]');
  if (textbox) {
    let parent = textbox.parentElement;
    for (let i = 0; i < 10 && parent; i++) {
      const buttons = parent.querySelectorAll('button');
      // prompt container ต้องมีปุ่มอย่างน้อย 2 (+ chip, generate, etc.)
      if (buttons.length >= 2) {
        return parent;
      }
      parent = parent.parentElement;
    }
  }

  // วิธี 2: หาจาก sc-c70e41ad-0 class (styled-component prompt container)
  const scPrompt = document.querySelector('[class*="sc-c70e41ad-0"]');
  if (scPrompt && scPrompt.offsetParent !== null) {
    return scPrompt;
  }

  // วิธี 3: หาจาก contenteditable ที่อยู่ครึ่งล่าง
  const editables = document.querySelectorAll('[contenteditable="true"]');
  for (const ed of editables) {
    const rect = ed.getBoundingClientRect();
    if (rect.top > window.innerHeight * 0.5) {
      let parent = ed.parentElement;
      for (let i = 0; i < 10 && parent; i++) {
        const buttons = parent.querySelectorAll('button');
        if (buttons.length >= 2) {
          return parent;
        }
        parent = parent.parentElement;
      }
    }
  }

  return null;
}

async function setDropdownValue(labelText, value) {
  // Find the dropdown by its label
  const labels = document.querySelectorAll('label, span, div');
  
  for (const label of labels) {
    if (label.textContent.includes(labelText)) {
      // Find nearby select or dropdown
      const parent = label.closest('div');
      if (parent) {
        const select = parent.querySelector('select, [role="listbox"], [class*="dropdown"]');
        if (select) {
          if (select.tagName === 'SELECT') {
            const option = Array.from(select.options).find(opt => opt.text.includes(value));
            if (option) {
              select.value = option.value;
              select.dispatchEvent(new Event('change', { bubbles: true }));
            }
          } else {
            select.click();
            await delay(300);
            
            const options = document.querySelectorAll('[role="option"], [class*="menu-item"], li');
            for (const opt of options) {
              if (opt.textContent.includes(value)) {
                opt.click();
                await delay(200);
                break;
              }
            }
          }
        }
      }
      break;
    }
  }
}

function base64ToFile(base64String, filename) {
  // Remove data URL prefix if present
  const base64Data = base64String.includes(',') 
    ? base64String.split(',')[1] 
    : base64String;
  
  // Get mime type
  const mimeMatch = base64String.match(/data:([^;]+);/);
  const mimeType = mimeMatch ? mimeMatch[1] : 'image/png';
  
  // Convert base64 to blob
  const byteCharacters = atob(base64Data);
  const byteNumbers = new Array(byteCharacters.length);
  
  for (let i = 0; i < byteCharacters.length; i++) {
    byteNumbers[i] = byteCharacters.charCodeAt(i);
  }
  
  const byteArray = new Uint8Array(byteNumbers);
  const blob = new Blob([byteArray], { type: mimeType });
  
  // Create file
  return new File([blob], filename, { type: mimeType });
}

function updateStatus(message, progress = null) {
  console.log('📢 Status:', message, progress ? `(${progress}%)` : '');
  
  chrome.runtime.sendMessage({
    action: 'statusUpdate',
    status: message,
    progress: progress
  });
}

