    // Clear session storage
    sessionStorage.removeItem('extendScenesList');
    sessionStorage.removeItem('extendSceneCurrentIndex');
    sessionStorage.removeItem('extendSceneCount');
    sessionStorage.removeItem('extendVideoModel');

    // แจ้ง popup
    chrome.runtime.sendMessage({
      action: 'extendSceneComplete',
      setIndex: extendSceneSetIndex,
      success: true,
      scenesCompleted: scenesList.length
    });

    hideBotOverlay();
    return; // จบ — ไม่ต้องไป Scenebuilder

    // === OLD CODE (Scenebuilder approach — disabled) ===
