// กดปุ่ม Generate ใน Extend form
// v6.2.1: เพิ่ม retry loop + verification เพราะบางครั้งกดแล้วไม่ trigger
async function clickExtendGenerateButton() {
  console.log('🔍 Looking for Generate button in Extend form...');

  const maxRetries = 5; // ลองสูงสุด 5 ครั้ง

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    console.log(`🔄 [Extend Attempt ${attempt}/${maxRetries}] Looking for Generate button...`);

    // รอก่อนหาปุ่ม (attempt แรกรอ 1 วิ, attempt ถัดไปรอ 1.5 วิ)
    await new Promise(r => setTimeout(r, attempt === 1 ? 1000 : 1500));

    // หาปุ่ม Generate หลายวิธี
    const allButtons = document.querySelectorAll('button');
    let generateBtn = null;

    for (const btn of allButtons) {
      const text = (btn.textContent || '').toLowerCase().trim();
      const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();
      const html = btn.innerHTML || '';

      // หาปุ่มที่มีข้อความ Generate หรือ ส่ง หรือ สร้าง
      const isGenerateBtn =
        text.includes('generate') ||
        text.includes('create') ||
        text.includes('สร้าง') ||
        text.includes('ส่ง') ||
        ariaLabel.includes('generate') ||
        ariaLabel.includes('send') ||
        ariaLabel.includes('submit') ||
        html.includes('>send<') ||
        html.includes('>arrow_upward<');

      if (isGenerateBtn) {
        const rect = btn.getBoundingClientRect();
        // ต้องเห็นได้และไม่ disabled
        if (rect.width > 0 && rect.height > 0 && !btn.disabled) {
          generateBtn = btn;
          break;
        }
      }
    }

    // Fallback: หาปุ่มส่ง (submit) ใกล้ textarea
    if (!generateBtn) {
      const textareas = document.querySelectorAll('textarea');
      for (const textarea of textareas) {
        const parent = textarea.closest('form') || textarea.parentElement?.parentElement;
        if (parent) {
          const submitBtn = parent.querySelector('button[type="submit"], button:last-child');
          if (submitBtn && !submitBtn.disabled) {
            generateBtn = submitBtn;
            break;
          }
        }
      }
    }

    if (generateBtn) {
      const text = (generateBtn.textContent || '').toLowerCase().trim();
      console.log(`✅ [Attempt ${attempt}] Found Generate button: "${text}"`);

      // v6.2.1: เช็คว่าปุ่ม disabled หรือ aria-disabled
      if (generateBtn.disabled || generateBtn.getAttribute('aria-disabled') === 'true') {
        console.log(`⚠️ [Attempt ${attempt}] Generate button is disabled, retrying...`);
        continue;
      }

      // v4.3: MAIN world click (default) → fallback CDP → fallback .click()
      window._flowGenerateFailed = null;
      const rect = generateBtn.getBoundingClientRect();
      const cx = Math.round(rect.left + rect.width / 2);
      const cy = Math.round(rect.top + rect.height / 2);

      // อ่าน toggle: ถ้าเปิด force CDP → skip MAIN
      const forceLegacy = await new Promise(resolve => {
        try {
          chrome.storage.local.get(['forceLegacyClickEnabled'], (r) => resolve(!!(r && r.forceLegacyClickEnabled)));
        } catch (e) { resolve(false); }
      });

      let clickOk = false;

      // === MAIN world click (default) ===
      if (!forceLegacy) {
        try {
          const requestId = Date.now() + Math.random();
          const mainResult = await new Promise((resolve) => {
            const handler = (e) => {
              if (e.detail && e.detail.requestId === requestId) {
                window.removeEventListener('__flow_main_click_result__', handler);
                resolve(e.detail);
              }
            };
            window.addEventListener('__flow_main_click_result__', handler);
            window.dispatchEvent(new CustomEvent('__flow_main_click__', { detail: { x: cx, y: cy, requestId } }));
            setTimeout(() => {
              window.removeEventListener('__flow_main_click_result__', handler);
              resolve({ success: false, error: 'timeout' });
            }, 3000);
          });
          if (mainResult.success) {
            console.log(`✅ [Attempt ${attempt}] MAIN world click work via ${mainResult.method} — ไม่มี yellow bar`);
            clickOk = true;
          } else {
            console.warn(`⚠️ [Attempt ${attempt}] MAIN click failed: ${mainResult.error} — fallback CDP`);
          }
        } catch (mainErr) {
          console.warn(`⚠️ [Attempt ${attempt}] MAIN exception: ${mainErr.message} — fallback CDP`);
        }
      }

      // === CDP click (fallback / force legacy) ===
      if (!clickOk) {
        try {
          console.log(`[CDP] กำลังคลิกผ่าน chrome.debugger ที่ (${cx}, ${cy})...`);
          const cdpResult = await new Promise((resolve) => {
            chrome.runtime.sendMessage({ action: 'cdpClick', x: cx, y: cy }, (response) => {
              resolve(response || { success: false, error: 'no response' });
            });
          });
          if (cdpResult.success) {
            console.log(`✅ [Attempt ${attempt}] CDP click ส่งสำเร็จ`);
            clickOk = true;
          } else {
            console.warn(`⚠️ [Attempt ${attempt}] CDP click failed: ${cdpResult.error} — fallback to .click()`);
          }
        } catch (cdpErr) {
          console.warn(`⚠️ [Attempt ${attempt}] CDP exception: ${cdpErr.message} — fallback to .click()`);
        }
      }

      // === Last resort: .click() ===
      if (!clickOk) {
        generateBtn.click();
      }
      await new Promise(r => setTimeout(r, 500));

      // v6.2.1: Verify ว่ากดสำเร็จจริง
      const hasProgress = await verifyExtendGenerateClicked();
      if (hasProgress) {
        console.log(`✅ [Attempt ${attempt}] Generate button clicked successfully!`);
        return { success: true, message: 'Clicked Generate button' };
      } else {
        console.log(`⚠️ [Attempt ${attempt}] Click didn't trigger generation, retrying...`);
        continue;
      }
    }

    console.log(`⚠️ [Attempt ${attempt}] Generate button not found, will retry...`);
  }

  console.log('❌ Generate button not found after all retry attempts');
  return { success: false, error: 'ไม่พบปุ่ม Generate - กรุณากดเอง' };
}

// v6.2.1: ตรวจสอบว่าการกด Generate ใน Extend form สำเร็จหรือไม่
async function verifyExtendGenerateClicked() {
  await new Promise(r => setTimeout(r, 500));

  // วิธีที่ 1: เช็คว่ามี loading spinner/progress
  const loadingIndicators = document.querySelectorAll(
    '[class*="loading"], [class*="progress"], [class*="spinner"], ' +
    '[class*="generating"], [aria-busy="true"], [role="progressbar"]'
  );
  if (loadingIndicators.length > 0) {
    console.log('✅ [Extend] Detected loading indicator after click');
    return true;
  }

  // วิธีที่ 2: เช็คว่า prompt field ถูก disabled
  const promptField = document.querySelector('textarea');
  if (promptField && (promptField.disabled || promptField.readOnly)) {
    console.log('✅ [Extend] Prompt field is now disabled (generating)');
    return true;
  }

  // วิธีที่ 3: เช็คว่ามี "Generating" text ปรากฏ
  const bodyText = document.body.innerText || '';
  if (bodyText.includes('Generating') || bodyText.includes('Creating') || bodyText.includes('กำลังสร้าง')) {
    console.log('✅ [Extend] Detected "Generating" text on page');
    return true;
  }

  // วิธีที่ 4: ถ้า overlay เปลี่ยนเป็น "กำลังสร้างฉาก" ก็ถือว่าสำเร็จ
  const overlay = document.getElementById('veo-bot-overlay');
  if (overlay && overlay.textContent.includes('กำลังสร้าง')) {
    console.log('✅ [Extend] Overlay shows generating status');
    return true;
  }

  console.log('⚠️ [Extend] No clear indication that generation started');
  return false;
}

// ==================== POST EXTEND SCENE - EXPORT & CLEANUP ====================

// v12: ทดสอบ Export Retry Flow โดยตรง (เรียกจากปุ่มทดสอบใน Settings)
async function testExportRetryFlow() {
  console.log('🧪 [v12] เริ่มทดสอบ Export Retry Flow...');
  updateBotOverlay('ทดสอบ Export Retry...', 'กำลังทดสอบ');

  // v13.4: เพิ่มจาก 5 เป็น 10 ครั้ง (2 เท่า)
  const MAX_EXPORT_RETRIES = 10;
  let exportSuccess = false;
  let exportAttempt = 0;

  while (!exportSuccess && exportAttempt < MAX_EXPORT_RETRIES) {
    exportAttempt++;
    console.log(`📦 [Test] กด Export... (ครั้งที่ ${exportAttempt}/${MAX_EXPORT_RETRIES})`);
    updateBotOverlay(`กด Export (${exportAttempt}/${MAX_EXPORT_RETRIES})`, 'ทดสอบ Export Retry');

    // v12: รอหาปุ่ม Export (retry 15 วินาที) เพราะ UI อาจยังไม่กลับมาหลัง failed
    let exportResult = null;
    let findButtonAttempt = 0;
    const maxFindAttempts = 15; // รอสูงสุด 15 วินาที

    while (findButtonAttempt < maxFindAttempts) {
      exportResult = await clickExportButton();
      if (exportResult.success) break;

      findButtonAttempt++;
      console.log(`⏳ [Test] หาปุ่ม Export... (${findButtonAttempt}/${maxFindAttempts})`);
      updateBotOverlay(`หาปุ่ม Export...`, `รอ ${findButtonAttempt}/${maxFindAttempts} วินาที`);
      await new Promise(r => setTimeout(r, 1000));
    }

    if (!exportResult?.success) {
      console.log('❌ [Test] ไม่พบปุ่ม Export หลังรอ 15 วินาที');
      return { success: false, attempts: exportAttempt, error: 'ไม่พบปุ่ม Export หลังรอ 15 วินาที' };
    }
    console.log('✅ [Test] กด Export แล้ว - รอผล...');

    // รอ Export เสร็จ (ใช้ timeout 120 วินาที)
    console.log(`⏳ [Test] รอ Export เสร็จ... (timeout 120 วินาที)`);
    updateBotOverlay(`รอ Export เสร็จ...`, `ครั้งที่ ${exportAttempt}/${MAX_EXPORT_RETRIES}`);

    const waitExportResult = await waitForExportComplete();

    if (waitExportResult.success) {
      console.log('✅ [Test] Export สำเร็จ!');
      exportSuccess = true;

      // ลอง Download
      console.log('💾 [Test] กำลังหาปุ่ม Download...');
      updateBotOverlay('หาปุ่ม Download...', 'Export สำเร็จ');

      const downloadResult = await findAndClickDownloadButton();
      if (downloadResult.success) {
        console.log('✅ [Test] กด Download แล้ว!');

        // รอให้ไฟล์ดาวน์โหลดเสร็จ
        console.log('⏳ [Test] รอไฟล์ดาวน์โหลด 5 วินาที...');
        updateBotOverlay('รอดาวน์โหลดเสร็จ...', '5 วินาที');
        await new Promise(r => setTimeout(r, 5000));

        // ลบคลิปทั้งหมด
        console.log('🗑️ [Test] ลบคลิปทั้งหมด...');
        updateBotOverlay('ลบคลิป...', 'เคลียร์ Scenebuilder');
        await deleteAllSceneClipsUntilEmpty();

        // รอสักครู่
        await new Promise(r => setTimeout(r, 2000));

        // กลับหน้าหลัก
        console.log('🔙 [Test] กลับหน้าหลัก...');
        updateBotOverlay('กลับหน้าหลัก...', 'เสร็จสิ้น');
        const backResult = await goBackToFlow();

        if (backResult.success) {
          console.log('✅ [Test] กลับหน้าหลักสำเร็จ!');
        } else {
          console.log('⚠️ [Test] กลับหน้าหลักไม่สำเร็จ:', backResult.error);
        }

        // รอแล้วซ่อน overlay
        await new Promise(r => setTimeout(r, 2000));
        hideBotOverlay();

        return { success: true, attempts: exportAttempt, downloadTriggered: true, cleanup: true };
      } else {
        console.log('⚠️ [Test] ไม่พบปุ่ม Download:', downloadResult.error);
        hideBotOverlay();
        return { success: true, attempts: exportAttempt, downloadTriggered: false, downloadError: downloadResult.error };
      }
    } else if (waitExportResult.failed) {
      // Export failed! - ลอง retry
      console.log(`❌ [Test] Export failed! (ครั้งที่ ${exportAttempt}/${MAX_EXPORT_RETRIES})`);
      updateBotOverlay(`Export failed!`, `retry ${exportAttempt + 1}/${MAX_EXPORT_RETRIES}...`);

      if (exportAttempt < MAX_EXPORT_RETRIES) {
        // v12: รอให้ "Export failed" popup หายก่อน retry (สูงสุด 30 วินาที)
        console.log('🔄 [Test] รอ popup "Export failed" หายก่อน retry...');
        let waitCount = 0;
        while (waitCount < 30) {
          await new Promise(r => setTimeout(r, 1000));
          waitCount++;
          const bodyText = document.body.innerText || '';
          if (!bodyText.includes('Export failed')) {
            console.log(`✅ [Test] Export failed popup หายแล้ว (${waitCount} วินาที)`);
            break;
          }
          console.log(`⏳ [Test] รอ popup หาย... (${waitCount}/30)`);
          updateBotOverlay('รอ popup หาย...', `${waitCount}/30 วินาที`);
        }
      }
    } else {
      // Timeout
      console.log(`⚠️ [Test] Export timeout (ครั้งที่ ${exportAttempt}/${MAX_EXPORT_RETRIES})`);
      updateBotOverlay(`Export timeout`, `retry ${exportAttempt + 1}/${MAX_EXPORT_RETRIES}...`);

      if (exportAttempt < MAX_EXPORT_RETRIES) {
        console.log('🔄 [Test] รอ 3 วินาที แล้ว retry...');
        await new Promise(r => setTimeout(r, 3000));
      }
    }
  }

  if (!exportSuccess) {
    console.log(`❌ [Test] Export ไม่สำเร็จหลัง ${MAX_EXPORT_RETRIES} ครั้ง`);
    updateBotOverlay('Export ไม่สำเร็จ', `ล้มเหลว ${MAX_EXPORT_RETRIES} ครั้ง - เคลียร์หน้า`);

    // v12: เคลียร์หน้าแล้วออกไปเหมือน flow จริง
    console.log('🗑️ [Test] Export ล้มเหลว - ลบคลิปทั้งหมด...');
    await deleteAllSceneClipsUntilEmpty();

    // รอสักครู่
    await new Promise(r => setTimeout(r, 2000));

    // กลับหน้าหลัก
    console.log('🔙 [Test] กลับหน้าหลัก...');
    updateBotOverlay('กลับหน้าหลัก...', 'Export ล้มเหลว');
    const backResult = await goBackToFlow();

    if (backResult.success) {
      console.log('✅ [Test] กลับหน้าหลักสำเร็จ!');
    } else {
      console.log('⚠️ [Test] กลับหน้าหลักไม่สำเร็จ:', backResult.error);
    }

    // รอแล้วซ่อน overlay
    await new Promise(r => setTimeout(r, 2000));
    hideBotOverlay();

    return { success: false, attempts: exportAttempt, error: `Export failed after ${MAX_EXPORT_RETRIES} retries`, cleanup: true };
  }

  return { success: exportSuccess, attempts: exportAttempt };
}

// v12: หาและกด Download (หลัง Export สำเร็จ)
// ปุ่ม Download จริงๆ เป็น <a target="_blank" class="sc-xxx">Download</a>
async function findAndClickDownloadButton() {
  console.log('🔍 [v12] หา Download link...');

  // รอให้ Download link ปรากฏ (retry 30 วินาที)
  const maxWait = 30000;
  const checkInterval = 1000;
  let waited = 0;

  while (waited < maxWait) {
    // วิธี 1: หา <a> tag ที่มี text "Download" (จาก popup "Video exported!")
    const allLinks = document.querySelectorAll('a');
    for (const link of allLinks) {
      const text = link.textContent.trim();
      if (text === 'Download') {
        console.log('✅ [v12] พบ Download link (<a> text="Download") - กด!');
        link.click();
        return { success: true };
      }
    }

    // วิธี 2: หา <a> tag ที่มี class เริ่มต้นด้วย "sc-" และมี text Download
    for (const link of allLinks) {
      const className = link.className || '';
      const text = link.textContent.trim();
      if (className.startsWith('sc-') && text.toLowerCase().includes('download')) {
        console.log('✅ [v12] พบ Download link (styled-component) - กด!');
        link.click();
        return { success: true };
      }
    }

    // วิธี 3: หา <a> tag ที่มี download attribute หรือ blob href (fallback)
    const downloadLinks = document.querySelectorAll('a[download], a[href*="blob"]');
    if (downloadLinks.length > 0) {
      console.log('✅ [v12] พบ Download link (attribute) - กด!');
      downloadLinks[0].click();
      return { success: true };
    }

    await new Promise(r => setTimeout(r, checkInterval));
    waited += checkInterval;
    console.log(`⏳ [v12] รอ Download link... (${waited / 1000}s)`);
  }

  return { success: false, error: 'ไม่พบ Download link หลัง 30 วินาที' };
}

// Step 7: กดปุ่ม Export (รวมคลิป) - ไอคอน download ขวาล่าง
async function clickExportButton() {
  console.log('🔍 Looking for Export button...');

  await new Promise(r => setTimeout(r, 500));

  // หาปุ่ม export/download ใน timeline area (ขวาล่าง)
  const allButtons = document.querySelectorAll('button');

  for (const btn of allButtons) {
    const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();
    const html = btn.innerHTML || '';
    const rect = btn.getBoundingClientRect();

    // หาปุ่มที่มี icon download หรือ export
    const isExportBtn =
      ariaLabel.includes('export') ||
      ariaLabel.includes('download') ||
      ariaLabel.includes('render') ||
      html.includes('download') ||
      html.includes('file_download') ||
      html.includes('save_alt');

    // ต้องอยู่บริเวณขวาล่าง (x > 1000, y > 500)
    if (isExportBtn && rect.width > 0 && rect.height > 0 && !btn.disabled) {
      console.log(`✅ Found Export button at (${rect.x}, ${rect.y})`);
      btn.click();
      return { success: true, message: 'Clicked Export button' };
    }
  }

  // Fallback: หาจาก icon SVG path
  const svgButtons = document.querySelectorAll('button svg, button [class*="icon"]');
  for (const svg of svgButtons) {
    const btn = svg.closest('button');
    if (btn && !btn.disabled) {
      const rect = btn.getBoundingClientRect();
      // ปุ่มอยู่ขวาล่าง ใกล้ timeline
      if (rect.x > 1100 && rect.y > 600) {
        console.log('✅ Found Export button by position (bottom-right)');
        btn.click();
        return { success: true, message: 'Clicked Export button (by position)' };
      }
    }
  }

  console.log('❌ Export button not found');
  return { success: false, error: 'ไม่พบปุ่ม Export' };
}

// Step 8: รอ Export เสร็จ (หา "Video exported!" หรือ "Export failed!")
// v12: รอ 3 วินาทีก่อนเริ่มเช็ค เพื่อให้ Export process เริ่มต้น
// v11.0: เพิ่มการตรวจจับ "Export failed!"
async function waitForExportComplete(timeoutMs = 600000) {
  console.log('⏳ Waiting for export to complete... (timeout:', timeoutMs / 1000, 's)');

  // v12: รอ 3 วินาทีก่อนเริ่มเช็ค (ให้ export process เริ่มต้น)
  console.log('⏳ รอ 3 วินาทีให้ export เริ่ม...');
  await new Promise(r => setTimeout(r, 3000));

  const startTime = Date.now();
  let lastLog = 0;

  while (Date.now() - startTime < timeoutMs) {
    const allText = document.body.innerText;

    // v12: เช็ค failed ก่อน (เพราะถ้า failed ต้อง retry)
    if (allText.includes('Export failed') || allText.includes('export failed') || allText.includes('Export failed!')) {
      console.log('❌ Export failed detected via innerText!');
      return { success: false, failed: true, error: 'Export failed' };
    }

    // v9.2: หา popup "Export failed!" โดยตรง (styled-components class)
    const allDivs = document.querySelectorAll('div');
    for (const div of allDivs) {
      const text = (div.textContent || '').trim();
      if (text === 'Export failed!' || text === 'Export failed') {
        console.log('❌ Export failed detected via div element!');
        return { success: false, failed: true, error: 'Export failed' };
      }
    }

    // v9.1: หา popup โดย class อื่นๆ (fallback)
    const failedPopup = document.querySelector('[class*="snack"], [class*="toast"], [class*="alert"], [role="alert"]');
    if (failedPopup) {
      const popupText = failedPopup.textContent || '';
      if (popupText.includes('failed') || popupText.includes('Failed')) {
        console.log('❌ Export failed detected via popup element!');
        return { success: false, failed: true, error: 'Export failed' };
      }
    }

    // v12: เช็ค success จากข้อความ "Video exported!" หรือ Download link
    let foundSuccess = false;

    // วิธี 1: หา <a> tag ที่มี text "Download" (popup สำเร็จจะมี link นี้)
    const allLinks = document.querySelectorAll('a');
    for (const link of allLinks) {
      const text = link.textContent.trim();
      if (text === 'Download') {
        console.log('✅ Export completed! (found Download link)');
        foundSuccess = true;
        break;
      }
    }

    // วิธี 2: หา element ที่มีข้อความ "Video exported!"
    if (!foundSuccess) {
      const successTexts = ['Video exported!', 'Video exported', 'Export complete'];
      const allElements = document.querySelectorAll('div, span, p');
      for (const el of allElements) {
        const text = (el.textContent || '').trim();
        if (successTexts.some(s => text === s || text.startsWith(s))) {
          console.log('✅ Export completed! (found text:', text, ')');
          foundSuccess = true;
          break;
        }
      }
    }

    if (foundSuccess) {
      return { success: true, message: 'Export completed' };
    }

    // Log ทุก 5 วินาที (ไม่ spam)
    if (Date.now() - lastLog > 5000) {
      console.log('⏳ Still waiting for export...');
      lastLog = Date.now();
    }

    await new Promise(r => setTimeout(r, 500));
  }

  console.log('⚠️ Export timeout');
  return { success: false, error: 'Export timeout' };
}

// v5.9.3: ดึง Video Base64 + ควบคุม Download ให้เกิดครั้งเดียว
// วิธีการ:
// 1. ตั้ง click interceptor ก่อนกด Download button
// 2. เมื่อหน้าเว็บสร้าง <a href="blob:..." download="..."> และ click มัน
// 3. Interceptor จะ preventDefault() ไม่ให้ download อัตโนมัติ
// 4. Fetch blob มาเก็บไว้
// 5. Trigger download เอง 1 ครั้ง (ควบคุมได้)
async function getExportedVideoBase64() {
  console.log('📥 [v16.3] Getting exported video - Enhanced Interceptor Method...');

  return new Promise((resolve) => {
    let resolved = false;
    let observer = null;
    let clickInterceptor = null;
    let capturedBlobUrl = null;
    let capturedFilename = null;
    let pageInterceptorListener = null;

    // Cleanup function
    const cleanup = () => {
      if (observer) {
        observer.disconnect();
        observer = null;
      }
      if (clickInterceptor) {
        document.removeEventListener('click', clickInterceptor, true);
        clickInterceptor = null;
      }
      if (pageInterceptorListener) {
        window.removeEventListener('pd-video-captured', pageInterceptorListener);
        pageInterceptorListener = null;
      }
      // Restore original createElement ใน page context
      try {
        const restoreScript = document.createElement('script');
        restoreScript.textContent = `
          if (window._pdOrigCreateElement) {
            document.createElement = window._pdOrigCreateElement;
            delete window._pdOrigCreateElement;
            delete window._pdVideoCapture;
            console.log('[PD v16.3] Restored original createElement');
          }
        `;
        document.documentElement.appendChild(restoreScript);
        restoreScript.remove();
      } catch (e) { }
    };

    // ฟังก์ชัน trigger download จาก URL (ควบคุมได้)
    const triggerSingleDownload = (url, filename) => {
      console.log('💾 [v16.3] Triggering single download...');
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      a.style.display = 'none';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      console.log('✅ [v16.3] Download triggered once!');
    };

    // v16.3: Inject createElement interceptor เข้า page context
    // จับ <a> element ที่มี href เป็น data:video/mp4 (ไฟล์ final ที่ตัดต่อแล้ว)
    const injectScript = document.createElement('script');
    injectScript.textContent = `
      (function() {
        if (window._pdOrigCreateElement) return; // inject แล้ว
        window._pdOrigCreateElement = document.createElement.bind(document);
        window._pdVideoCapture = { ready: false, dataUrl: null, filename: null };

        document.createElement = function(tag) {
          const el = window._pdOrigCreateElement(tag);
          if (tag.toLowerCase() === 'a') {
            const origClick = el.click.bind(el);
            el.click = function() {
              // จับ data:video/mp4 (ไฟล์ final ที่ export แล้ว)
              if (el.href && el.href.startsWith('data:video/mp4')) {
                console.log('[PD v16.3] 🎯 CAPTURED final video data URL! filename:', el.download, 'size:', el.href.length);
                window._pdVideoCapture = {
                  ready: true,
                  dataUrl: el.href,
                  filename: el.download || 'exported_video.mp4'
                };
                // แจ้ง content script ผ่าน CustomEvent
                window.dispatchEvent(new CustomEvent('pd-video-captured', {
                  detail: { filename: el.download || 'exported_video.mp4', size: el.href.length }
                }));
              }
              // จับ blob: URL ด้วย (เผื่อ Google เปลี่ยนวิธี)
              if (el.href && el.href.startsWith('blob:')) {
                console.log('[PD v16.3] 🎯 CAPTURED blob video URL! filename:', el.download);
                window.dispatchEvent(new CustomEvent('pd-video-blob-captured', {
                  detail: { blobUrl: el.href, filename: el.download || 'exported_video.mp4' }
                }));
              }
              return origClick();
            };
          }
          return el;
        };
        console.log('[PD v16.3] createElement interceptor injected');
      })();
    `;
    document.documentElement.appendChild(injectScript);
    injectScript.remove();
    console.log('🛡️ [v16.3] Page-level createElement interceptor injected');

    // ฟังก์ชันจัดการ data URL ที่จับได้จาก page context
    const handleCapturedDataUrl = async () => {
      if (resolved) return;

      // ดึง data URL จาก page context
      const extractScript = document.createElement('script');
      extractScript.textContent = `
        if (window._pdVideoCapture && window._pdVideoCapture.ready) {
          document.dispatchEvent(new CustomEvent('pd-video-data-ready', {
            detail: JSON.stringify({
              dataUrl: window._pdVideoCapture.dataUrl,
              filename: window._pdVideoCapture.filename
            })
          }));
        }
      `;
      document.documentElement.appendChild(extractScript);
      extractScript.remove();
    };

    // Listen สำหรับ data URL จาก page context
    const dataReadyHandler = async (e) => {
      if (resolved) return;
      resolved = true;

      document.removeEventListener('pd-video-data-ready', dataReadyHandler);

      try {
        const data = JSON.parse(e.detail);
        console.log(`🎯 [v16.3] Got final video data URL! filename: ${data.filename}, size: ${data.dataUrl.length} chars`);

        // แปลง data URL เป็น base64
        const base64 = data.dataUrl.split(',')[1];
        const binaryLen = Math.round(base64.length * 3 / 4);
        console.log(`✅ [v16.3] Final video base64 extracted! ~${Math.round(binaryLen / 1024)} KB`);

        // Trigger download ด้วย (ดาวน์โหลดลงเครื่อง)
        triggerSingleDownload(data.dataUrl, data.filename);

        cleanup();
        resolve({
          success: true,
          base64: base64,
          size: binaryLen,
          filename: data.filename,
          mimeType: 'video/mp4',
          isFinalExport: true // v16.3: flag ว่าเป็นไฟล์ final (ตัดต่อแล้ว)
        });
      } catch (err) {
        console.error('[v16.3] Error processing captured data URL:', err);
        cleanup();
        resolve({ success: false, error: err.message });
      }
    };
    document.addEventListener('pd-video-data-ready', dataReadyHandler);

    // Listen สำหรับ signal จาก page interceptor (data:video/mp4 captured)
    pageInterceptorListener = (e) => {
      console.log(`🎯 [v16.3] Video captured signal! filename: ${e.detail?.filename}, size: ${e.detail?.size}`);
      // รอ 500ms แล้วดึง data URL ออกมา
      setTimeout(() => handleCapturedDataUrl(), 500);
    };
    window.addEventListener('pd-video-captured', pageInterceptorListener);

    // Listen สำหรับ blob URL captured (fallback กรณี Google ใช้ blob แทน data URL)
    const blobCapturedHandler = async (e) => {
      if (resolved) return;
      const { blobUrl, filename } = e.detail || {};
      if (!blobUrl) return;

      console.log(`🎯 [v16.3] Blob video captured! URL: ${blobUrl}`);
      capturedBlobUrl = blobUrl;
      capturedFilename = filename || `extended_clip_${Date.now()}.mp4`;

      // ลอง fetch blob
      try {
        const response = await fetch(blobUrl);
        const blob = await response.blob();
        const base64 = await blobToBase64(blob);
        console.log(`✅ [v16.3] Blob video fetched! ${Math.round(blob.size / 1024)} KB`);

        if (!resolved) {
          resolved = true;
          cleanup();
          window.removeEventListener('pd-video-blob-captured', blobCapturedHandler);
          resolve({
            success: true,
            base64: base64,
            size: blob.size,
            filename: capturedFilename,
            mimeType: blob.type || 'video/mp4',
            isFinalExport: true
          });
        }
      } catch (err) {
        console.log(`⚠️ [v16.3] Blob fetch failed:`, err.message);
      }
    };
    window.addEventListener('pd-video-blob-captured', blobCapturedHandler);

    // Click interceptor (เดิม) - จับ click บน <a download> ที่ content script เห็น
    clickInterceptor = (e) => {
      const target = e.target.closest('a[download]');
      if (!target) return;

      const href = target.href;
      if (!href) return;

      if (href.startsWith('blob:') || href.startsWith('data:video')) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();

        console.log(`🛑 [v16.3] Intercepted download click! type: ${href.startsWith('blob:') ? 'blob' : 'data'}`);

        if (href.startsWith('data:video')) {
          // data URL → ดึง base64 ตรงๆ
          if (!resolved) {
            resolved = true;
            cleanup();
            window.removeEventListener('pd-video-blob-captured', blobCapturedHandler);

            const base64 = href.split(',')[1];
            const binaryLen = Math.round(base64.length * 3 / 4);
            const filename = target.download || `exported_video_${Date.now()}.mp4`;

            triggerSingleDownload(href, filename);

            resolve({
              success: true,
              base64: base64,
              size: binaryLen,
              filename: filename,
              mimeType: 'video/mp4',
              isFinalExport: true
            });
          }
        } else {
          // blob URL
          capturedBlobUrl = href;
          capturedFilename = target.download || `extended_clip_${Date.now()}.mp4`;
          handleCapturedBlobLegacy();
        }
      }
    };

    // Legacy blob handler (เดิม)
    const handleCapturedBlobLegacy = async () => {
      if (resolved || !capturedBlobUrl) return;
      resolved = true;
      cleanup();
      window.removeEventListener('pd-video-blob-captured', blobCapturedHandler);

      console.log('🎯 [v16.3] Processing captured blob (legacy):', capturedBlobUrl);

      try {
        const response = await fetch(capturedBlobUrl);
        const blob = await response.blob();
        const base64 = await blobToBase64(blob);
        console.log(`✅ [v16.3] Got video base64! Size: ${Math.round(blob.size / 1024)} KB`);

        triggerSingleDownload(capturedBlobUrl, capturedFilename);

        resolve({
          success: true,
          base64: base64,
          size: blob.size,
          filename: capturedFilename,
          mimeType: blob.type || 'video/mp4'
        });
      } catch (e) {
        console.log('❌ [v16.3] Failed to fetch blob:', e.message);
        if (capturedBlobUrl) {
          triggerSingleDownload(capturedBlobUrl, capturedFilename);
        }
        resolve({ success: false, error: e.message });
      }
    };

    // MutationObserver จับ <a download> element (เดิม + เพิ่ม data URL)
    observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        for (const node of mutation.addedNodes) {
          if (node.nodeType === Node.ELEMENT_NODE) {
            const checkAnchor = (anchor) => {
              const href = anchor.href;
              if (href && (href.startsWith('blob:') || href.startsWith('data:video'))) {
                console.log(`👀 [v16.3] Detected download anchor: ${href.substring(0, 80)}...`);
                if (!capturedBlobUrl) {
                  capturedBlobUrl = href;
                  capturedFilename = anchor.download || `extended_clip_${Date.now()}.mp4`;
                }
              }
            };
            if (node.tagName === 'A' && node.hasAttribute('download')) {
              checkAnchor(node);
            }
            const anchors = node.querySelectorAll ? node.querySelectorAll('a[download]') : [];
            for (const anchor of anchors) {
              checkAnchor(anchor);
            }
          }
        }
      }
    });

    document.addEventListener('click', clickInterceptor, true);
    console.log('🛡️ [v16.3] Click interceptor registered');

    observer.observe(document.body, { childList: true, subtree: true });
    console.log('👀 [v16.3] MutationObserver started');

    // หา Download button แบบ retry (รอสูงสุด 30 วินาที)
    const findAndClickDownload = async () => {
      const MAX_RETRIES = 30;

      for (let retry = 0; retry < MAX_RETRIES; retry++) {
        if (resolved) return;

        await new Promise(r => setTimeout(r, 1000));

        const allElements = document.querySelectorAll('a, button, [role="button"]');
        let downloadBtn = null;

        for (const el of allElements) {
          const text = (el.textContent || '').trim().toLowerCase();
          const rect = el.getBoundingClientRect();
          if (text === 'download' && rect.width > 0 && rect.height > 0) {
            downloadBtn = el;
            break;
          }
        }

        if (downloadBtn) {
          console.log(`✅ [v16.3] Found Download button after ${retry + 1} seconds`);
          downloadBtn.click();
          return;
        }

        if ((retry + 1) % 5 === 0) {
          console.log(`⏳ [v16.3] Still waiting for Download button... (${retry + 1}/${MAX_RETRIES}s)`);
        }
      }

      if (!resolved) {
        resolved = true;
        cleanup();
        window.removeEventListener('pd-video-blob-captured', blobCapturedHandler);
        console.log('❌ [v16.3] Download button not found after 30 seconds');
        resolve({ success: false, error: 'ไม่พบ Download button หลังจากรอ 30 วินาที' });
      }
    };

    findAndClickDownload();

    // Timeout 60 วิ (เพิ่มจาก 30 เพราะ export multi-scene อาจนาน)
    setTimeout(() => {
      if (!resolved && capturedBlobUrl) {
        console.log('⏰ [v16.3] Timeout but have captured URL, processing...');
        if (capturedBlobUrl.startsWith('data:video')) {
          const base64 = capturedBlobUrl.split(',')[1];
          resolved = true;
          cleanup();
          window.removeEventListener('pd-video-blob-captured', blobCapturedHandler);
          resolve({
            success: true,
            base64: base64,
            size: Math.round(base64.length * 3 / 4),
            filename: capturedFilename || 'exported_video.mp4',
            mimeType: 'video/mp4',
            isFinalExport: true
          });
        } else {
          handleCapturedBlobLegacy();
        }
      } else if (!resolved) {
        // v16.3: Last resort — ลองดึงจาก page context variable ตรงๆ
        console.log('⏰ [v16.3] Timeout - trying last resort page context check...');
        handleCapturedDataUrl();

        // ถ้ายังไม่ได้ หลัง 2 วินาที → give up
        setTimeout(() => {
          if (!resolved) {
            resolved = true;
            cleanup();
            window.removeEventListener('pd-video-blob-captured', blobCapturedHandler);
            console.log('⚠️ [v16.3] Timeout 60s - video not captured');
            resolve({ success: false, error: 'Timeout 60s - video ไม่ถูก capture' });
          }
        }, 2000);
      }
    }, 60000);
  });
}

// Helper: แปลง Blob เป็น Base64
async function blobToBase64(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64Data = reader.result.split(',')[1];
      resolve(base64Data);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

// === v16.3: IndexedDB helpers for large video storage (รองรับ 100MB+) ===
// v4.2.2: var แทน const — กัน redeclaration error
var VIDEO_IDB_NAME = 'pd-auto-flow-video';
var VIDEO_IDB_STORE = 'videos';
var VIDEO_IDB_KEY = 'final-export';

function openVideoIDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(VIDEO_IDB_NAME, 1);
    request.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(VIDEO_IDB_STORE)) {
        db.createObjectStore(VIDEO_IDB_STORE);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function saveVideoToIDB(base64, filename, isFinalExport) {
  const db = await openVideoIDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(VIDEO_IDB_STORE, 'readwrite');
    const store = tx.objectStore(VIDEO_IDB_STORE);
    store.put({ base64, filename, isFinalExport, savedAt: Date.now() }, VIDEO_IDB_KEY);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { db.close(); reject(tx.error); };
  });
}

async function getVideoFromIDB() {
  const db = await openVideoIDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(VIDEO_IDB_STORE, 'readonly');
    const store = tx.objectStore(VIDEO_IDB_STORE);
    const request = store.get(VIDEO_IDB_KEY);
    request.onsuccess = () => { db.close(); resolve(request.result || null); };
    request.onerror = () => { db.close(); reject(request.error); };
  });
}

async function deleteVideoFromIDB() {
  const db = await openVideoIDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(VIDEO_IDB_STORE, 'readwrite');
    const store = tx.objectStore(VIDEO_IDB_STORE);
    store.delete(VIDEO_IDB_KEY);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { db.close(); reject(tx.error); };
  });
}

// v16.3: Send video chunks from content→popup (รองรับไฟล์ใหญ่ 60MB+)
async function sendVideoChunksToPopup(base64, filename) {
  const CHUNK_SIZE = 8 * 1024 * 1024; // 8MB per chunk (safe for Chrome message limit)
  const totalChunks = Math.ceil(base64.length / CHUNK_SIZE);

  console.log(`📤 [v16.3] Sending video to popup: ${Math.round(base64.length / 1024)} KB in ${totalChunks} chunks`);

  chrome.runtime.sendMessage({
    action: 'videoFromContent_start',
    totalChunks,
    totalSize: base64.length,
    filename
  });

  for (let i = 0; i < totalChunks; i++) {
    const chunk = base64.substring(i * CHUNK_SIZE, (i + 1) * CHUNK_SIZE);
    chrome.runtime.sendMessage({
      action: 'videoFromContent_chunk',
      chunkIndex: i,
      data: chunk
    });
    // Small delay between chunks to avoid overwhelming message queue
    await new Promise(r => setTimeout(r, 50));
  }

  chrome.runtime.sendMessage({ action: 'videoFromContent_end' });
  console.log(`✅ [v16.3] All ${totalChunks} chunks sent to popup`);
}

// Step 9: กดปุ่ม Download (link สีฟ้าในกล่อง notification)
async function clickDownloadLink() {
  console.log('🔍 Looking for Download link...');

  await new Promise(r => setTimeout(r, 1000));

  // หา link/button ที่มีคำว่า "Download"
  const allElements = document.querySelectorAll('a, button, [role="button"]');

  for (const el of allElements) {
    const text = (el.textContent || '').trim().toLowerCase();
    const rect = el.getBoundingClientRect();

    if (text === 'download' && rect.width > 0 && rect.height > 0) {
      console.log('✅ Found Download link');
      el.click();
      await new Promise(r => setTimeout(r, 1000));
      return { success: true, message: 'Clicked Download link' };
    }
  }

  // Fallback: หาจาก class
  const downloadLinks = document.querySelectorAll('[class*="download"], a[href*="download"]');
  for (const link of downloadLinks) {
    const rect = link.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0) {
      console.log('✅ Found Download link by class');
      link.click();
      return { success: true, message: 'Clicked Download link (by class)' };
    }
  }

  console.log('❌ Download link not found');
  return { success: false, error: 'ไม่พบปุ่ม Download' };
}

// Step 10: กดปุ่ม Arrange (3 ขีด) ข้างปุ่ม Export
// v8.7.8: เพิ่ม retry loop เพราะบางทีหน้าโหลดช้า ปุ่มยังไม่ render
async function openSceneMenu() {
  console.log('🔍 Looking for Arrange button (flex_no_wrap icon)...');

  // v8.7.8: retry 10 รอบ รอ 2 วิต่อรอบ = 20 วินาที
  for (let retry = 0; retry < 10; retry++) {
    await new Promise(r => setTimeout(r, 2000));
    console.log(`🔍 [Retry ${retry + 1}/10] Searching for Arrange button...`);

    const allButtons = document.querySelectorAll('button');
    const screenWidth = window.innerWidth;
    const screenHeight = window.innerHeight;

    // วิธีที่ 1: หาจาก icon "flex_no_wrap" หรือ text "Arrange"
    for (const btn of allButtons) {
      const text = (btn.textContent || '').toLowerCase();
      const html = btn.innerHTML || '';
      const rect = btn.getBoundingClientRect();

      const isArrangeBtn =
        html.includes('flex_no_wrap') ||
        text.includes('arrange') ||
        html.includes('Arrange');

      if (isArrangeBtn && rect.width > 0 && rect.height > 0) {
        console.log(`✅ Found Arrange button at (${rect.x}, ${rect.y})`);
        btn.click();
        await new Promise(r => setTimeout(r, 1000));
        return { success: true, message: 'Opened Arrange menu' };
      }
    }

    // วิธีที่ 2: หาจาก google-symbols icon
    const icons = document.querySelectorAll('.google-symbols, [class*="google-symbols"]');
    for (const icon of icons) {
      const iconText = (icon.textContent || '').trim();
      if (iconText === 'flex_no_wrap') {
        const btn = icon.closest('button');
        if (btn) {
          console.log('✅ Found Arrange button via google-symbols icon');
          btn.click();
          await new Promise(r => setTimeout(r, 1000));
          return { success: true, message: 'Opened Arrange menu (via icon)' };
        }
      }
    }

    // วิธีที่ 3: หาจาก aria-label หรือ icon อื่นๆ
    for (const btn of allButtons) {
      const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();
      const html = btn.innerHTML || '';
      const rect = btn.getBoundingClientRect();

      const isMenuBtn =
        ariaLabel.includes('arrange') ||
        ariaLabel.includes('menu') ||
        ariaLabel.includes('more') ||
        ariaLabel.includes('option') ||
        html.includes('view_list') ||
        html.includes('reorder');

      if (isMenuBtn && rect.width > 0 && rect.height > 0 && rect.x > screenWidth * 0.7 && rect.y > screenHeight * 0.5) {
        console.log(`✅ Found menu button at (${rect.x}, ${rect.y})`);
        btn.click();
        await new Promise(r => setTimeout(r, 1000));
        return { success: true, message: 'Opened scene menu' };
      }
    }

    // วิธีที่ 4: หาจากตำแหน่งข้างปุ่ม download
    const bottomRightButtons = [];
    for (const btn of allButtons) {
      const rect = btn.getBoundingClientRect();
      if (rect.width > 0 && rect.height > 0 && rect.y > screenHeight * 0.6 && rect.x > screenWidth * 0.6) {
        bottomRightButtons.push({ btn, rect });
      }
    }
    bottomRightButtons.sort((a, b) => b.rect.x - a.rect.x);

    if (bottomRightButtons.length >= 2) {
      const menuBtn = bottomRightButtons[1].btn;
      console.log(`✅ Found menu button (2nd from right)`);
      menuBtn.click();
      await new Promise(r => setTimeout(r, 1000));
      return { success: true, message: 'Opened scene menu (by position)' };
    }

    // วิธีที่ 5: หา svg ที่เป็น 3 ขีด
    const svgs = document.querySelectorAll('svg');
    for (const svg of svgs) {
      const lines = svg.querySelectorAll('line, rect, path');
      if (lines.length >= 3) {
        const btn = svg.closest('button');
        if (btn) {
          const rect = btn.getBoundingClientRect();
          if (rect.y > screenHeight * 0.6 && rect.x > screenWidth * 0.6) {
            console.log('✅ Found menu button by SVG lines');
            btn.click();
            await new Promise(r => setTimeout(r, 1000));
            return { success: true, message: 'Opened scene menu (by SVG)' };
          }
        }
      }
    }

    console.log(`⚠️ [Retry ${retry + 1}/10] Arrange button not found, retrying...`);
  }

  console.log('❌ Scene menu button not found after 10 retries');
  return { success: false, error: 'ไม่พบปุ่ม Menu' };
}

// Step 11: ลบคลิปทั้งหมด (กด "-" บนแต่ละคลิป)
// v8.5: เพิ่มดีเลย์ให้นานขึ้นเผื่อคอมช้า
async function deleteAllSceneClips() {
  console.log('🗑️ [v8.5] Deleting all scene clips...');

  // v8.5: เพิ่มดีเลย์เริ่มต้นจาก 1000ms เป็น 2000ms
  await new Promise(r => setTimeout(r, 2000));

  let deletedCount = 0;
  const maxAttempts = 15; // v8.5: เพิ่มจาก 10 เป็น 15

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    // หาปุ่ม "-" (delete) บนคลิป
    const deleteButtons = [];

    const allButtons = document.querySelectorAll('button');
    for (const btn of allButtons) {
      const text = (btn.textContent || '').trim();
      const ariaLabel = (btn.getAttribute('aria-label') || '').toLowerCase();
      const html = btn.innerHTML || '';
      const rect = btn.getBoundingClientRect();

      // หาปุ่มที่เป็น "-" หรือ delete/remove
      const isDeleteBtn =
        text === '-' ||
        text === '−' ||
        ariaLabel.includes('delete') ||
        ariaLabel.includes('remove') ||
        html.includes('remove') ||
        html.includes('delete') ||
        html.includes('close');

      if (isDeleteBtn && rect.width > 0 && rect.height > 0 && rect.width < 50) {
        deleteButtons.push(btn);
      }
    }

    if (deleteButtons.length === 0) {
      console.log(`✅ [v8.5] All clips deleted (total: ${deletedCount})`);
      break;
    }

    // กดปุ่ม delete แรกที่เจอ
    console.log(`🗑️ [v8.5] Found ${deleteButtons.length} delete buttons, clicking first one... (attempt ${attempt + 1}/${maxAttempts})`);
    deleteButtons[0].click();
    deletedCount++;

    // v8.5: เพิ่มดีเลย์จาก 1000ms เป็น 2000ms เผื่อคอมช้า
    await new Promise(r => setTimeout(r, 2000));
  }

  // v8.5: รอเพิ่มหลังลบเสร็จเพื่อให้ UI อัพเดท
  await new Promise(r => setTimeout(r, 1500));

  if (deletedCount > 0) {
    return { success: true, message: `Deleted ${deletedCount} clips` };
  }

  console.log('⚠️ [v8.5] No clips to delete or delete buttons not found');
  return { success: false, error: 'ไม่พบปุ่มลบคลิป' };
}

// v7.0: ลบคลิปและ refresh เพื่อเช็คให้แน่ใจว่าเหลือ 0 วินาทีก่อนออก
// ต้อง refresh ทุกครั้ง เพราะบางทีหน้าแสดง 0 วิ แต่พอ refresh กลับเจอคลิปค้าง
// v8.5: เพิ่มดีเลย์และ double-check ก่อน refresh
async function deleteAllSceneClipsUntilEmpty() {
  console.log('🗑️ [v8.5] deleteAllSceneClipsUntilEmpty - starting...');

  // 1. เปิด menu และลบคลิปทั้งหมด (เหมือนเดิม)
  const menuResult = await openSceneMenu();
  if (menuResult.success) {
    // v8.5: เพิ่มดีเลย์จาก 1000ms เป็น 2000ms
    await new Promise(r => setTimeout(r, 2000));
    await deleteAllSceneClips();
    // v8.5: เพิ่มดีเลย์หลังลบจาก 1000ms เป็น 2500ms
    await new Promise(r => setTimeout(r, 2500));
  }

  // v8.5: Double-check ว่าคลิปหมดจริงก่อน refresh
  console.log('🔍 [v8.5] Double-checking clips before refresh...');
  updateBotOverlay('ตรวจสอบคลิปค้าง...', 'กำลังเช็ค');

  const totalSecsBeforeRefresh = getTotalSecondsInScenebuilder();
  console.log(`📊 [v8.5] Total seconds before refresh: ${totalSecsBeforeRefresh}`);

  // ถ้ายังมีคลิปค้าง ลองลบอีกรอบ
  if (totalSecsBeforeRefresh > 0) {
    console.log('⚠️ [v8.5] Still have clips! Trying to delete again before refresh...');
    updateBotOverlay('ยังมีคลิปค้าง!', 'ลบอีกรอบ');
    await new Promise(r => setTimeout(r, 1500));
    await deleteAllSceneClips();
    await new Promise(r => setTimeout(r, 2000));
  }

  // 2. Refresh ทุกครั้งหลังลบ เพื่อเช็คว่ามีคลิปซ่อนอยู่ไหม
  console.log('🔄 [v8.5] Refreshing to verify clips are truly empty...');
  updateBotOverlay('รีเฟรชเพื่อตรวจสอบ', 'กำลังเช็คคลิปค้าง');

  // v8.3: ไม่ต้องเก็บ setIndex แล้ว เพราะ message ถูกส่งก่อน refresh แล้ว
  // (autoExtendSetIndexForCallback ถูก remove ไปแล้วก่อนถึงจุดนี้)

  sessionStorage.setItem('v7_verify_empty_clips', 'true');
  sessionStorage.setItem('v7_verify_rounds', '1');

  // v8.5: รอเพิ่มก่อน reload เผื่อคอมช้า
  await new Promise(r => setTimeout(r, 1000));

  window.location.reload();
  await new Promise(r => setTimeout(r, 10000)); // รอ reload (จะไม่ถึงบรรทัดนี้)
  return { success: false, needsRefresh: true };
}

// v7.0: ดึงเวลารวมใน Scenebuilder (วินาที)
function getTotalSecondsInScenebuilder() {
  const timeDisplay = document.body.innerText.match(/\d+:\d+\s*\/\s*(\d+):(\d+)/);
  if (timeDisplay) {
    const minutes = parseInt(timeDisplay[1]);
    const seconds = parseInt(timeDisplay[2]);
    return minutes * 60 + seconds;
  }
  return 0;
}

// v8.6: รอให้ Scenebuilder time display โหลดเสร็จก่อนเช็คว่าคลิปหมดหรือยัง
// ป้องกันปัญหาหน้าโหลดช้าแล้วบอทคิดว่าคลิปหมดแล้วทั้งๆที่ยังมีอยู่
async function waitForScenebuilderTimeDisplay(maxWaitMs = 60000) { // v1.1.2: เพิ่มจาก 15s → 60s (รองรับคอมช้า)
  console.log('⏳ [v8.6] Waiting for Scenebuilder time display to load...');

  const startTime = Date.now();
  const checkInterval = 500; // เช็คทุก 500ms

  while (Date.now() - startTime < maxWaitMs) {
    // หา time display pattern เช่น "0:00 / 8:00" หรือ "0:00 / 0:00"
    const timeDisplay = document.body.innerText.match(/\d+:\d+\s*\/\s*\d+:\d+/);

    if (timeDisplay) {
      const waitedMs = Date.now() - startTime;
      console.log(`✅ [v8.6] Time display found: "${timeDisplay[0]}" (waited ${waitedMs}ms)`);
      return { found: true, display: timeDisplay[0], waitedMs };
    }

    // หา element อื่นๆ ที่บ่งบอกว่า Scenebuilder โหลดเสร็จ
    const sceneIndicators = document.querySelectorAll('[class*="timeline"], [class*="scene-builder"], [class*="export"]');
    if (sceneIndicators.length > 0) {
      // มี element แต่ยังไม่เจอ time display - รออีกนิด
      console.log(`⏳ [v8.6] Scene elements found but no time display yet, waiting...`);
    }

    await new Promise(r => setTimeout(r, checkInterval));
  }

  console.log(`⚠️ [v8.6] Time display not found after ${maxWaitMs}ms - page may still be loading`);
  return { found: false, waitedMs: maxWaitMs };
}

// v7.0: เช็คและลบคลิปที่เหลือหลัง refresh (เรียกตอนโหลดหน้า)
// v8.5: เพิ่มความเข้มงวดในการตรวจสอบ + เพิ่มดีเลย์
// v8.6: ใช้ waitForScenebuilderTimeDisplay แทนการรอแบบ fixed delay
async function verifyAndDeleteClipsAfterRefresh() {
  const needVerify = sessionStorage.getItem('v7_verify_empty_clips');
  if (needVerify !== 'true') return;

  console.log('🔍 [v8.6] Post-refresh: Verifying clips are empty...');

  // ลบ flag
  sessionStorage.removeItem('v7_verify_empty_clips');
  const rounds = parseInt(sessionStorage.getItem('v7_verify_rounds') || '1');
  sessionStorage.removeItem('v7_verify_rounds');

  // v8.6: รอให้ time display โหลดเสร็จก่อน (รอสูงสุด 15 วินาที)
  // ป้องกันปัญหาหน้าโหลดช้าแล้วบอทคิดว่าคลิปหมดแล้วทั้งๆที่ยังมีอยู่
  showBotOverlay('รอหน้าโหลด...', 'กำลังตรวจสอบคลิป');
  const displayResult = await waitForScenebuilderTimeDisplay(15000);

  if (!displayResult.found) {
    // ไม่เจอ time display - รอเพิ่มอีก 5 วินาทีแล้วลองใหม่
    console.log('⚠️ [v8.6] Time display not found, waiting additional 5s...');
    await new Promise(r => setTimeout(r, 5000));
  }

  // เช็คเวลารวม
  const totalSeconds = getTotalSecondsInScenebuilder();
  console.log(`📊 [v8.5] After refresh round ${rounds}: ${totalSeconds} seconds`);

  // v8.5: เพิ่มจำนวน rounds จาก 3 เป็น 5 เผื่อคอมช้า
  if (totalSeconds > 0 && rounds < 5) {
    // ยังมีคลิปค้าง - ลบอีกรอบ
    console.log(`⚠️ [v8.5] Still have ${totalSeconds}s of clips! Deleting round ${rounds + 1}...`);
    showBotOverlay('ยังมีคลิปค้าง!', `ลบรอบ ${rounds + 1}/5`);

    const menuResult = await openSceneMenu();
    if (menuResult.success) {
      // v8.5: เพิ่มดีเลย์จาก 1000ms เป็น 2000ms
      await new Promise(r => setTimeout(r, 2000));
      await deleteAllSceneClips();
      // v8.5: เพิ่มดีเลย์จาก 1000ms เป็น 2500ms
      await new Promise(r => setTimeout(r, 2500));
    }

    // v8.5: รอเพิ่มให้ UI อัพเดท
    await new Promise(r => setTimeout(r, 1500));

    // เช็คอีกครั้ง
    const newTotalSeconds = getTotalSecondsInScenebuilder();
    console.log(`📊 [v8.5] After delete attempt: ${newTotalSeconds} seconds`);

    if (newTotalSeconds > 0) {
      // ยังไม่หมด - refresh อีกรอบ
      console.log(`⚠️ [v8.5] Still ${newTotalSeconds}s remaining, will refresh again...`);
      sessionStorage.setItem('v7_verify_empty_clips', 'true');
      sessionStorage.setItem('v7_verify_rounds', String(rounds + 1));
      // v8.5: รอก่อน reload
      await new Promise(r => setTimeout(r, 1000));
      window.location.reload();
      return;
    }
  }

  // คลิปหมดแล้ว - กลับหน้าหลัก
  console.log('✅ [v9.0] Clips verified empty! Going back to Flow...');
  showBotOverlay('คลิปหมดแล้ว!', 'กลับหน้าหลัก');

  await goBackToFlow();

  // รอให้หน้าหลักโหลดเสร็จ
  await new Promise(r => setTimeout(r, 2000));

  // === v9.0: ส่ง message หลัง cleanup เสร็จ (ย้ายมาจาก Step 10) ===
  const autoSetIndex = sessionStorage.getItem('autoExtendSetIndexForCallback');
  if (autoSetIndex !== null) {
    sessionStorage.removeItem('autoExtendSetIndexForCallback');

    console.log('🎬 [v9.0] Cleanup complete! Now sending autoVideoComplete...');

    const messagePayload = {
      action: 'autoVideoComplete',
      setIndex: parseInt(autoSetIndex),
      extended: true
    };

    // รวม video data ถ้ามี
    const videoSize = sessionStorage.getItem('v9_video_size');
    const videoFilename = sessionStorage.getItem('v9_video_filename');
    if (videoSize) {
      messagePayload.videoSize = parseInt(videoSize);
      messagePayload.videoFilename = videoFilename || '';
      console.log(`🎬 [v9.0] Including video data: ${Math.round(parseInt(videoSize) / 1024)} KB`);

      // ลบ video data หลังใช้
      sessionStorage.removeItem('v9_video_size');
      sessionStorage.removeItem('v9_video_filename');
    }

    // v16.3: ดึง video base64 จาก IndexedDB และส่งแบบ chunked ไป popup
    let hasVideoFromContent = false;
    try {
      const videoRecord = await getVideoFromIDB();
      if (videoRecord && videoRecord.base64) {
        console.log(`📦 [v16.3] Found video in IDB: ${Math.round(videoRecord.base64.length / 1024)} KB`);
        await sendVideoChunksToPopup(videoRecord.base64, videoRecord.filename || videoFilename || '');
        hasVideoFromContent = true;
        await deleteVideoFromIDB();
        console.log('✅ [v16.3] Video sent and IDB cleaned up');
      }
    } catch (idbErr) {
      console.warn('⚠️ [v16.3] IDB video retrieval failed:', idbErr.message);
    }
    messagePayload.hasVideoFromContent = hasVideoFromContent;

    chrome.runtime.sendMessage(messagePayload);
    console.log('✅ [v9.0] autoVideoComplete sent! Popup can now proceed to next set.');
  }

  showBotOverlay('ต่อฉากเสร็จแล้ว!', 'พร้อมเริ่มชุดถัดไป');
  setTimeout(() => hideBotOverlay(), 2000);
}

// v15.2: หาปุ่ม New project
function findNewProjectButton() {
  const allBtns = document.querySelectorAll('button');
  for (const btn of allBtns) {
    const text = btn.textContent || '';
    if (text.includes('New project') || text.includes('add_2')) {
      return btn;
    }
  }
  return null;
}

// v15.2: เช็คว่ามีรูป/คลิปอยู่ในโปรเจ็คหรือไม่
function checkForExistingContent() {
  // หา image cards (มักมี class หรือ attribute บ่งบอก)
  // ลองหลายวิธี

  // วิธี 1: หา card ที่มี thumbnail image
  const imgCards = document.querySelectorAll('img[src*="blob:"], img[src*="data:image"], img[src*="googleusercontent"]');
  if (imgCards.length > 0) {
    console.log('[Flow v15.2] Found image cards:', imgCards.length);
    return true;
  }

  // วิธี 2: หา video elements
  const videos = document.querySelectorAll('video');
  if (videos.length > 0) {
    console.log('[Flow v15.2] Found video elements:', videos.length);
    return true;
  }

  // วิธี 3: หา card containers ที่มักจะมีเนื้อหา (ดูจาก layout)
  // หา elements ที่มี "Generated" หรือ time indicators
  const allText = document.body.innerText || '';
  if (allText.includes('Generated') || allText.match(/\d+\s*(sec|วิ)/)) {
    // อาจมี generated content
    const cards = document.querySelectorAll('[class*="card"], [class*="thumbnail"], [class*="preview"]');
    if (cards.length > 2) { // มากกว่า UI cards ปกติ
      console.log('[Flow v15.2] Found content cards:', cards.length);
      return true;
    }
  }

  // วิธี 4: เช็คจาก grid layout ที่มี content
  const gridItems = document.querySelectorAll('[role="gridcell"], [role="listitem"]');
  for (const item of gridItems) {
    const hasImg = item.querySelector('img');
    const hasVideo = item.querySelector('video');
    if (hasImg || hasVideo) {
      console.log('[Flow v15.2] Found grid item with media content');
      return true;
    }
  }

  console.log('[Flow v15.2] No existing content found');
  return false;
}

// v15.2: กลับไปหน้า Flow หลัก (จากหน้าโปรเจ็ค)
async function goBackToMainFlow() {
  console.log('[Flow v15.2] Going back to main Flow page...');

  // หา breadcrumb link "Flow" หรือ icon home
  const allLinks = document.querySelectorAll('a, button, [role="link"]');

  for (const link of allLinks) {
    const text = (link.textContent || '').trim().toLowerCase();
    const rect = link.getBoundingClientRect();

    // หา "Flow" link ใน breadcrumb (บน y < 100)
    if ((text === 'flow' || text.includes('home')) && rect.y < 100 && rect.y > 0) {
      console.log('[Flow v15.2] Found Flow/Home link - clicking...');
      link.click();
      await delay(2000);
      return { success: true };
    }
  }

  // หา home icon
  const icons = document.querySelectorAll('[class*="home"], [aria-label*="home"], [aria-label*="Home"]');
  for (const icon of icons) {
    const rect = icon.getBoundingClientRect();
    if (rect.y < 100 && rect.y > 0) {
      console.log('[Flow v15.2] Found home icon - clicking...');
      icon.click();
      await delay(2000);
      return { success: true };
    }
  }

  // หา back button
  const backBtns = document.querySelectorAll('button[aria-label*="back"], button[aria-label*="Back"], [class*="back"]');
  for (const btn of backBtns) {
    const rect = btn.getBoundingClientRect();
    if (rect.y < 150 && rect.y > 0) {
      console.log('[Flow v15.2] Found back button - clicking...');
      btn.click();
      await delay(2000);
      return { success: true };
    }
  }

  // Fallback: ใช้ history.back()
  console.log('[Flow v15.2] No navigation element found - using history.back()');
  window.history.back();
  await delay(2000);
  return { success: true, method: 'history' };
}

// Step 12: กลับไปหน้าโหมดเดิม (กด link วันที่/เวลา ข้างซ้าย Scenebuilder)
async function goBackToFlow() {
  console.log('🔍 Looking for way to go back to main page...');

  await new Promise(r => setTimeout(r, 1000));

  // === วิธีที่ 0 (v6.8): กดที่ button วันที่-เวลา ซ้ายของ Scenebuilder ===
  // Pattern: "Dec 12 - 09:51" หรือ "Jan 05 - 14:30" (เดือน วัน - เวลา)
  const dateTimePattern = /(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d+\s*-\s*\d+:\d+/i;

  // หา button ที่มี pattern วันที่-เวลา (สำคัญ! ต้องหา button ก่อน)
  const allButtons = document.querySelectorAll('button');
  for (const btn of allButtons) {
    const text = (btn.textContent || '').trim();
    const rect = btn.getBoundingClientRect();

    // หา button ที่มี pattern วันที่-เวลา และอยู่บริเวณ breadcrumb (บนซ้าย y < 100)
    if (dateTimePattern.test(text) && rect.y < 100 && rect.y > 0 && rect.width > 0) {
      console.log(`✅ Found date-time BUTTON: "${text}" - clicking...`);
      btn.click();
      await new Promise(r => setTimeout(r, 2000));
      return { success: true, message: 'Went back via date-time button' };
    }
  }

  // หา link ทั้งหมดใน breadcrumb (fallback)
  const links = document.querySelectorAll('a, [role="link"], span');

  // วิธีที่ 1: หา link ที่มี pattern วันที่ (Dec, Nov, Jan, etc. + ตัวเลข) - ไม่มีเวลา
  const datePattern = /(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+\d+/i;

  for (const link of links) {
    const text = (link.textContent || '').trim();
    const rect = link.getBoundingClientRect();

    // เช็คว่าเป็น pattern วันที่ และอยู่บริเวณบน (breadcrumb)
    if (datePattern.test(text) && rect.y < 100 && rect.y > 0) {
      console.log(`✅ Found date link: "${text}"`);
      link.click();
      await new Promise(r => setTimeout(r, 2000));
      return { success: true, message: 'Went back to main mode' };
    }
  }

  // วิธีที่ 2: หา link ที่อยู่ระหว่าง Flow และ Scenebuilder (ตรงกลาง breadcrumb)
  for (const link of links) {
    const text = (link.textContent || '').trim();
    const rect = link.getBoundingClientRect();

    // ต้องอยู่บน (y < 100) และอยู่ตรงกลาง (x > 50 และ x < 400)
    if (rect.y < 100 && rect.y > 0 && rect.x > 50 && rect.x < 400 && rect.width > 0) {
      // ไม่ใช่ Flow และไม่ใช่ Scenebuilder
      if (text !== 'Flow' && !text.includes('Scenebuilder') && text.length > 3) {
        console.log(`✅ Found middle breadcrumb: "${text}"`);
        link.click();
        await new Promise(r => setTimeout(r, 2000));
        return { success: true, message: 'Went back via middle breadcrumb' };
      }
    }
  }

  // วิธีที่ 3: หา pencil icon (✏️) ใน breadcrumb
  const pencilBtns = document.querySelectorAll('button[aria-label*="edit"], button[aria-label*="rename"], [class*="edit"]');
  for (const btn of pencilBtns) {
    const rect = btn.getBoundingClientRect();
    if (rect.y < 100 && rect.y > 0) {
      // กด link ข้างๆ pencil
      const parent = btn.parentElement;
      const siblingLink = parent?.querySelector('a, [role="link"]');
      if (siblingLink) {
        console.log('✅ Found link near pencil icon');
        siblingLink.click();
        await new Promise(r => setTimeout(r, 2000));
        return { success: true, message: 'Went back via pencil sibling' };
      }
    }
  }

  // วิธีสุดท้าย (v6.8): ใช้ browser history.back()
  console.log('⚠️ Link not found, trying browser back...');
  try {
    window.history.back();
    await new Promise(r => setTimeout(r, 2000));
    return { success: true, message: 'Went back via browser history' };
  } catch (e) {
    console.log('❌ Browser back failed:', e);
  }

  console.log('❌ All methods failed to go back');
  return { success: false, error: 'ไม่พบลิงก์กลับหน้าเดิม' };
}

// ==================== CREATOR MODE: Multi-Scene Extension ====================
// v12: สำหรับ Podcast/Storyboard ที่ต้องการต่อฉากมากกว่า 2 ฉาก

// v12: ดึงความยาววิดีโอใน Scenebuilder (วินาที)
function getSceneVideoDuration() {
  // หาจาก time display เช่น "0:10 / 0:15"
  const timeDisplay = document.body.innerText.match(/\d+:\d+\s*\/\s*(\d+):(\d+)/);
  if (timeDisplay) {
    const minutes = parseInt(timeDisplay[1]);
    const seconds = parseInt(timeDisplay[2]);
    return minutes * 60 + seconds;
  }
  return 0;
}

// v12: คำนวณจำนวนฉากจาก Duration
// 2 ฉาก = 15 วิ, 3 ฉาก = 22 วิ (+7 ต่อฉาก)
function calculateSceneCountFromDuration(duration) {
  if (duration < 10) return 1;
  if (duration < 20) return 2;
  // ฉากที่ 3+ = 15 + ((N-2) * 7)
  // N = ((duration - 15) / 7) + 2
  return Math.floor((duration - 15) / 7) + 2;
}

// v12: คำนวณ Duration ที่ควรได้จากจำนวนฉาก
function calculateExpectedDuration(sceneCount) {
  if (sceneCount <= 1) return 8;
  if (sceneCount === 2) return 15;
  // ฉากที่ 3+ = 15 + ((N-2) * 7)
  return 15 + ((sceneCount - 2) * 7);
}

// v12: เช็คว่ามี Loading indicator ใน Scenebuilder หรือไม่
function hasSceneLoading() {
  // หา loading percentage เช่น "5%", "99%"
  const loadingEl = document.querySelector('.hQLkNR, [class*="hQLkNR"]');
  if (loadingEl) {
    const text = loadingEl.textContent || '';
    if (text.match(/\d+%/)) {
      return true;
    }
  }

  // หา loading indicator อื่นๆ
  const bodyText = document.body.innerText || '';
  if (bodyText.match(/\d+%/) && bodyText.includes('Scenebuilder')) {
    // เช็คว่าเป็น % ใน timeline หรือไม่
    const allText = document.querySelectorAll('div');
    for (const div of allText) {
      const text = div.textContent || '';
      if (text.match(/^\d+%$/) && text !== '100%') {
        return true;
      }
    }
  }

  return false;
}

// v13.1: ดึงค่า loading percentage ปัจจุบัน (return -1 ถ้าไม่พบ)
function getSceneLoadingPercentage() {
  // หา loading percentage element
  const loadingEl = document.querySelector('.hQLkNR, [class*="hQLkNR"]');
  if (loadingEl) {
    const text = loadingEl.textContent || '';
    const match = text.match(/(\d+)%/);
    if (match) {
      return parseInt(match[1]);
    }
  }

  // หา % จาก divs อื่นๆ
  const allDivs = document.querySelectorAll('div');
  for (const div of allDivs) {
    const text = (div.textContent || '').trim();
    const match = text.match(/^(\d+)%$/);
    if (match) {
      return parseInt(match[1]);
    }
  }

  return -1; // ไม่พบ loading %
}

// v12: คลิกเลือกคลิปใน Timeline ตาม index (0-based)
// ต้องคลิกคลิปก่อนหน้าก่อนถึงจะ Extend ได้
async function clickSceneClipByIndex(clipIndex) {
  console.log(`🎯 [Creator] Clicking scene clip ${clipIndex + 1}...`);

  // หา clips ใน Timeline (divs ที่มี class bJkTtw หรือคล้ายกัน)
  // จากรูปจะเห็นว่า clip container มี class sc-962285be-4 bJkTtw
  const clipContainers = document.querySelectorAll('[class*="sc-962285be-4"], [class*="bJkTtw"]');

  console.log(`📊 Found ${clipContainers.length} potential clip containers`);

  // Filter เอาเฉพาะ clips ที่อยู่ใน timeline area (ด้านล่างของหน้า)
  const timelineClips = [];
  for (const container of clipContainers) {
    const rect = container.getBoundingClientRect();
    // Timeline อยู่ด้านล่าง (y > 60% ของหน้าจอ) และมีขนาดพอสมควร
    if (rect.top > window.innerHeight * 0.5 && rect.width > 50 && rect.height > 30) {
      timelineClips.push(container);
    }
  }

  console.log(`📊 Filtered to ${timelineClips.length} timeline clips`);

  // Sort by x position (left to right)
  timelineClips.sort((a, b) => a.getBoundingClientRect().left - b.getBoundingClientRect().left);

  if (clipIndex >= timelineClips.length) {
    console.log(`❌ Clip index ${clipIndex} out of range (only ${timelineClips.length} clips)`);
    return { success: false, error: `ไม่พบคลิปที่ ${clipIndex + 1}` };
  }

  const targetClip = timelineClips[clipIndex];
  console.log(`🎯 Clicking clip at index ${clipIndex}:`, targetClip);

  // คลิกที่คลิป
  targetClip.click();
  await new Promise(r => setTimeout(r, 500));

  // ลอง dispatch events เพิ่มเติม
  targetClip.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
  targetClip.dispatchEvent(new MouseEvent('mouseup', { bubbles: true }));

  console.log(`✅ Clicked clip ${clipIndex + 1}`);
  return { success: true };
}

// v12: รอให้ฉากใหม่สร้างเสร็จใน Scenebuilder
// ใช้การเช็ค Duration แทนการนับคลิป (แม่นกว่า)
async function waitForCreatorSceneComplete(targetSceneCount, timeoutMs = 5 * 60 * 1000) {
  const expectedDuration = calculateExpectedDuration(targetSceneCount);
  console.log(`⏳ [Creator] Waiting for scene ${targetSceneCount} (expected: ${expectedDuration}s)...`);

  const startTime = Date.now();
  let lastLoadingCheck = Date.now();
  let loadingDisappearedTime = null;

  while (Date.now() - startTime < timeoutMs) {
    await new Promise(r => setTimeout(r, 2000)); // เช็คทุก 2 วินาที

    const currentDuration = getSceneVideoDuration();
    const hasLoading = hasSceneLoading();

    console.log(`📊 [Creator] Duration: ${currentDuration}s / ${expectedDuration}s | Loading: ${hasLoading}`);

    // เช็ค "something went wrong" error
    const bodyText = document.body.innerText || '';
    if (bodyText.toLowerCase().includes('something went wrong') ||
        bodyText.toLowerCase().includes('error') ||
        bodyText.includes('ผิดพลาด')) {
      console.log(`❌ [Creator] Error detected in page!`);
      return { success: false, error: 'something went wrong', shouldRetry: true };
    }

    // ถ้า Duration ถึง/เกิน expected แล้ว = สำเร็จ!
    if (currentDuration >= expectedDuration) {
      console.log(`✅ [Creator] Scene ${targetSceneCount} complete! (${currentDuration}s >= ${expectedDuration}s)`);
      return { success: true, duration: currentDuration };
    }

    // ถ้า loading หายไปแล้ว แต่ duration ยังไม่ถึง = อาจจะ fail
    if (!hasLoading) {
      if (!loadingDisappearedTime) {
        loadingDisappearedTime = Date.now();
        console.log(`⚠️ [Creator] Loading disappeared, checking if success...`);
      } else if (Date.now() - loadingDisappearedTime > 5000) {
        // Loading หายไปนานกว่า 5 วินาทีแล้ว แต่ duration ไม่เพิ่ม = fail
        const currentDuration2 = getSceneVideoDuration();
        if (currentDuration2 < expectedDuration) {
          console.log(`❌ [Creator] Loading gone but duration not reached (${currentDuration2}s < ${expectedDuration}s)`);
          return { success: false, error: 'Loading หายแต่คลิปไม่เพิ่ม', shouldRetry: true };
        }
      }
    } else {
      // Loading กลับมา = reset timer
      loadingDisappearedTime = null;
    }

    // Update overlay
    const elapsed = Math.floor((Date.now() - startTime) / 1000);
    const remaining = Math.floor((timeoutMs - (Date.now() - startTime)) / 1000);
    updateBotOverlay(`สร้างฉาก ${targetSceneCount}...`, `${currentDuration}s / ${expectedDuration}s | เหลือ ${remaining} วิ`);
  }

  // Timeout
  console.log(`⏰ [Creator] Timeout waiting for scene ${targetSceneCount}`);
  return { success: false, error: 'Timeout', shouldRetry: true };
}

// v13: รอให้ฉาก Podcast สร้างเสร็จใน Scenebuilder
// ใช้ logic เดียวกับ Creator Mode
// v13.1: เพิ่มการเช็ค 99% stuck
async function waitForPodcastSceneComplete(targetScene, expectedDuration, timeoutMs = 5 * 60 * 1000) {
  console.log(`⏳ [Podcast] Waiting for scene ${targetScene} (expected: ${expectedDuration}s)...`);

  const startTime = Date.now();
  let loadingDisappearedTime = null;
  let stuckAt99Time = null; // v13.1: track เวลาที่ค้างที่ 99%
  const STUCK_AT_99_THRESHOLD = 30000; // 30 วินาที = ถือว่าค้าง

  while (Date.now() - startTime < timeoutMs) {
    await new Promise(r => setTimeout(r, 2000)); // เช็คทุก 2 วินาที

    const currentDuration = getSceneVideoDuration();
    const hasLoading = hasSceneLoading();
    const loadingPercent = getSceneLoadingPercentage(); // v13.1

    console.log(`📊 [Podcast] Duration: ${currentDuration}s / ${expectedDuration}s | Loading: ${hasLoading} (${loadingPercent}%)`);

    // v13.1: เช็คว่าค้างที่ 99% หรือไม่
    if (loadingPercent >= 99 && hasLoading) {
      if (!stuckAt99Time) {
        stuckAt99Time = Date.now();
        console.log(`⚠️ [Podcast] Progress at 99%, watching...`);
      } else if (Date.now() - stuckAt99Time > STUCK_AT_99_THRESHOLD) {
        console.log(`⚠️ [Podcast] Stuck at 99% for ${Math.floor((Date.now() - stuckAt99Time) / 1000)}s!`);
        return {
          success: false,
          error: 'ค้างที่ 99% นาน - อาจเสร็จแล้วแต่ UI ไม่อัพเดท',
          shouldRetry: true,
          wasStuckAt99: true // v13.1: flag บอกว่าควร refresh ก่อน retry
        };
      }
    } else if (loadingPercent < 99 && loadingPercent > 0) {
      // ถ้า % ลดลงหรือยังไม่ถึง 99 = reset timer
      stuckAt99Time = null;
    }

    // เช็ค error
    const bodyText = document.body.innerText || '';
    if (bodyText.toLowerCase().includes('something went wrong') ||
        bodyText.includes('ผิดพลาด')) {
      console.log(`❌ [Podcast] Error detected!`);
      return { success: false, error: 'something went wrong', shouldRetry: true };
    }

    // ถ้า Duration ถึง/เกิน expected แล้ว = สำเร็จ!
    if (currentDuration >= expectedDuration) {
      console.log(`✅ [Podcast] Scene ${targetScene} complete! (${currentDuration}s >= ${expectedDuration}s)`);
      return { success: true, duration: currentDuration };
    }

    // ถ้า loading หายไปแล้ว แต่ duration ยังไม่ถึง = อาจจะ fail
    if (!hasLoading) {
      if (!loadingDisappearedTime) {
        loadingDisappearedTime = Date.now();
        console.log(`⚠️ [Podcast] Loading disappeared, checking...`);
      } else if (Date.now() - loadingDisappearedTime > 5000) {
        const currentDuration2 = getSceneVideoDuration();
        if (currentDuration2 < expectedDuration) {
          console.log(`❌ [Podcast] Loading gone but duration not reached (${currentDuration2}s < ${expectedDuration}s)`);
          return { success: false, error: 'Loading หายแต่คลิปไม่เพิ่ม', shouldRetry: true };
        }
      }
    } else {
      loadingDisappearedTime = null;
    }

    // Update overlay
    const elapsed = Math.floor((Date.now() - startTime) / 1000);
    updateBotOverlay(`สร้างฉาก ${targetScene}...`, `${currentDuration}s / ${expectedDuration}s | ${elapsed} วิ`);
  }

  // Timeout
  console.log(`⏰ [Podcast] Timeout waiting for scene ${targetScene}`);
  return { success: false, error: 'Timeout', shouldRetry: true };
}

// v12: Main function สำหรับ Creator Mode Multi-Scene Extension
// เรียกจาก popup.js เมื่อต้องการต่อฉากที่ 3+
async function runCreatorMultiSceneExtend(config) {
  const { currentSceneCount, targetSceneCount, prompt, maxRetries = 3 } = config;

  console.log(`🎬 [Creator] ===== EXTEND SCENE ${currentSceneCount} → ${targetSceneCount} =====`);
  console.log(`📝 Prompt: ${prompt?.substring(0, 50)}...`);

  let retryCount = 0;

  while (retryCount < maxRetries) {
    try {
      showBotOverlay(`ต่อฉาก ${targetSceneCount}...`, `เริ่มต้น (ครั้งที่ ${retryCount + 1})`);

      // Step 1: คลิกเลือกคลิปก่อนหน้า (ฉาก N-1)
      const clipIndexToClick = currentSceneCount - 1; // 0-based index
      console.log(`👆 Step 1: Clicking clip ${clipIndexToClick + 1} (scene ${currentSceneCount})...`);
      updateBotOverlay(`ต่อฉาก ${targetSceneCount}`, `เลือกคลิปฉาก ${currentSceneCount}`);

      const clickResult = await clickSceneClipByIndex(clipIndexToClick);
      if (!clickResult.success) {
        throw new Error(clickResult.error || 'คลิกคลิปไม่สำเร็จ');
      }
      await new Promise(r => setTimeout(r, 1000));

      // Step 2: กดปุ่ม + และ Extend
      console.log(`➕ Step 2: Clicking + and Extend...`);
      updateBotOverlay(`ต่อฉาก ${targetSceneCount}`, `กด Extend...`);

      const extendResult = await clickPlusAndExtend();
      if (!extendResult.success) {
        throw new Error(extendResult.error || 'กด Extend ไม่สำเร็จ');
      }
      await new Promise(r => setTimeout(r, 3000));

      // Step 3: กรอก Prompt
      console.log(`📝 Step 3: Filling prompt...`);
      updateBotOverlay(`ต่อฉาก ${targetSceneCount}`, `กรอก Prompt...`);

      const finalPrompt = prompt || 'ต่อเนื่องจากฉากก่อนหน้า static camera, natural movement';
      const promptResult = await fillExtendPromptField(finalPrompt);
      if (!promptResult.success) {
        console.log('⚠️ Could not fill prompt:', promptResult.error);
      }
      await new Promise(r => setTimeout(r, 1000));

      // Step 4: กด Generate
      console.log(`🚀 Step 4: Clicking Generate...`);
      updateBotOverlay(`ต่อฉาก ${targetSceneCount}`, `กด Generate...`);

      const genResult = await clickExtendGenerateButton();
      if (!genResult.success) {
        throw new Error(genResult.error || 'กด Generate ไม่สำเร็จ');
      }

      // Step 5: รอฉากใหม่สร้างเสร็จ (Timeout 5 นาที)
      console.log(`⏳ Step 5: Waiting for scene ${targetSceneCount}...`);
      updateBotOverlay(`สร้างฉาก ${targetSceneCount}...`, `กำลังรอ AI`);

      const waitResult = await waitForCreatorSceneComplete(targetSceneCount);

      if (waitResult.success) {
        console.log(`✅ [Creator] Scene ${targetSceneCount} created successfully!`);
        updateBotOverlay(`ฉาก ${targetSceneCount} สำเร็จ!`, `Duration: ${waitResult.duration}s`);

        return {
          success: true,
          sceneCount: targetSceneCount,
          duration: waitResult.duration
        };
      }

      // Failed - ลอง retry
      console.log(`❌ [Creator] Scene ${targetSceneCount} failed: ${waitResult.error}`);

      if (waitResult.shouldRetry && retryCount < maxRetries - 1) {
        retryCount++;
        console.log(`🔄 [Creator] Retrying... (${retryCount}/${maxRetries})`);
        updateBotOverlay(`ลองใหม่ครั้งที่ ${retryCount + 1}`, waitResult.error);

        // ถ้า Timeout ให้ refresh ก่อน
        if (waitResult.error === 'Timeout') {
          console.log(`🔄 [Creator] Refreshing page before retry...`);
          window.location.reload();
          // Note: หลัง reload จะต้อง resume จาก sessionStorage
          sessionStorage.setItem('creatorMultiSceneRetry', JSON.stringify({
            currentSceneCount,
            targetSceneCount,
            prompt,
            retryCount,
            maxRetries
          }));
          return { success: false, error: 'Refreshing for retry', refreshing: true };
        }

        await new Promise(r => setTimeout(r, 3000));
        continue;
      }

      throw new Error(waitResult.error);

    } catch (error) {
      console.error(`❌ [Creator] Error:`, error);
      retryCount++;

      if (retryCount < maxRetries) {
        console.log(`🔄 [Creator] Retrying after error... (${retryCount}/${maxRetries})`);
        updateBotOverlay(`เกิดข้อผิดพลาด`, `ลองใหม่ครั้งที่ ${retryCount + 1}`);
        await new Promise(r => setTimeout(r, 3000));
        continue;
      }

      updateBotOverlay(`ต่อฉาก ${targetSceneCount} ไม่สำเร็จ`, error.message);
      setTimeout(() => hideBotOverlay(), 5000);

      return {
        success: false,
        error: error.message,
        sceneCount: currentSceneCount
      };
    }
  }

  return {
    success: false,
    error: `Failed after ${maxRetries} retries`,
    sceneCount: currentSceneCount
  };
}

// v12: เช็คและ Resume Creator Multi-Scene หลัง reload
async function checkCreatorMultiSceneRetry() {
  const retryData = sessionStorage.getItem('creatorMultiSceneRetry');
  if (!retryData) return;

  console.log('🔄 [Creator] Resuming multi-scene extend after reload...');
  sessionStorage.removeItem('creatorMultiSceneRetry');

  try {
    const config = JSON.parse(retryData);
    console.log('📋 [Creator] Resume config:', config);

    // รอให้หน้าโหลดเสร็จ
    await new Promise(r => setTimeout(r, 10000));

    // เช็คว่าอยู่ใน Scenebuilder หรือไม่
    if (!isInScenebuilderPage()) {
      console.log('⚠️ [Creator] Not in Scenebuilder after reload, aborting retry');
      return;
    }

    // เช็ค Duration ปัจจุบัน
    const currentDuration = getSceneVideoDuration();
    const expectedDuration = calculateExpectedDuration(config.targetSceneCount);

    // ถ้า Duration ถึงแล้ว = อาจจะสำเร็จตอน refresh
    if (currentDuration >= expectedDuration) {
      console.log(`✅ [Creator] Scene already complete after refresh! (${currentDuration}s >= ${expectedDuration}s)`);

      chrome.runtime.sendMessage({
        action: 'creatorSceneComplete',
        success: true,
        sceneCount: config.targetSceneCount,
        duration: currentDuration
      });
      return;
    }

    // ยังไม่เสร็จ - ลอง retry
    config.retryCount = (config.retryCount || 0) + 1;
    const result = await runCreatorMultiSceneExtend(config);

    chrome.runtime.sendMessage({
      action: 'creatorSceneComplete',
      ...result
    });

  } catch (error) {
    console.error('❌ [Creator] Resume error:', error);
  }
}

// v13.2: เช็คและ resume export retry หลัง refresh + play
async function checkPendingExportRetryWithPlay() {
  const pending = sessionStorage.getItem('pendingExportRetryWithPlay');
  const timestamp = sessionStorage.getItem('pendingExportRetryTime');

  if (!pending) return;

  // ล้าง flag ทันที
  sessionStorage.removeItem('pendingExportRetryWithPlay');
  sessionStorage.removeItem('pendingExportRetryTime');

  // เช็คว่า flag ไม่เก่าเกิน 5 นาที
  if (timestamp) {
    const age = Date.now() - parseInt(timestamp);
    if (age > 5 * 60 * 1000) {
      console.log('⚠️ [Export Retry] Pending flag too old, ignoring');
      return;
    }
  }

  console.log('🔄 [Export Retry] Found pending export retry with play flag, resuming...');

  // รอหน้าโหลดสมบูรณ์
  await new Promise(r => setTimeout(r, 5000));

  // เริ่ม retry with play
  await runExportRetryWithPlay();
}

// v13.2: ลอง Export อีกรอบหลัง refresh โดยกด Play ก่อน
async function runExportRetryWithPlay() {
  // v13.4: เพิ่มจาก 5 เป็น 10 ครั้ง (2 เท่า)
  const MAX_EXPORT_RETRIES = 10;
  let exportSuccess = false;
  let exportAttempt = 0;

  console.log('▶️ [Export Retry] Starting export retry with play method...');
  showBotOverlay('Export รอบ 2', 'กำลังเล่นคลิป...');

  // 1. กด Play และรอคลิปเล่นจบ
  const playResult = await clickPlayAndWaitForCompletion();
  if (!playResult.success) {
    console.log('⚠️ [Export Retry] Could not play clip:', playResult.error);
    // ยังลองต่อแม้ play ไม่ได้
  }

  // รอเพิ่มอีก 3 วินาที
  await new Promise(r => setTimeout(r, 3000));

  // v13.2: Helper to send phase 2 progress
  const sendPhase2Progress = (status, attempt = exportAttempt, maxAttempts = MAX_EXPORT_RETRIES) => {
    try {
      chrome.runtime.sendMessage({
        action: 'exportRetryProgress',
        status,
        attempt,
        maxAttempts,
        phase: 2
      });
    } catch (e) {
      console.log('[Export] Cannot send progress:', e.message);
    }
  };

  // 2. ลอง Export 5 ครั้ง
  console.log('🔄 [Export Retry] Starting export attempts...');

  while (!exportSuccess && exportAttempt < MAX_EXPORT_RETRIES) {
    exportAttempt++;
    console.log(`📦 [Export Retry] Attempt ${exportAttempt}/${MAX_EXPORT_RETRIES}`);
    updateBotOverlay('ลอง Export รอบ 2...', `ครั้งที่ ${exportAttempt}/${MAX_EXPORT_RETRIES}`);
    sendPhase2Progress('phase2_retrying'); // v13.2

    // หาและกดปุ่ม Export
    let exportResult = null;
    let findButtonAttempt = 0;
    const maxFindAttempts = 15;

    while (findButtonAttempt < maxFindAttempts) {
      exportResult = await clickExportButton();
      if (exportResult.success) break;

      findButtonAttempt++;
      console.log(`⏳ [Export Retry] หาปุ่ม Export... (${findButtonAttempt}/${maxFindAttempts})`);
      updateBotOverlay('หาปุ่ม Export...', `รอ ${findButtonAttempt}/${maxFindAttempts} วินาที`);
      await new Promise(r => setTimeout(r, 1000));
    }

    if (!exportResult?.success) {
      console.log('❌ [Export Retry] ไม่พบปุ่ม Export หลัง 15 วินาที');
      continue;
    }
    console.log('✅ [Export Retry] Clicked Export button');

    // รอ Export เสร็จ
    console.log('⏳ [Export Retry] Waiting for export to complete...');
    updateBotOverlay('รอ Export เสร็จ...', `ครั้งที่ ${exportAttempt}/${MAX_EXPORT_RETRIES}`);

    const waitExportResult = await waitForExportComplete();

    if (waitExportResult.success) {
      console.log('✅ [Export Retry] Export completed!');
      exportSuccess = true;
    } else if (waitExportResult.failed) {
      console.log(`❌ [Export Retry] Export failed! (attempt ${exportAttempt}/${MAX_EXPORT_RETRIES})`);

      if (exportAttempt < MAX_EXPORT_RETRIES) {
        // รอ popup หาย
        console.log('🔄 [Export Retry] รอ popup หายก่อน retry...');
        updateBotOverlay('Export ไม่สำเร็จ', 'รอ popup หาย...');

        let waitCount = 0;
        while (waitCount < 30) {
          await new Promise(r => setTimeout(r, 1000));
          waitCount++;
          const bodyText = document.body.innerText || '';
          if (!bodyText.includes('Export failed')) {
            console.log(`✅ [Export Retry] popup หายแล้ว (${waitCount} วินาที)`);
            break;
          }
        }

        await new Promise(r => setTimeout(r, 3000));
        continue;
      }
    } else if (waitExportResult.timeout) {
      console.log(`⏰ [Export Retry] Timeout (attempt ${exportAttempt}/${MAX_EXPORT_RETRIES})`);
      if (exportAttempt < MAX_EXPORT_RETRIES) {
        await new Promise(r => setTimeout(r, 3000));
        continue;
      }
    }
  }

  // ผลลัพธ์
  if (!exportSuccess) {
    console.log(`❌ [Export Retry] Failed after ${MAX_EXPORT_RETRIES} attempts in round 2`);
    updateBotOverlay('Export ไม่สำเร็จ', `ลองทั้งหมด 10 ครั้งแล้ว`);
    sendPhase2Progress('phase2_failed'); // v13.2
    setTimeout(() => hideBotOverlay(), 5000);

    // แจ้ง popup.js
    chrome.runtime.sendMessage({
      action: 'exportRetryFailed',
      error: `Export failed หลังลอง 10 ครั้ง (รวม refresh + play)`
    });
    return;
  }

  // Export สำเร็จ - กด Download
  console.log('📥 [Export Retry] Export success! Looking for Download button...');
  updateBotOverlay('Export สำเร็จ!', 'กำลัง Download...');
  sendPhase2Progress('phase2_success'); // v13.2

  const downloadResult = await findAndClickDownloadButton();

  if (downloadResult.success) {
    console.log('✅ [Export Retry] Download started!');
    updateBotOverlay('Download สำเร็จ!', 'กำลังดาวน์โหลดไฟล์');
    setTimeout(() => hideBotOverlay(), 3000);

    // แจ้ง popup.js
    chrome.runtime.sendMessage({
      action: 'exportRetrySuccess',
      message: 'Export และ Download สำเร็จ (หลัง refresh + play)'
    });
  } else {
    console.log('⚠️ [Export Retry] Could not click Download:', downloadResult.error);
    updateBotOverlay('Export สำเร็จ', 'กรุณากด Download เอง');
    setTimeout(() => hideBotOverlay(), 5000);

    chrome.runtime.sendMessage({
      action: 'exportRetrySuccess',
      needManualDownload: true,
      message: 'Export สำเร็จ แต่ต้องกด Download เอง'
    });
  }
}

// v13.2: กดปุ่ม Play ใน Scenebuilder timeline
async function clickPlayButton() {
  console.log('▶️ [Play] Looking for Play button...');

  // หาปุ่ม Play จาก material icon "play_arrow"
  const playBtn = Array.from(document.querySelectorAll('button')).find(btn => {
    const icon = btn.querySelector('i.material-icons');
    if (icon && icon.textContent.trim() === 'play_arrow') {
      return true;
    }
    return false;
  });

  if (playBtn) {
    console.log('✅ [Play] Found Play button, clicking...');
    playBtn.click();
    await new Promise(r => setTimeout(r, 500));
    return { success: true };
  }

  console.log('❌ [Play] Play button not found');
  return { success: false, error: 'ไม่พบปุ่ม Play' };
}

// v13.2: ดึงความยาวคลิปจาก UI (format: "0:00 / 0:16")
function getClipDurationSeconds() {
  // หา element ที่แสดงเวลา เช่น "0:00 / 0:16"
  const timeElements = document.querySelectorAll('*');
  for (const el of timeElements) {
    const text = el.textContent?.trim() || '';
    // Match format: "X:XX / X:XX" หรือ "XX:XX / XX:XX"
    const match = text.match(/(\d+:\d+)\s*\/\s*(\d+:\d+)/);
    if (match) {
      const totalTime = match[2]; // "0:16"
      const parts = totalTime.split(':');
      const minutes = parseInt(parts[0]) || 0;
      const seconds = parseInt(parts[1]) || 0;
      const totalSeconds = minutes * 60 + seconds;
      console.log(`⏱️ [Duration] Found duration: ${totalTime} = ${totalSeconds} seconds`);
      return totalSeconds;
    }
  }

  // ถ้าหาไม่เจอ ใช้ค่า default 30 วินาที
  console.log('⚠️ [Duration] Could not find duration, using default 30s');
  return 30;
}

// v13.2: กด Play และรอคลิปเล่นจบ
async function clickPlayAndWaitForCompletion() {
  console.log('▶️ [Play & Wait] Starting playback and wait...');

  // กดปุ่ม Play
  const playResult = await clickPlayButton();
  if (!playResult.success) {
    return playResult;
  }

  // ดึงความยาวคลิป
  const duration = getClipDurationSeconds();
  const waitTime = duration + 3; // เพิ่มอีก 3 วินาที buffer

  console.log(`⏳ [Play & Wait] Waiting ${waitTime} seconds for playback to complete...`);
  updateBotOverlay('กำลังเล่นคลิป...', `รอ ${waitTime} วินาที`);

  // countdown
  for (let i = waitTime; i > 0; i--) {
    updateBotOverlay('กำลังเล่นคลิป...', `เหลือ ${i} วินาที`);
    await new Promise(r => setTimeout(r, 1000));
  }

  console.log('✅ [Play & Wait] Playback completed');
  return { success: true, duration };
}

// v12: Export และ Download สำหรับ Creator Mode
// v13.4: เพิ่มจาก 5 เป็น 10 ครั้ง (2 เท่า) - Retry สูงสุด 10 ครั้ง
// v13.2: เพิ่ม retry หลัง refresh + play ถ้ารอบแรกไม่สำเร็จ
async function runCreatorExportAndDownload() {
  // v13.4: เพิ่มจาก 5 เป็น 10 ครั้ง (2 เท่า)
  const MAX_EXPORT_RETRIES = 10;
  let exportSuccess = false;
  let exportAttempt = 0;

  // v13.2: Helper function to send progress to popup
  const sendExportProgress = (status, attempt = exportAttempt, maxAttempts = MAX_EXPORT_RETRIES) => {
    try {
      chrome.runtime.sendMessage({
        action: 'exportRetryProgress',
        status,
        attempt,
        maxAttempts,
        phase: 1
      });
    } catch (e) {
      console.log('[Export] Cannot send progress:', e.message);
    }
  };

  console.log('📦 [Creator Export] Starting export process...');
  showBotOverlay('กำลัง Export...', 'เตรียมรวมคลิป');

  while (!exportSuccess && exportAttempt < MAX_EXPORT_RETRIES) {
    exportAttempt++;
    console.log(`📦 [Creator Export] Attempt ${exportAttempt}/${MAX_EXPORT_RETRIES}`);
    updateBotOverlay('กำลัง Export...', `ครั้งที่ ${exportAttempt}/${MAX_EXPORT_RETRIES}`);
    sendExportProgress('retrying'); // v13.2

    // Step 1: หาและกดปุ่ม Export (retry 15 วินาที)
    let exportResult = null;
    let findButtonAttempt = 0;
    const maxFindAttempts = 15;

    while (findButtonAttempt < maxFindAttempts) {
      exportResult = await clickExportButton();
      if (exportResult.success) break;

      findButtonAttempt++;
      console.log(`⏳ [Creator Export] หาปุ่ม Export... (${findButtonAttempt}/${maxFindAttempts})`);
      updateBotOverlay('หาปุ่ม Export...', `รอ ${findButtonAttempt}/${maxFindAttempts} วินาที`);
      await new Promise(r => setTimeout(r, 1000));
    }

    if (!exportResult?.success) {
      console.log('❌ [Creator Export] ไม่พบปุ่ม Export หลัง 15 วินาที');
      return { success: false, error: 'ไม่พบปุ่ม Export' };
    }
    console.log('✅ [Creator Export] Clicked Export button');

    // Step 2: รอ Export เสร็จ (เช็ค Download link หรือ Export failed)
    console.log('⏳ [Creator Export] Waiting for export to complete...');
    updateBotOverlay('รอ Export เสร็จ...', `ครั้งที่ ${exportAttempt}/${MAX_EXPORT_RETRIES}`);

    const waitExportResult = await waitForExportComplete();

    if (waitExportResult.success) {
      console.log('✅ [Creator Export] Export completed!');
      exportSuccess = true;
      sendExportProgress('success'); // v13.2
    } else if (waitExportResult.failed) {
      // Export failed! - ลอง retry
      console.log(`❌ [Creator Export] Export failed! (attempt ${exportAttempt}/${MAX_EXPORT_RETRIES})`);
      sendExportProgress('failed'); // v13.2

      if (exportAttempt < MAX_EXPORT_RETRIES) {
        // รอให้ "Export failed" popup หายก่อน retry (สูงสุด 30 วินาที)
        console.log('🔄 [Creator Export] รอ popup "Export failed" หายก่อน retry...');
        updateBotOverlay('Export ไม่สำเร็จ', 'รอ popup หาย...');
        sendExportProgress('waiting'); // v13.2

        let waitCount = 0;
        while (waitCount < 30) {
          await new Promise(r => setTimeout(r, 1000));
          waitCount++;
          const bodyText = document.body.innerText || '';
          if (!bodyText.includes('Export failed')) {
            console.log(`✅ [Creator Export] popup หายแล้ว (${waitCount} วินาที)`);
            break;
          }
        }

        // รอเพิ่มอีก 3 วินาที ให้ UI พร้อม
        await new Promise(r => setTimeout(r, 3000));
        updateBotOverlay('ลอง Export ใหม่...', `ครั้งที่ ${exportAttempt + 1}/${MAX_EXPORT_RETRIES}`);
        continue;
      }
    } else if (waitExportResult.timeout) {
      console.log(`⏰ [Creator Export] Timeout (attempt ${exportAttempt}/${MAX_EXPORT_RETRIES})`);
      if (exportAttempt < MAX_EXPORT_RETRIES) {
        await new Promise(r => setTimeout(r, 3000));
        continue;
      }
    }
  }

  // v13.2: ถ้า Export ไม่สำเร็จหลัง 5 ครั้ง → ลอง refresh + play + retry อีก 5 ครั้ง
  if (!exportSuccess) {
    console.log(`⚠️ [Creator Export] Failed first ${MAX_EXPORT_RETRIES} attempts, trying refresh + play method...`);
    updateBotOverlay('Export ไม่สำเร็จ', 'จะ Refresh + Play แล้วลองใหม่...');
    sendExportProgress('refreshing', exportAttempt, MAX_EXPORT_RETRIES); // v13.2

    // เก็บ flag ใน sessionStorage ก่อน refresh
    sessionStorage.setItem('pendingExportRetryWithPlay', 'true');
    sessionStorage.setItem('pendingExportRetryTime', Date.now().toString());

    // รอ 2 วินาทีแล้ว refresh
    await new Promise(r => setTimeout(r, 2000));
    console.log('🔄 [Creator Export] Refreshing page for retry with play...');
    window.location.reload();

    // หลัง reload โค้ดจะไม่ทำงานต่อ - จะถูก resume โดย checkPendingExportRetryWithPlay()
    return { success: false, refreshingForRetry: true };
  }

  // Step 3: กดปุ่ม Download
  console.log('📥 [Creator Export] Looking for Download button...');
  updateBotOverlay('กำลัง Download...', 'หาปุ่ม Download');

  const downloadResult = await findAndClickDownloadButton();

  if (downloadResult.success) {
    console.log('✅ [Creator Export] Download started!');
    updateBotOverlay('Download สำเร็จ!', 'กำลังดาวน์โหลดไฟล์');
    setTimeout(() => hideBotOverlay(), 3000);
    return { success: true, message: 'Export และ Download สำเร็จ' };
  } else {
    console.log('⚠️ [Creator Export] Could not click Download:', downloadResult.error);
    updateBotOverlay('Export สำเร็จ', 'กรุณากด Download เอง');
    setTimeout(() => hideBotOverlay(), 5000);
    return { success: true, needManualDownload: true, message: 'Export สำเร็จ แต่ต้องกด Download เอง' };
  }
}

// v12: Full Creator Mode Pipeline (สร้างทุกฉาก + Export + Download)
// เรียกจาก popup.js สำหรับ Podcast/Storyboard
async function runCreatorFullPipeline(config) {
  const { targetSceneCount, prompts, startFromScene = 2 } = config;

  console.log(`🎬 [Creator Pipeline] ===== START FULL PIPELINE =====`);
  console.log(`🎯 Target: ${targetSceneCount} scenes`);
  console.log(`📝 Prompts: ${prompts?.length || 0}`);

  let currentSceneCount = startFromScene;

  // Loop ต่อฉากจนครบ
  while (currentSceneCount < targetSceneCount) {
    const nextScene = currentSceneCount + 1;
    const prompt = prompts?.[currentSceneCount - 1] || prompts?.[0] || '';

    console.log(`🎬 [Creator Pipeline] Extending scene ${currentSceneCount} → ${nextScene}...`);
    showBotOverlay(`สร้างฉาก ${nextScene}/${targetSceneCount}`, 'กำลังเตรียม...');

    const extendResult = await runCreatorMultiSceneExtend({
      currentSceneCount,
      targetSceneCount: nextScene,
      prompt,
      maxRetries: 3
    });

    if (!extendResult.success) {
      console.log(`❌ [Creator Pipeline] Scene ${nextScene} failed: ${extendResult.error}`);

      // ถ้า refreshing ให้รอ resume จาก checkCreatorMultiSceneRetry
      if (extendResult.refreshing) {
        return { success: false, error: 'Refreshing', refreshing: true, currentScene: currentSceneCount };
      }

      return {
        success: false,
        error: `สร้างฉาก ${nextScene} ไม่สำเร็จ: ${extendResult.error}`,
        completedScenes: currentSceneCount
      };
    }

    console.log(`✅ [Creator Pipeline] Scene ${nextScene} completed!`);
    currentSceneCount = nextScene;

    // รอสักครู่ก่อนฉากถัดไป
    if (currentSceneCount < targetSceneCount) {
      await new Promise(r => setTimeout(r, 2000));
    }
  }

  console.log(`🎉 [Creator Pipeline] All ${targetSceneCount} scenes created!`);
  updateBotOverlay(`ครบ ${targetSceneCount} ฉากแล้ว!`, 'กำลัง Export...');

  // Export และ Download
  const exportResult = await runCreatorExportAndDownload();

  if (exportResult.success) {
    console.log('✅ [Creator Pipeline] Pipeline completed successfully!');
    return {
      success: true,
      totalScenes: targetSceneCount,
      message: 'สร้างคลิปและ Export สำเร็จ!'
    };
  } else {
    console.log('⚠️ [Creator Pipeline] Export failed:', exportResult.error);
    return {
      success: false,
      error: exportResult.error,
      completedScenes: targetSceneCount,
      exportFailed: true
    };
  }
}

// =============================================
// v4.5 Merge Mode — สร้าง 1 ฉาก (image + animate + รอ video ผ่าน hook)
// reuse createStorySceneImage (auto-attaches scene N-1 จาก gallery สำหรับฉาก 2+)
// =============================================
async function runMergeGenerateScene_v1(data) {
  const {
    sceneIndex = 1,
    sceneCount = 5,
    isFirstScene = false,
    imagePrompt = '',
    productImages = [],
    aspect = '9:16',
    imageModel = 'nano_banana_pro',
    // v4.4.5: skip image gen + ใช้ภาพเดิมจาก gallery (ตอน retry video เฟล แต่ภาพยังดี)
    skipImageGen = false,
    existingImageUrl = '',
    // v4.4.9c: คุณภาพ download (720p/1080p/4k) — 1080p/4K ต้องรอ upscale
    quality = '720p',
  } = data || {};

  console.log(`[Merge v4.5] === Scene ${sceneIndex}/${sceneCount} ${isFirstScene ? '(FIRST)' : ''}${skipImageGen ? ' [SKIP IMAGE GEN — reuse existing]' : ''} ===`);

  // v4.5: แสดง overlay ตลอด scene เพื่อให้ user เห็นว่ายังทำงานอยู่ (กัน "ม่านหาย")
  const sceneLabel = `Merge Mode ฉาก ${sceneIndex}/${sceneCount}`;
  try { showBotOverlay(sceneLabel, 'เริ่มเตรียมการ...'); } catch (_) {}
  mergeForwardLog(`🎬 เริ่มฉาก ${sceneIndex}/${sceneCount}${skipImageGen ? ' — ข้ามสร้างภาพ (ใช้ภาพเดิม)' : ''}`);

  // 1) เตรียม referenceImages — ส่ง refs (สินค้า+นางแบบ1+นางแบบ2) "ทุกฉาก" เหมือนตอนฉาก 1
  //    - ฉาก 1: createStorySceneImage จะ upload + attach
  //    - ฉาก 2+: createStorySceneImage จะ search by filename จาก gallery (ที่ upload ตอนฉาก 1) + attach
  //    - **ไม่** auto-attach รูปฉากก่อนหน้า (ส่ง attachPreviousSceneRef:false)
  // v4.5.1: รับ refs format ใหม่: array ของ {base64, filename, kind} หรือ base64 string ล้วน (backward compat)
  const refs = (Array.isArray(productImages) ? productImages : []).map((item, idx) => {
    if (typeof item === 'string') {
      return { base64: item, filename: `merge-ref-${idx + 1}.png`, type: 'product', uploadOnly: false };
    }
    const kind = item.kind || 'product';
    const defaultName = kind === 'model' ? 'merge-model-1.png' :
                        kind === 'model2' ? 'merge-model-2.png' :
                        `merge-${kind}-${idx + 1}.png`;
    return {
      base64: item.base64,
      filename: item.filename || defaultName,
      type: 'product', // Story Mode treats all as upload+attach refs
      // v4.5.9: honor uploadOnly — ฉาก 1 อัพตัวละครทุกคนเข้า gallery แต่ "แนบ" เฉพาะคนในฉาก
      //   (คนที่ไม่อยู่ฉาก 1 ส่ง uploadOnly:true → upload ไว้เฉยๆ ให้ฉากหลังหา by name เจอ)
      uploadOnly: !!item.uploadOnly,
      // v4.6: 🥕 Character Anchor — ส่งต่อ forceUpload ให้ createStorySceneImage
      //   (anchor = ภาพฉาก 1 ต้อง upload+attach ทุกฉาก เพราะเพิ่งเกิดหลังฉาก 1 — หา by name ไม่เจอถ้าไม่อัพ)
      forceUpload: !!item.forceUpload,
    };
  });
  console.log(`[Merge v4.5] Scene ${sceneIndex}: ${refs.length} refs — ${refs.map(r => r.filename).join(', ')} — ${isFirstScene ? 'upload+attach' : 'search by name + attach'}`);

  // 2) สร้างภาพ (reuse createStorySceneImage with attachPreviousSceneRef:false)
  // v4.4.5: aspect lock — ป้องกัน AI gen ภาพแนวนอนแล้ว pad blur ให้เป็น 9:16 (letterbox bug)
  //   เฉพาะ Merge pipeline (ไม่กระทบ Story Mode v1 หรือ Auto Mode เก่า)
  //   ⚠️ อย่าใช้คำว่า "phone screen" / "TikTok style" / "mobile" — AI จะวาด mockup มือถือจริง!
  //   ใช้ aspect ratio + composition เป็นภาษากลาง + negative กัน phone mockup
  let finalImagePrompt = imagePrompt || '';
  if (aspect === '9:16') {
    finalImagePrompt += '\n\n[Aspect Ratio Lock]\n' +
      '9:16 vertical portrait aspect ratio, tall composition, ' +
      'subject and background fill the entire frame from top to bottom edge-to-edge, ' +
      'no empty space at top or bottom, content extends to all four edges of the frame, ' +
      'NO letterbox, NO black bars, NO blurred padding at top or bottom, NO horizontal matte borders, ' +
      'NO phone mockup, NO device frame, NO smartphone bezel, NO app interface, NO screen frame inside the image';
  } else if (aspect === '1:1') {
    finalImagePrompt += '\n\n[Aspect Ratio Lock]\n' +
      '1:1 square aspect ratio composition, ' +
      'content fills entire square frame edge-to-edge from all four sides, ' +
      'NO letterbox, NO black bars, NO padding on any side, ' +
      'NO phone mockup, NO device frame inside the image';
  }
  // v4.4.5: ถ้า skipImageGen + มี existingImageUrl → ข้ามสร้างภาพ ใช้ภาพเดิม
  let imgResult;
  if (skipImageGen && existingImageUrl) {
    try { updateBotOverlay(sceneLabel, '🖼️ ใช้ภาพเดิม — ข้ามสร้างใหม่'); } catch (_) {}
    mergeForwardLog(`🖼️ ฉาก ${sceneIndex}: ใช้ภาพเดิม (ข้ามสร้างใหม่ + ข้ามอัพรูป ref)`, 'info');
    // v4.5.8: หลัง refresh-retry gallery อาจยังโหลดภาพไม่ทัน → รอให้มีภาพก่อน animate
    //   (กัน animate หาภาพไม่เจอ → คลิปมั่ว text-to-video) — เคส "ใช้รูปเดิมทุกฉาก" + retry refresh
    try {
      let hasImg = false;
      for (let w = 0; w < 20; w++) {
        const imgCards = Array.from(document.querySelectorAll('.sc-5923b123-0')).filter(c => {
          const t = (c.textContent || '').toLowerCase();
          return c.querySelector('img') && !t.includes('failed') && !c.querySelector('video');
        });
        if (imgCards.length > 0) { hasImg = true; break; }
        if (w === 0) mergeForwardLog(`⏳ ฉาก ${sceneIndex}: รอ gallery โหลดภาพ (หลัง refresh)...`, 'info');
        await new Promise(r => setTimeout(r, 1000));
      }
      if (!hasImg) {
        mergeForwardLog(`⚠️ ฉาก ${sceneIndex}: ยังไม่เจอภาพใน gallery — จะ retry (ไม่ทำ text-to-video)`, 'warning');
        return { success: false, error: 'GALLERY_NO_IMAGE: ไม่พบภาพใน gallery หลัง refresh — retry' };
      }
    } catch (_) {}
    imgResult = { success: true, imageUrl: existingImageUrl };
  } else {
    try { updateBotOverlay(sceneLabel, '🎨 กำลังสร้างภาพ...'); } catch (_) {}
    mergeForwardLog(`🎨 สร้างภาพฉาก ${sceneIndex}... (${refs.length} refs, ${aspect})`);
    try {
      imgResult = await createStorySceneImage(
        finalImagePrompt,
        aspect,
        sceneIndex,
        refs,
        imageModel,
        { attachPreviousSceneRef: false } // v4.5: ห้ามแนบรูปฉากก่อนหน้า
      );
    } catch (err) {
      return { success: false, error: 'createStorySceneImage threw: ' + err.message };
    }
  }
  if (!imgResult || !imgResult.success) {
    return { success: false, error: (imgResult && imgResult.error) || 'Image gen failed (unknown)' };
  }
  console.log(`[Merge v4.5] Scene ${sceneIndex} image done`);
  try { showBotOverlay(sceneLabel, '✅ ภาพเสร็จ → เตรียม Animate...'); } catch (_) {}
  mergeForwardLog(`✅ ภาพฉาก ${sceneIndex} เสร็จ → animate + video gen`, 'success');

  // 3) สร้างคลิป — ใช้ createStoryClip_v17 ที่ครอบ animate + config + prompt + generate + monitor เป๊ะ
  //    (เหมือน Story Mode / Auto Mode ทุกขั้นตอน)
  await new Promise((r) => setTimeout(r, 1500)); // settle
  const speechText = (data && data.speechText) || '';
  // v4.4.5: รับ videoPrompt + videoModel ตรงจาก caller (Story Mode มี videoPrompt ของตัวเองที่ AI gen มา)
  //   - ถ้า caller ส่ง videoPrompt มา → ใช้ตรงๆ (Story Mode เทพอยู่แล้ว ห้ามทับ)
  //   - ไม่งั้น fallback = speechText || imagePrompt (Merge Mode pattern เดิม)
  const videoPrompt = (data && data.videoPrompt) || speechText || imagePrompt;
  const videoModel = (data && data.videoModel) || 'veo_lite_lower';

  // v4.5: take fail baseline ก่อน gen → ใช้ตรวจ fail หลังเสร็จ + ระหว่างรอ download
  const failedBaseline = (typeof countAllFailedGenerations === 'function') ? countAllFailedGenerations() : 0;
  console.log(`[Merge v4.5] failedBaseline = ${failedBaseline}`);

  // v4.5.8: 🆔 snapshot คลิปที่มี "ก่อนสร้าง" — ใช้หา "คลิปตัวใหม่" ตอนดาวน์โหลด (กัน reuse หยิบคลิปข้ามชุด)
  const beforeClipKeys = _pdSnapshotClipKeys();
  console.log(`[Merge v4.5.8] snapshot ${beforeClipKeys.size} clips before gen scene ${sceneIndex}`);

  let clipResult;
  try {
    clipResult = await createStoryClip_v17({
      imageUrl: imgResult.imageUrl,
      videoPrompt,
      videoModel,
      aspectRatio: aspect,
      sceneNumber: sceneIndex,
      sceneIndex,
      totalScenes: sceneCount,
    });
  } catch (err) {
    // v4.4.5: return imageUrl ด้วย — popup เก็บไว้ retry video อย่างเดียว
    return { success: false, error: 'createStoryClip_v17 threw: ' + err.message, imageUrl: imgResult.imageUrl };
  }
  if (!clipResult || !clipResult.success) {
    return { success: false, error: (clipResult && clipResult.error) || 'video gen failed', imageUrl: imgResult.imageUrl };
  }

  // v4.5: ตรวจ fail ใหม่หลัง gen — Auto Mode pattern เช็ค new failed cards
  await new Promise((r) => setTimeout(r, 1500)); // รอ DOM stabilize ให้ Failed badge render
  if (typeof countAllFailedGenerations === 'function') {
    const failedAfter = countAllFailedGenerations();
    const newFails = failedAfter - failedBaseline;
    console.log(`[Merge v4.5] failedAfter=${failedAfter}, newFails=${newFails}`);
    if (newFails > 0) {
      // v4.4.5: ตรวจว่าเป็นเคส Flow บล็อค (unusual activity) ไหม → ต้องการ refresh page
      const pageText = (document.body.textContent || '').toLowerCase();
      const isFlowBlocked = pageText.includes('unusual activity') || pageText.includes('visit the help center');
      // v4.4.5: ⭐ return imageUrl ด้วย — popup เก็บไว้ retry video อย่างเดียว (ภาพไม่ได้เฟล)
      if (isFlowBlocked) {
        mergeForwardLog(`🚫 ฉาก ${sceneIndex} — Flow บล็อค (unusual activity) ตรวจพบ! แจ้ง popup ให้ refresh`, 'error');
        return { success: false, error: 'FLOW_BLOCKED', flowBlocked: true, imageUrl: imgResult.imageUrl };
      }
      mergeForwardLog(`❌ ฉาก ${sceneIndex} เฟล — เจอ Failed card ใหม่ ${newFails} อัน (รวม ${failedAfter})`, 'error');
      return { success: false, error: `Scene ${sceneIndex} fail — new Failed card detected (+${newFails})`, imageUrl: imgResult.imageUrl };
    }
  }

  console.log(`[Merge v4.5] Scene ${sceneIndex} video generated — triggering download for hook capture...`);
  try { showBotOverlay(sceneLabel, '✅ คลิปสร้างเสร็จ → กำลังดาวน์โหลด...'); } catch (_) {}
  mergeForwardLog(`✅ คลิปฉาก ${sceneIndex} gen เสร็จ → เริ่มดาวน์โหลด`, 'success');

  // 4) Trigger download คลิปล่าสุด → hook ดักไฟล์ → __flowFinalVideoData__
  // v4.4.9c: ส่ง quality (720p/1080p/4k) ให้ executeClipDownload — UI flow จะรอ upscale อัตโนมัติ
  await new Promise((r) => setTimeout(r, 2500)); // v4.5: รอ DOM stabilize หลัง video gen เสร็จ (จาก 1.5 → 2.5s)
  let downloadTriggered = false;
  try {
    downloadTriggered = await mergeTriggerLatestClipDownload_v45(sceneIndex, quality, beforeClipKeys);
  } catch (err) {
    console.warn(`[Merge v4.5] download trigger error scene ${sceneIndex}:`, err.message);
  }
  if (!downloadTriggered) {
    console.warn(`[Merge v4.5] Scene ${sceneIndex}: download click ไม่สำเร็จ — ลองรอ hook capture เผื่อมี auto-download`);
  }
  try { updateBotOverlay(sceneLabel, '⏳ รอ video blob (hook capture)...'); } catch (_) {}

  // 5) รอ __flowFinalVideoData__ ผ่าน hook (timeout 3 นาที — ลดจาก 5 เพราะมี fail detect แล้ว)
  //    v4.5: ระหว่างรอ — ตรวจ new Failed cards เป็นระยะ + abort เร็วถ้าเจอ
  const startWait = Date.now();
  const TIMEOUT_MS = 180000; // 3 นาที (จาก 5)
  let lastLog = 0;
  let lastFailCheck = 0;
  const FAIL_CHECK_INTERVAL_MS = 5000;
  // v0.6.1 (port VIP v4.6.7): 🆘 ถ้า hook ดักไฟล์ไม่ติดภายใน 35s (Flow A/B เปลี่ยนวิธี download)
  //   → ดึงวิดีโอจาก DOM ตรงๆ (สูงสุด 3 ครั้ง ห่าง 40s) · เครื่องที่ hook ทำงานปกติจะไม่เข้า block นี้เลย
  const FALLBACK_AFTER_MS = 35000;
  let lastFallbackAt = 0;
  let fallbackAttempts = 0;
  while (Date.now() - startWait < TIMEOUT_MS) {
    if (window.__pdFootageStopNow__) { // v0.6.1: หยุดทันที — ไม่รอ video blob ต่อ (กันค้าง 180 วิ ตอน user กดหยุด)
      mergeForwardLog(`⏹️ หยุดโดยผู้ใช้ — ยกเลิกฉาก ${sceneIndex}`, 'error');
      return { success: false, error: 'STOPPED', stopped: true };
    }
    if (window.__flowFinalVideoData__ && window.__flowFinalVideoData__.base64) {
      const sz = window.__flowFinalVideoData__.size || 0;
      console.log(`[Merge v4.5] ✅ Scene ${sceneIndex} video captured ${Math.round(sz / 1024 / 1024 * 10) / 10} MB`);
      try { showBotOverlay(sceneLabel, `✅ ฉาก ${sceneIndex} เสร็จ (${Math.round(sz / 1024 / 1024 * 10) / 10} MB) → ฉากถัดไป...`); } catch (_) {}
      mergeForwardLog(`✅ ฉาก ${sceneIndex} video captured (${Math.round(sz / 1024 / 1024 * 10) / 10} MB)`, 'success');
      // v4.4.5: return imageUrl ด้วย — popup เก็บไว้เผื่อ retry video อย่างเดียว
      // v4.5.0: เพิ่ม imageBase64 — Story v2 ใช้สำหรับ Export Prompts JSON (Prompt Viewer)
      return { success: true, sceneIndex, videoSize: sz, imageUrl: imgResult.imageUrl, imageBase64: imgResult.imageBase64 || null };
    }

    const now = Date.now();

    // v4.5: ตรวจ new Failed cards ทุก 5s (ระหว่างรอ download/hook) — ป้องกันค้างยาวเมื่อเฟล
    if (now - lastFailCheck > FAIL_CHECK_INTERVAL_MS && typeof countAllFailedGenerations === 'function') {
      lastFailCheck = now;
      const failedNow = countAllFailedGenerations();
      const newFails = failedNow - failedBaseline;
      if (newFails > 0) {
        mergeForwardLog(`❌ ฉาก ${sceneIndex} เฟลระหว่างรอ download — Failed card ใหม่ +${newFails}`, 'error');
        return { success: false, error: `Scene ${sceneIndex} fail during wait — new Failed card (+${newFails})` };
      }
    }

    // v0.6.1 (port VIP v4.6.7): 🆘 hook ดักไฟล์ไม่ติด → ดึงวิดีโอจาก DOM ตรงๆ (additive — ไม่กระทบทางปกติ)
    if ((now - startWait) > FALLBACK_AFTER_MS && (now - lastFallbackAt) > 40000 && fallbackAttempts < 3) {
      lastFallbackAt = now;
      fallbackAttempts++;
      try {
        await mergeFallbackCaptureVideo_v467(sceneIndex, beforeClipKeys, fallbackAttempts);
      } catch (e) {
        mergeForwardLog(`⚠️ ฉาก ${sceneIndex}: fallback error: ${e.message}`, 'warning');
      }
    }

    if (now - lastLog > 20000) {
      const sec = Math.floor((now - startWait) / 1000);
      console.log(`[Merge v4.5] ...still waiting video scene ${sceneIndex} (${sec}s)`);
      mergeForwardLog(`⏳ รอ video blob (${sec}s)...`);
      lastLog = now;
    }
    await new Promise((r) => setTimeout(r, 2000));
  }
  mergeForwardLog(`⏱️ Timeout ${TIMEOUT_MS / 1000}s รอ video ฉาก ${sceneIndex}`, 'error');
  return { success: false, error: `Timeout (${TIMEOUT_MS / 1000}s) รอ video scene ${sceneIndex}` };
}

// v0.6.1 (port VIP v4.6.7): อ่าน video src จาก clip card (currentSrc/src/<source>) — null ถ้ายังไม่โหลด <video>
function _pdGetClipVideoSrc(card) {
  if (!card) return null;
  try {
    const v = card.querySelector('video') || (card.tagName === 'VIDEO' ? card : null);
    if (v) {
      if (v.currentSrc) return v.currentSrc;
      if (v.src) return v.src;
      const s = v.querySelector && v.querySelector('source');
      if (s && s.src) return s.src;
    }
  } catch (_) {}
  return null;
}

// v0.6.1 (port VIP v4.6.7): 🆘 Fallback ดึงวิดีโอตรงจาก DOM — ใช้เมื่อ hook ดักไฟล์ไม่ติด (Flow เปลี่ยนวิธี download แบบ A/B)
//   ADDITIVE: ทำงานเฉพาะตอน hook ไม่ทำงาน → ไม่กระทบโหมดอื่น · หาคลิปใหม่ → อ่าน <video> src → ให้ MAIN world fetch → dispatch __flow_final_video__ (path เดิม set __flowFinalVideoData__)
async function mergeFallbackCaptureVideo_v467(sceneIndex, beforeClipKeys, attempt) {
  mergeForwardLog(`🆘 ฉาก ${sceneIndex}: hook ดักไฟล์ไม่ติด (ครั้งที่ ${attempt}) — ลองดึงวิดีโอจากหน้าตรงๆ`, 'warning');

  // === Diagnostic: รายงานสภาพ ณ ตอนนี้ (ทำเฉพาะครั้งแรก ไม่ให้ log รก) ===
  if (attempt === 1) {
    try {
      const seen = window.__pdFinalVideoSeen__;
      if (seen && seen.count) {
        mergeForwardLog(`🔬 hook ยิง event ${seen.count} ครั้ง (ล่าสุด ${Math.round((seen.lastSize || 0) / 1024)}KB · source: ${seen.lastSource}) — แต่ไม่มีตัว >1MB`, 'info');
      } else {
        mergeForwardLog(`🔬 hook ไม่ยิง event เลย → Flow น่าจะเปลี่ยนวิธี download (blob/anchor ไม่ match)`, 'info');
      }
      const anchors = Array.from(document.querySelectorAll('a[download]')).slice(0, 3)
        .map(a => `${(a.getAttribute('download') || '?')}|${(a.href || '').slice(0, 22)}`);
      if (anchors.length) mergeForwardLog(`🔬 anchor[download] บนหน้า: ${anchors.join('  ,  ')}`, 'info');
      else mergeForwardLog(`🔬 ไม่มี <a download> บนหน้า (Flow ดาวน์โหลดแบบอื่น)`, 'info');
    } catch (_) {}
  }

  // === หาคลิปตัวใหม่ (เหมือน logic ดาวน์โหลด — กันหยิบคลิปข้ามฉาก) ===
  let card = null;
  try {
    const cards = findClipContainers() || [];
    if (beforeClipKeys) {
      const idx = _pdFindNewClipIndex(beforeClipKeys);
      card = (idx >= 0 ? cards[idx] : cards[cards.length - 1]) || null;
    } else {
      card = cards[cards.length - 1] || null;
    }
  } catch (_) {}
  if (!card) {
    mergeForwardLog(`⚠️ ฉาก ${sceneIndex}: fallback หา card คลิปไม่เจอ`, 'warning');
    return;
  }

  // === อ่าน video src — ถ้าไม่มี <video> ให้ hover/scroll card เพื่อ trigger Flow โหลด player ===
  let src = _pdGetClipVideoSrc(card);
  if (!src) {
    try {
      card.scrollIntoView({ block: 'center' });
      const r = card.getBoundingClientRect();
      const opts = { bubbles: true, cancelable: true, view: window, clientX: r.left + r.width / 2, clientY: r.top + r.height / 2, pointerId: 1, pointerType: 'mouse' };
      card.dispatchEvent(new PointerEvent('pointerover', opts));
      card.dispatchEvent(new MouseEvent('mouseover', opts));
      card.dispatchEvent(new MouseEvent('mousemove', opts));
    } catch (_) {}
    for (let w = 0; w < 10 && !src; w++) {
      await new Promise(r => setTimeout(r, 1000));
      src = _pdGetClipVideoSrc(card);
      if (!src) { // เผื่อ card reference เก่า — ลองคลิปใหม่สุดอีกที
        const cs = findClipContainers() || [];
        src = _pdGetClipVideoSrc(cs[cs.length - 1]);
      }
    }
  }
  if (!src) {
    mergeForwardLog(`⚠️ ฉาก ${sceneIndex}: fallback อ่าน video src ไม่ได้ (ยังไม่โหลด <video>)`, 'warning');
    return;
  }
  mergeForwardLog(`🔬 fallback เจอ video src (${src.startsWith('blob:') ? 'blob' : 'http'}): ${src.slice(0, 32)}...`, 'info');

  // === ให้ MAIN world (flow-hook) fetch แล้ว dispatch __flow_final_video__ (path เดิม set __flowFinalVideoData__) ===
  const onResult = (e) => {
    const d = e.detail || {};
    if (d.ok) mergeForwardLog(`✅ ฉาก ${sceneIndex}: fallback ดึงวิดีโอสำเร็จ (${Math.round((d.size || 0) / 1024 / 1024 * 10) / 10} MB)`, 'success');
    else mergeForwardLog(`⚠️ ฉาก ${sceneIndex}: fallback fetch ล้มเหลว: ${d.error || '?'}`, 'warning');
    window.removeEventListener('__flow_fetch_video_result__', onResult);
  };
  window.addEventListener('__flow_fetch_video_result__', onResult);
  window.dispatchEvent(new CustomEvent('__flow_fetch_video_url__', { detail: { url: src, sceneIndex } }));
  // ผลวิดีโอจะถูก set ที่ window.__flowFinalVideoData__ ผ่าน path เดิม → loop หลักจับได้เอง
}

// v4.5: trigger download คลิปล่าสุด — ใช้ executeClipDownload ที่ verified แล้ว
//       Pattern: hover thumbnail → click 3-dot → click "Download" menuitem → pick 720p
//       Hook ดักไฟล์ที่ skipDownload=true ไม่ลงเครื่อง แล้วเก็บ base64 ใน __flowFinalVideoData__
async function mergeTriggerLatestClipDownload_v45(sceneIndex, quality = '720p', beforeClipKeys = null) {
  // v4.4.9c: รับ quality (720p/1080p/4k) — ส่งต่อ executeClipDownload ที่ handle UI + upscale wait
  const qLabel = quality === '4k' ? '4K' : quality;

  // v4.5.8: 🆔 หา index ของ "คลิปตัวใหม่" จาก snapshot-diff (กัน reuse mode หยิบคลิปข้ามชุด)
  //   รอคลิปใหม่โผล่สูงสุด ~30s (เผื่อ DOM ยัง render ไม่ทัน) — ทำหน้าที่ยืนยัน "คลิปเสร็จ" ด้วย
  // v4.6.2 🐛 FIX (คลิปซ้ำตอนฉากเยอะ): findClipContainers() เรียง [0]=เก่าสุด, [length-1]=ใหม่สุด
  //   เดิม fallback = index 0 → ดาวน์โหลดคลิปเก่าสุดซ้ำตอน diff หาไม่เจอ. แก้: fallback = คลิปใหม่สุด
  const _newestIdx = () => Math.max(0, (findClipContainers() || []).length - 1);
  let targetIdx = _newestIdx();
  if (beforeClipKeys) {
    let found = -1;
    for (let w = 0; w < 15; w++) {
      found = _pdFindNewClipIndex(beforeClipKeys);
      if (found >= 0) break;
      await new Promise(r => setTimeout(r, 2000));
    }
    if (found >= 0) {
      targetIdx = found;
      mergeForwardLog(`🆔 ฉาก ${sceneIndex}: เจอคลิปตัวใหม่ที่ตำแหน่ง ${targetIdx} (snapshot-diff — ดาวน์โหลดถูกตัว)`, 'info');
    } else {
      targetIdx = _newestIdx();
      mergeForwardLog(`⚠️ ฉาก ${sceneIndex}: หาคลิปตัวใหม่ไม่เจอ (diff) — fallback คลิปใหม่สุด (ตำแหน่ง ${targetIdx})`, 'warning');
    }
  }

  mergeForwardLog(`🔍 ดาวน์โหลดคลิปฉาก ${sceneIndex} (${qLabel}) ผ่าน 3-dot menu...`);
  console.log(`[Merge v4.5] executeClipDownload(${targetIdx}, '${quality}') for scene ${sceneIndex}...`);
  try {
    if (typeof executeClipDownload === 'function') {
      // v4.5.8: ดาวน์โหลด "คลิปตัวใหม่" ที่ diff เจอ (ไม่ใช่ index 0 ตายตัว) — กันหยิบผิดใน reuse
      // 1080p/4K: executeClipDownload จะรอ upscale อัตโนมัติ (Smart Detection ใน Step 7)
      await executeClipDownload(targetIdx, quality);
      mergeForwardLog(`✅ คลิก Download ${qLabel} สำเร็จ (รอ hook capture)`, 'success');
      return true;
    } else {
      mergeForwardLog('❌ executeClipDownload ไม่พบในหน้านี้', 'error');
      return false;
    }
  } catch (err) {
    mergeForwardLog(`❌ executeClipDownload error: ${err.message}`, 'error');
    console.warn('[Merge v4.5] executeClipDownload error:', err.message);
    return false;
  }
}

// v4.5: forward log จาก content.js → popup mergeLog UI (กัน user งง ว่าทำอะไรอยู่)
function mergeForwardLog(text, type) {
  try {
    chrome.runtime.sendMessage({
      action: 'mergeProgressLog',
      text: '[bot] ' + text,
      type: type || 'info',
    }).catch(() => {});
  } catch (_) {}
  console.log(`[Merge v4.5 fwd] ${text}`);
}

// =====================================================================
// v4.5.0: Story Mode 🚀 Express Engine (API Direct) — pure Flow API path
// =====================================================================
// ใส่ logic ที่อีกทีมเขียน (v4.4.10 branch) เข้า slot "🚀 Express Engine"
// ใน Story Mode (UI radio card ที่เราเตรียมไว้ตั้งแต่ v4.4.9c แล้ว)
//
// ทำงานยังไง: เลียน structure ของ Story Merge (v.2) แต่เปลี่ยนทุก step
// เป็น Flow API ตรง (ไม่ใช้ UI click) — เหมือนกับ Auto Mode Express:
//   1. Upload refs (สินค้า + ตัวละคร) ครั้งเดียวต้นรอบ
//   2. Loop scene: generateImage → animateImage → poll
//   3. Concat ทุกคลิป → MP4 → dispatch __flow_final_video__
//
// Retry: 3 ต่อ step (image / animate+poll)
// Failure: skip ฉากนั้น, ฉากอื่นไหลต่อ — ไม่ทำให้ทั้ง run fail
// Stop: เช็ค window._storyApiStopFlag ทุก iteration
//
// data shape:
// {
//   scenes: [{ sceneNumber, imagePrompt, videoPrompt, script }],
//   refs: [{ name, base64, filename }],   // ตัวละคร + product (upload ครั้งเดียวต้นรอบ)
//   imageModel: 'nano_banana_pro'|'imagen_4'|'imagen_3_5',
//   videoModel: 'veo_lite_lower'|'veo_lite'|'veo_fast'|'veo_quality',
//   aspectRatio: '9:16'|'16:9'|'1:1',
//   storyLoopIndex: 0,
// }
//
// 🛡️ ISOLATION: function นี้ไม่กระทบ Story v.2 Merge / Auto Mode Express / Auto Merge
//   - ใช้ helper เดิมของ content.js (callFlowAPI, _pdWaitForVideo, _pdConcatAndWait, ฯลฯ)
//   - ไม่แก้ shared helpers, ไม่แก้ flow-api.js
//   - Express ไม่มี upscale — quality dropdown ของ Story v.2 จะถูกซ่อนตอนเลือก Express
// =====================================================================
async function startStoryViaAPI_v1(data) {
  const loopIdx = (data.storyLoopIndex || 0) + 1;
  const tag = `[v4.5.0 StoryExpress L${loopIdx}]`;
  const scenes = Array.isArray(data.scenes) ? data.scenes : [];
  const totalScenes = scenes.length;
  console.log(`${tag} starting — ${totalScenes} scenes`);
  forwardLog(`📖 [Story Express] เริ่ม Story รอบ ${loopIdx} (${totalScenes} ฉาก)`);
  showApiDirectCurtain(`📖 Story Express: เตรียม ${totalScenes} ฉาก...`);
  showBotOverlay(`📖 Story Express`, `${totalScenes} ฉาก`);

  const projectId = _pdGetProjectIdFromURL();
  if (!projectId) throw new Error('Story Express: ไม่พบ projectId ใน URL — เปิดหน้า project ก่อน');
  if (totalScenes === 0) throw new Error('Story Express: ไม่มี scenes ใน data');
  const sessionId = ';' + Date.now();

  await callFlowAPI('isReady');
  window._storyApiStopFlag = false;

  // ===== STEP 1: Upload refs (ครั้งเดียว) =====
  const refUUIDs = [];
  const refs = Array.isArray(data.refs) ? data.refs : [];
  if (refs.length > 0) {
    forwardLog(`📤 [Story Express] อัพ ref ${refs.length} รูป...`);
    for (let i = 0; i < refs.length; i++) {
      if (window._storyApiStopFlag) throw new Error('Story Express: หยุดโดยผู้ใช้');
      if (i > 0) await _pdSleepJitter(1500, 3000);
      const r = refs[i];
      if (!r || !r.base64) continue;
      showBotOverlay(`📤 อัพรูป ${i + 1}/${refs.length}`, r.filename || `ref${i + 1}`);
      try {
        const fileBlob = _pdBase64ToBlob(r.base64);
        const media = await callFlowAPI('uploadImage', {
          projectId,
          fileBlob,
          fileName: r.filename || `pd-ref${i + 1}.png`,
          mimeType: fileBlob.type,
        });
        if (media && media.name) {
          refUUIDs.push(media.name);
          console.log(`${tag} ref ${i + 1} uploaded — ${media.name}`);
          forwardLog(`✅ [Story Express] อัพ ${r.filename || `ref${i + 1}`} เสร็จ`);
        }
      } catch (err) {
        console.warn(`${tag} ref upload ${i} fail:`, err.message);
        forwardLog(`⚠️ [Story Express] อัพ ${r.filename || `ref${i + 1}`} เฟล — ข้าม (${(err.message || '').substring(0, 80)})`);
      }
    }
  }
  await _pdSleepJitter(1500, 3000);

  // ===== Model + aspect mapping =====
  // v4.5.2: nano_banana_2 ยังไม่มี API key ของ Flow → fallback ใช้ Pro ชั่วคราว
  const imgModelMap = {
    'nano_banana_pro': 'GEM_PIX_2',
    'nano_banana_2':   'GEM_PIX_2', // v4.5.2 TEMP — ใช้ Pro แทนจนกว่าจะรู้ API key ของ Nano 2
    'imagen_4': 'IMAGEN_4',
    'imagen_3_5': 'IMAGEN_3_5',
  };
  const imageModelName = imgModelMap[data.imageModel] || 'IMAGEN_4';
  if (data.imageModel === 'nano_banana_2') {
    forwardLog(`ℹ️ [Story Express] Nano Banana 2 ยังไม่รองรับใน API Direct → ใช้ Pro แทน`);
  }
  const i2vModelMap = {
    'veo_lite_lower': 'veo_3_1_i2v_lite_low_priority',
    'veo_lite':       'veo_3_1_i2v_lite',
    'veo_fast':       'veo_3_1_i2v_fast',
    'veo_quality':    'veo_3_1_i2v_quality',
    'omni_flash':     'abra_i2v_8s',   // Omni Flash (i2v 8s, ~12 credits) — codename abra
  };
  let videoModelKey = i2vModelMap[data.videoModel] || 'veo_3_1_i2v_lite_low_priority';
  // ⏱️ Omni Flash: จำนวนวิฝังในชื่อคีย์ (abra_i2v_8s / abra_i2v_10s)
  if (data.videoModel === 'omni_flash') videoModelKey = 'abra_i2v_' + (Number(data.omniSeconds) === 10 ? 10 : 8) + 's';
  const imgAspectMap = {
    '9:16': 'IMAGE_ASPECT_RATIO_PORTRAIT',
    '16:9': 'IMAGE_ASPECT_RATIO_LANDSCAPE',
    '1:1':  'IMAGE_ASPECT_RATIO_SQUARE',
  };
  const imageAspect = imgAspectMap[data.aspectRatio] || 'IMAGE_ASPECT_RATIO_PORTRAIT';
  const vidAspectMap = {
    '9:16': 'VIDEO_ASPECT_RATIO_PORTRAIT',
    '16:9': 'VIDEO_ASPECT_RATIO_LANDSCAPE',
    '1:1':  'VIDEO_ASPECT_RATIO_SQUARE',
  };
  const videoAspect = vidAspectMap[data.aspectRatio] || 'VIDEO_ASPECT_RATIO_PORTRAIT';

  console.log(`${tag} models: img=${imageModelName} vid=${videoModelKey} imgAR=${imageAspect} vidAR=${videoAspect}`);
  forwardLog(`🎛️ [Story Express] model: image=${data.imageModel}→${imageModelName}, video=${data.videoModel}→${videoModelKey}`);

  // ===== STEP 2: Loop per scene =====
  const allClipMediaIds = [];
  const sceneFailures = [];
  const IMG_MAX = 3;
  const VID_MAX = 3;

  for (let i = 0; i < totalScenes; i++) {
    if (window._storyApiStopFlag) throw new Error('Story Express: หยุดโดยผู้ใช้');
    const scene = scenes[i];
    const sceneNum = scene.sceneNumber || (i + 1);
    forwardLog(`🎬 [Story Express] ฉาก ${sceneNum}/${totalScenes}`);
    showBotOverlay(`📖 ฉาก ${sceneNum}/${totalScenes}`, 'Image');

    // ---- 2a) generateImage (retry 3) ----
    let imgMediaId = null;
    let lastImgErr = null;
    for (let attempt = 1; attempt <= IMG_MAX; attempt++) {
      if (window._storyApiStopFlag) throw new Error('Story Express: หยุดโดยผู้ใช้');
      if (attempt > 1) {
        const waitMs = attempt === 2 ? _pdJitter(5000, 15000) : _pdJitter(20000, 35000);
        forwardLog(`⏳ [Story Express] รอ ${Math.round(waitMs / 1000)}s ก่อน retry image ฉาก ${sceneNum}`);
        await new Promise(r => setTimeout(r, waitMs));
      }
      try {
        const imgRes = await callFlowAPI('generateImage', {
          projectId, sessionId,
          prompt: scene.imagePrompt || '',
          refUUIDs,
          imageModelName,
          aspectRatio: imageAspect,
        });
        const m = imgRes && imgRes.media && imgRes.media[0];
        if (!m || !m.name) throw new Error('image gen returned no media');
        imgMediaId = m.name;
        console.log(`${tag} scene ${sceneNum} image OK — ${imgMediaId}`);
        forwardLog(`✅ [Story Express] ฉาก ${sceneNum}: รูปเสร็จ`);
        break;
      } catch (err) {
        lastImgErr = err;
        console.warn(`${tag} scene ${sceneNum} image attempt ${attempt} fail: ${err.message}`);
        forwardLog(`❌ [Story Express] ฉาก ${sceneNum} รูป รอบ ${attempt}/${IMG_MAX} เฟล: ${(err.message || '').substring(0, 80)}`);
      }
    }
    if (!imgMediaId) {
      sceneFailures.push({ sceneNum, step: 'image', error: lastImgErr?.message || 'unknown' });
      forwardLog(`⏭️ [Story Express] ข้ามฉาก ${sceneNum} (รูปสร้างไม่ได้)`);
      continue;
    }
    await _pdSleepJitter(1500, 3000);

    // ---- 2b) animateImage + poll (retry 3) ----
    showBotOverlay(`📖 ฉาก ${sceneNum}/${totalScenes}`, 'Animate');
    let videoMediaId = null;
    let lastVidErr = null;
    // v4.5.0: capture full diagnostic on fail — last animate response + last poll media
    let lastAnimResponse = null;
    let lastPolledMedia = null;
    for (let attempt = 1; attempt <= VID_MAX; attempt++) {
      if (window._storyApiStopFlag) throw new Error('Story Express: หยุดโดยผู้ใช้');
      if (attempt > 1) {
        const waitMs = attempt === 2 ? _pdJitter(8000, 18000) : _pdJitter(25000, 40000);
        forwardLog(`⏳ [Story Express] รอ ${Math.round(waitMs / 1000)}s ก่อน retry video ฉาก ${sceneNum}`);
        await new Promise(r => setTimeout(r, waitMs));
      }
      try {
        // v4.5.0: log prompt ที่ส่งไปทุก attempt (ตัด 200 chars พอ)
        let promptUsed = scene.videoPrompt || scene.imagePrompt || '';
        // ✂️ รอบก่อนโดน 400 = พรอมต์ยาวเกินลิมิตใหม่ → รีทายด้วยฉบับตัด
        if (attempt > 1 && _pdIs400(lastVidErr)) {
          promptUsed = _pdTrimPrompt(promptUsed, attempt >= 3);
          forwardLog(`✂️ [Story Express] ฉาก ${sceneNum}: พรอมต์ยาวเกินลิมิตใหม่ (400) — ตัด${attempt >= 3 ? 'แรงขึ้น' : 'ท่อนเสริม'} แล้วลองใหม่`);
        }
        console.log(`${tag} scene ${sceneNum} attempt ${attempt} prompt:`, promptUsed.slice(0, 200));

        const animRes = await callFlowAPI('animateImage', {
          projectId, sessionId,
          prompt: promptUsed,
          imageMediaId: imgMediaId,
          aspectRatio: videoAspect,
          videoModelKey,
          // cropCoordinates ถอดออก 2026-08-10 — เว็บจริงไม่ส่งแล้ว
        });
        lastAnimResponse = animRes;
        const m = animRes && animRes.media && animRes.media[0];
        if (!m || !m.name) throw new Error('animate returned no media (response: ' + JSON.stringify(animRes || {}).slice(0, 200) + ')');
        const candidateId = m.name;
        console.log(`${tag} scene ${sceneNum} animate started — ${candidateId}`);
        showBotOverlay(`📖 ฉาก ${sceneNum}/${totalScenes}`, 'Polling');
        await _pdWaitForVideo(projectId, candidateId, {
          timeoutMs: 10 * 60 * 1000,
          tag: `Story ฉาก ${sceneNum}/${totalScenes}`,
          // v4.5.0: capture media object ทุก poll → ใช้ extract failureMessage ตอน fail
          onProgress: (status, media) => { if (media) lastPolledMedia = media; },
        });
        videoMediaId = candidateId;
        forwardLog(`✅ [Story Express] ฉาก ${sceneNum}: คลิปเสร็จ`);
        break;
      } catch (err) {
        lastVidErr = err;
        // v4.5.0: log แบบละเอียดทุก attempt (HTTP status + body + Veo failureMessage)
        const errStatus = err.status || '';
        const errBody = err.body ? (typeof err.body === 'string' ? err.body : JSON.stringify(err.body)).slice(0, 300) : '';
        const failMsg = lastPolledMedia?.mediaMetadata?.mediaStatus?.failureMessage
                     || lastPolledMedia?.mediaMetadata?.mediaStatus?.failureReason
                     || lastPolledMedia?.mediaMetadata?.errorMessage
                     || '';
        console.warn(`${tag} scene ${sceneNum} video attempt ${attempt} fail:`, {
          msg: err.message,
          httpStatus: errStatus,
          httpBody: errBody,
          veoFailureMessage: failMsg,
          lastPolledMedia: lastPolledMedia ? JSON.stringify(lastPolledMedia).slice(0, 500) : null,
          promptHead: (scene.videoPrompt || scene.imagePrompt || '').slice(0, 150),
        });
        // forwardLog → popup log panel — แสดงข้อมูลพอใช้แก้บั๊กได้
        const detailParts = [`รอบ ${attempt}/${VID_MAX}`];
        if (errStatus) detailParts.push(`HTTP ${errStatus}`);
        detailParts.push(`msg: ${(err.message || '').substring(0, 80)}`);
        if (failMsg) detailParts.push(`Veo: ${String(failMsg).substring(0, 80)}`);
        forwardLog(`❌ [Story Express] ฉาก ${sceneNum} คลิปเฟล (${detailParts.join(' | ')})`);
        if (errBody && attempt === VID_MAX) {
          // ตอนรอบสุดท้าย → log response body เต็มๆ ใน popup ด้วย
          forwardLog(`📝 [Story Express] response body ฉาก ${sceneNum}: ${errBody}`);
        }
      }
    }
    if (!videoMediaId) {
      const finalErrMsg = lastVidErr?.message || 'unknown';
      const finalFailMsg = lastPolledMedia?.mediaMetadata?.mediaStatus?.failureMessage
                        || lastPolledMedia?.mediaMetadata?.mediaStatus?.failureReason
                        || '';
      sceneFailures.push({
        sceneNum,
        step: 'video',
        error: finalErrMsg,
        veoFailureMessage: finalFailMsg,
        promptHead: (scene.videoPrompt || scene.imagePrompt || '').slice(0, 200),
      });
      forwardLog(`⏭️ [Story Express] ข้ามฉาก ${sceneNum} (คลิปสร้างไม่ได้) — เหตุผล: ${finalFailMsg || finalErrMsg}`);
      continue;
    }

    allClipMediaIds.push(videoMediaId);
    try {
      chrome.runtime.sendMessage({
        action: 'storyApiSceneProgress',
        sceneNum,
        totalScenes,
        successCount: allClipMediaIds.length,
        failCount: sceneFailures.length,
      }).catch(() => {});
    } catch (_) {}
    await _pdSleepJitter(2000, 4000);
  }

  // ===== STEP 3: Concat =====
  if (allClipMediaIds.length === 0) {
    forwardLog(`❌ [Story Express] ไม่มีฉากใดสำเร็จเลย — fail`);
    throw new Error(`Story Express: ทุกฉาก fail (0/${totalScenes})`);
  }

  forwardLog(`🎬 [Story Express] รวม ${allClipMediaIds.length}/${totalScenes} คลิป → MP4...`);
  showApiDirectCurtain(`🎬 รวม ${allClipMediaIds.length} คลิปเป็น MP4...`);
  showBotOverlay(`📖 Concat`, `${allClipMediaIds.length} clips`);
  const inputVideos = allClipMediaIds.map((id) => ({
    mediaGenerationId: id,
    length: '8000000000',
    startTimeOffset: '0s',
    endTimeOffset: '8s',
  }));
  const concatRes = await _pdConcatAndWait(inputVideos, {
    timeoutMs: 10 * 60 * 1000,
    onProgress: (status) => {
      if (status === 'MEDIA_GENERATION_STATUS_ACTIVE') {
        showBotOverlay(`📖 Story Express: encode`, 'Active');
      }
    },
  });
  const encodedVideo = concatRes && concatRes.encodedVideo;
  if (!encodedVideo) throw new Error('concat OK but no encodedVideo');

  const sizeBytes = Math.round(encodedVideo.length * 3 / 4);
  const sizeMB = Math.round(sizeBytes / 1024 / 1024 * 10) / 10;
  console.log(`${tag} ✅ encode done — ${sizeMB} MB`);
  forwardLog(`✅ [Story Express] ได้คลิปสุดท้าย ${sizeMB} MB (${allClipMediaIds.length}/${totalScenes} ฉาก)`);

  // ===== STEP 4: Deliver to popup =====
  const filename = `pd_story_express_${Date.now()}.mp4`;
  window.dispatchEvent(new CustomEvent('__flow_final_video__', {
    detail: {
      base64: 'data:video/mp4;base64,' + encodedVideo,
      size: sizeBytes,
      filename,
      source: 'storyExpress_v4.5.0',
    },
  }));
  console.log(`${tag} dispatched __flow_final_video__`);

  await new Promise(r => setTimeout(r, 1500));

  try {
    chrome.runtime.sendMessage({
      action: 'storyV1ApiComplete',
      success: true,
      totalScenes,
      scenesCompleted: allClipMediaIds.length,
      sceneFailures,
      videoFilename: filename,
      videoSizeBytes: sizeBytes,
      source: 'storyExpress_v4.5.0',
    });
    console.log(`${tag} sent storyV1ApiComplete`);
  } catch (e) {
    console.warn(`${tag} sendMessage storyV1ApiComplete failed:`, e);
  }

  try { hideApiDirectCurtain(); } catch (_) {}
  try { hideBotOverlay(); } catch (_) {}
  isProcessing = false;
  return {
    videoMediaIds: allClipMediaIds,
    sceneFailures,
    encodedVideoLen: encodedVideo.length,
  };
}

// v4.5.0: Message handler สำหรับ Story Mode Express Engine (รับ trigger จาก popup)
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.action === 'createStoryViaAPI_v1') {
    if (isProcessing) {
      sendResponse({ success: false, error: 'กำลังดำเนินการอยู่' });
      return true;
    }
    isProcessing = true;
    sendResponse({ success: true, started: true });
    startStoryViaAPI_v1(message.data)
      .catch((error) => {
        console.error('[v4.5.0 StoryExpress] error:', error);
        if (error && error.status) console.error('[v4.5.0 StoryExpress] HTTP status:', error.status);
        if (error && error.body) console.error('[v4.5.0 StoryExpress] Response body:', error.body);
        const errMsg = (error.message || String(error)).substring(0, 150);
        showBotOverlay('❌ Story Express เฟล: ' + errMsg, 'Error');
        try { updateApiDirectCurtain('❌ Story Express เฟล — ' + errMsg); } catch (_) {}
        setTimeout(() => { try { hideApiDirectCurtain(); } catch (_) {} }, 8000);
        isProcessing = false;
        try {
          chrome.runtime.sendMessage({
            action: 'storyV1ApiFailed',
            error: errMsg,
            stopped: /หยุดโดยผู้ใช้/.test(error.message || ''),
          });
        } catch (_) {}
      });
    return true;
  }
});
